    def _ensure_time_series_classification_immutability_guards(self) -> None:
        immutable_fields_by_table = {
            "measurement_dimensions": ("id", "dimension_key", "value_kind"),
            "measurement_units": (
                "id",
                "unit_key",
                "symbol",
                "dimension_id",
                "physical_dimension",
            ),
            "time_series_data_classes": ("id", "data_class_key"),
            "time_series_semantic_types": (
                "id",
                "semantic_key",
                "dimension_id",
                "canonical_unit_id",
                "value_kind",
                "default_aggregation",
                "validation_rules_json",
                "is_system",
            ),
            "time_series_binding_roles": (
                "id",
                "role_key",
                "dimension_id",
                "canonical_unit_id",
                "association_allowed",
                "execution_allowed",
                "execution_contract_key",
                "is_system",
            ),
            "linkable_object_types": (
                "id",
                "object_type_key",
                "object_kind",
                "is_system",
            ),
            "time_series_role_compatibilities": (
                "id",
                "semantic_type_id",
                "binding_role_id",
                "object_type_id",
                "association_allowed",
                "execution_allowed",
                "rule_version",
                "supersedes_rule_id",
                "created_at",
                "created_by",
            ),
        }
        if self.database_backend == "postgresql":
            statements = [
                """
                CREATE OR REPLACE FUNCTION reject_classification_contract_delete()
                RETURNS trigger AS $$
                BEGIN
                    RAISE EXCEPTION 'TS_CLASSIFICATION_IMMUTABLE';
                END;
                $$ LANGUAGE plpgsql;
                """
            ]
            for index, (table_name, fields) in enumerate(
                immutable_fields_by_table.items(), start=1
            ):
                condition = " OR ".join(
                    f"OLD.{field} IS DISTINCT FROM NEW.{field}" for field in fields
                )
                statements.append(
                    f"""
                    CREATE OR REPLACE FUNCTION reject_classification_contract_update_{index}()
                    RETURNS trigger AS $$
                    BEGIN
                        IF {condition} THEN
                            RAISE EXCEPTION 'TS_CLASSIFICATION_IMMUTABLE';
                        END IF;
                        RETURN NEW;
                    END;
                    $$ LANGUAGE plpgsql;

                    DROP TRIGGER IF EXISTS ts_classification_contract_update_{index}
                        ON {table_name};
                    CREATE TRIGGER ts_classification_contract_update_{index}
                    BEFORE UPDATE ON {table_name}
                    FOR EACH ROW EXECUTE FUNCTION
                        reject_classification_contract_update_{index}();

                    DROP TRIGGER IF EXISTS ts_classification_contract_delete_{index}
                        ON {table_name};
                    CREATE TRIGGER ts_classification_contract_delete_{index}
                    BEFORE DELETE ON {table_name}
                    FOR EACH ROW EXECUTE FUNCTION reject_classification_contract_delete();
                    """
                )
            self.connection.executescript("\n".join(statements))
            return

        statements = [
            "DROP TRIGGER IF EXISTS time_series_semantic_types_immutable_contract;"
        ]
        for index, (table_name, fields) in enumerate(
            immutable_fields_by_table.items(), start=1
        ):
            condition = " OR ".join(
                f"OLD.{field} IS NOT NEW.{field}" for field in fields
            )
            statements.append(
                f"""
                DROP TRIGGER IF EXISTS ts_classification_contract_update_{index};
                CREATE TRIGGER ts_classification_contract_update_{index}
                BEFORE UPDATE ON {table_name}
                FOR EACH ROW
                WHEN {condition}
                BEGIN
                    SELECT RAISE(ABORT, 'TS_CLASSIFICATION_IMMUTABLE');
                END;

                DROP TRIGGER IF EXISTS ts_classification_contract_delete_{index};
                CREATE TRIGGER ts_classification_contract_delete_{index}
                BEFORE DELETE ON {table_name}
                FOR EACH ROW
                BEGIN
                    SELECT RAISE(ABORT, 'TS_CLASSIFICATION_IMMUTABLE');
                END;
                """
            )
        self.connection.executescript("\n".join(statements))

    def _seed_time_series_classification_catalog(self) -> None:
        validate_signal_registry_contract(TIME_SERIES_SIGNAL_CATALOG)
        expected_data_classes = {
            row["data_class_key"] for row in TIME_SERIES_DATA_CLASS_SEED
        }
        if set(TIME_SERIES_DATA_KINDS) != expected_data_classes:
            raise ClassificationContractDriftError(
                context={
                    "catalog": "TIME_SERIES_DATA_KINDS",
                    "key": "*",
                    "field": "keys",
                    "expected": sorted(expected_data_classes),
                    "actual": sorted(TIME_SERIES_DATA_KINDS),
                }
            )
        self._assert_persisted_time_series_classification_contract()
        self.connection.executemany(
            """
            INSERT INTO measurement_dimensions (
                id, dimension_key, display_name, value_kind, status
            ) VALUES (?, ?, ?, ?, ?)
            ON CONFLICT (dimension_key) DO NOTHING
            """,
            [
                (
                    row["id"],
                    row["dimension_key"],
                    row["display_name"],
                    row["value_kind"],
                    row["status"],
                )
                for row in MEASUREMENT_DIMENSION_SEED
            ],
        )
        self.connection.executemany(
            """
            INSERT INTO measurement_units (
                id, unit_key, symbol, dimension_id, physical_dimension, status
            ) VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT (unit_key) DO NOTHING
            """,
            [tuple(row.values()) for row in MEASUREMENT_UNIT_SEED],
        )
        self.connection.executemany(
            """
            INSERT INTO time_series_data_classes (
                id, data_class_key, display_name, status
            ) VALUES (?, ?, ?, ?)
            ON CONFLICT (data_class_key) DO NOTHING
            """,
            [tuple(row.values()) for row in TIME_SERIES_DATA_CLASS_SEED],
        )
        self.connection.executemany(
            """
            INSERT INTO time_series_semantic_types (
                id, semantic_key, display_name, description, dimension_id,
                canonical_unit_id, value_kind, default_aggregation,
                validation_rules_json, is_system, status, created_at, updated_at,
                created_by, updated_by
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT (semantic_key) DO NOTHING
            """,
            [tuple(row.values()) for row in TIME_SERIES_SEMANTIC_TYPE_SEED],
        )
        self.connection.executemany(
            """
            INSERT INTO time_series_binding_roles (
                id, role_key, display_name, dimension_id, canonical_unit_id,
                association_allowed, execution_allowed, execution_contract_key,
                is_system, status
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT (role_key) DO NOTHING
            """,
            [tuple(row.values()) for row in TIME_SERIES_BINDING_ROLE_SEED],
        )
        self.connection.executemany(
            """
            INSERT INTO linkable_object_types (
                id, object_type_key, object_kind, display_name, is_system, status
            ) VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT (object_type_key) DO NOTHING
            """,
            [tuple(row.values()) for row in LINKABLE_OBJECT_TYPE_SEED],
        )
        self.connection.executemany(
            """
            INSERT INTO time_series_role_compatibilities (
                id, semantic_type_id, binding_role_id, object_type_id,
                association_allowed, execution_allowed, rule_version, status,
                supersedes_rule_id, created_at, created_by, archived_at, archived_by
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT DO NOTHING
            """,
            [tuple(row.values()) for row in TIME_SERIES_ROLE_COMPATIBILITY_SEED],
        )

    def _assert_persisted_time_series_classification_contract(self) -> None:
        for table_name, key_column, seed_rows, immutable_fields in CLASSIFICATION_SEED_TABLES:
            for expected in seed_rows:
                key = expected[key_column]
                existing = self.connection.execute(
                    f"SELECT * FROM {table_name} WHERE {key_column} = ?",
                    (key,),
                ).fetchone()
                if existing is None:
                    continue
                for field in immutable_fields:
                    actual_value = existing[field]
                    expected_value = expected[field]
                    if actual_value != expected_value:
                        raise ClassificationContractDriftError(
                            context={
                                "catalog": table_name,
                                "key": key,
                                "field": field,
                                "expected": expected_value,
                                "actual": actual_value,
                            }
                        )

    def _ensure_canonical_content_model(self) -> None:
        for statement in canonical_schema_statements(self.database_backend):
            self.connection.execute(statement)
        self.connection.executescript(canonical_guard_script(self.database_backend))

    def _ensure_linkable_object_register(self) -> None:
        # The register lands before the content model because a canonical set
        # owned by an object references ``linkable_objects(id, project_id)``.
        for statement in linkable_object_schema_statements(self.database_backend):
            self.connection.execute(statement)
        self.connection.executescript(
            linkable_object_guard_script(self.database_backend)
        )

    def _ensure_canonical_owner_object_reference(self) -> None:
        script = canonical_owner_object_reference_script(self.database_backend)
        if script is not None:
            self.connection.executescript(script)

    def _ensure_link_layer(self) -> None:
        for statement in link_layer_schema_statements(self.database_backend):
            self.connection.execute(statement)
        constraint_upgrade = link_layer_constraint_upgrade_script(
            self.database_backend
        )
        if constraint_upgrade is not None:
            self.connection.executescript(constraint_upgrade)
        self.connection.executescript(link_layer_guard_script(self.database_backend))
        self.connection.executescript(link_history_guard_script(self.database_backend))

    def _ensure_catalog_projection(self) -> None:
        for statement in catalog_projection_schema_statements(self.database_backend):
            self.connection.execute(statement)
        self._ensure_catalog_projection_read_columns()

    def _ensure_object_series_tables(self) -> None:
        for statement in object_series_schema_statements(self.database_backend):
            self.connection.execute(statement)
        # TS7-013 binds a staged shared revision to the association that opened
        # it, so an already-landed TS7-010 table gains the column additively.
        self._ensure_canonical_space_column(
            self._object_series_table("time_series_ingestions"),
            "catalog_association_id",
            "BIGINT" if self.database_backend == "postgresql" else "INTEGER",
        )

    def _ensure_migration_control_surface(self) -> None:
        # Chapter 10.3. Additive on both engines and independent of ``ts_next``:
        # C0 inventories the legacy source, so its control rows must survive a
        # rollback that abandons the expansion.
        for statement in migration_control_schema_statements(self.database_backend):
            self.connection.execute(statement)

    def _ensure_canonical_space_column(
        self, table: str, column: str, definition: str
    ) -> None:
        """Add one column to a schema-qualified expansion table, once."""

        if self.database_backend == "postgresql":
            schema_name, table_name = table.split(".", 1)
            existing = {
                row["column_name"]
                for row in self.connection.execute(
                    """
                    SELECT column_name FROM information_schema.columns
                    WHERE table_schema = ? AND table_name = ?
                    """,
                    (schema_name, table_name),
                ).fetchall()
            }
        else:
            existing = {
                row["name"]
                for row in self.connection.execute(
                    f"PRAGMA table_info({table})"
                ).fetchall()
            }
        if column not in existing:
            self.connection.execute(
                f"ALTER TABLE {table} ADD COLUMN {column} {definition}"
            )

    def _ensure_catalog_projection_read_columns(self) -> None:
        """Expand an already-landed TS7-005 projection for TS7-006 rows."""

        table = self._projection("time_series_catalog_entries")
        definitions = {
            "owner_project_name": "TEXT NOT NULL DEFAULT ''",
            "set_name": "TEXT NOT NULL DEFAULT ''",
            "set_version_number": "INTEGER NOT NULL DEFAULT 1",
            "set_version_label": "TEXT NOT NULL DEFAULT ''",
            "set_description": "TEXT NOT NULL DEFAULT ''",
            "signal_description": "TEXT NOT NULL DEFAULT ''",
            "revision_created_at": "TEXT NOT NULL DEFAULT ''",
            "source_timezone": "TEXT NOT NULL DEFAULT 'UTC'",
        }
        if self.database_backend == "postgresql":
            schema_name, table_name = table.split(".", 1)
            existing = {
                row["column_name"]
                for row in self.connection.execute(
                    """
                    SELECT column_name FROM information_schema.columns
                    WHERE table_schema = ? AND table_name = ?
                    """,
                    (schema_name, table_name),
                ).fetchall()
            }
        else:
            existing = {
                row["name"]
                for row in self.connection.execute(
                    f"PRAGMA table_info({table})"
                ).fetchall()
            }
        missing = [column for column in definitions if column not in existing]
        for column in missing:
            self.connection.execute(
                f"ALTER TABLE {table} ADD COLUMN {column} {definitions[column]}"
            )
        if not missing:
            return
        now = utc_now_iso()
        projected_sets = self._projected_catalog_set_ids()
        for set_id in projected_sets:
            self._project_catalog_entries(set_id=set_id, now=now)
        if projected_sets:
            self._raise_catalog_generation(now=now)

    def catalog_projection_table_names(self) -> dict[str, str]:
        """Physical name of every TS7-005 table on the configured engine."""

        return catalog_projection_table_names(self.database_backend)

    def canonical_table_names(self) -> dict[str, str]:
        """Physical name of every canonical table on the configured engine."""

        return canonical_table_names(self.database_backend)

    def linkable_object_table_names(self) -> dict[str, str]:
        """Physical name of every register table on the configured engine."""

        return linkable_object_table_names(self.database_backend)

    def link_layer_table_names(self) -> dict[str, str]:
        """Physical name of every TS7-004 table on the configured engine."""

        return link_layer_table_names(self.database_backend)

    def migration_control_table_names(self) -> dict[str, str]:
        """Physical name of every TS7-015 control table on this engine."""

        return migration_control_table_names(self.database_backend)

    # -- C0 inventory, manifest and recovery point (TS7-015) ----------------
    #
    # C0 is the recovery point every later phase is measured against. It reads
    # the legacy source only: it never writes into it, never touches ``ts_next``
    # and produces a signed manifest plus a copy whose restore is proven by
    # recomputing the same inventory over the restored rows.

    def _migration(self, logical: str) -> str:
        return migration_control_table_names(self.database_backend)[logical]

    def _insert_migration_row(self, sql: str, parameters: tuple) -> int:
        # The control tables are unqualified on both engines but unknown to the
        # PostgreSQL compatibility layer's id table, so the writer spells the
        # returning clause out instead of relying on ``lastrowid``.
        row = self.connection.execute(
            f"{sql.rstrip().rstrip(';')} RETURNING id", parameters
        ).fetchone()
        return int(row["id"])

    def _c0_table_inventory(self, table: str) -> dict[str, Any]:
        rows = [
            dict(row)
            for row in self.connection.execute(
                f"SELECT * FROM {table} ORDER BY id"
            ).fetchall()
        ]
        return {
            "row_count": len(rows),
            "maximum_primary_key": max((int(row["id"]) for row in rows), default=0),
            "content_hash": rows_digest(rows),
        }

    def _c0_inventory(self) -> dict[str, Any]:
        return {
            table: self._c0_table_inventory(table) for table in C0_INVENTORY_TABLES
        }

    def _c0_duplicate_findings(self) -> list[dict[str, Any]]:
        findings = [
            structural_finding(
                "duplicate_series_key",
                kind="duplicates",
                row_count=int(row["row_count"]),
                evidence={
                    "table": "time_series_signals",
                    "time_series_set_id": int(row["time_series_set_id"]),
                    "series_key": str(row["signal_key"]),
                    "signal_ids": [
                        int(value) for value in str(row["signal_ids"]).split(",")
                    ],
                },
                finding_key=(
                    f"duplicate_series_key:set={int(row['time_series_set_id'])}"
                    f":series_key={row['signal_key']}"
                ),
            )
            for row in self.connection.execute(
                """
                SELECT time_series_set_id,
                       signal_key,
                       COUNT(*) AS row_count,
                       GROUP_CONCAT(CAST(id AS TEXT), ',') AS signal_ids
                FROM time_series_signals
                GROUP BY time_series_set_id, signal_key
                HAVING COUNT(*) > 1
                ORDER BY time_series_set_id, signal_key
                """
                if self.database_backend != "postgresql"
                else """
                SELECT time_series_set_id,
                       signal_key,
                       COUNT(*) AS row_count,
                       STRING_AGG(CAST(id AS TEXT), ',' ORDER BY id) AS signal_ids
                FROM time_series_signals
                GROUP BY time_series_set_id, signal_key
                HAVING COUNT(*) > 1
                ORDER BY time_series_set_id, signal_key
                """
            ).fetchall()
        ]
        # ``entity_id`` is nullable and NULL never equals NULL in a unique key,
        # so the legacy constraint lets the same binding target land twice.
        findings.extend(
            structural_finding(
                "duplicate_binding_target",
                kind="duplicates",
                row_count=int(row["row_count"]),
                evidence={
                    "table": "case_time_series_bindings",
                    "case_input_variant_id": int(row["case_input_variant_id"]),
                    "signal_key": str(row["signal_key"]),
                    "entity_type": row["entity_type"],
                    "entity_id": row["entity_id"],
                },
                finding_key=(
                    "duplicate_binding_target"
                    f":variant={int(row['case_input_variant_id'])}"
                    f":signal_key={row['signal_key']}"
                    f":entity={row['entity_type'] or ''}/{row['entity_id'] or ''}"
                ),
            )
            for row in self.connection.execute(
                """
                SELECT case_input_variant_id,
                       signal_key,
                       entity_type,
                       entity_id,
                       COUNT(*) AS row_count
                FROM case_time_series_bindings
                GROUP BY case_input_variant_id, signal_key,
                         COALESCE(entity_type, ''), COALESCE(entity_id, ''),
                         entity_type, entity_id
                HAVING COUNT(*) > 1
                ORDER BY case_input_variant_id, signal_key
                """
            ).fetchall()
        )
        return findings

    def _c0_broken_reference_findings(self) -> list[dict[str, Any]]:
        findings: list[dict[str, Any]] = []
        # A binding names its series by text. Chapter 10.7 requires
        # ``signal_key + time_series_set_id`` to resolve exactly one identity;
        # zero is a break C0 can prove without the object register.
        for row in self.connection.execute(
            """
            SELECT binding.id AS binding_id,
                   binding.signal_key AS signal_key,
                   binding.time_series_set_id AS time_series_set_id
            FROM case_time_series_bindings AS binding
            WHERE NOT EXISTS (
                SELECT 1 FROM time_series_signals AS signal
                WHERE signal.time_series_set_id = binding.time_series_set_id
                  AND signal.signal_key = binding.signal_key
            )
            ORDER BY binding.id
            """
        ).fetchall():
            findings.append(
                structural_finding(
                    "binding_signal_unresolved",
                    kind="broken_references",
                    row_count=1,
                    evidence={
                        "table": "case_time_series_bindings",
                        "binding_id": int(row["binding_id"]),
                        "signal_key": str(row["signal_key"]),
                        "time_series_set_id": int(row["time_series_set_id"]),
                    },
                    finding_key=f"binding_signal_unresolved:binding={int(row['binding_id'])}",
                )
            )
        for row in self.connection.execute(
            """
            SELECT binding.id AS binding_id,
                   scenario.project_id AS variant_project_id,
                   sets.project_id AS set_project_id
            FROM case_time_series_bindings AS binding
            JOIN case_input_variants AS variant
              ON variant.id = binding.case_input_variant_id
            JOIN optimization_cases AS optimization_case
              ON optimization_case.id = variant.case_id
            JOIN scenarios AS scenario
              ON scenario.id = optimization_case.scenario_id
            JOIN time_series_sets AS sets
              ON sets.id = binding.time_series_set_id
            WHERE scenario.project_id <> sets.project_id
            ORDER BY binding.id
            """
        ).fetchall():
            findings.append(
                structural_finding(
                    "binding_project_mismatch",
                    kind="broken_references",
                    row_count=1,
                    evidence={
                        "table": "case_time_series_bindings",
                        "binding_id": int(row["binding_id"]),
                        "variant_project_id": int(row["variant_project_id"]),
                        "set_project_id": int(row["set_project_id"]),
                    },
                    finding_key=f"binding_project_mismatch:binding={int(row['binding_id'])}",
                )
            )
        for row in self.connection.execute(
            """
            SELECT value.time_series_set_id AS time_series_set_id,
                   COUNT(*) AS row_count
            FROM time_series_values AS value
            JOIN time_series_signals AS signal
              ON signal.id = value.time_series_signal_id
            JOIN time_series_periods AS period
              ON period.id = value.time_series_period_id
            WHERE signal.time_series_set_id <> value.time_series_set_id
               OR period.time_series_set_id <> value.time_series_set_id
            GROUP BY value.time_series_set_id
            ORDER BY value.time_series_set_id
            """
        ).fetchall():
            findings.append(
                structural_finding(
                    "value_set_mismatch",
                    kind="broken_references",
                    row_count=int(row["row_count"]),
                    evidence={
                        "table": "time_series_values",
                        "time_series_set_id": int(row["time_series_set_id"]),
                    },
                    finding_key=f"value_set_mismatch:set={int(row['time_series_set_id'])}",
                )
            )
        for row in self.connection.execute(
            """
            SELECT revision.id AS revision_id,
                   revision.time_series_set_id AS time_series_set_id,
                   revision.superseded_revision_number AS superseded_revision_number
            FROM time_series_set_revisions AS revision
            WHERE revision.superseded_revision_number IS NOT NULL
              AND NOT EXISTS (
                SELECT 1 FROM time_series_set_revisions AS previous
                WHERE previous.time_series_set_id = revision.time_series_set_id
                  AND previous.revision_number = revision.superseded_revision_number
              )
            ORDER BY revision.id
            """
        ).fetchall():
            findings.append(
                structural_finding(
                    "revision_chain_broken",
                    kind="broken_references",
                    row_count=1,
                    evidence={
                        "table": "time_series_set_revisions",
                        "revision_id": int(row["revision_id"]),
                        "time_series_set_id": int(row["time_series_set_id"]),
                        "superseded_revision_number": int(
                            row["superseded_revision_number"]
                        ),
                    },
                    finding_key=f"revision_chain_broken:revision={int(row['revision_id'])}",
                )
            )
        return findings

    def _c0_structural_differences(
        self, explanations: Mapping[str, str] | None
    ) -> tuple[dict[str, Any], list[dict[str, Any]]]:
        given = {str(key): str(value) for key, value in (explanations or {}).items()}
        findings = self._c0_broken_reference_findings() + self._c0_duplicate_findings()
        for finding in findings:
            explanation = given.get(finding["finding_key"], "").strip()
            finding["explained"] = bool(explanation)
            finding["explanation"] = explanation
        by_kind = {"broken_references": [], "duplicates": []}
        for finding in findings:
            by_kind[finding["kind"]].append(finding)
        document = {
            "broken_references": sorted(
                by_kind["broken_references"], key=lambda entry: entry["finding_key"]
            ),
            "duplicates": sorted(
                by_kind["duplicates"], key=lambda entry: entry["finding_key"]
            ),
            "difference_count": len(findings),
            # Only explanations that answered a real finding travel in the
            # manifest; an explanation for a difference that is not there would
            # make two identical sources produce two manifests.
            "explained": {
                finding["finding_key"]: finding["explanation"]
                for finding in sorted(findings, key=lambda entry: entry["finding_key"])
                if finding["explained"]
            },
        }
        return document, findings

    def _c0_executable_variants(self, findings) -> dict[str, Any]:
        """Which variants a canonical run could reproduce, and their fingerprint.

        A variant is executable when it carries at least one binding and no
        structural finding touches any of them: chapter 10.7 forbids falling
        back to the legacy reader for a binding the migration cannot resolve, so
        a variant with one broken binding is not executable at all. The
        fingerprint covers the content each binding would feed the optimizer,
        which is what C5 compares to prove materialization parity.
        """

        blocked_by_binding: dict[int, list[str]] = defaultdict(list)
        for finding in findings:
            binding_id = finding["evidence"].get("binding_id")
            if binding_id is not None:
                blocked_by_binding[int(binding_id)].append(finding["finding_key"])

        bindings_by_variant: dict[int, list[dict[str, Any]]] = defaultdict(list)
        for row in self.connection.execute(
            """
            SELECT binding.id AS binding_id,
                   binding.case_input_variant_id AS case_input_variant_id,
                   binding.signal_key AS signal_key,
                   binding.entity_type AS entity_type,
                   binding.entity_id AS entity_id,
                   binding.time_series_set_id AS time_series_set_id,
                   binding.required AS required,
                   sets.content_hash AS content_hash
            FROM case_time_series_bindings AS binding
            LEFT JOIN time_series_sets AS sets
              ON sets.id = binding.time_series_set_id
            ORDER BY binding.case_input_variant_id, binding.signal_key, binding.id
            """
        ).fetchall():
            bindings_by_variant[int(row["case_input_variant_id"])].append(dict(row))

        variants = []
        for row in self.connection.execute(
            """
            SELECT variant.id AS case_input_variant_id,
                   variant.variant_key AS variant_key,
                   variant.case_id AS case_id,
                   scenario.project_id AS project_id
            FROM case_input_variants AS variant
            JOIN optimization_cases AS optimization_case
              ON optimization_case.id = variant.case_id
            JOIN scenarios AS scenario
              ON scenario.id = optimization_case.scenario_id
            ORDER BY variant.id
            """
        ).fetchall():
            variant_id = int(row["case_input_variant_id"])
            bindings = bindings_by_variant.get(variant_id, [])
            blocked: list[str] = []
            if not bindings:
                blocked.append("no_bindings")
            for binding in bindings:
                blocked.extend(blocked_by_binding.get(int(binding["binding_id"]), []))
                if not str(binding["content_hash"] or "").strip():
                    blocked.append(
                        f"binding_content_missing:binding={int(binding['binding_id'])}"
                    )
            projection = {
                "case_input_variant_id": variant_id,
                "variant_key": str(row["variant_key"]),
                "case_id": int(row["case_id"]),
                "project_id": int(row["project_id"]),
                "binding_count": len(bindings),
                "executable": not blocked,
                "blocked_by": sorted(set(blocked)),
                "fingerprint": canonical_digest(
                    [
                        {
                            "signal_key": str(binding["signal_key"]),
                            "entity_type": binding["entity_type"],
                            "entity_id": binding["entity_id"],
                            "time_series_set_id": int(binding["time_series_set_id"]),
                            "content_hash": str(binding["content_hash"] or ""),
                            "required": int(binding["required"]),
                        }
                        for binding in bindings
                    ]
                ),
            }
            variants.append(projection)

        executable = [variant for variant in variants if variant["executable"]]
        return {
            "count": len(executable),
            "fingerprint": canonical_digest(
                [
                    {
                        "case_input_variant_id": variant["case_input_variant_id"],
                        "fingerprint": variant["fingerprint"],
                    }
                    for variant in executable
                ]
            ),
            "variants": variants,
        }

    def _record_migration_anomalies(
        self, *, migration_run_id: int, phase: str, findings, now: str
    ) -> None:
        actor = migration_actor(migration_run_id)
        for finding in findings:
            self.connection.execute(
                f"""
                INSERT INTO {self._migration('time_series_migration_anomalies')} (
                    migration_run_id, phase, code, severity, finding_key,
                    evidence_json, resolution, resolution_note, resolved_at,
                    resolved_by, created_at, actor
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    migration_run_id,
                    phase,
                    finding["code"],
                    finding["severity"],
                    finding["finding_key"],
                    json.dumps(finding["evidence"], sort_keys=True),
                    "explained" if finding["explained"] else "open",
                    finding["explanation"],
                    now if finding["explained"] else None,
                    actor if finding["explained"] else None,
                    now,
                    actor,
                ),
            )

    def record_migration_mapping(
        self,
        *,
        migration_run_id: int,
        source_kind: str,
        source_table: str,
        source_id: str,
        target_kind: str,
        target_id: str,
        source_hash: str = "",
    ) -> dict[str, Any]:
        """Record one legacy-to-canonical correspondence, idempotently.

        The unique key is ``source_kind + source_table + source_id +
        target_kind`` (chapter 10.3). Repeating the same correspondence
        converges; a different target or a different observed source hash is a
        conflict a human resolves, never a second row.
        """

        with self._lock:
            table = self._migration("time_series_migration_mappings")
            key = (
                str(source_kind),
                str(source_table),
                str(source_id),
                str(target_kind),
            )
            existing = self.connection.execute(
                f"""
                SELECT * FROM {table}
                WHERE source_kind = ? AND source_table = ?
                  AND source_id = ? AND target_kind = ?
                """,
                key,
            ).fetchone()
            if existing is not None:
                if str(existing["target_id"]) != str(target_id):
                    raise MigrationControlError(
                        MAPPING_CONFLICT,
                        reason="target_changed",
                        source_kind=key[0],
                        source_table=key[1],
                        source_id=key[2],
                        target_kind=key[3],
                        existing_target_id=str(existing["target_id"]),
                        incoming_target_id=str(target_id),
                    )
                if str(existing["source_hash"]) != str(source_hash):
                    raise MigrationControlError(
                        MAPPING_CONFLICT,
                        reason="source_hash_changed",
                        source_kind=key[0],
                        source_table=key[1],
                        source_id=key[2],
                        target_kind=key[3],
                        existing_target_id=str(existing["target_id"]),
                        incoming_target_id=str(target_id),
                        existing_source_hash=str(existing["source_hash"]),
                        incoming_source_hash=str(source_hash),
                    )
                return {
                    "status": "unchanged",
                    "migration_mapping_id": int(existing["id"]),
                }
            mapping_id = self._insert_migration_row(
                f"""
                INSERT INTO {table} (
                    migration_run_id, source_kind, source_table, source_id,
                    target_kind, target_id, source_hash, created_at, actor
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    int(migration_run_id),
                    *key,
                    str(target_id),
                    str(source_hash),
                    utc_now_iso(),
                    migration_actor(migration_run_id),
                ),
            )
            self.connection.commit()
            return {"status": "created", "migration_mapping_id": mapping_id}

    def enqueue_legacy_dirty_root(
        self, *, migration_run_id: int, root_kind: str, root_id: str
    ) -> dict[str, Any]:
        """Append one root touched after the watermark (chapter 10.3).

        The queue is monotone, not a set: a root dirtied again after a drain
        takes a new sequence number, because the backfill has to revisit it.
        """

        with self._lock:
            table = self._migration("time_series_legacy_dirty_roots")
            now = utc_now_iso()
            actor = migration_actor(migration_run_id)
            next_sequence = (
                int(
                    self.connection.execute(
                        f"SELECT COALESCE(MAX(sequence_number), 0) AS high FROM {table}"
                    ).fetchone()["high"]
                )
                + 1
            )
            entry_id = self._insert_migration_row(
                f"""
                INSERT INTO {table} (
                    sequence_number, root_kind, root_id, watermark, created_at, actor
                )
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (next_sequence, str(root_kind), str(root_id), now, now, actor),
            )
            self.connection.commit()
            return {
                "id": entry_id,
                "sequence_number": next_sequence,
                "root_kind": str(root_kind),
                "root_id": str(root_id),
                "actor": actor,
            }

    def read_pending_dirty_roots(self) -> list[dict[str, Any]]:
        table = self._migration("time_series_legacy_dirty_roots")
        return [
            dict(row)
            for row in self.connection.execute(
                f"""
                SELECT * FROM {table}
                WHERE drained_at IS NULL
                ORDER BY sequence_number
                """
            ).fetchall()
        ]

    def drain_legacy_dirty_roots(self, *, through_sequence: int) -> dict[str, Any]:
        with self._lock:
            table = self._migration("time_series_legacy_dirty_roots")
            cursor = self.connection.execute(
                f"""
                UPDATE {table}
                SET drained_at = ?
                WHERE drained_at IS NULL AND sequence_number <= ?
                """,
                (utc_now_iso(), int(through_sequence)),
            )
            self.connection.commit()
            return {
                "drained_count": int(cursor.rowcount),
                "pending_count": len(self.read_pending_dirty_roots()),
            }

    def begin_legacy_mutation_pause(
        self, *, actor: str, reason: str
    ) -> dict[str, Any]:
        """Hold legacy time-series writes so a phase can read a settled source.

        Chapter 10.2 gives C5 a *short* pause, not a maintenance window: it is
        taken around the drain and the comparison and released with the phase,
        so a crash cannot leave the legacy writer disabled.
        """

        resolved_reason = str(reason).strip()
        if not resolved_reason:
            raise ValueError("reason must not be blank")
        with self._lock:
            if self._legacy_mutation_pause is not None:
                raise MigrationControlError(
                    MUTATION_PAUSED,
                    reason="already_paused",
                    paused_by=str(self._legacy_mutation_pause["actor"]),
                )
            self._legacy_mutation_pause = {
                "actor": str(actor),
                "reason": resolved_reason,
                "paused_at": utc_now_iso(),
            }
            return dict(self._legacy_mutation_pause)

    def release_legacy_mutation_pause(self, *, actor: str) -> dict[str, Any]:
        with self._lock:
            pause = self._legacy_mutation_pause
            if pause is None:
                return {"released": False, "reason": "not_paused"}
            self._legacy_mutation_pause = None
            return {
                "released": True,
                "actor": str(actor),
                "paused_by": str(pause["actor"]),
                "paused_at": str(pause["paused_at"]),
            }

    def read_legacy_mutation_pause(self) -> dict[str, Any] | None:
        pause = self._legacy_mutation_pause
        return None if pause is None else dict(pause)

    def _require_no_legacy_mutation_pause(self, operation: str) -> None:
        pause = self._legacy_mutation_pause
        if pause is None:
            return
        raise MigrationControlError(
            MUTATION_PAUSED,
            operation=str(operation),
            paused_by=str(pause["actor"]),
            paused_at=str(pause["paused_at"]),
            pause_reason=str(pause["reason"]),
        )

    def open_migration_phase(self, *, phase: str, actor: str) -> dict[str, Any]:
        """Start a phase after C0, refusing without a live recovery point.

        AC-MIG-01 wants the manifest and the proven restore to exist *before*
        the migration touches anything. The enforceable form of that rule is
        this gate: no later phase opens unless a proven C0 exists and its
        inventory still describes the source it would be rolled back to.
        """

        with self._lock:
            runs = self._migration("time_series_migration_runs")
            proven = self.connection.execute(
                f"""
                SELECT * FROM {runs}
                WHERE phase = 'C0' AND status = 'proven'
                ORDER BY id DESC
                """
            ).fetchone()
            if proven is None:
                raise MigrationControlError(
                    RECOVERY_POINT_REQUIRED, reason="no_proven_c0", phase=str(phase)
                )
            recovered = json.loads(proven["manifest_json"] or "{}")
            if recovered.get("inventory") != self._c0_inventory():
                raise MigrationControlError(
                    RECOVERY_POINT_REQUIRED,
                    reason="source_moved_since_recovery_point",
                    phase=str(phase),
                    recovery_point_run_id=int(proven["id"]),
                )
            now = utc_now_iso()
            run_id = self._insert_migration_row(
                f"""
                INSERT INTO {runs} (
                    control_version, phase, status, source_engine, watermark,
                    checkpoint_json, started_at, started_by, actor
                )
                VALUES (?, ?, 'running', ?, ?, ?, ?, ?, ?)
                """,
                (
                    MIGRATION_CONTROL_VERSION,
                    str(phase),
                    self.database_backend,
                    now,
                    json.dumps(
                        {"recovery_point_run_id": int(proven["id"])}, sort_keys=True
                    ),
                    now,
                    actor,
                    migration_actor(0),
                ),
            )
            self.connection.execute(
                f"UPDATE {runs} SET actor = ? WHERE id = ?",
                (migration_actor(run_id), run_id),
            )
            self.connection.commit()
            return {
                "migration_run_id": run_id,
                "phase": str(phase),
                "status": "running",
                "actor": migration_actor(run_id),
                "recovery_point_run_id": int(proven["id"]),
                "recovery_point_digest": str(proven["manifest_digest"]),
            }

    def read_migration_run(self, migration_run_id: int) -> dict[str, Any]:
        row = self.connection.execute(
            f"SELECT * FROM {self._migration('time_series_migration_runs')} WHERE id = ?",
            (int(migration_run_id),),
        ).fetchone()
        if row is None:
            raise KeyError(f"migration run {migration_run_id} not found")
        run = dict(row)
        run["manifest"] = json.loads(run.pop("manifest_json") or "{}")
        run["checkpoint"] = json.loads(run.pop("checkpoint_json") or "{}")
        return run

    def read_migration_anomalies(self, migration_run_id: int) -> list[dict[str, Any]]:
        anomalies = []
        for row in self.connection.execute(
            f"""
            SELECT * FROM {self._migration('time_series_migration_anomalies')}
            WHERE migration_run_id = ?
            ORDER BY finding_key, id
            """,
            (int(migration_run_id),),
        ).fetchall():
            anomaly = dict(row)
            anomaly["evidence"] = json.loads(anomaly.pop("evidence_json") or "{}")
            anomalies.append(anomaly)
        return anomalies

    def _migration_table_evidence(self, table_names) -> dict[str, dict[str, Any]]:
        """Stable count and row hash for a group of migration outputs."""

        evidence: dict[str, dict[str, Any]] = {}
        for table_name in table_names:
            rows = [
                dict(row)
                for row in self.connection.execute(
                    f"SELECT * FROM {table_name}"
                ).fetchall()
            ]
            rows.sort(
                key=lambda row: json.dumps(
                    normalize_source_row(row),
                    sort_keys=True,
                    separators=(",", ":"),
                )
            )
            evidence[table_name] = {
                "row_count": len(rows),
                "rows_hash": rows_digest(rows),
            }
        return evidence

    def _finish_migration_run(
        self,
        *,
        migration_run_id: int,
        status: str,
        manifest: Mapping[str, Any],
        checkpoint: Mapping[str, Any] | None = None,
    ) -> None:
        runs = self._migration("time_series_migration_runs")
        manifest_document = dict(manifest)
        self.connection.execute(
            f"""
            UPDATE {runs}
            SET status = ?, manifest_json = ?, manifest_digest = ?,
                checkpoint_json = ?, finished_at = ?
            WHERE id = ?
            """,
            (
                status,
                json.dumps(manifest_document, sort_keys=True),
                canonical_digest(manifest_document),
                json.dumps(dict(checkpoint or {}), sort_keys=True),
                utc_now_iso(),
                int(migration_run_id),
            ),
        )
        self.connection.commit()

    def backfill_time_series_c2(self, *, actor: str) -> dict[str, Any]:
        """Converge classifications and the deterministic object register.

        C2 is deliberately a domain operation rather than an HTTP endpoint:
        it is an operator-controlled migration phase, gated by a still-valid
        C0 recovery point.  Its manifest contains only resulting state, never
        run-local timestamps or ids, so repeating an unchanged source proves
        convergence byte for byte.
        """

        opened = self.open_migration_phase(phase="C2", actor=actor)
        run_id = int(opened["migration_run_id"])
        technical_actor = migration_actor(run_id)
        classification_tables = tuple(
            table_name for table_name, _key, _rows, _fields in CLASSIFICATION_SEED_TABLES
        )
        object_tables = tuple(self.linkable_object_table_names().values())
        output_tables = classification_tables + object_tables
        before = self._migration_table_evidence(output_tables)

        try:
            with self._lock:
                with self._database_transaction():
                    self._seed_time_series_classification_catalog()
                    materialized = []
                    for project in self.connection.execute(
                        "SELECT id FROM projects ORDER BY id"
                    ).fetchall():
                        materialized.append(
                            self._materialize_project_linkable_objects(
                                project_id=int(project["id"]), actor=technical_actor
                            )
                        )
        except LinkableObjectError as error:
            if error.code != "TS_MIGRATION_OBJECT_AMBIGUOUS":
                raise
            evidence = {
                **dict(error.context),
                "project_id": int(error.context.get("project_id") or project["id"]),
            }
            finding = {
                "code": error.code,
                "severity": "blocking",
                "finding_key": (
                    f"object:{evidence['project_id']}:"
                    f"{evidence.get('component_key', 'unknown')}"
                ),
                "evidence": evidence,
                "explained": False,
                "explanation": "",
            }
            now = utc_now_iso()
            self._record_migration_anomalies(
                migration_run_id=run_id, phase="C2", findings=[finding], now=now
            )
            stopped_manifest = {
                "manifest_version": 1,
                "phase": "C2",
                "source_engine": self.database_backend,
                "classification_contract_version": CLASSIFICATION_CONTRACT_VERSION,
                "outputs": self._migration_table_evidence(output_tables),
                "anomalies": [
                    {
                        "code": finding["code"],
                        "finding_key": finding["finding_key"],
                        "evidence": finding["evidence"],
                    }
                ],
            }
            self._finish_migration_run(
                migration_run_id=run_id,
                status="stopped",
                manifest=stopped_manifest,
            )
            raise MigrationPhaseStopped(
                C2_STOPPED, migration_run_id=run_id, findings=[finding]
            ) from error

        mapping_changes = 0
        for project_result in materialized:
            for registered in project_result["objects"]:
                mapping = self.record_migration_mapping(
                    migration_run_id=run_id,
                    source_kind="legacy_object",
                    source_table=str(registered["object_kind"]),
                    source_id=str(registered["subtype_id"]),
                    target_kind="linkable_object",
                    target_id=str(registered["id"]),
                    source_hash=canonical_digest(
                        {
                            "project_id": int(registered["project_id"]),
                            "object_kind": str(registered["object_kind"]),
                            "subtype_id": int(registered["subtype_id"]),
                        }
                    ),
                )
                mapping_changes += mapping["status"] == "created"

        after = self._migration_table_evidence(output_tables)
        created_rows = sum(
            after[table]["row_count"] - before[table]["row_count"]
            for table in output_tables
        )
        manifest = {
            "manifest_version": 1,
            "phase": "C2",
            "source_engine": self.database_backend,
            "classification_contract_version": CLASSIFICATION_CONTRACT_VERSION,
            "outputs": after,
        }
        self._finish_migration_run(
            migration_run_id=run_id,
            status="proven",
            manifest=manifest,
            checkpoint={"projects_completed": len(materialized)},
        )
        return {
            **opened,
            "status": "proven",
            "created_rows": created_rows,
            "mapping_changes": int(mapping_changes),
            "manifest": manifest,
            "manifest_digest": canonical_digest(manifest),
        }

    def _require_proven_migration_phase(self, phase: str) -> dict[str, Any]:
        row = self.connection.execute(
            f"""
            SELECT * FROM {self._migration('time_series_migration_runs')}
            WHERE phase = ? AND status = 'proven'
            ORDER BY id DESC
            """,
            (str(phase),),
        ).fetchone()
        if row is None:
            raise MigrationControlError(
                MIGRATION_PHASE_REQUIRED, required_phase=str(phase)
            )
        return dict(row)

    def _legacy_time_series_set_snapshot(self, set_id: int) -> dict[str, Any]:
        set_row = self.connection.execute(
            "SELECT * FROM time_series_sets WHERE id = ?", (int(set_id),)
        ).fetchone()
        if set_row is None:
            raise KeyError(f"legacy time-series set {set_id} not found")
        revisions = [
            dict(row)
            for row in self.connection.execute(
                """
                SELECT * FROM time_series_set_revisions
                WHERE time_series_set_id = ?
                ORDER BY revision_number, id
                """,
                (int(set_id),),
            ).fetchall()
        ]
        signals = [
            dict(row)
            for row in self.connection.execute(
                """
                SELECT * FROM time_series_signals
                WHERE time_series_set_id = ? ORDER BY id
                """,
                (int(set_id),),
            ).fetchall()
        ]
        periods = [
            dict(row)
            for row in self.connection.execute(
                """
                SELECT * FROM time_series_periods
                WHERE time_series_set_id = ? ORDER BY period_index, id
                """,
                (int(set_id),),
            ).fetchall()
        ]
        values = [
            dict(row)
            for row in self.connection.execute(
                """
                SELECT value.*, period.period_index AS period_index,
                       signal.signal_key AS signal_key
                FROM time_series_values AS value
                JOIN time_series_periods AS period
                  ON period.id = value.time_series_period_id
                JOIN time_series_signals AS signal
                  ON signal.id = value.time_series_signal_id
                WHERE value.time_series_set_id = ?
                ORDER BY period.period_index, signal.signal_key, value.id
                """,
                (int(set_id),),
            ).fetchall()
        ]
        source_ids = sorted(
            {
                int(row["time_series_source_id"])
                for row in revisions
                if row["time_series_source_id"] is not None
            }
        )
        sources = [
            dict(row)
            for source_id in source_ids
            for row in [
                self.connection.execute(
                    "SELECT * FROM time_series_sources WHERE id = ?", (source_id,)
                ).fetchone()
            ]
            if row is not None
        ]
        return {
            "set": dict(set_row),
            "revisions": revisions,
            "signals": signals,
            "periods": periods,
            "values": values,
            "sources": sources,
        }

    def _legacy_snapshot_content_hash(self, snapshot: Mapping[str, Any]) -> str:
        legacy_set = snapshot["set"]
        return compute_catalog_content_hash(
            set_name=str(legacy_set["name"]),
            version_label=str(legacy_set["version_label"]),
            data_kind=str(legacy_set["data_kind"]),
            timezone=str(legacy_set["timezone"]),
            signals=[
                {
                    "signal_key": row["signal_key"],
                    "unit": row["unit"],
                    "source_column": row.get("source_column") or "",
                    "source_unit": row.get("source_unit") or "",
                    "entity_type": row["entity_type"],
                    "entity_key": row["entity_key"],
                }
                for row in snapshot["signals"]
            ],
            periods=[
                {
                    "period_index": int(row["period_index"]),
                    "timestamp_start": row["timestamp_start"],
                    "timestamp_end": row["timestamp_end"],
                    "duration_hours": float(row["duration_hours"]),
                }
                for row in snapshot["periods"]
            ],
            values=[
                {
                    "period_index": int(row["period_index"]),
                    "signal_key": row["signal_key"],
                    "value_numeric": float(row["value_numeric"]),
                    "source_row_number": row["source_row_number"],
                    "entity_key": next(
                        (
                            signal["entity_key"]
                            for signal in snapshot["signals"]
                            if int(signal["id"])
                            == int(row["time_series_signal_id"])
                        ),
                        None,
                    ),
                }
                for row in snapshot["values"]
            ],
        )

    def _legacy_canonical_signals(
        self, snapshot: Mapping[str, Any]
    ) -> list[dict[str, Any]]:
        result = []
        legacy_data_class = str(snapshot["set"]["data_kind"])
        for row in snapshot["signals"]:
            signal_key = str(row["signal_key"])
            semantic_type_key = SIGNAL_SEMANTIC_TYPE_KEYS.get(signal_key)
            unit = self.connection.execute(
                """
                SELECT unit_key FROM measurement_units
                WHERE symbol = ? AND status = 'active'
                """,
                (str(row["unit"]),),
            ).fetchone()
            data_class = self.connection.execute(
                """
                SELECT data_class_key FROM time_series_data_classes
                WHERE data_class_key = ? AND status = 'active'
                """,
                (legacy_data_class,),
            ).fetchone()
            source_id = json.dumps(
                [signal_key, str(row["unit"]), legacy_data_class],
                ensure_ascii=False,
                separators=(",", ":"),
            )
            mapped = self.connection.execute(
                f"""
                SELECT target_id
                FROM {self._migration('time_series_migration_mappings')}
                WHERE source_kind = 'administrative_classification'
                  AND source_table = 'legacy_signal_contract'
                  AND source_id = ?
                  AND target_kind = 'canonical_classification'
                """,
                (source_id,),
            ).fetchone()
            if mapped is not None:
                decision = json.loads(str(mapped["target_id"]))
                semantic_type_key = str(decision["semantic_type_key"])
                unit = {"unit_key": str(decision["unit_key"])}
                data_class = {"data_class_key": str(decision["data_class_key"])}
            if semantic_type_key is None or data_class is None:
                raise MigrationControlError(
                    "TS_MIGRATION_UNKNOWN_SEMANTIC_TYPE",
                    set_id=int(snapshot["set"]["id"]),
                    signal_id=int(row["id"]),
                    signal_key=signal_key,
                    unit=str(row["unit"]),
                    data_class=legacy_data_class,
                )
            if unit is None:
                raise MigrationControlError(
                    "TS_MIGRATION_UNKNOWN_UNIT",
                    set_id=int(snapshot["set"]["id"]),
                    signal_id=int(row["id"]),
                    signal_key=signal_key,
                    unit=str(row["unit"]),
                    data_class=legacy_data_class,
                )
            result.append(
                {
                    "ordinal": len(result),
                    "series_key": signal_key,
                    "display_name": signal_key,
                    "description": "",
                    "semantic_type_key": semantic_type_key,
                    "unit_key": str(unit["unit_key"]),
                    "data_class_key": str(data_class["data_class_key"]),
                    "signal_role": str(row["signal_role"]),
                    "aggregation": str(row["aggregation"]),
                    "metadata": {
                        "legacy_entity_type": row["entity_type"],
                        "legacy_entity_key": row["entity_key"],
                        "legacy_source_column": row.get("source_column") or "",
                        "legacy_source_unit": row.get("source_unit") or "",
                    },
                }
            )
        return result

    def resolve_time_series_migration_classification(
        self,
        *,
        anomaly_id: int,
        semantic_type_key: str,
        unit_key: str,
        data_class_key: str,
        actor: str,
        reason: str,
    ) -> dict[str, Any]:
        """Record the explicit administrative decision required by AC-MIG-07."""

        clean_actor = str(actor).strip()
        clean_reason = str(reason).strip()
        if not clean_actor or not clean_reason:
            raise MigrationControlError(
                "TS_MIGRATION_CLASSIFICATION_DECISION_INVALID",
                reason="actor_and_reason_required",
            )
        table = self._migration("time_series_migration_anomalies")
        anomaly = self.connection.execute(
            f"SELECT * FROM {table} WHERE id = ?", (int(anomaly_id),)
        ).fetchone()
        if anomaly is None or anomaly["code"] not in {
            "TS_MIGRATION_UNKNOWN_SEMANTIC_TYPE",
            "TS_MIGRATION_UNKNOWN_UNIT",
        }:
            raise MigrationControlError(
                "TS_MIGRATION_CLASSIFICATION_DECISION_INVALID",
                anomaly_id=int(anomaly_id),
                reason="classification_anomaly_required",
            )
        evidence = json.loads(anomaly["evidence_json"] or "{}")
        semantic = self.connection.execute(
            """
            SELECT id, canonical_unit_id FROM time_series_semantic_types
            WHERE semantic_key = ? AND status = 'active'
            """,
            (str(semantic_type_key),),
        ).fetchone()
        unit = self.connection.execute(
            """
            SELECT id FROM measurement_units
            WHERE unit_key = ? AND status = 'active'
            """,
            (str(unit_key),),
        ).fetchone()
        data_class = self.connection.execute(
            """
            SELECT id FROM time_series_data_classes
            WHERE data_class_key = ? AND status = 'active'
            """,
            (str(data_class_key),),
        ).fetchone()
        if (
            semantic is None
            or unit is None
            or data_class is None
            or int(semantic["canonical_unit_id"]) != int(unit["id"])
        ):
            raise MigrationControlError(
                "TS_MIGRATION_CLASSIFICATION_DECISION_INVALID",
                anomaly_id=int(anomaly_id),
                reason="target_contract_is_not_active_and_canonical",
            )
        source_id = json.dumps(
            [
                str(evidence.get("signal_key") or ""),
                str(evidence.get("unit") or ""),
                str(evidence.get("data_class") or ""),
            ],
            ensure_ascii=False,
            separators=(",", ":"),
        )
        target_id = json.dumps(
            {
                "data_class_key": str(data_class_key),
                "semantic_type_key": str(semantic_type_key),
                "unit_key": str(unit_key),
            },
            sort_keys=True,
            separators=(",", ":"),
        )
        mapping = self.record_migration_mapping(
            migration_run_id=int(anomaly["migration_run_id"]),
            source_kind="administrative_classification",
            source_table="legacy_signal_contract",
            source_id=source_id,
            target_kind="canonical_classification",
            target_id=target_id,
            source_hash=canonical_digest(
                {
                    "signal_key": evidence.get("signal_key"),
                    "unit": evidence.get("unit"),
                    "data_class": evidence.get("data_class"),
                }
            ),
        )
        now = utc_now_iso()
        self.connection.execute(
            f"""
            UPDATE {table}
            SET resolution = 'resolved', resolution_note = ?,
                resolved_at = ?, resolved_by = ?
            WHERE id = ? AND resolution = 'open'
            """,
            (clean_reason, now, clean_actor, int(anomaly_id)),
        )
        self.connection.commit()
        return {
            "status": "recorded" if mapping["status"] == "created" else "unchanged",
            "anomaly_id": int(anomaly_id),
            "mapping_id": int(mapping["migration_mapping_id"]),
            "semantic_type_key": str(semantic_type_key),
            "unit_key": str(unit_key),
            "data_class_key": str(data_class_key),
            "resolved_by": clean_actor,
        }

    def _insert_preserved_canonical_source(
        self, source: Mapping[str, Any], *, technical_actor: str
    ) -> bool:
        table = self._canonical("time_series_sources")
        existing = self.connection.execute(
            f"SELECT * FROM {table} WHERE id = ?", (int(source["id"]),)
        ).fetchone()
        if existing is not None:
            return False
        metadata = json.loads(source.get("metadata_json") or "{}")
        metadata["legacy_source_kind"] = str(source["kind"])
        metadata["migration_actor"] = technical_actor
        self.connection.execute(
            f"""
            INSERT INTO {table} (
                id, project_id, source_key, kind, original_filename, media_type,
                checksum, stored_path, selected_sheet, metadata_json,
                created_at, created_by
            ) VALUES (?, ?, ?, 'migration', ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                int(source["id"]),
                int(source["project_id"]),
                str(source["source_key"]),
                str(source["original_filename"]),
                str(source["media_type"]),
                str(source["checksum"]),
                str(source["stored_path"]),
                source["selected_sheet"],
                json.dumps(metadata, sort_keys=True),
                str(source["created_at"]),
                str(source["created_by"]),
            ),
        )
        return True

    def _sync_canonical_identity_sequences(self, logical_tables=None) -> None:
        """Advance PostgreSQL identities past IDs preserved from legacy rows."""

        if self.database_backend != "postgresql":
            return
        for logical in logical_tables or CANONICAL_IDENTITY_TABLES:
            table = self._canonical(logical)
            self.connection.execute(
                f"""
                SELECT setval(
                    pg_get_serial_sequence('{table}', 'id'),
                    COALESCE((SELECT MAX(id) FROM {table}), 1),
                    EXISTS (SELECT 1 FROM {table})
                )
                """
            )

    def _legacy_object_specific_owner(
        self, snapshot: Mapping[str, Any]
    ) -> int | None:
        """Return the proven owner of a legacy local definition, never a guess."""

        revisions = list(snapshot["revisions"])
        if not revisions:
            return None
        try:
            metadata = json.loads(revisions[-1].get("metadata_json") or "{}")
        except json.JSONDecodeError:
            metadata = {}
        provenance = metadata.get("provenance") if isinstance(metadata, dict) else None
        signals = list(snapshot["signals"])
        if not isinstance(provenance, dict) or provenance.get("kind") != (
            "object_specific_definition"
        ):
            if len(signals) == 1 and str(signals[0].get("entity_key") or "").strip():
                raise MigrationControlError(
                    "TS_MIGRATION_OBJECT_SPECIFIC_REVIEW_REQUIRED",
                    set_id=int(snapshot["set"]["id"]),
                    signal_id=int(signals[0]["id"]),
                    entity_type=signals[0].get("entity_type"),
                    entity_key=signals[0].get("entity_key"),
                    reason="explicit_local_provenance_missing",
                )
            return None

        legacy_set = snapshot["set"]
        evidence = {
            "set_id": int(legacy_set["id"]),
            "provenance": provenance,
        }
        if len(signals) != 1:
            raise MigrationControlError(
                "TS_MIGRATION_OBJECT_SPECIFIC_REVIEW_REQUIRED",
                **evidence,
                reason="local_definition_must_have_one_signal",
            )
        signal = signals[0]
        entity_type = str(signal.get("entity_type") or "").strip()
        entity_key = str(signal.get("entity_key") or "").strip()
        if (
            not entity_type
            or not entity_key
            or str(provenance.get("entity_type") or "") != entity_type
            or str(provenance.get("entity_key") or "") != entity_key
        ):
            raise MigrationControlError(
                "TS_MIGRATION_OBJECT_SPECIFIC_REVIEW_REQUIRED",
                **evidence,
                reason="signal_and_provenance_owner_do_not_match",
            )
        try:
            owner = self.resolve_linkable_object_reference(
                project_id=int(legacy_set["project_id"]),
                entity_type=entity_type,
                entity_id=entity_key,
            )
        except LinkableObjectError as error:
            raise MigrationControlError(
                "TS_MIGRATION_OBJECT_SPECIFIC_REVIEW_REQUIRED",
                **evidence,
                reason="owner_is_not_uniquely_registered",
                object_error=error.code,
            ) from error

        for binding in self.connection.execute(
            """
            SELECT entity_type, entity_id FROM case_time_series_bindings
            WHERE time_series_set_id = ?
            """,
            (int(legacy_set["id"]),),
        ).fetchall():
            try:
                bound_owner = self.resolve_linkable_object_reference(
                    project_id=int(legacy_set["project_id"]),
                    entity_type=str(binding["entity_type"] or ""),
                    entity_id=binding["entity_id"],
                )
            except LinkableObjectError as error:
                raise MigrationControlError(
                    "TS_MIGRATION_OBJECT_SPECIFIC_REVIEW_REQUIRED",
                    **evidence,
                    reason="binding_owner_is_not_uniquely_registered",
                    object_error=error.code,
                ) from error
            if int(bound_owner["id"]) != int(owner["id"]):
                raise MigrationControlError(
                    "TS_MIGRATION_OBJECT_SPECIFIC_REVIEW_REQUIRED",
                    **evidence,
                    reason="binding_points_to_another_object",
                )

        series_key = str(signal["signal_key"])
        if (
            str(legacy_set["name"]) != series_key
            or str(legacy_set["version_label"]) != "object"
            or int(legacy_set["version_number"]) != 1
        ):
            raise MigrationControlError(
                "TS_MIGRATION_OBJECT_SPECIFIC_REVIEW_REQUIRED",
                **evidence,
                reason="legacy_identity_does_not_fit_object_series_contract",
            )
        forbidden_origins = {
            "catalog_import",
            "draft_extraction",
            "transformation",
            "console_copy",
            "hydraulic_legacy_migration",
        }
        if any(
            str(source.get("kind") or "") in forbidden_origins
            for source in snapshot["sources"]
        ):
            raise MigrationControlError(
                "TS_MIGRATION_OBJECT_SPECIFIC_REVIEW_REQUIRED",
                **evidence,
                reason="origin_is_not_exclusively_local",
            )
        return int(owner["id"])

    def _backfill_legacy_set_c3(
        self, *, snapshot: Mapping[str, Any], migration_run_id: int
    ) -> dict[str, Any]:
        legacy_set = snapshot["set"]
        set_id = int(legacy_set["id"])
        sets_table = self._canonical("time_series_sets")
        revisions_table = self._canonical("time_series_set_revisions")
        technical_actor = migration_actor(migration_run_id)
        existing = self.connection.execute(
            f"SELECT * FROM {sets_table} WHERE id = ?", (set_id,)
        ).fetchone()

        revisions = list(snapshot["revisions"])
        if not revisions:
            raise MigrationControlError(
                "TS_MIGRATION_REVISION_UNMATERIALIZED",
                set_id=set_id,
                reason="legacy_set_has_no_revision",
            )
        latest_revision = revisions[-1]
        legacy_hash = self._legacy_snapshot_content_hash(snapshot)
        legacy_revision_hash_matches = (
            str(latest_revision["content_hash"]) != legacy_hash
            or str(legacy_set["content_hash"]) != legacy_hash
        ) is False
        if not legacy_revision_hash_matches:
            active_consumer = self.connection.execute(
                """
                SELECT id FROM case_time_series_bindings
                WHERE time_series_set_id = ? LIMIT 1
                """,
                (set_id,),
            ).fetchone()
            if active_consumer is not None:
                raise MigrationControlError(
                    "TS_MIGRATION_HASH_MISMATCH",
                    set_id=set_id,
                    binding_id=int(active_consumer["id"]),
                    stored_revision_hash=str(latest_revision["content_hash"]),
                    stored_set_hash=str(legacy_set["content_hash"]),
                    observed_hash=legacy_hash,
                )

        canonical_signals = self._legacy_canonical_signals(snapshot)
        series_keys = [row["series_key"] for row in canonical_signals]
        if len(series_keys) != len(set(series_keys)):
            raise MigrationControlError(
                "TS_MIGRATION_DUPLICATE_SERIES_KEY",
                set_id=set_id,
                series_keys=sorted(
                    key for key in set(series_keys) if series_keys.count(key) > 1
                ),
            )
        canonical_data_class_key = str(canonical_signals[0]["data_class_key"])
        try:
            classification = self._canonical_classification(
                canonical_signals, canonical_data_class_key
            )
        except CanonicalRevisionError as error:
            raise MigrationControlError(
                (
                    "TS_MIGRATION_UNKNOWN_UNIT"
                    if error.context.get("reason") == "unit_is_not_canonical"
                    else "TS_MIGRATION_UNKNOWN_SEMANTIC_TYPE"
                ),
                set_id=set_id,
                reason=error.context.get("reason", error.code),
                canonical_error=error.code,
            ) from error
        try:
            normalize_canonical_periods(snapshot["periods"])
        except CanonicalRevisionError as error:
            raise MigrationControlError(
                "TS_MIGRATION_HASH_MISMATCH",
                set_id=set_id,
                reason=error.context.get("reason", error.code),
                canonical_error=error.code,
            ) from error
        owner_linkable_object_id = self._legacy_object_specific_owner(snapshot)
        series_kind = (
            "object_specific" if owner_linkable_object_id is not None else "catalog"
        )
        object_series_key = (
            canonical_signals[0]["series_key"]
            if owner_linkable_object_id is not None
            else None
        )
        object_specific_signal_id = (
            int(snapshot["signals"][0]["id"])
            if owner_linkable_object_id is not None
            else None
        )
        if existing is not None:
            expected_identity = {
                "owner_project_id": int(legacy_set["project_id"]),
                "name": str(legacy_set["name"]),
                "version_number": int(legacy_set["version_number"]),
                "version_label": str(legacy_set["version_label"]),
                "series_kind": series_kind,
                "owner_linkable_object_id": owner_linkable_object_id,
                "object_series_key": object_series_key,
                "object_specific_signal_id": object_specific_signal_id,
            }
            mismatches = {
                key: {"expected": expected, "actual": existing[key]}
                for key, expected in expected_identity.items()
                if existing[key] != expected
            }
            if mismatches:
                raise MigrationControlError(
                    MAPPING_CONFLICT,
                    set_id=set_id,
                    reason="canonical_set_id_already_assigned",
                    mismatches=mismatches,
                )
            if existing["current_revision_id"] is not None:
                revision = self.connection.execute(
                    f"SELECT * FROM {revisions_table} WHERE id = ?",
                    (int(existing["current_revision_id"]),),
                ).fetchone()
                if (
                    revision is None
                    or revision["state"] != "sealed"
                    or str(revision["legacy_content_hash"]) != legacy_hash
                ):
                    raise MigrationControlError(
                        MAPPING_CONFLICT,
                        set_id=set_id,
                        reason="canonical_set_id_already_assigned",
                    )
                return {
                    "set_id": set_id,
                    "state": "sealed",
                    "series_kind": str(existing["series_kind"]),
                    "legacy_hash": str(revision["legacy_content_hash"]),
                    "canonical_hash": str(revision["content_hash"]),
                    "created": False,
                }
        for source in snapshot["sources"]:
            self._insert_preserved_canonical_source(
                source, technical_actor=technical_actor
            )

        if existing is None:
            self.connection.execute(
                f"""
                INSERT INTO {sets_table} (
                    id, owner_project_id, name, version_number, version_label,
                    visibility_scope, scope_revision, series_kind,
                    owner_linkable_object_id, object_series_key,
                    object_specific_signal_id,
                    current_revision_id, status, description, data_kind,
                    timezone, content_hash, created_at, updated_at,
                    created_by, updated_by
                ) VALUES (?, ?, ?, ?, ?, 'project', 0, ?, ?, ?, ?, NULL, ?, '',
                          ?, ?, NULL, ?, ?, ?, ?)
                """,
                (
                    set_id,
                    int(legacy_set["project_id"]),
                    str(legacy_set["name"]),
                    int(legacy_set["version_number"]),
                    str(legacy_set["version_label"]),
                    series_kind,
                    owner_linkable_object_id,
                    object_series_key,
                    object_specific_signal_id,
                    str(legacy_set["status"]),
                    str(legacy_set["data_kind"]),
                    str(legacy_set["timezone"]),
                    str(legacy_set["created_at"]),
                    str(legacy_set["updated_at"]),
                    str(legacy_set["created_by"]),
                    str(legacy_set["updated_by"]),
                ),
            )

        revisions_by_number = {int(row["revision_number"]): row for row in revisions}
        historical_revisions = (
            revisions[:-1] if legacy_revision_hash_matches else revisions
        )
        for historical in historical_revisions:
            superseded_number = historical["superseded_revision_number"]
            supersedes_id = (
                int(revisions_by_number[int(superseded_number)]["id"])
                if superseded_number is not None
                and int(superseded_number) in revisions_by_number
                else None
            )
            self.connection.execute(
                f"""
                INSERT INTO {revisions_table} (
                    id, time_series_set_id, revision_number,
                    supersedes_revision_id, time_series_source_id,
                    data_class_id, timezone, timestamp_convention,
                    content_hash, legacy_content_hash, state,
                    change_summary, metadata_json, created_at, created_by
                ) VALUES (?, ?, ?, ?, ?, ?, ?, 'period_start', NULL, ?,
                          'legacy_unmaterialized', ?, ?, ?, ?)
                """,
                (
                    int(historical["id"]),
                    set_id,
                    int(historical["revision_number"]),
                    supersedes_id,
                    historical["time_series_source_id"],
                    int(classification["data_class_id"]),
                    str(legacy_set["timezone"]),
                    str(historical["content_hash"]),
                    str(historical["change_summary"]),
                    str(historical["metadata_json"] or "{}"),
                    str(historical["created_at"]),
                    str(historical["created_by"]),
                ),
            )

        if legacy_revision_hash_matches:
            superseded_number = latest_revision["superseded_revision_number"]
            supersedes_id = (
                int(revisions_by_number[int(superseded_number)]["id"])
                if superseded_number is not None
                and int(superseded_number) in revisions_by_number
                else None
            )
            revision_id = int(latest_revision["id"])
            self.connection.execute(
                f"""
                INSERT INTO {revisions_table} (
                    id, time_series_set_id, revision_number,
                    supersedes_revision_id, time_series_source_id,
                    data_class_id, timezone, timestamp_convention,
                    content_hash, legacy_content_hash, state,
                    change_summary, metadata_json, created_at, created_by
                ) VALUES (?, ?, ?, ?, ?, ?, ?, 'period_start', NULL, ?, 'building',
                          ?, ?, ?, ?)
                """,
                (
                    revision_id,
                    set_id,
                    int(latest_revision["revision_number"]),
                    supersedes_id,
                    latest_revision["time_series_source_id"],
                    int(classification["data_class_id"]),
                    str(legacy_set["timezone"]),
                    legacy_hash,
                    str(latest_revision["change_summary"]),
                    str(latest_revision["metadata_json"] or "{}"),
                    str(latest_revision["created_at"]),
                    str(latest_revision["created_by"]),
                ),
            )
        else:
            self._sync_canonical_identity_sequences(
                ("time_series_set_revisions",)
            )
            revision_id = self._insert_canonical_row(
                f"""
                INSERT INTO {revisions_table} (
                    time_series_set_id, revision_number,
                    supersedes_revision_id, time_series_source_id,
                    data_class_id, timezone, timestamp_convention,
                    content_hash, legacy_content_hash, state,
                    change_summary, metadata_json, created_at, created_by
                ) VALUES (?, ?, ?, ?, ?, ?, 'period_start', NULL, ?, 'building',
                          'migration_baseline', ?, ?, ?)
                """,
                (
                    set_id,
                    int(latest_revision["revision_number"]) + 1,
                    int(latest_revision["id"]),
                    latest_revision["time_series_source_id"],
                    int(classification["data_class_id"]),
                    str(legacy_set["timezone"]),
                    legacy_hash,
                    json.dumps(
                        {
                            "migration_reason": "migration_baseline",
                            "legacy_revision_id": int(latest_revision["id"]),
                            "stored_legacy_hash": str(latest_revision["content_hash"]),
                        },
                        sort_keys=True,
                    ),
                    utc_now_iso(),
                    technical_actor,
                ),
            )

        signals_table = self._canonical("time_series_signals")
        revision_signals_table = self._canonical("time_series_revision_signals")
        for legacy_signal, signal in zip(snapshot["signals"], canonical_signals):
            signal_id = int(legacy_signal["id"])
            self.connection.execute(
                f"""
                INSERT INTO {signals_table} (
                    id, time_series_set_id, series_kind, series_key,
                    display_name, description, status, created_at, created_by
                ) VALUES (?, ?, ?, ?, ?, '', 'active', ?, ?)
                """,
                (
                    signal_id,
                    set_id,
                    series_kind,
                    signal["series_key"],
                    signal["display_name"],
                    str(legacy_signal["created_at"]),
                    technical_actor,
                ),
            )
            resolved = classification["signals"][signal["series_key"]]
            self.connection.execute(
                f"""
                INSERT INTO {revision_signals_table} (
                    set_revision_id, signal_id, time_series_set_id,
                    semantic_type_id, unit_id, data_class_id, signal_role,
                    aggregation, ordinal, metadata_json
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    revision_id,
                    signal_id,
                    set_id,
                    int(resolved["semantic_type_id"]),
                    int(resolved["unit_id"]),
                    int(resolved["data_class_id"]),
                    signal["signal_role"],
                    resolved["aggregation"],
                    int(signal["ordinal"]),
                    json.dumps(signal["metadata"], sort_keys=True),
                ),
            )

        periods_table = self._canonical("time_series_periods")
        for period in snapshot["periods"]:
            self.connection.execute(
                f"""
                INSERT INTO {periods_table} (
                    id, set_revision_id, period_index, timestamp_start,
                    timestamp_end, duration_hours
                ) VALUES (?, ?, ?, ?, ?, ?)
                """,
                (
                    int(period["id"]),
                    revision_id,
                    int(period["period_index"]),
                    str(period["timestamp_start"]),
                    str(period["timestamp_end"]),
                    float(period["duration_hours"]),
                ),
            )

        values_table = self._canonical("time_series_values")
        self.connection.executemany(
            f"""
            INSERT INTO {values_table} (
                set_revision_id, signal_id, time_series_period_id,
                value_numeric, quality_flag, source_row_number, metadata_json
            ) VALUES (?, ?, ?, ?, NULL, ?, '{{}}')
            """,
            [
                (
                    revision_id,
                    int(value["time_series_signal_id"]),
                    int(value["time_series_period_id"]),
                    float(value["value_numeric"]),
                    value["source_row_number"],
                )
                for value in snapshot["values"]
            ],
        )
        expected_value_count = len(snapshot["signals"]) * len(snapshot["periods"])
        if len(snapshot["values"]) != expected_value_count:
            raise MigrationControlError(
                "TS_MIGRATION_HASH_MISMATCH",
                set_id=set_id,
                signal_count=len(snapshot["signals"]),
                period_count=len(snapshot["periods"]),
                expected_value_count=expected_value_count,
                observed_value_count=len(snapshot["values"]),
            )
        canonical_hash = self._stream_canonical_content_hash(
            revision_id=revision_id,
            revision_timezone=str(legacy_set["timezone"]),
            timestamp_convention="period_start",
            data_class_key=canonical_data_class_key,
        )
        validation = {
            "legacy_snapshot_hash_verified": True,
            "legacy_revision_hash_matched": legacy_revision_hash_matches,
            "canonical_hash_verified": True,
            "signal_count": len(snapshot["signals"]),
            "period_count": len(snapshot["periods"]),
            "value_count": len(snapshot["values"]),
        }
        self.connection.execute(
            f"""
            UPDATE {revisions_table}
            SET state = 'sealed', content_hash = ?, validation_payload_json = ?
            WHERE id = ? AND state = 'building'
            """,
            (canonical_hash, json.dumps(validation, sort_keys=True), revision_id),
        )
        sealed = self.connection.execute(
            f"SELECT state, content_hash, legacy_content_hash FROM {revisions_table} WHERE id = ?",
            (revision_id,),
        ).fetchone()
        if (
            sealed is None
            or sealed["state"] != "sealed"
            or sealed["content_hash"] != canonical_hash
            or sealed["legacy_content_hash"] != legacy_hash
        ):
            raise MigrationControlError(
                "TS_MIGRATION_HASH_MISMATCH",
                set_id=set_id,
                reason="sealed_hash_verification_failed",
            )
        self.connection.execute(
            f"""
            UPDATE {sets_table}
            SET current_revision_id = ?, content_hash = ?, status = ?,
                updated_at = ?, updated_by = ?
            WHERE id = ?
            """,
            (
                revision_id,
                canonical_hash,
                str(legacy_set["status"]),
                str(legacy_set["updated_at"]),
                str(legacy_set["updated_by"]),
                set_id,
            ),
        )
        self._project_catalog_entries(set_id=set_id, now=utc_now_iso())
        self._raise_catalog_generation(now=utc_now_iso())
        self._sync_canonical_identity_sequences()
        return {
            "set_id": set_id,
            "state": "sealed",
            "series_kind": series_kind,
            "legacy_hash": legacy_hash,
            "canonical_hash": canonical_hash,
            "created": True,
        }

    def _ensure_c3_quarantine_set(
        self, *, snapshot: Mapping[str, Any], migration_run_id: int
    ) -> None:
        """Keep an unresolved legacy identity visible but never executable."""

        legacy_set = snapshot["set"]
        technical_actor = migration_actor(migration_run_id)
        for source in snapshot["sources"]:
            self._insert_preserved_canonical_source(
                source, technical_actor=technical_actor
            )
        sets_table = self._canonical("time_series_sets")
        existing = self.connection.execute(
            f"SELECT id FROM {sets_table} WHERE id = ?", (int(legacy_set["id"]),)
        ).fetchone()
        if existing is not None:
            return
        self.connection.execute(
            f"""
            INSERT INTO {sets_table} (
                id, owner_project_id, name, version_number, version_label,
                visibility_scope, scope_revision, series_kind,
                current_revision_id, status, description, data_kind,
                timezone, content_hash, created_at, updated_at,
                created_by, updated_by
            ) VALUES (?, ?, ?, ?, ?, 'project', 0, 'catalog', NULL, 'draft', '',
                      ?, ?, NULL, ?, ?, ?, ?)
            """,
            (
                int(legacy_set["id"]),
                int(legacy_set["project_id"]),
                str(legacy_set["name"]),
                int(legacy_set["version_number"]),
                str(legacy_set["version_label"]),
                str(legacy_set["data_kind"]),
                str(legacy_set["timezone"]),
                str(legacy_set["created_at"]),
                str(legacy_set["updated_at"]),
                str(legacy_set["created_by"]),
                str(legacy_set["updated_by"]),
            ),
        )

    def _c3_failure_finding(
        self, *, error: MigrationControlError, snapshot: Mapping[str, Any]
    ) -> dict[str, Any]:
        set_id = int(snapshot["set"]["id"])
        binding = self.connection.execute(
            """
            SELECT 1 AS present FROM case_time_series_bindings
            WHERE time_series_set_id = ? LIMIT 1
            """,
            (set_id,),
        ).fetchone()
        evidence = {"set_id": set_id, **dict(error.context)}
        discriminator = evidence.get("signal_id") or evidence.get("reason") or "set"
        return {
            "code": error.code,
            "severity": "blocking" if binding is not None else "informational",
            "finding_key": f"{error.code}:set={set_id}:subject={discriminator}",
            "evidence": evidence,
            "explained": False,
            "explanation": "",
        }

    def _c3_mapping_specs(
        self, snapshot: Mapping[str, Any]
    ) -> list[dict[str, str]]:
        specs = []
        for source in snapshot["sources"]:
            specs.append(
                {
                    "source_table": "time_series_sources",
                    "source_id": str(source["id"]),
                    "target_kind": "canonical_source",
                    "target_id": str(source["id"]),
                    "source_hash": canonical_digest(source),
                }
            )
        for table_key, source_table, target_kind in (
            ("signals", "time_series_signals", "canonical_signal"),
            ("periods", "time_series_periods", "canonical_period"),
            ("revisions", "time_series_set_revisions", "canonical_revision"),
        ):
            for row in snapshot[table_key]:
                specs.append(
                    {
                        "source_table": source_table,
                        "source_id": str(row["id"]),
                        "target_kind": target_kind,
                        "target_id": str(row["id"]),
                        "source_hash": canonical_digest(row),
                    }
                )
        specs.append(
            {
                "source_table": "time_series_sets",
                "source_id": str(snapshot["set"]["id"]),
                "target_kind": "canonical_set",
                "target_id": str(snapshot["set"]["id"]),
                "source_hash": canonical_digest(snapshot["set"]),
            }
        )
        return specs

    def _resume_time_series_migration_phase(
        self, *, migration_run_id: int, phase: str, actor: str
    ) -> dict[str, Any]:
        run = self.read_migration_run(int(migration_run_id))
        if (
            run["phase"] != phase
            or run["status"] != "running"
            or str(run["started_by"]) != str(actor)
        ):
            raise MigrationControlError(
                "TS_MIGRATION_CHECKPOINT_INVALID",
                migration_run_id=int(migration_run_id),
                phase=run["phase"],
                status=run["status"],
            )
        proven = self.connection.execute(
            f"""
            SELECT * FROM {self._migration('time_series_migration_runs')}
            WHERE phase = 'C0' AND status = 'proven'
            ORDER BY id DESC
            """
        ).fetchone()
        recovered = json.loads(proven["manifest_json"] or "{}") if proven else {}
        if proven is None or recovered.get("inventory") != self._c0_inventory():
            raise MigrationControlError(
                RECOVERY_POINT_REQUIRED,
                reason="source_moved_since_checkpoint",
                phase=phase,
                migration_run_id=int(migration_run_id),
            )
        return {
            "migration_run_id": int(migration_run_id),
            "phase": phase,
            "status": "running",
            "actor": str(run["actor"]),
            "checkpoint": dict(run["checkpoint"]),
        }

    def _checkpoint_migration_run(
        self, *, migration_run_id: int, checkpoint: Mapping[str, Any]
    ) -> None:
        self.connection.execute(
            f"""
            UPDATE {self._migration('time_series_migration_runs')}
            SET checkpoint_json = ? WHERE id = ? AND status = 'running'
            """,
            (
                json.dumps(dict(checkpoint), sort_keys=True),
                int(migration_run_id),
            ),
        )
        self.connection.commit()

    def _c3_manifest_set(self, snapshot: Mapping[str, Any]) -> dict[str, Any]:
        set_id = int(snapshot["set"]["id"])
        canonical_set = self.connection.execute(
            f"SELECT * FROM {self._canonical('time_series_sets')} WHERE id = ?",
            (set_id,),
        ).fetchone()
        if canonical_set is None or canonical_set["current_revision_id"] is None:
            return {
                "set_id": set_id,
                "state": "quarantined",
                "series_kind": "catalog",
                "legacy_hash": str(snapshot["set"]["content_hash"]),
                "canonical_hash": None,
            }
        revision = self.connection.execute(
            f"""
            SELECT state, legacy_content_hash, content_hash
            FROM {self._canonical('time_series_set_revisions')}
            WHERE id = ?
            """,
            (int(canonical_set["current_revision_id"]),),
        ).fetchone()
        return {
            "set_id": set_id,
            "state": str(revision["state"]),
            "series_kind": str(canonical_set["series_kind"]),
            "legacy_hash": str(revision["legacy_content_hash"]),
            "canonical_hash": str(revision["content_hash"]),
        }

    def backfill_time_series_c3(
        self,
        *,
        actor: str,
        batch_size: int | None = None,
        migration_run_id: int | None = None,
    ) -> dict[str, Any]:
        """Backfill legacy sets in resumable, independently atomic batches."""

        self._require_proven_migration_phase("C2")
        if batch_size is not None and int(batch_size) <= 0:
            raise ValueError("batch_size must be positive")
        if migration_run_id is None:
            opened = self.open_migration_phase(phase="C3", actor=actor)
            last_set_id = 0
        else:
            opened = self._resume_time_series_migration_phase(
                migration_run_id=int(migration_run_id), phase="C3", actor=actor
            )
            last_set_id = int(opened["checkpoint"].get("last_set_id") or 0)
        run_id = int(opened["migration_run_id"])
        output_tables = tuple(self.canonical_table_names().values())
        before = self._migration_table_evidence(output_tables)
        all_snapshots = [
            self._legacy_time_series_set_snapshot(int(row["id"]))
            for row in self.connection.execute(
                "SELECT id FROM time_series_sets ORDER BY id"
            ).fetchall()
        ]
        pending = [
            snapshot
            for snapshot in all_snapshots
            if int(snapshot["set"]["id"]) > last_set_id
        ]
        limit = len(pending) if batch_size is None else int(batch_size)
        snapshots = pending[:limit]
        has_more = len(pending) > len(snapshots)
        results = []
        successful_snapshots = []
        findings = []
        with self._lock:
            for snapshot in snapshots:
                try:
                    with self._database_transaction():
                        result = self._backfill_legacy_set_c3(
                            snapshot=snapshot, migration_run_id=run_id
                        )
                except MigrationControlError as error:
                    with self._database_transaction():
                        self._ensure_c3_quarantine_set(
                            snapshot=snapshot, migration_run_id=run_id
                        )
                    finding = self._c3_failure_finding(
                        error=error, snapshot=snapshot
                    )
                    findings.append(finding)
                    results.append(
                        {
                            "set_id": int(snapshot["set"]["id"]),
                            "state": "quarantined",
                            "series_kind": "catalog",
                            "legacy_hash": str(snapshot["set"]["content_hash"]),
                            "canonical_hash": None,
                            "created": True,
                        }
                    )
                    continue
                results.append(result)
                successful_snapshots.append(snapshot)

        mapping_changes = 0
        for snapshot in successful_snapshots:
            for spec in self._c3_mapping_specs(snapshot):
                recorded = self.record_migration_mapping(
                    migration_run_id=run_id,
                    source_kind="legacy_time_series",
                    **spec,
                )
                mapping_changes += recorded["status"] == "created"

        after = self._migration_table_evidence(output_tables)
        created_rows = sum(
            after[table]["row_count"] - before[table]["row_count"]
            for table in output_tables
        )
        checkpoint = {
            "last_set_id": (
                int(snapshots[-1]["set"]["id"]) if snapshots else last_set_id
            )
        }
        if has_more and not findings:
            self._checkpoint_migration_run(
                migration_run_id=run_id, checkpoint=checkpoint
            )
            return {
                **opened,
                "status": "running",
                "created_rows": created_rows,
                "mapping_changes": int(mapping_changes),
                "checkpoint": checkpoint,
                "manifest": None,
                "manifest_digest": "",
            }
        manifest = {
            "manifest_version": 1,
            "phase": "C3",
            "source_engine": self.database_backend,
            "sets": [self._c3_manifest_set(snapshot) for snapshot in all_snapshots],
            "outputs": after,
            "anomalies": [
                {
                    "code": finding["code"],
                    "severity": finding["severity"],
                    "finding_key": finding["finding_key"],
                    "evidence": finding["evidence"],
                }
                for finding in findings
            ],
        }
        if findings:
            self._record_migration_anomalies(
                migration_run_id=run_id,
                phase="C3",
                findings=findings,
                now=utc_now_iso(),
            )
        self._finish_migration_run(
            migration_run_id=run_id,
            status="stopped" if findings else "proven",
            manifest=manifest,
            checkpoint=checkpoint,
        )
        if findings:
            raise MigrationPhaseStopped(
                C3_STOPPED,
                migration_run_id=run_id,
                findings=findings,
                completed_set_ids=[
                    result["set_id"]
                    for result in results
                    if result["state"] == "sealed"
                ],
            )
        return {
            **opened,
            "status": "proven",
            "created_rows": created_rows,
            "mapping_changes": int(mapping_changes),
            "checkpoint": checkpoint,
            "manifest": manifest,
            "manifest_digest": canonical_digest(manifest),
        }

    # -- C4 association and binding backfill (TS7-017) -------------------

    @staticmethod
    def _c4_actor(migration_run_id: int) -> dict[str, Any]:
        return {
            "id": None,
            "email": migration_actor(migration_run_id),
            "role": "migration",
        }

    def _c4_legacy_binding_rows(self) -> list[dict[str, Any]]:
        return [
            dict(row)
            for row in self.connection.execute(
                """
                SELECT binding.*, optimization_case.scenario_id,
                       scenario.project_id
                FROM case_time_series_bindings AS binding
                JOIN case_input_variants AS variant
                  ON variant.id = binding.case_input_variant_id
                JOIN optimization_cases AS optimization_case
                  ON optimization_case.id = variant.case_id
                JOIN scenarios AS scenario
                  ON scenario.id = optimization_case.scenario_id
                ORDER BY binding.id
                """
            ).fetchall()
        ]

    def _c4_legacy_signal_rows(self) -> list[dict[str, Any]]:
        return [
            dict(row)
            for row in self.connection.execute(
                """
                SELECT signal.*, legacy_set.project_id
                FROM time_series_signals AS signal
                JOIN time_series_sets AS legacy_set
                  ON legacy_set.id = signal.time_series_set_id
                ORDER BY signal.id
                """
            ).fetchall()
        ]

    def _c4_binding_role_keys(self, legacy: Mapping[str, Any]) -> tuple[str, ...]:
        signal_key = str(legacy["signal_key"])
        expanded = LEGACY_BINDING_ROLE_EXPANSIONS.get(signal_key)
        if expanded is not None:
            return expanded
        role_key = LEGACY_BINDING_ROLE_ALIASES.get(signal_key)
        if role_key is None:
            raise MigrationControlError(
                "TS_MIGRATION_BINDING_ROLE_UNRESOLVED",
                binding_id=int(legacy["id"]),
                signal_key=signal_key,
                reason="exact_alias_missing",
            )
        return (role_key,)

    def _c4_linkable_object(
        self, *, legacy: Mapping[str, Any], binding_role_key: str
    ) -> dict[str, Any]:
        entity_type = str(legacy.get("entity_type") or "").strip()
        entity_id = legacy.get("entity_id")
        # Only the explicit system-compatible roles may turn an absent legacy
        # entity into the project's unique global slot.
        if not entity_type and entity_id is None and binding_role_key in {
            "grid_import_price",
            "grid_export_price",
        }:
            entity_type = "global:system"
            entity_id = "system"
        if not entity_type and entity_id is not None:
            exact_candidates = [
                item
                for item in self.list_linkable_objects(
                    project_id=int(legacy["project_id"])
                )
                if item["object_key"] == str(entity_id)
            ]
            if len(exact_candidates) > 1:
                raise MigrationControlError(
                    "TS_MIGRATION_OBJECT_AMBIGUOUS",
                    binding_id=int(legacy["id"]),
                    variant_id=int(legacy["case_input_variant_id"]),
                    project_id=int(legacy["project_id"]),
                    entity_type=legacy.get("entity_type"),
                    entity_id=entity_id,
                    reason="entity_type_missing_with_multiple_exact_objects",
                    candidates=[
                        {
                            "linkable_object_id": int(candidate["id"]),
                            "object_type_key": candidate["object_type_key"],
                            "object_key": candidate["object_key"],
                        }
                        for candidate in exact_candidates
                    ],
                )
        if not entity_type or entity_id is None:
            raise MigrationControlError(
                "TS_MIGRATION_OBJECT_NOT_FOUND",
                binding_id=int(legacy["id"]),
                entity_type=legacy.get("entity_type"),
                entity_id=entity_id,
                reason="legacy_reference_incomplete",
            )
        try:
            return self.resolve_linkable_object_reference(
                project_id=int(legacy["project_id"]),
                entity_type=entity_type,
                entity_id=entity_id,
            )
        except (LinkableObjectError, TypeError, ValueError) as error:
            object_code = getattr(error, "code", "TS_OBJECT_NOT_REGISTERED")
            code = {
                "TS_MIGRATION_OBJECT_AMBIGUOUS": "TS_MIGRATION_OBJECT_AMBIGUOUS",
                "TS_OBJECT_PROJECT_MISMATCH": "TS_MIGRATION_PROJECT_MISMATCH",
                "TS_COMPAT_PROJECT_CONTEXT_MISMATCH": "TS_MIGRATION_PROJECT_MISMATCH",
            }.get(object_code, "TS_MIGRATION_OBJECT_NOT_FOUND")
            raise MigrationControlError(
                code,
                binding_id=int(legacy["id"]),
                variant_id=int(legacy["case_input_variant_id"]),
                project_id=int(legacy["project_id"]),
                entity_type=entity_type,
                entity_id=entity_id,
                object_error=object_code,
                candidates=getattr(error, "context", {}).get("candidates", []),
            ) from error

    def _c4_canonical_signal(self, legacy: Mapping[str, Any]) -> dict[str, Any]:
        rows = self.connection.execute(
            f"""
            SELECT signal.id AS signal_id, signal.time_series_set_id,
                   canonical_set.series_kind,
                   canonical_set.owner_linkable_object_id,
                   canonical_set.current_revision_id,
                   revision.state AS revision_state,
                   revision.content_hash
            FROM {self._canonical('time_series_signals')} AS signal
            JOIN {self._canonical('time_series_sets')} AS canonical_set
              ON canonical_set.id = signal.time_series_set_id
            LEFT JOIN {self._canonical('time_series_set_revisions')} AS revision
              ON revision.id = canonical_set.current_revision_id
            WHERE signal.time_series_set_id = ? AND signal.series_key = ?
            ORDER BY signal.id
            """,
            (int(legacy["time_series_set_id"]), str(legacy["signal_key"])),
        ).fetchall()
        if len(rows) != 1:
            raise MigrationControlError(
                "TS_MIGRATION_BINDING_SIGNAL_UNRESOLVED",
                binding_id=int(legacy["id"]),
                time_series_set_id=int(legacy["time_series_set_id"]),
                signal_key=str(legacy["signal_key"]),
                match_count=len(rows),
            )
        signal = dict(rows[0])
        if (
            signal["current_revision_id"] is None
            or signal["revision_state"] != "sealed"
            or not str(signal["content_hash"] or "").strip()
        ):
            raise MigrationControlError(
                "TS_MIGRATION_REVISION_UNMATERIALIZED",
                binding_id=int(legacy["id"]),
                time_series_set_id=int(legacy["time_series_set_id"]),
                revision_id=signal["current_revision_id"],
            )
        return signal

    @staticmethod
    def _c4_compatibility_anomaly_code(errors: list[Mapping[str, Any]]) -> str:
        codes = {str(error.get("code") or "") for error in errors}
        if codes & {
            "TS_COMPAT_PROJECT_CONTEXT_MISMATCH",
            "TS_COMPAT_SCOPE_NOT_ACCESSIBLE",
            "TS_COMPAT_OBJECT_OWNER_MISMATCH",
        }:
            return "TS_MIGRATION_PROJECT_MISMATCH"
        if codes & {"TS_COMPAT_ROLE_INACTIVE", "TS_COMPAT_ROLE_USAGE_NOT_ALLOWED"}:
            return "TS_MIGRATION_BINDING_ROLE_UNRESOLVED"
        if "TS_COMPAT_SIGNAL_UNAVAILABLE" in codes:
            return "TS_MIGRATION_REVISION_UNMATERIALIZED"
        return "TS_MIGRATION_BINDING_INCOMPATIBLE"

    def _c4_ensure_association(
        self,
        *,
        legacy: Mapping[str, Any],
        signal: Mapping[str, Any],
        linkable: Mapping[str, Any],
        binding_role_key: str,
        migration_run_id: int,
    ) -> tuple[int | None, bool]:
        if signal["series_kind"] == "object_specific":
            if int(signal["owner_linkable_object_id"] or 0) != int(linkable["id"]):
                raise MigrationControlError(
                    "TS_MIGRATION_PROJECT_MISMATCH",
                    binding_id=int(legacy["id"]),
                    reason="object_specific_owner_mismatch",
                )
            return None, False
        operation = {
            "client_operation_id": f"migration-association-{int(legacy['id'])}",
            "action": "add",
            "signal_id": int(signal["signal_id"]),
            "linkable_object_id": int(linkable["id"]),
            "binding_role_key": binding_role_key,
            "expected_absent": True,
            "reason_code": "legacy_binding_migrated",
            "reason_text": "Created from an exact legacy binding reference.",
        }
        prevalidated, _ = self._prevalidate_catalog_association_add(
            operation, target_project_id=int(legacy["project_id"])
        )
        if not prevalidated["compatibility_decision"]["allowed"]:
            raise MigrationControlError(
                self._c4_compatibility_anomaly_code(prevalidated["errors"]),
                binding_id=int(legacy["id"]),
                usage="association",
                errors=prevalidated["errors"],
            )
        existing = prevalidated["observed_state"]["active_association"]
        if existing is not None:
            return int(existing["id"]), False
        created = self._insert_catalog_association_add(
            operation=operation,
            prevalidated=prevalidated,
            actor_user=self._c4_actor(migration_run_id),
            request_id=f"migration-c4:{migration_run_id}",
            batch_id=f"migration-c4:{migration_run_id}",
            occurred_at=utc_now_iso(),
        )
        return int(created["association_id"]), True

    def _c4_prevalidate_binding(
        self,
        *,
        legacy: Mapping[str, Any],
        signal: Mapping[str, Any],
        linkable: Mapping[str, Any],
        binding_role_key: str,
        catalog_association_id: int | None,
        existing_binding_id: int | None,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        operation = {
            "client_operation_id": f"migration-binding-{int(legacy['id'])}",
            "action": "create",
            "linkable_object_id": int(linkable["id"]),
            "binding_role_key": binding_role_key,
            "signal_id": int(signal["signal_id"]),
            "revision": {
                "mode": "current",
                "revision_id": int(signal["current_revision_id"]),
                "content_hash": str(signal["content_hash"]),
            },
            "catalog_association_id": catalog_association_id,
            "reason_code": "legacy_binding_migrated",
            "reason_text": "Reauthorized from the exact legacy reference.",
        }
        context = self._canonical_binding_context(
            scenario_id=int(legacy["scenario_id"]),
            variant_id=int(legacy["case_input_variant_id"]),
        )
        prevalidated, observed = self._prevalidate_case_binding_create(
            operation, context=context
        )
        remaining_errors = [
            error
            for error in prevalidated["errors"]
            if not (
                error["code"] == "TS_LINK_CONFLICT"
                and int(error["context"].get("binding_id") or 0)
                == int(existing_binding_id or 0)
            )
        ]
        if remaining_errors:
            raise MigrationControlError(
                self._c4_compatibility_anomaly_code(remaining_errors),
                binding_id=int(legacy["id"]),
                usage="execution",
                errors=remaining_errors,
            )
        return operation, {**prevalidated, "observed_state": observed}

    def _c4_insert_binding(
        self,
        *,
        legacy: Mapping[str, Any],
        operation: Mapping[str, Any],
        prevalidated: Mapping[str, Any],
        migration_run_id: int,
        preferred_binding_id: int | None,
    ) -> int:
        observed = prevalidated["observed_state"]
        signal = observed["signal"]
        linkable = observed["object"]
        technical_actor = migration_actor(migration_run_id)
        validated_at = utc_now_iso()
        metadata = {
            "migration_actor": technical_actor,
            "legacy_binding": {
                key: legacy.get(key)
                for key in (
                    "id",
                    "case_input_variant_id",
                    "signal_key",
                    "entity_type",
                    "entity_id",
                    "time_series_set_id",
                    "required",
                    "created_at",
                    "updated_at",
                    "created_by",
                    "updated_by",
                )
            },
        }
        bindings = self.link_layer_table_names()["case_time_series_bindings"]
        columns = [
            "case_input_variant_id",
            "linkable_object_id",
            "binding_role_id",
            "signal_id",
            "time_series_set_id",
            "set_revision_id",
            "bound_content_hash",
            "source_kind",
            "source_owner_linkable_object_id",
            "catalog_association_id",
            "compatibility_rule_id",
            "required",
            "status",
            "supersedes_binding_id",
            "lifecycle_revision",
            "change_reason_code",
            "change_reason_text",
            "validated_at",
            "created_at",
            "updated_at",
            "created_by",
            "updated_by",
            "metadata_json",
        ]
        values: list[Any] = [
            int(legacy["case_input_variant_id"]),
            int(linkable["id"]),
            int(observed["binding_role_id"]),
            int(signal["signal_id"]),
            int(signal["time_series_set_id"]),
            int(operation["revision"]["revision_id"]),
            str(signal["selected_content_hash"]),
            str(signal["series_kind"]),
            signal["owner_linkable_object_id"],
            operation.get("catalog_association_id"),
            int(observed["compatibility_rule_id"]),
            int(bool(legacy["required"])),
            "active",
            None,
            1,
            "legacy_binding_migrated",
            operation["reason_text"],
            validated_at,
            str(legacy["created_at"]),
            str(legacy["updated_at"]),
            str(legacy["created_by"]),
            str(legacy["updated_by"]),
            json.dumps(metadata, sort_keys=True),
        ]
        if preferred_binding_id is not None:
            columns.insert(0, "id")
            values.insert(0, int(preferred_binding_id))
        placeholders = ", ".join("?" for _ in values)
        binding_id = self._insert_canonical_row(
            f"INSERT INTO {bindings} ({', '.join(columns)}) VALUES ({placeholders})",
            tuple(values),
        )
        compatibility_fingerprint, object_scope_fingerprint = (
            self._case_binding_fingerprints(
                observed=observed,
                binding_role_key=str(operation["binding_role_key"]),
                contract_version=int(
                    prevalidated["compatibility_decision"]["contract_version"]
                ),
            )
        )
        self.connection.execute(
            f"""
            INSERT INTO {self.link_layer_table_names()['time_series_link_validations']} (
                binding_id, subject_lifecycle_revision, validation_mode,
                validated_set_revision_id, observed_current_revision_id,
                compatibility_rule_id, compatibility_fingerprint,
                object_scope_fingerprint, variant_dependency_fingerprint,
                validated_at, validated_by, reason_code, reason_text
            ) VALUES (?, 1, 'binding_current', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                binding_id,
                int(operation["revision"]["revision_id"]),
                int(signal["current_revision_id"]),
                int(observed["compatibility_rule_id"]),
                compatibility_fingerprint,
                object_scope_fingerprint,
                observed["variant"]["variant_dependency_fingerprint"],
                validated_at,
                technical_actor,
                "legacy_binding_migrated",
                operation["reason_text"],
            ),
        )
        after = {
            "binding_id": binding_id,
            "case_input_variant_id": int(legacy["case_input_variant_id"]),
            "linkable_object_id": int(linkable["id"]),
            "binding_role_key": str(operation["binding_role_key"]),
            "signal_id": int(signal["signal_id"]),
            "set_revision_id": int(operation["revision"]["revision_id"]),
            "bound_content_hash": str(signal["selected_content_hash"]),
            "status": "active",
        }
        self.connection.execute(
            f"""
            INSERT INTO {self.link_layer_table_names()['time_series_link_events']} (
                batch_id, binding_id, event_type, actor_user_id,
                actor_identity_snapshot, actor_role_snapshot, reason_code,
                reason_text, before_json, after_json, request_id, occurred_at
            ) VALUES (?, ?, 'migrated', NULL, ?, 'migration', ?, ?, ?, ?, ?, ?)
            """,
            (
                f"migration-c4:{migration_run_id}",
                binding_id,
                technical_actor,
                "legacy_binding_migrated",
                operation["reason_text"],
                json.dumps(metadata["legacy_binding"], sort_keys=True),
                json.dumps(after, sort_keys=True),
                f"migration-c4:{migration_run_id}",
                validated_at,
            ),
        )
        self._sync_canonical_identity_sequences(("case_time_series_bindings",))
        return binding_id

    def _c4_binding_mapping_target_kind(
        self, *, legacy: Mapping[str, Any], binding_role_key: str
    ) -> str:
        if len(self._c4_binding_role_keys(legacy)) == 1:
            return "canonical_binding"
        return f"canonical_binding:{binding_role_key}"

    def _c4_mapped_binding_id(
        self, *, legacy: Mapping[str, Any], binding_role_key: str
    ) -> int | None:
        mapping = self.connection.execute(
            f"""
            SELECT target_id
            FROM {self._migration('time_series_migration_mappings')}
            WHERE source_kind = 'legacy_time_series'
              AND source_table = 'case_time_series_bindings'
              AND source_id = ? AND target_kind = ?
            """,
            (
                str(legacy["id"]),
                self._c4_binding_mapping_target_kind(
                    legacy=legacy, binding_role_key=binding_role_key
                ),
            ),
        ).fetchone()
        return None if mapping is None else int(mapping["target_id"])

    def _c4_existing_expanded_binding(
        self,
        *,
        legacy: Mapping[str, Any],
        linkable_object_id: int,
        binding_role_key: str,
    ):
        return self.connection.execute(
            f"""
            SELECT binding.*
            FROM {self.link_layer_table_names()['case_time_series_bindings']} AS binding
            JOIN time_series_binding_roles AS role
              ON role.id = binding.binding_role_id
            WHERE binding.case_input_variant_id = ?
              AND binding.linkable_object_id = ?
              AND role.role_key = ? AND binding.status = 'active'
            """,
            (
                int(legacy["case_input_variant_id"]),
                int(linkable_object_id),
                str(binding_role_key),
            ),
        ).fetchone()

    def _c4_migrate_binding_role(
        self,
        *,
        legacy: Mapping[str, Any],
        binding_role_key: str,
        preferred_binding_id: int | None,
        migration_run_id: int,
    ) -> dict[str, Any]:
        linkable = self._c4_linkable_object(
            legacy=legacy, binding_role_key=binding_role_key
        )
        signal = self._c4_canonical_signal(legacy)
        association_id, association_created = self._c4_ensure_association(
            legacy=legacy,
            signal=signal,
            linkable=linkable,
            binding_role_key=binding_role_key,
            migration_run_id=migration_run_id,
        )
        mapped_binding_id = self._c4_mapped_binding_id(
            legacy=legacy, binding_role_key=binding_role_key
        )
        lookup_binding_id = mapped_binding_id or preferred_binding_id
        existing = None
        if lookup_binding_id is not None:
            existing = self.connection.execute(
                f"""
                SELECT *
                FROM {self.link_layer_table_names()['case_time_series_bindings']}
                WHERE id = ?
                """,
                (int(lookup_binding_id),),
            ).fetchone()
        if existing is None and preferred_binding_id is None:
            existing = self._c4_existing_expanded_binding(
                legacy=legacy,
                linkable_object_id=int(linkable["id"]),
                binding_role_key=binding_role_key,
            )
        existing_binding_id = None if existing is None else int(existing["id"])
        operation, prevalidated = self._c4_prevalidate_binding(
            legacy=legacy,
            signal=signal,
            linkable=linkable,
            binding_role_key=binding_role_key,
            catalog_association_id=association_id,
            existing_binding_id=existing_binding_id,
        )
        binding_created = existing is None
        if binding_created:
            binding_id = self._c4_insert_binding(
                legacy=legacy,
                operation=operation,
                prevalidated=prevalidated,
                migration_run_id=migration_run_id,
                preferred_binding_id=preferred_binding_id,
            )
        else:
            binding_id = int(existing["id"])
            expected = {
                "case_input_variant_id": int(legacy["case_input_variant_id"]),
                "linkable_object_id": int(linkable["id"]),
                "binding_role_id": int(
                    prevalidated["observed_state"]["binding_role_id"]
                ),
                "signal_id": int(signal["signal_id"]),
                "time_series_set_id": int(signal["time_series_set_id"]),
                "set_revision_id": int(signal["current_revision_id"]),
                "bound_content_hash": str(signal["content_hash"]),
                "source_kind": str(signal["series_kind"]),
                "source_owner_linkable_object_id": signal[
                    "owner_linkable_object_id"
                ],
                "catalog_association_id": association_id,
                "compatibility_rule_id": int(
                    prevalidated["observed_state"]["compatibility_rule_id"]
                ),
                "required": int(bool(legacy["required"])),
                "status": "active",
            }
            mismatches = {
                key: {"expected": value, "actual": existing[key]}
                for key, value in expected.items()
                if existing[key] != value
            }
            if mismatches:
                raise MigrationControlError(
                    MAPPING_CONFLICT,
                    binding_id=binding_id,
                    legacy_binding_id=int(legacy["id"]),
                    reason="canonical_binding_id_already_assigned",
                    mismatches=mismatches,
                )
        self._refresh_catalog_link_counts([int(signal["signal_id"])])
        return {
            "binding_id": binding_id,
            "legacy_binding_id": int(legacy["id"]),
            "signal_id": int(signal["signal_id"]),
            "linkable_object_id": int(linkable["id"]),
            "binding_role_key": binding_role_key,
            "set_revision_id": int(signal["current_revision_id"]),
            "catalog_association_id": association_id,
            "association_created": association_created,
            "binding_created": binding_created,
            "mapping_target_kind": self._c4_binding_mapping_target_kind(
                legacy=legacy, binding_role_key=binding_role_key
            ),
        }

    def _refresh_catalog_link_counts(self, signal_ids) -> None:
        """Move the projection's link counts with the transaction that changed them.

        Chapter 9.3 requires the read model to be updated synchronously by the
        same service and the same transaction that changes the source. The
        canonical association and binding batches already do this; the migrator
        writes the same link tables directly and owes the projection the same
        update, or C5 finds a divergence the migrator itself created.
        """

        ids = sorted({int(signal_id) for signal_id in signal_ids})
        if not ids:
            return
        entries = self._projection("time_series_catalog_entries")
        associations = self.link_layer_table_names()[
            "time_series_catalog_associations"
        ]
        bindings = self.link_layer_table_names()["case_time_series_bindings"]
        placeholders = ", ".join("?" for _ in ids)
        self.connection.execute(
            f"""
            UPDATE {entries}
            SET association_count = (
                    SELECT COUNT(*) FROM {associations}
                    WHERE signal_id = {entries}.signal_id AND status = 'active'
                ),
                binding_count = (
                    SELECT COUNT(*) FROM {bindings}
                    WHERE signal_id = {entries}.signal_id AND status = 'active'
                ),
                projection_revision = projection_revision + 1
            WHERE signal_id IN ({placeholders})
            """,
            tuple(ids),
        )

    def _c4_migrate_binding(
        self, *, legacy: Mapping[str, Any], migration_run_id: int
    ) -> list[dict[str, Any]]:
        results = []
        for ordinal, role_key in enumerate(self._c4_binding_role_keys(legacy)):
            results.append(
                self._c4_migrate_binding_role(
                    legacy=legacy,
                    binding_role_key=role_key,
                    preferred_binding_id=(
                        int(legacy["id"]) if ordinal == 0 else None
                    ),
                    migration_run_id=migration_run_id,
                )
            )
        return results

    def _c4_migrate_signal_associations(
        self, *, legacy_signal: Mapping[str, Any], migration_run_id: int
    ) -> list[dict[str, Any]]:
        try:
            role_keys = self._c4_binding_role_keys(legacy_signal)
        except MigrationControlError:
            return []
        entity_type = str(legacy_signal.get("entity_type") or "").strip()
        entity_key = legacy_signal.get("entity_key")
        results = []
        for role_key in role_keys:
            global_role = role_key in {"grid_import_price", "grid_export_price"}
            if not global_role and (not entity_type or entity_key is None):
                continue
            evidence = {
                "id": int(legacy_signal["id"]),
                "case_input_variant_id": 0,
                "project_id": int(legacy_signal["project_id"]),
                "signal_key": str(legacy_signal["signal_key"]),
                "time_series_set_id": int(legacy_signal["time_series_set_id"]),
                "entity_type": entity_type or None,
                "entity_id": entity_key,
            }
            linkable = self._c4_linkable_object(
                legacy=evidence, binding_role_key=role_key
            )
            signal = self._c4_canonical_signal(evidence)
            association_id, created = self._c4_ensure_association(
                legacy=evidence,
                signal=signal,
                linkable=linkable,
                binding_role_key=role_key,
                migration_run_id=migration_run_id,
            )
            results.append(
                {
                    "association_id": association_id,
                    "signal_id": int(signal["signal_id"]),
                    "linkable_object_id": int(linkable["id"]),
                    "binding_role_key": role_key,
                    "created": created,
                }
            )
        self._refresh_catalog_link_counts(
            result["signal_id"] for result in results
        )
        return results

    def _record_c4_association_mapping(
        self, *, result: Mapping[str, Any], migration_run_id: int
    ) -> bool:
        if result["association_id"] is None:
            return False
        source_id = json.dumps(
            [
                result["signal_id"],
                result["linkable_object_id"],
                result["binding_role_key"],
            ],
            separators=(",", ":"),
        )
        mapping = self.record_migration_mapping(
            migration_run_id=migration_run_id,
            source_kind="legacy_time_series",
            source_table="time_series_signals",
            source_id=source_id,
            target_kind="catalog_association",
            target_id=str(result["association_id"]),
            source_hash=canonical_digest(
                {
                    "signal_id": result["signal_id"],
                    "linkable_object_id": result["linkable_object_id"],
                    "binding_role_key": result["binding_role_key"],
                }
            ),
        )
        return mapping["status"] == "created"

    def _c4_binding_disposition(self, binding_id: int):
        return self.connection.execute(
            f"""
            SELECT * FROM {self._migration('time_series_migration_mappings')}
            WHERE source_kind = 'legacy_time_series'
              AND source_table = 'case_time_series_bindings'
              AND source_id = ? AND target_kind = 'binding_disposition'
            """,
            (str(binding_id),),
        ).fetchone()

    def _resolve_previous_c4_binding_anomalies(
        self, *, binding_id: int, actor: str, note: str
    ) -> None:
        table = self._migration("time_series_migration_anomalies")
        for row in self.connection.execute(
            f"""
            SELECT id, evidence_json FROM {table}
            WHERE phase = 'C4' AND resolution <> 'resolved'
            ORDER BY id
            """
        ).fetchall():
            evidence = json.loads(row["evidence_json"] or "{}")
            if int(evidence.get("binding_id") or 0) != int(binding_id):
                continue
            self.connection.execute(
                f"""
                UPDATE {table}
                SET resolution = 'resolved', resolution_note = ?,
                    resolved_at = ?, resolved_by = ?
                WHERE id = ? AND resolution <> 'resolved'
                """,
                (str(note), utc_now_iso(), str(actor), int(row["id"])),
            )

    def _record_c4_migration_anomalies(
        self, *, migration_run_id: int, findings: list[Mapping[str, Any]]
    ) -> None:
        """Keep one open C4 finding per stable subject and evidence."""

        table = self._migration("time_series_migration_anomalies")
        now = utc_now_iso()
        for finding in findings:
            evidence_json = json.dumps(finding["evidence"], sort_keys=True)
            existing = self.connection.execute(
                f"""
                SELECT id FROM {table}
                WHERE phase = 'C4' AND code = ? AND finding_key = ?
                  AND evidence_json = ? AND resolution <> 'resolved'
                LIMIT 1
                """,
                (
                    str(finding["code"]),
                    str(finding["finding_key"]),
                    evidence_json,
                ),
            ).fetchone()
            if existing is None:
                self._record_migration_anomalies(
                    migration_run_id=migration_run_id,
                    phase="C4",
                    findings=[finding],
                    now=now,
                )

    def read_time_series_migration_binding_history(
        self, binding_id: int
    ) -> dict[str, Any]:
        legacy = next(
            (
                row
                for row in self._c4_legacy_binding_rows()
                if int(row["id"]) == int(binding_id)
            ),
            None,
        )
        if legacy is None:
            raise KeyError(f"legacy binding {binding_id} not found")
        disposition = self._c4_binding_disposition(int(binding_id))
        if disposition is None or disposition["target_id"] != "retired":
            return {
                "binding_id": int(binding_id),
                "status": "active",
                "reason": None,
                "retired_at": None,
                "retired_by": None,
                "legacy_binding": normalize_source_row(legacy),
            }
        resolved = None
        for row in self.connection.execute(
            f"""
            SELECT * FROM {self._migration('time_series_migration_anomalies')}
            WHERE phase = 'C4' AND resolution = 'resolved'
            ORDER BY resolved_at DESC, id DESC
            """
        ).fetchall():
            evidence = json.loads(row["evidence_json"] or "{}")
            if int(evidence.get("binding_id") or 0) == int(binding_id):
                resolved = row
                break
        if resolved is None:
            raise MigrationControlError(
                MAPPING_CONFLICT,
                binding_id=int(binding_id),
                reason="retirement_has_no_resolved_anomaly",
            )
        return {
            "binding_id": int(binding_id),
            "status": "retired",
            "reason": str(resolved["resolution_note"]),
            "retired_at": str(resolved["resolved_at"]),
            "retired_by": str(resolved["resolved_by"]),
            "legacy_binding": normalize_source_row(legacy),
        }

    def _retire_c4_canonical_bindings(
        self, *, legacy_binding_id: int, actor: str, reason: str, occurred_at: str
    ) -> None:
        mappings = self._migration("time_series_migration_mappings")
        bindings = self.link_layer_table_names()["case_time_series_bindings"]
        events = self.link_layer_table_names()["time_series_link_events"]
        rows = self.connection.execute(
            f"""
            SELECT DISTINCT target_id FROM {mappings}
            WHERE source_kind = 'legacy_time_series'
              AND source_table = 'case_time_series_bindings'
              AND source_id = ?
              AND (target_kind = 'canonical_binding'
                   OR target_kind LIKE 'canonical_binding:%')
            ORDER BY target_id
            """,
            (str(legacy_binding_id),),
        ).fetchall()
        touched_signal_ids = []
        for mapping in rows:
            binding = self.connection.execute(
                f"SELECT * FROM {bindings} WHERE id = ?",
                (int(mapping["target_id"]),),
            ).fetchone()
            if binding is None or binding["status"] != "active":
                continue
            touched_signal_ids.append(int(binding["signal_id"]))
            next_revision = int(binding["lifecycle_revision"]) + 1
            self.connection.execute(
                f"""
                UPDATE {bindings}
                SET status = 'removed', lifecycle_revision = ?,
                    change_reason_code = 'legacy_binding_retired',
                    change_reason_text = ?, removed_at = ?, removed_by = ?,
                    updated_at = ?, updated_by = ?
                WHERE id = ? AND status = 'active'
                """,
                (
                    next_revision,
                    reason,
                    occurred_at,
                    actor,
                    occurred_at,
                    actor,
                    int(binding["id"]),
                ),
            )
            before = {
                "binding_id": int(binding["id"]),
                "legacy_binding_id": int(legacy_binding_id),
                "status": "active",
                "lifecycle_revision": int(binding["lifecycle_revision"]),
            }
            after = {
                **before,
                "status": "removed",
                "lifecycle_revision": next_revision,
            }
            self.connection.execute(
                f"""
                INSERT INTO {events} (
                    batch_id, binding_id, event_type, actor_user_id,
                    actor_identity_snapshot, actor_role_snapshot, reason_code,
                    reason_text, before_json, after_json, request_id, occurred_at
                ) VALUES (?, ?, 'removed', NULL, ?, 'migration_admin', ?, ?, ?, ?, ?, ?)
                """,
                (
                    f"migration-c4-retirement:{legacy_binding_id}",
                    int(binding["id"]),
                    actor,
                    "legacy_binding_retired",
                    reason,
                    json.dumps(before, sort_keys=True),
                    json.dumps(after, sort_keys=True),
                    f"migration-c4-retirement:{legacy_binding_id}",
                    occurred_at,
                ),
            )
        self._refresh_catalog_link_counts(touched_signal_ids)

    def retire_time_series_migration_binding(
        self, *, anomaly_id: int, actor: str, reason: str
    ) -> dict[str, Any]:
        """Explicitly retire one unresolved legacy binding without erasing it."""

        clean_actor = str(actor).strip()
        clean_reason = str(reason).strip()
        if not clean_actor or not clean_reason:
            raise ValueError("actor and retirement reason are required")
        anomalies = self._migration("time_series_migration_anomalies")
        anomaly = self.connection.execute(
            f"SELECT * FROM {anomalies} WHERE id = ?", (int(anomaly_id),)
        ).fetchone()
        if anomaly is None or anomaly["phase"] != "C4" or anomaly["severity"] != "blocking":
            raise MigrationControlError(
                "TS_MIGRATION_BINDING_ANOMALY_REQUIRED", anomaly_id=int(anomaly_id)
            )
        evidence = json.loads(anomaly["evidence_json"] or "{}")
        binding_id = int(evidence.get("binding_id") or 0)
        legacy = next(
            (
                row
                for row in self._c4_legacy_binding_rows()
                if int(row["id"]) == binding_id
            ),
            None,
        )
        if legacy is None:
            raise MigrationControlError(
                "TS_MIGRATION_BINDING_ANOMALY_REQUIRED",
                anomaly_id=int(anomaly_id),
                reason="legacy_binding_missing",
            )
        existing = self._c4_binding_disposition(binding_id)
        if existing is not None:
            if existing["target_id"] != "retired":
                raise MigrationControlError(
                    MAPPING_CONFLICT,
                    binding_id=binding_id,
                    reason="binding_disposition_changed",
                )
            with self._lock:
                with self._database_transaction():
                    self._retire_c4_canonical_bindings(
                        legacy_binding_id=binding_id,
                        actor=clean_actor,
                        reason=clean_reason,
                        occurred_at=utc_now_iso(),
                    )
            return self.read_time_series_migration_binding_history(binding_id)

        mapping_table = self._migration("time_series_migration_mappings")
        now = utc_now_iso()
        with self._lock:
            with self._database_transaction():
                self._retire_c4_canonical_bindings(
                    legacy_binding_id=binding_id,
                    actor=clean_actor,
                    reason=clean_reason,
                    occurred_at=now,
                )
                self._insert_migration_row(
                    f"""
                    INSERT INTO {mapping_table} (
                        migration_run_id, source_kind, source_table, source_id,
                        target_kind, target_id, source_hash, created_at, actor
                    ) VALUES (?, 'legacy_time_series',
                              'case_time_series_bindings', ?,
                              'binding_disposition', 'retired', ?, ?, ?)
                    """,
                    (
                        int(anomaly["migration_run_id"]),
                        str(binding_id),
                        canonical_digest(legacy),
                        now,
                        clean_actor,
                    ),
                )
                self.connection.execute(
                    f"""
                    UPDATE {anomalies}
                    SET resolution = 'resolved', resolution_note = ?,
                        resolved_at = ?, resolved_by = ?
                    WHERE id = ?
                    """,
                    (clean_reason, now, clean_actor, int(anomaly_id)),
                )
        return self.read_time_series_migration_binding_history(binding_id)

    def read_time_series_c4_cutover_gate(self) -> dict[str, Any]:
        """Account for every legacy binding before C6 may be considered."""

        legacy_bindings = {
            int(row["id"]): row for row in self._c4_legacy_binding_rows()
        }
        legacy_ids = set(legacy_bindings)
        mappings = self._migration("time_series_migration_mappings")
        canonical_roles: dict[int, set[str]] = {}
        retired_ids: set[int] = set()
        for row in self.connection.execute(
            f"""
            SELECT source_id, target_kind, target_id FROM {mappings}
            WHERE source_kind = 'legacy_time_series'
              AND source_table = 'case_time_series_bindings'
              AND (target_kind = 'canonical_binding'
                   OR target_kind LIKE 'canonical_binding:%'
                   OR target_kind = 'binding_disposition')
            ORDER BY source_id, target_kind
            """
        ).fetchall():
            source_id = int(row["source_id"])
            legacy = legacy_bindings.get(source_id)
            if legacy is None:
                continue
            if row["target_kind"] == "binding_disposition":
                if row["target_id"] == "retired":
                    retired_ids.add(source_id)
                continue
            try:
                binding = self.read_case_binding(
                    scenario_id=int(legacy["scenario_id"]),
                    variant_id=int(legacy["case_input_variant_id"]),
                    binding_id=int(row["target_id"]),
                )
            except (KeyError, BindingMutationError, LinkableObjectError):
                continue
            if binding["status"] == "active" and binding["state"] in {
                "valid_current",
                "valid_pinned",
            }:
                canonical_roles.setdefault(source_id, set()).add(
                    str(binding["binding_role"]["key"])
                )
        canonical_ids: set[int] = set()
        for binding_id, legacy in legacy_bindings.items():
            try:
                expected_roles = set(self._c4_binding_role_keys(legacy))
            except MigrationControlError:
                continue
            if expected_roles <= canonical_roles.get(binding_id, set()):
                canonical_ids.add(binding_id)
        resolved_retirements = set()
        for row in self.connection.execute(
            f"""
            SELECT evidence_json, resolution_note, resolved_by
            FROM {self._migration('time_series_migration_anomalies')}
            WHERE phase = 'C4' AND severity = 'blocking'
              AND resolution = 'resolved'
            """
        ).fetchall():
            evidence = json.loads(row["evidence_json"] or "{}")
            binding_id = int(evidence.get("binding_id") or 0)
            if (
                binding_id in legacy_ids
                and str(row["resolution_note"] or "").strip()
                and str(row["resolved_by"] or "").strip()
            ):
                resolved_retirements.add(binding_id)
        retired_ids &= resolved_retirements
        open_blocking = int(
            self.connection.execute(
                f"""
                SELECT COUNT(*) AS row_count
                FROM {self._migration('time_series_migration_anomalies')}
                WHERE phase = 'C4' AND severity = 'blocking'
                  AND resolution <> 'resolved'
                """
            ).fetchone()["row_count"]
        )
        accounted = canonical_ids | retired_ids
        unaccounted = sorted(legacy_ids - accounted)
        return {
            "active_bindings": len(legacy_ids),
            "revalidated_bindings": len(canonical_ids),
            "retired_bindings": len(retired_ids),
            "unaccounted_binding_ids": unaccounted,
            "open_blocking_anomalies": open_blocking,
            "cutover_ready": not unaccounted and open_blocking == 0,
        }

    def backfill_time_series_c4(self, *, actor: str) -> dict[str, Any]:
        """Resolve and reauthorize every current legacy binding."""

        self._require_proven_migration_phase("C3")
        opened = self.open_migration_phase(phase="C4", actor=actor)
        run_id = int(opened["migration_run_id"])
        output_tables = tuple(self.link_layer_table_names().values())
        before = self._migration_table_evidence(output_tables)
        results = []
        association_results = []
        retired = []
        findings = []
        mapping_changes = 0
        legacy_bindings = self._c4_legacy_binding_rows()
        with self._lock:
            for legacy_signal in self._c4_legacy_signal_rows():
                try:
                    with self._database_transaction():
                        associations = self._c4_migrate_signal_associations(
                            legacy_signal=legacy_signal,
                            migration_run_id=run_id,
                        )
                except MigrationControlError as error:
                    # A consumed signal is reported with the complete binding
                    # context below.  Unused bad evidence is informational.
                    consumed = self.connection.execute(
                        """
                        SELECT 1 FROM case_time_series_bindings
                        WHERE time_series_set_id = ? AND signal_key = ? LIMIT 1
                        """,
                        (
                            int(legacy_signal["time_series_set_id"]),
                            str(legacy_signal["signal_key"]),
                        ),
                    ).fetchone()
                    if consumed is None:
                        findings.append(
                            {
                                "code": error.code,
                                "severity": "informational",
                                "finding_key": (
                                    f"{error.code}:signal={int(legacy_signal['id'])}"
                                ),
                                "evidence": {
                                    "signal_id": int(legacy_signal["id"]),
                                    "project_id": int(legacy_signal["project_id"]),
                                    **dict(error.context),
                                },
                                "explained": False,
                                "explanation": "",
                            }
                        )
                    continue
                for association in associations:
                    association_results.append(association)
                    mapping_changes += self._record_c4_association_mapping(
                        result=association, migration_run_id=run_id
                    )
            for legacy in legacy_bindings:
                disposition = self._c4_binding_disposition(int(legacy["id"]))
                if disposition is not None and disposition["target_id"] == "retired":
                    retired.append(
                        self.read_time_series_migration_binding_history(
                            int(legacy["id"])
                        )
                    )
                    continue
                try:
                    with self._database_transaction():
                        binding_results = self._c4_migrate_binding(
                            legacy=legacy, migration_run_id=run_id
                        )
                except MigrationControlError as error:
                    evidence = {
                        "binding_id": int(legacy["id"]),
                        "variant_id": int(legacy["case_input_variant_id"]),
                        "project_id": int(legacy["project_id"]),
                        "legacy_binding": normalize_source_row(legacy),
                        **dict(error.context),
                    }
                    findings.append(
                        {
                            "code": error.code,
                            "severity": "blocking",
                            "finding_key": (
                                f"{error.code}:binding={int(legacy['id'])}"
                            ),
                            "evidence": evidence,
                            "explained": False,
                            "explanation": "",
                        }
                    )
                    continue
                results.extend(binding_results)
                for result in binding_results:
                    if result["catalog_association_id"] is not None:
                        mapping_changes += self._record_c4_association_mapping(
                            result={
                                **result,
                                "association_id": result["catalog_association_id"],
                            },
                            migration_run_id=run_id,
                        )
                    mapping = self.record_migration_mapping(
                        migration_run_id=run_id,
                        source_kind="legacy_time_series",
                        source_table="case_time_series_bindings",
                        source_id=str(legacy["id"]),
                        target_kind=result["mapping_target_kind"],
                        target_id=str(result["binding_id"]),
                        source_hash=canonical_digest(legacy),
                    )
                    mapping_changes += mapping["status"] == "created"
                self._resolve_previous_c4_binding_anomalies(
                    binding_id=int(legacy["id"]),
                    actor=migration_actor(run_id),
                    note=f"Revalidated by C4 migration run {run_id}.",
                )

        after = self._migration_table_evidence(output_tables)
        created_rows = sum(
            after[table]["row_count"] - before[table]["row_count"]
            for table in output_tables
        )
        if findings:
            self._record_c4_migration_anomalies(
                migration_run_id=run_id, findings=findings
            )
        gate = self.read_time_series_c4_cutover_gate()
        manifest = {
            "manifest_version": 1,
            "phase": "C4",
            "source_engine": self.database_backend,
            "bindings": [
                {
                    key: result[key]
                    for key in (
                        "binding_id",
                        "signal_id",
                        "linkable_object_id",
                        "binding_role_key",
                        "set_revision_id",
                        "catalog_association_id",
                    )
                }
                for result in results
            ],
            "associations": [
                {
                    key: result[key]
                    for key in (
                        "association_id",
                        "signal_id",
                        "linkable_object_id",
                        "binding_role_key",
                    )
                }
                for result in association_results
            ],
            "outputs": after,
            "anomalies": [
                {
                    "code": finding["code"],
                    "severity": finding["severity"],
                    "finding_key": finding["finding_key"],
                    "evidence": finding["evidence"],
                }
                for finding in findings
            ],
            "blocking_anomalies": gate["open_blocking_anomalies"],
            "active_bindings": len(legacy_bindings),
            "revalidated_bindings": gate["revalidated_bindings"],
            "retired_bindings": gate["retired_bindings"],
            "cutover_ready": gate["cutover_ready"],
        }
        self._finish_migration_run(
            migration_run_id=run_id,
            status="proven" if gate["cutover_ready"] else "stopped",
            manifest=manifest,
        )
        blocking_findings = [
            finding for finding in findings if finding["severity"] == "blocking"
        ]
        if blocking_findings:
            raise MigrationPhaseStopped(
                C4_STOPPED,
                migration_run_id=run_id,
                findings=blocking_findings,
                migrated_binding_ids=[result["binding_id"] for result in results],
            )
        return {
            **opened,
            "status": "proven",
            "created_rows": created_rows,
            "mapping_changes": int(mapping_changes),
            "manifest": manifest,
            "manifest_digest": canonical_digest(manifest),
        }

    # -- C5 shadow reads, settled source and convergence (TS7-018) --------
    #
    # C5 proves the canonical reads are right before they serve traffic, and
    # proves the migrator has stopped moving.  It compares and it records; it
    # never repairs.  Chapter 9.10 gives reconciliation the job of detecting
    # divergence, and chapter 10.2 makes a single difference a rollback
    # trigger rather than a finding to triage later.

    def _c5_unit_symbols(self) -> dict[str, str]:
        return {
            str(row["unit_key"]): str(row["symbol"])
            for row in self.connection.execute(
                "SELECT unit_key, symbol FROM measurement_units"
            ).fetchall()
        }

    def _c5_legacy_current_revision(self, set_id: int):
        return self.connection.execute(
            """
            SELECT id, revision_number, content_hash
            FROM time_series_set_revisions
            WHERE time_series_set_id = ?
            ORDER BY revision_number DESC, id DESC
            LIMIT 1
            """,
            (int(set_id),),
        ).fetchone()

    def _c5_mapped_target(
        self, *, source_table: str, source_id: str, target_kind: str
    ) -> str | None:
        row = self.connection.execute(
            f"""
            SELECT target_id
            FROM {self._migration('time_series_migration_mappings')}
            WHERE source_kind = 'legacy_time_series' AND source_table = ?
              AND source_id = ? AND target_kind = ?
            """,
            (str(source_table), str(source_id), str(target_kind)),
        ).fetchone()
        return None if row is None else str(row["target_id"])

    def _c5_legacy_set_view(self, *, project_id: int, set_id: int) -> dict[str, Any]:
        """The legacy read of one set, reduced to what parity compares."""

        legacy = self.get_time_series_set(int(project_id), int(set_id))
        revision = self._c5_legacy_current_revision(set_id)
        values: dict[str, dict[int, float]] = {}
        for row in legacy["values"]:
            values.setdefault(str(row["signal_key"]), {})[
                int(row["period_index"])
            ] = float(row["value_numeric"])
        return {
            "semantics": {
                "series_keys": sorted(
                    str(signal["signal_key"]) for signal in legacy["signals"]
                ),
                "units": {
                    str(signal["signal_key"]): str(signal["unit"])
                    for signal in legacy["signals"]
                },
                "data_kind": str(legacy["data_kind"]),
                "timezone": str(legacy["timezone"]),
            },
            "counts": {
                "signal_count": int(legacy["signal_count"]),
                "period_count": int(legacy["period_count"]),
                "value_count": len(legacy["values"]),
            },
            "values": values,
            "hashes": {"content_hash": str(legacy["content_hash"])},
            "authorization": {
                "project_id": int(legacy["project_id"]),
                "status": str(legacy["status"]),
                "name": str(legacy["name"]),
                "version_number": int(legacy["version_number"]),
                "version_label": str(legacy["version_label"]),
            },
            "lineage": {
                "set_id": str(int(set_id)),
                "revision_id": None if revision is None else str(revision["id"]),
                "revision_number": (
                    None if revision is None else int(revision["revision_number"])
                ),
            },
        }

    def _c5_canonical_set_view(self, set_id: int) -> dict[str, Any]:
        """The canonical read of the same set, in the same reduced shape."""

        canonical = self.read_canonical_set(int(set_id))
        current = canonical["current_revision"]
        if current is None:
            raise MigrationControlError(
                MIGRATION_ANOMALY_CODES["revision_unmaterialized"],
                set_id=int(set_id),
                reason="no_current_revision",
            )
        revision = self.read_canonical_revision(int(current["id"]))
        symbols = self._c5_unit_symbols()
        period_indexes = [
            int(period["period_index"]) for period in revision["periods"]
        ]
        values = {
            str(series_key): {
                period_indexes[position]: float(value)
                for position, value in enumerate(column)
            }
            for series_key, column in revision["values"].items()
        }
        legacy_revision = self._c5_legacy_current_revision(set_id)
        return {
            "semantics": {
                "series_keys": sorted(
                    str(signal["series_key"]) for signal in revision["signals"]
                ),
                "units": {
                    str(signal["series_key"]): symbols.get(
                        str(signal["unit_key"]), str(signal["unit_key"])
                    )
                    for signal in revision["signals"]
                },
                "data_kind": str(revision["data_class_key"]),
                "timezone": str(revision["timezone"]),
            },
            "counts": {
                "signal_count": int(revision["signal_count"]),
                "period_count": int(revision["period_count"]),
                "value_count": int(revision["value_count"]),
            },
            "values": values,
            "hashes": {"content_hash": str(revision["legacy_content_hash"])},
            "authorization": {
                "project_id": int(canonical["owner_project_id"]),
                "status": str(canonical["status"]),
                "name": str(canonical["name"]),
                "version_number": int(canonical["version_number"]),
                "version_label": str(canonical["version_label"]),
            },
            "lineage": {
                "set_id": self._c5_mapped_target(
                    source_table="time_series_sets",
                    source_id=str(int(set_id)),
                    target_kind="canonical_set",
                ),
                "revision_id": (
                    None
                    if legacy_revision is None
                    else self._c5_mapped_target(
                        source_table="time_series_set_revisions",
                        source_id=str(legacy_revision["id"]),
                        target_kind="canonical_revision",
                    )
                ),
                "revision_number": int(revision["revision_number"]),
            },
        }

    def _c5_shadow_difference(
        self, *, subject: str, dimension: str, legacy: Any, canonical: Any
    ) -> dict[str, Any]:
        code = C5_ANOMALY_CODES["shadow_difference"]
        return {
            "code": code,
            "severity": "blocking",
            "finding_key": f"{code}:{subject}:{dimension}",
            "evidence": {
                "subject": subject,
                "dimension": dimension,
                "legacy": legacy,
                "canonical": canonical,
            },
            "explained": False,
            "explanation": "",
        }

    def _c5_compare_migrated_set(self, *, set_id: int, project_id: int):
        """Compare one migrated set on all six dimensions of chapter 10.2."""

        subject = f"set:{int(set_id)}"
        try:
            legacy_view = self._c5_legacy_set_view(
                project_id=project_id, set_id=set_id
            )
        except KeyError as error:
            return [
                self._c5_shadow_difference(
                    subject=subject,
                    dimension="lineage",
                    legacy={"readable": False, "reason": str(error)},
                    canonical={"readable": True, "set_id": int(set_id)},
                )
            ]
        try:
            canonical_view = self._c5_canonical_set_view(set_id)
        except MigrationControlError as error:
            return [
                self._c5_shadow_difference(
                    subject=subject,
                    dimension="counts",
                    legacy=legacy_view["counts"],
                    canonical={"error": error.code, **dict(error.context)},
                )
            ]
        differences = []
        for dimension in C5_SHADOW_DIMENSIONS:
            legacy_side = legacy_view[dimension]
            canonical_side = canonical_view[dimension]
            if legacy_side != canonical_side:
                differences.append(
                    self._c5_shadow_difference(
                        subject=subject,
                        dimension=dimension,
                        legacy=legacy_side,
                        canonical=canonical_side,
                    )
                )
        return differences

    def _c5_set_object_families(self) -> dict[int, set[str]]:
        register = self._linkable("linkable_objects")
        signals = self._canonical("time_series_signals")
        families: dict[int, set[str]] = {}
        for link_table in (
            self.link_layer_table_names()["time_series_catalog_associations"],
            self.link_layer_table_names()["case_time_series_bindings"],
        ):
            for row in self.connection.execute(
                f"""
                SELECT DISTINCT signal.time_series_set_id AS set_id,
                       registered.object_kind AS object_kind
                FROM {link_table} AS link
                JOIN {signals} AS signal ON signal.id = link.signal_id
                JOIN {register} AS registered
                  ON registered.id = link.linkable_object_id
                WHERE link.status = 'active'
                """
            ).fetchall():
                families.setdefault(int(row["set_id"]), set()).add(
                    str(row["object_kind"])
                )
        return families

    def _c5_sample(self, *, set_ids=None) -> dict[str, Any]:
        """The recorded, stratified selection the shadow read compares.

        Every canonical set is stratified by ``series_kind``, its state and the
        family of the objects it is linked to, so the manifest shows which
        strata the source has and which of them the sample reached. A narrower
        explicit selection is allowed and is then checked against that map.
        """

        families = self._c5_set_object_families()
        source_sets = []
        for row in self.connection.execute(
            f"""
            SELECT the_set.id AS id,
                   the_set.owner_project_id AS owner_project_id,
                   the_set.series_kind AS series_kind,
                   the_set.status AS status,
                   COALESCE(revision.state, 'unmaterialized') AS revision_state
            FROM {self._canonical('time_series_sets')} AS the_set
            LEFT JOIN {self._canonical('time_series_set_revisions')} AS revision
              ON revision.id = the_set.current_revision_id
            ORDER BY the_set.id
            """
        ).fetchall():
            set_id = int(row["id"])
            source_sets.append(
                {
                    "set_id": set_id,
                    "project_id": int(row["owner_project_id"]),
                    "series_kind": str(row["series_kind"]),
                    "set_state": f"{row['status']}/{row['revision_state']}",
                    "object_families": sorted(families.get(set_id) or {"unlinked"}),
                    "migrated": self._c5_mapped_target(
                        source_table="time_series_sets",
                        source_id=str(set_id),
                        target_kind="canonical_set",
                    )
                    is not None,
                }
            )
        if set_ids is None:
            selection_mode = "all"
            selected = {entry["set_id"] for entry in source_sets}
        else:
            selection_mode = "explicit"
            selected = {int(set_id) for set_id in set_ids}
        strata: dict[str, list[int]] = {}
        for entry in source_sets:
            for family in entry["object_families"]:
                key = f"{entry['series_kind']}|{entry['set_state']}|{family}"
                strata.setdefault(key, []).append(entry["set_id"])
        sampled = [entry for entry in source_sets if entry["set_id"] in selected]
        binding_ids = [
            int(row["id"])
            for row in self.connection.execute(
                """
                SELECT id, time_series_set_id FROM case_time_series_bindings
                ORDER BY id
                """
            ).fetchall()
            if int(row["time_series_set_id"]) in selected
        ]
        return {
            "sample_version": C5_SAMPLE_VERSION,
            "selection_mode": selection_mode,
            "set_ids": [entry["set_id"] for entry in sampled],
            "binding_ids": binding_ids,
            "sets": sampled,
            "strata": {
                key: {
                    "source_set_ids": source_ids,
                    "sampled_set_ids": [
                        set_id for set_id in source_ids if set_id in selected
                    ],
                }
                for key, source_ids in sorted(strata.items())
            },
            "series_kinds": sorted({entry["series_kind"] for entry in sampled}),
            "set_states": sorted({entry["set_state"] for entry in sampled}),
            "object_families": sorted(
                {
                    family
                    for entry in sampled
                    for family in entry["object_families"]
                }
            ),
        }

    def _migration_mapping_count(self) -> int:
        return int(
            self.connection.execute(
                "SELECT COUNT(*) AS total FROM "
                + self._migration("time_series_migration_mappings")
            ).fetchone()["total"]
        )

    def _c5_canonical_binding_ids(self, legacy_binding_id: int) -> list[int]:
        return [
            int(row["target_id"])
            for row in self.connection.execute(
                f"""
                SELECT DISTINCT target_id
                FROM {self._migration('time_series_migration_mappings')}
                WHERE source_kind = 'legacy_time_series'
                  AND source_table = 'case_time_series_bindings'
                  AND source_id = ?
                  AND (target_kind = 'canonical_binding'
                       OR target_kind LIKE 'canonical_binding:%')
                ORDER BY target_id
                """,
                (str(int(legacy_binding_id)),),
            ).fetchall()
        ]

    def _c5_binding_comparison(self, sample: Mapping[str, Any]) -> dict[str, Any]:
        """Every sampled legacy binding, against what the canonical read serves.

        The C4 receipt already decides which legacy bindings are backed by an
        active canonical row plus validation and which were retired on the
        record; C5 re-reads it here rather than re-deriving it, and then checks
        the one thing the receipt cannot: that each canonical binding still
        points at the legacy set the reference named.
        """

        gate = self.read_time_series_c4_cutover_gate()
        legacy_rows = {
            int(row["id"]): row for row in self._c4_legacy_binding_rows()
        }
        unaccounted = set(gate["unaccounted_binding_ids"])
        findings = []
        compared = 0
        sampled_unaccounted = []
        for binding_id in sample["binding_ids"]:
            legacy = legacy_rows.get(int(binding_id))
            if legacy is None:
                continue
            subject = f"binding:{int(binding_id)}"
            if int(binding_id) in unaccounted:
                sampled_unaccounted.append(int(binding_id))
                findings.append(
                    self._c5_shadow_difference(
                        subject=subject,
                        dimension="lineage",
                        legacy={"accounted": True, "legacy_binding_id": int(binding_id)},
                        canonical={"accounted": False, "canonical_binding_ids": []},
                    )
                )
                continue
            compared += 1
            for canonical_id in self._c5_canonical_binding_ids(int(binding_id)):
                try:
                    binding = self.read_case_binding(
                        scenario_id=int(legacy["scenario_id"]),
                        variant_id=int(legacy["case_input_variant_id"]),
                        binding_id=int(canonical_id),
                    )
                except (KeyError, BindingMutationError, LinkableObjectError):
                    continue
                if binding["status"] != "active":
                    continue
                if int(binding["time_series_set_id"]) != int(
                    legacy["time_series_set_id"]
                ):
                    findings.append(
                        self._c5_shadow_difference(
                            subject=subject,
                            dimension="values",
                            legacy={
                                "time_series_set_id": int(
                                    legacy["time_series_set_id"]
                                )
                            },
                            canonical={
                                "canonical_binding_id": int(canonical_id),
                                "time_series_set_id": int(
                                    binding["time_series_set_id"]
                                ),
                            },
                        )
                    )
        if gate["open_blocking_anomalies"]:
            findings.append(
                self._c5_shadow_difference(
                    subject="bindings",
                    dimension="lineage",
                    legacy={"open_blocking_anomalies": 0},
                    canonical={
                        "open_blocking_anomalies": int(
                            gate["open_blocking_anomalies"]
                        )
                    },
                )
            )
        return {
            "state": {
                "compared": compared,
                "unaccounted_binding_ids": sorted(sampled_unaccounted),
                "open_blocking_anomalies": int(gate["open_blocking_anomalies"]),
                "retired_bindings": int(gate["retired_bindings"]),
            },
            "findings": findings,
        }

    def _c5_sample_coverage_findings(self, sample: Mapping[str, Any]):
        """A stratum the source has and the sample does not reach is a gap.

        The wide sample of chapter 10.2 is what makes "no difference" mean
        anything, so an explicit narrower selection has to prove it still
        reaches every set state, object family and ``series_kind`` the source
        actually carries.
        """

        code = C5_ANOMALY_CODES["sample_incomplete"]
        findings = []
        for stratum, coverage in sample["strata"].items():
            if coverage["source_set_ids"] and not coverage["sampled_set_ids"]:
                findings.append(
                    {
                        "code": code,
                        "severity": "blocking",
                        "finding_key": f"{code}:{stratum}",
                        "evidence": {
                            "stratum": stratum,
                            "selection_mode": sample["selection_mode"],
                            "source_set_ids": coverage["source_set_ids"],
                        },
                        "explained": False,
                        "explanation": "",
                    }
                )
        return findings

    def _c5_registry_comparison(self) -> dict[str, Any]:
        """Compare the persisted projection against the Python signal registry.

        Chapter 10.4 makes this the last check before the database becomes
        authoritative: while ``TIME_SERIES_SIGNAL_CATALOG`` is still the seed
        contract, a projection that shows a different unit for a registered key
        is a divergence that blocks the phase, never a value to reconcile.
        """

        symbols = self._c5_unit_symbols()
        entries = self._projection("time_series_catalog_entries")
        code = C5_ANOMALY_CODES["registry_divergence"]
        findings = []
        compared = 0
        unregistered = set()
        for row in self.connection.execute(
            f"""
            SELECT signal_id, series_key, unit_key FROM {entries}
            ORDER BY signal_id
            """
        ).fetchall():
            series_key = str(row["series_key"])
            definition = TIME_SERIES_SIGNAL_CATALOG.get(series_key)
            if definition is None:
                unregistered.add(series_key)
                continue
            compared += 1
            projected_unit = symbols.get(
                str(row["unit_key"]), str(row["unit_key"])
            )
            if projected_unit != definition.unit:
                findings.append(
                    {
                        "code": code,
                        "severity": "blocking",
                        "finding_key": f"{code}:signal={int(row['signal_id'])}",
                        "evidence": {
                            "signal_id": int(row["signal_id"]),
                            "series_key": series_key,
                            "registry_unit": definition.unit,
                            "projected_unit": projected_unit,
                        },
                        "explained": False,
                        "explanation": "",
                    }
                )
        return {
            "state": {
                "contract_entries": len(TIME_SERIES_SIGNAL_CATALOG),
                "compared_entries": compared,
                "unregistered_series_keys": sorted(unregistered),
            },
            "findings": findings,
        }

    def _c5_projection_comparison(self) -> dict[str, Any]:
        """Reconcile the persisted projection against the canonical model.

        A stale or missing row is a canonical read that no longer answers what
        the source says, so it is a shadow difference on counts. A leaked
        ``object_specific`` row is reported on its own dimension: the global
        list must never be able to see one (chapter 10.10).
        """

        divergence = self.catalog_projection_divergence()
        findings = []
        if divergence["object_specific"]:
            findings.append(
                self._c5_shadow_difference(
                    subject="projection:inputs",
                    dimension="authorization",
                    legacy={"object_specific": []},
                    canonical={"object_specific": divergence["object_specific"]},
                )
            )
        drifted = {
            key: divergence[key] for key in ("missing", "unexpected", "stale")
        }
        if any(drifted.values()):
            findings.append(
                self._c5_shadow_difference(
                    subject="projection:inputs",
                    dimension="counts",
                    legacy={key: [] for key in drifted},
                    canonical={**drifted, "converged": False},
                )
            )
        return {
            "state": {
                "section": divergence["section"],
                "converged": bool(divergence["converged"]),
                "content_hash": self._catalog_projection_content_hash(
                    self._projection("time_series_catalog_entries")
                ),
            },
            "findings": findings,
        }

    def _c5_settle_source(self) -> dict[str, Any]:
        """Drain the dirty-roots journal so the comparison sees a settled source.

        Only the resulting state reaches the manifest: how many roots this run
        happened to drain is run-local, and a convergent repeat must reproduce
        the same document.
        """

        pending = self.read_pending_dirty_roots()
        drained = {"drained_count": 0}
        if pending:
            drained = self.drain_legacy_dirty_roots(
                through_sequence=max(
                    int(entry["sequence_number"]) for entry in pending
                )
            )
        remaining = self.read_pending_dirty_roots()
        findings = []
        if remaining:
            code = C5_ANOMALY_CODES["dirty_roots_pending"]
            findings.append(
                {
                    "code": code,
                    "severity": "blocking",
                    "finding_key": f"{code}:journal",
                    "evidence": {
                        "pending_dirty_roots": len(remaining),
                        "sequence_numbers": [
                            int(entry["sequence_number"]) for entry in remaining
                        ],
                    },
                    "explained": False,
                    "explanation": "",
                }
            )
        return {
            "drained_count": int(drained["drained_count"]),
            "state": {
                "pending_dirty_roots": len(remaining),
                "mutation_pause": "taken",
            },
            "findings": findings,
        }

    def verify_time_series_c5_shadow(
        self, *, actor: str, set_ids=None
    ) -> dict[str, Any]:
        """Compare canonical and legacy reads in shadow, and prove convergence."""

        self._require_proven_migration_phase("C4")
        opened = self.open_migration_phase(phase="C5", actor=actor)
        run_id = int(opened["migration_run_id"])
        output_tables = (
            tuple(self.canonical_table_names().values())
            + tuple(self.link_layer_table_names().values())
            + tuple(self.catalog_projection_table_names().values())
        )
        before = self._migration_table_evidence(output_tables)
        mappings_before = self._migration_mapping_count()
        findings = []
        # The comparison is only worth taking against a source that has stopped
        # moving, so the pause, the drain and every read happen together.
        self.begin_legacy_mutation_pause(
            actor=actor, reason=f"C5 shadow comparison (migration run {run_id})"
        )
        try:
            settled = self._c5_settle_source()
            findings.extend(settled["findings"])
            registry = self._c5_registry_comparison()
            findings.extend(registry["findings"])
            projection = self._c5_projection_comparison()
            findings.extend(projection["findings"])
            sample = self._c5_sample(set_ids=set_ids)
            findings.extend(self._c5_sample_coverage_findings(sample))
            compared_sets = 0
            for entry in sample["sets"]:
                if not entry["migrated"]:
                    continue
                compared_sets += 1
                findings.extend(
                    self._c5_compare_migrated_set(
                        set_id=entry["set_id"], project_id=entry["project_id"]
                    )
                )
            bindings = self._c5_binding_comparison(sample)
            findings.extend(bindings["findings"])
        finally:
            self.release_legacy_mutation_pause(actor=actor)

        after = self._migration_table_evidence(output_tables)
        created_rows = sum(
            after[table]["row_count"] - before[table]["row_count"]
            for table in output_tables
        )
        manifest = {
            "manifest_version": 1,
            "phase": "C5",
            "source_engine": self.database_backend,
            "sample": sample,
            "shadow_read": {
                "dimensions": list(C5_SHADOW_DIMENSIONS),
                "compared_sets": compared_sets,
            },
            "settled_source": settled["state"],
            "registry": registry["state"],
            "projection": projection["state"],
            "bindings": bindings["state"],
            "differences": [
                {
                    "code": finding["code"],
                    "finding_key": finding["finding_key"],
                    "evidence": finding["evidence"],
                }
                for finding in findings
            ],
            "outputs": after,
        }
        if findings:
            self._record_migration_anomalies(
                migration_run_id=run_id,
                phase="C5",
                findings=findings,
                now=utc_now_iso(),
            )
        self._finish_migration_run(
            migration_run_id=run_id,
            status="stopped" if findings else "proven",
            manifest=manifest,
        )
        if findings:
            raise MigrationPhaseStopped(
                C5_STOPPED,
                migration_run_id=run_id,
                findings=findings,
                rollback_trigger=True,
            )
        return {
            **opened,
            "status": "proven",
            "created_rows": created_rows,
            "mapping_changes": self._migration_mapping_count() - mappings_before,
            "drained_dirty_roots": settled["drained_count"],
            "manifest": manifest,
            "manifest_digest": canonical_digest(manifest),
        }

    def _write_recovery_copy(self, copy_directory) -> dict[str, Any]:
        """A consistent logical copy of the closure C0 has to be able to restore."""

        directory = Path(copy_directory)
        directory.mkdir(parents=True, exist_ok=True)
        document = {
            "copy_version": C0_COPY_VERSION,
            "source_engine": self.database_backend,
            "tables": {
                table: [
                    {
                        str(column): transport_value(row[column])
                        for column in row.keys()
                    }
                    for row in self.connection.execute(
                        f"SELECT * FROM {table} ORDER BY id"
                    ).fetchall()
                ]
                for table in C0_RESTORE_TABLES
            },
        }
        path = directory / C0_COPY_FILENAME
        path.write_text(
            json.dumps(document, sort_keys=True, ensure_ascii=False),
            encoding="utf-8",
        )
        return {"path": path, "digest": canonical_digest(document), "document": document}

    def prove_recovery_copy(self, copy_path, *, restore_directory=None) -> dict[str, Any]:
        """Restore the copy and prove it reproduces the inventory of the source.

        The restore always lands on SQLite: what C0 has to prove is that the
        copy is complete and reloadable, and a scratch engine keeps the proof
        from depending on a second production database being available.
        """

        path = Path(copy_path)
        document = json.loads(path.read_text(encoding="utf-8"))
        target_directory = Path(restore_directory or path.parent / "restore")
        target_directory.mkdir(parents=True, exist_ok=True)
        target_path = target_directory / "c0_restore.sqlite3"
        if target_path.exists():
            target_path.unlink()

        source_inventory = self._c0_inventory()
        restore = AnalystStore(f"sqlite:///{target_path.as_posix()}")
        try:
            for table in C0_RESTORE_TABLES:
                for row in document["tables"].get(table, []):
                    columns = sorted(row)
                    restore.connection.execute(
                        f"INSERT INTO {table} ({', '.join(columns)}) "
                        f"VALUES ({', '.join('?' for _ in columns)})",
                        tuple(restored_value(row[column]) for column in columns),
                    )
            restore.connection.commit()
            restored_inventory = restore._c0_inventory()
        except sqlite3.DatabaseError as error:
            restore.close()
            raise MigrationControlError(
                C0_RESTORE_NOT_PROVEN,
                reason="restore_failed",
                detail=str(error),
                divergent_tables=[],
            ) from error
        else:
            restore.close()

        divergent = sorted(
            table
            for table in C0_INVENTORY_TABLES
            if restored_inventory[table] != source_inventory[table]
        )
        if divergent:
            raise MigrationControlError(
                C0_RESTORE_NOT_PROVEN,
                reason="inventory_divergence",
                divergent_tables=divergent,
                source_inventory_digest=canonical_digest(source_inventory),
                restored_inventory_digest=canonical_digest(restored_inventory),
            )
        return {
            "proven": True,
            "restore_engine": "sqlite",
            "source_inventory_digest": canonical_digest(source_inventory),
            "restored_inventory_digest": canonical_digest(restored_inventory),
        }

    def verify_c0_manifest(self, *, manifest: Mapping[str, Any], manifest_signature: str) -> bool:
        """True when this deployment signed exactly this manifest document."""

        return manifest_signature_matches(
            canonical_digest(dict(manifest)),
            manifest_signature,
            secret=self._migration_manifest_secret,
        )

    def take_c0_recovery_point(
        self,
        *,
        actor: str,
        copy_directory,
        explanations: Mapping[str, str] | None = None,
    ) -> dict[str, Any]:
        """Inventory the legacy source, sign its manifest and prove the copy."""

        with self._lock:
            now = utc_now_iso()
            run_id = self._insert_migration_row(
                f"""
                INSERT INTO {self._migration('time_series_migration_runs')} (
                    control_version, phase, status, source_engine, watermark,
                    started_at, started_by, actor
                )
                VALUES (?, 'C0', 'running', ?, ?, ?, ?, ?)
                """,
                (
                    MIGRATION_CONTROL_VERSION,
                    self.database_backend,
                    now,
                    now,
                    actor,
                    migration_actor(0),
                ),
            )
            technical_actor = migration_actor(run_id)
            self.connection.execute(
                f"""
                UPDATE {self._migration('time_series_migration_runs')}
                SET actor = ?
                WHERE id = ?
                """,
                (technical_actor, run_id),
            )
            # The watermark belongs to the run, not to the manifest: a repeated
            # C0 over an unchanged source must reproduce the same document, and
            # a clock reading would make every repetition differ.
            differences, findings = self._c0_structural_differences(explanations)
            copy = self._write_recovery_copy(copy_directory)
            proof = self.prove_recovery_copy(
                copy["path"], restore_directory=Path(copy_directory) / "restore"
            )
            manifest = {
                "manifest_version": C0_MANIFEST_VERSION,
                "phase": "C0",
                "source_engine": self.database_backend,
                "inventory": self._c0_inventory(),
                "structural_differences": differences,
                "executable_variants": self._c0_executable_variants(findings),
                # The path is deliberately absent: two recovery points taken
                # from the same source into different directories are the same
                # manifest, and the copy is identified by its digest.
                "recovery_point": {
                    "copy_version": C0_COPY_VERSION,
                    "copy_digest": copy["digest"],
                    **proof,
                },
            }
            manifest_digest = canonical_digest(manifest)
            self._record_migration_anomalies(
                migration_run_id=run_id, phase="C0", findings=findings, now=now
            )
            unexplained = [
                finding for finding in findings if not finding["explained"]
            ]
            if unexplained:
                # Chapter 10.2: the difference is recorded as evidence and the
                # phase stops. A stopped run is never signed, so no later phase
                # can mistake it for a recovery point.
                self.connection.execute(
                    f"""
                    UPDATE {self._migration('time_series_migration_runs')}
                    SET status = 'stopped',
                        manifest_json = ?,
                        manifest_digest = ?,
                        finished_at = ?
                    WHERE id = ?
                    """,
                    (
                        json.dumps(manifest, sort_keys=True),
                        manifest_digest,
                        utc_now_iso(),
                        run_id,
                    ),
                )
                self.connection.commit()
                raise MigrationPhaseStopped(
                    C0_STOPPED, migration_run_id=run_id, findings=findings
                )
            signature = sign_manifest(
                manifest_digest, secret=self._migration_manifest_secret
            )
            self.connection.execute(
                f"""
                UPDATE {self._migration('time_series_migration_runs')}
                SET status = 'proven',
                    manifest_json = ?,
                    manifest_digest = ?,
                    manifest_signature = ?,
                    finished_at = ?
                WHERE id = ?
                """,
                (
                    json.dumps(manifest, sort_keys=True),
                    manifest_digest,
                    signature,
                    utc_now_iso(),
                    run_id,
                ),
            )
            self.connection.commit()
            return {
                "migration_run_id": run_id,
                "status": "proven",
                "actor": technical_actor,
                "copy_path": str(copy["path"]),
                "manifest": manifest,
                "manifest_digest": manifest_digest,
                "manifest_signature": signature,
            }

    # -- Closed register of linkable objects (TS7-003) ----------------------
    #
    # Every link target - the project ``system`` slot, an electrical component,
    # a hydraulic system, node, reach, plant or unit - is registered once, with
    # a real typed foreign key into its subtype table. The parent and the
    # subtype are written in the same transaction, and the object type is
    # derived from the real object: the caller never declares it.

    def _linkable(self, logical: str) -> str:
        return linkable_object_table_name(logical, self.database_backend)

    def _read_linkable_subtype(self, object_kind: str, subtype_id: int):
        return self.connection.execute(
            subtype_lookup_sql(object_kind, self.linkable_object_table_names()),
            (subtype_id,),
        ).fetchone()

    def _linkable_object_type(self, object_type_key: str):
        return self.connection.execute(
            """
            SELECT id, object_type_key, object_kind, status
            FROM linkable_object_types
            WHERE object_type_key = ? AND status = 'active'
            """,
            (object_type_key,),
        ).fetchone()

    def register_linkable_object(
        self,
        *,
        project_id: int,
        object_kind: str,
        subtype_id: int,
        actor: str = "internal_analyst",
    ) -> dict[str, Any]:
        """Register one real object as a link target, or return the existing row."""

        if object_kind not in LINKABLE_OBJECT_BRANCHES:
            raise LinkableObjectError(
                "TS_OBJECT_FAMILY_NOT_LINKABLE",
                object_kind=object_kind,
                reason=(
                    "never_a_link_target"
                    if object_kind in NON_LINKABLE_FAMILIES
                    else "unknown_family"
                ),
            )
        with self._lock:
            with self._database_transaction():
                return self._register_linkable_object(
                    project_id=project_id,
                    object_kind=object_kind,
                    subtype_id=int(subtype_id),
                    actor=actor,
                )

    def _register_linkable_object(
        self, *, project_id: int, object_kind: str, subtype_id: int, actor: str
    ) -> dict[str, Any]:
        subtype = self._read_linkable_subtype(object_kind, subtype_id)
        if subtype is None:
            raise LinkableObjectError(
                "TS_OBJECT_SUBTYPE_NOT_FOUND",
                object_kind=object_kind,
                subtype_id=subtype_id,
            )
        if int(subtype["project_id"]) != int(project_id):
            raise LinkableObjectError(
                "TS_OBJECT_PROJECT_MISMATCH",
                object_kind=object_kind,
                subtype_id=subtype_id,
                project_id=int(project_id),
                object_project_id=int(subtype["project_id"]),
            )
        object_type_key = str(subtype["object_type_key"])
        object_type = self._linkable_object_type(object_type_key)
        if object_type is None:
            # ``component:bus`` and any slot that is not ``system`` land here:
            # the closed catalog does not carry them, so they are not targets.
            raise LinkableObjectError(
                "TS_OBJECT_FAMILY_NOT_LINKABLE",
                object_kind=object_kind,
                object_type_key=object_type_key,
                subtype_id=subtype_id,
            )
        branch = LINKABLE_OBJECT_BRANCHES[object_kind]
        register = self._linkable("linkable_objects")
        existing = self.connection.execute(
            f"SELECT id FROM {register} WHERE {branch} = ?", (subtype_id,)
        ).fetchone()
        if existing is not None:
            return self._read_linkable_object(int(existing["id"]))
        registered_id = self._insert_canonical_row(
            f"""
            INSERT INTO {register} (
                project_id, object_kind, object_type_id, {branch},
                status, created_at, created_by
            ) VALUES (?, ?, ?, ?, 'active', ?, ?)
            """,
            (
                int(project_id),
                object_kind,
                int(object_type["id"]),
                subtype_id,
                utc_now_iso(),
                actor,
            ),
        )
        return self._read_linkable_object(registered_id)

    def _read_linkable_object(self, linkable_object_id: int) -> dict[str, Any]:
        row = self.connection.execute(
            f"""
            {linkable_object_projection_sql(self.linkable_object_table_names())}
            WHERE registered.id = ?
            """,
            (int(linkable_object_id),),
        ).fetchone()
        if row is None:
            raise LinkableObjectError(
                "TS_OBJECT_NOT_REGISTERED", linkable_object_id=int(linkable_object_id)
            )
        return dict(row)

    def get_linkable_object(self, linkable_object_id: int) -> dict[str, Any]:
        return self._read_linkable_object(int(linkable_object_id))

    def list_linkable_objects(
        self, *, project_id: int, include_archived: bool = False
    ) -> list[dict[str, Any]]:
        status_filter = "" if include_archived else " AND registered.status = 'active'"
        return [
            dict(row)
            for row in self.connection.execute(
                f"""
                {linkable_object_projection_sql(self.linkable_object_table_names())}
                WHERE registered.project_id = ?{status_filter}
                ORDER BY registered.object_kind, object_key, registered.id
                """,
                (int(project_id),),
            ).fetchall()
        ]

    def ensure_global_signal_slot(
        self,
        *,
        project_id: int,
        slot_key: str = SYSTEM_SLOT_KEY,
        display_name: str = "",
        actor: str = "internal_analyst",
    ) -> dict[str, Any]:
        """The project-wide destination for signals without a physical asset."""

        with self._lock:
            with self._database_transaction():
                slot_id = self._ensure_global_signal_slot_row(
                    project_id=int(project_id),
                    slot_key=slot_key,
                    display_name=display_name,
                    actor=actor,
                )
                return self._register_linkable_object(
                    project_id=int(project_id),
                    object_kind="global_signal_slot",
                    subtype_id=slot_id,
                    actor=actor,
                )

    def ensure_project_component(
        self,
        *,
        project_id: int,
        component_key: str,
        component_type: str,
        display_name: str = "",
        external_reference: str | None = None,
        metadata: dict[str, Any] | None = None,
        actor: str = "internal_analyst",
    ) -> dict[str, Any]:
        """Materialize one component of a project and register it as a target."""

        with self._lock:
            with self._database_transaction():
                component_id = self._materialize_component(
                    project_id=int(project_id),
                    component_key=component_key,
                    component_type=component_type,
                    display_name=display_name,
                    external_reference=external_reference,
                    metadata=metadata,
                    actor=actor,
                )
                return self._register_linkable_object(
                    project_id=int(project_id),
                    object_kind="component",
                    subtype_id=component_id,
                    actor=actor,
                )

    def archive_linkable_object(
        self,
        *,
        linkable_object_id: int,
        actor: str = "internal_analyst",
        reason_text: str = "",
    ) -> dict[str, Any]:
        """Retire an object without erasing it (chapter 2.4).

        Withdrawal is expressed as ``status = 'archived'``, never as a physical
        delete, and the real object is deactivated in the same transaction so
        the register and the object can never disagree about being retired.
        """

        register = self._linkable("linkable_objects")
        components = self._linkable("components")
        with self._lock:
            with self._database_transaction():
                registered = self._read_linkable_object(int(linkable_object_id))
                if registered["status"] == "archived":
                    return registered
                self.connection.execute(
                    f"""
                    UPDATE {register}
                    SET status = 'archived', archived_at = ?, archived_by = ?
                    WHERE id = ?
                    """,
                    (utc_now_iso(), actor, int(linkable_object_id)),
                )
                if registered["object_kind"] == "component":
                    # The register row is already archived, so the guard that
                    # refuses retiring a component behind the register's back
                    # lets this one through.
                    self.connection.execute(
                        f"""
                        UPDATE {components}
                        SET is_active = 0, updated_at = ?
                        WHERE id = ?
                        """,
                        (utc_now_iso(), int(registered["subtype_id"])),
                    )
                archived = self._read_linkable_object(int(linkable_object_id))
                archived["archived_reason_text"] = reason_text
                return archived

    def resolve_linkable_object_reference(
        self, *, project_id: int, entity_type: str, entity_id: Any
    ) -> dict[str, Any]:
        """Turn a legacy text pair into a registered object, or refuse.

        The pair is a lookup key and nothing else. The project of the route is
        the authority (chapter 5.3): an object of another project is refused
        before any series is resolved, and a case-scoped reference is followed
        through its own foreign key to the base entity, never taken as the id
        of a link target.
        """

        project_id = int(project_id)
        object_kind, subtype_id = self._resolve_reference_subtype(
            project_id=project_id, entity_type=entity_type, entity_id=entity_id
        )
        branch = LINKABLE_OBJECT_BRANCHES[object_kind]
        register = self._linkable("linkable_objects")
        row = self.connection.execute(
            f"SELECT id FROM {register} WHERE {branch} = ? AND status = 'active'",
            (subtype_id,),
        ).fetchone()
        if row is None:
            raise LinkableObjectError(
                "TS_OBJECT_NOT_REGISTERED",
                entity_type=entity_type,
                entity_id=entity_id,
                object_kind=object_kind,
                subtype_id=subtype_id,
            )
        registered = self._read_linkable_object(int(row["id"]))
        return self.authorize_linkable_object_project(
            linkable_object=registered, project_id=project_id
        )

    def authorize_linkable_object_project(
        self, *, linkable_object: Mapping[str, Any], project_id: int
    ) -> dict[str, Any]:
        """Every linkable object has one owning project; the route must match."""

        if int(linkable_object["project_id"]) != int(project_id):
            raise LinkableObjectError(
                "TS_COMPAT_PROJECT_CONTEXT_MISMATCH",
                linkable_object_id=int(linkable_object["id"]),
                project_id=int(project_id),
                object_project_id=int(linkable_object["project_id"]),
            )
        return dict(linkable_object)

    def _resolve_reference_subtype(
        self, *, project_id: int, entity_type: str, entity_id: Any
    ) -> tuple[str, int]:
        reference = str(entity_type or "").strip()

        if reference in CASE_SCOPED_HYDRAULIC_REFERENCES:
            case_table, foreign_key = CASE_SCOPED_HYDRAULIC_REFERENCES[reference]
            row = self.connection.execute(
                f"SELECT {foreign_key} AS base_id FROM {case_table} WHERE id = ?",
                (int(entity_id),),
            ).fetchone()
            if row is None or row["base_id"] is None:
                raise LinkableObjectError(
                    "TS_OBJECT_NOT_REGISTERED",
                    entity_type=reference,
                    entity_id=entity_id,
                    reason="case_copy_not_found",
                )
            return BASE_HYDRAULIC_REFERENCES[reference[len("case_") :]], int(
                row["base_id"]
            )

        if reference in BASE_HYDRAULIC_REFERENCES:
            return reference, int(entity_id)

        if reference == "component" or reference.startswith("component:"):
            declared_type = (
                reference.split(":", 1)[1] if ":" in reference else None
            )
            return "component", self._resolve_component_reference(
                project_id=project_id,
                component_key=str(entity_id or "").strip(),
                declared_type=declared_type,
            )

        if reference in ("global", "global_signal_slot") or reference.startswith(
            "global:"
        ):
            slot_key = (
                reference.split(":", 1)[1] if ":" in reference else SYSTEM_SLOT_KEY
            )
            slots = self._linkable("global_signal_slots")
            row = self.connection.execute(
                f"SELECT id FROM {slots} WHERE project_id = ? AND slot_key = ?",
                (project_id, slot_key),
            ).fetchone()
            if row is None:
                raise LinkableObjectError(
                    "TS_OBJECT_NOT_REGISTERED",
                    entity_type=reference,
                    project_id=project_id,
                    slot_key=slot_key,
                )
            return "global_signal_slot", int(row["id"])

        raise LinkableObjectError(
            "TS_OBJECT_FAMILY_NOT_LINKABLE",
            object_kind=reference,
            entity_id=entity_id,
        )

    def _resolve_component_reference(
        self, *, project_id: int, component_key: str, declared_type: str | None
    ) -> int:
        components = self._linkable("components")
        rows = self.connection.execute(
            f"""
            SELECT id, project_id, component_type
            FROM {components}
            WHERE component_key = ?
            ORDER BY project_id, id
            """,
            (component_key,),
        ).fetchall()
        if not rows:
            raise LinkableObjectError(
                "TS_OBJECT_NOT_REGISTERED",
                entity_type="component",
                component_key=component_key,
                project_id=project_id,
            )
        own = [row for row in rows if int(row["project_id"]) == project_id]
        if not own:
            # The key exists, but under another project: the route decides.
            raise LinkableObjectError(
                "TS_COMPAT_PROJECT_CONTEXT_MISMATCH",
                component_key=component_key,
                project_id=project_id,
                object_project_id=int(rows[0]["project_id"]),
            )
        if len(own) > 1:
            raise LinkableObjectError(
                "TS_MIGRATION_OBJECT_AMBIGUOUS",
                component_key=component_key,
                project_id=project_id,
                reason="more_than_one_component",
            )
        component = own[0]
        if declared_type is not None and str(
            component["component_type"]
        ) != declared_type:
            # The declared text is checked against the real object, never
            # trusted: it names a type the component does not have.
            raise LinkableObjectError(
                "TS_OBJECT_TYPE_MISMATCH",
                component_key=component_key,
                declared_type=declared_type,
                component_type=str(component["component_type"]),
            )
        return int(component["id"])

    def materialize_project_linkable_objects(
        self, *, project_id: int, actor: str = "internal_analyst"
    ) -> dict[str, Any]:
        """Register every link target a project already has (chapter 10.4).

        Repeatable by construction: identities come from stable keys, so a
        second pass creates no row and moves no key. It refuses rather than
        guesses, and one refusal leaves the whole pass unwritten.
        """

        with self._lock:
            with self._database_transaction():
                return self._materialize_project_linkable_objects(
                    project_id=int(project_id), actor=actor
                )

    def _materialize_project_linkable_objects(
        self, *, project_id: int, actor: str
    ) -> dict[str, Any]:
        appearances = self._project_component_appearances(project_id)
        groups, skipped = group_component_appearances(appearances)

        before = self._registered_object_ids(project_id)
        objects = [
            self._register_linkable_object(
                project_id=project_id,
                object_kind="global_signal_slot",
                subtype_id=self._ensure_global_signal_slot_row(
                    project_id=project_id, slot_key=SYSTEM_SLOT_KEY, actor=actor
                ),
                actor=actor,
            )
        ]
        for component_key in sorted(groups):
            group = groups[component_key]
            if group["component_type"] not in LINKABLE_COMPONENT_TYPES:
                # ``bus`` is topology, not a link target (chapter 2.4).
                continue
            component_id = self._materialize_component(
                project_id=project_id,
                component_key=component_key,
                component_type=group["component_type"],
                display_name=group["display_name"],
                metadata={"origins": sorted(set(group["origins"]))},
                actor=actor,
            )
            objects.append(
                self._register_linkable_object(
                    project_id=project_id,
                    object_kind="component",
                    subtype_id=component_id,
                    actor=actor,
                )
            )
        objects.extend(
            self._register_project_hydraulic_objects(project_id=project_id, actor=actor)
        )

        created = sorted({entry["id"] for entry in objects} - before)
        return {
            "project_id": project_id,
            "created": len(created),
            "unchanged": len(objects) - len(created),
            "skipped": sorted({str(entry["skipped"]) for entry in skipped}),
            "skipped_count": len(skipped),
            "objects": objects,
        }

    def _registered_object_ids(self, project_id: int) -> set[int]:
        register = self._linkable("linkable_objects")
        return {
            int(row["id"])
            for row in self.connection.execute(
                f"SELECT id FROM {register} WHERE project_id = ?", (project_id,)
            ).fetchall()
        }

    def _project_component_appearances(self, project_id: int) -> list[dict[str, Any]]:
        """Every authoritative appearance of a component in the project."""

        appearances: list[dict[str, Any]] = []
        for row in self.connection.execute(
            """
            SELECT version.id AS version_id, version.system_case_json AS document
            FROM scenario_versions AS version
            JOIN scenarios ON scenarios.id = version.scenario_id
            WHERE scenarios.project_id = ?
            ORDER BY version.id
            """,
            (project_id,),
        ).fetchall():
            appearances.extend(
                case_component_appearances(
                    json.loads(row["document"]), origin=f"case:{row['version_id']}"
                )
            )
        for row in self.connection.execute(
            """
            SELECT draft.id AS draft_id, draft.document_json AS document
            FROM scenario_drafts AS draft
            JOIN scenarios ON scenarios.id = draft.scenario_id
            WHERE scenarios.project_id = ?
            ORDER BY draft.id
            """,
            (project_id,),
        ).fetchall():
            appearances.extend(
                draft_component_appearances(
                    json.loads(row["document"]), origin=f"draft:{row['draft_id']}"
                )
            )
        return appearances

    def _register_project_hydraulic_objects(
        self, *, project_id: int, actor: str
    ) -> list[dict[str, Any]]:
        """The hydraulic base entities are already stable rows; register them.

        The case copies are deliberately absent: a case-scoped row is a copy of
        the base entity, never a link target of its own.
        """

        sources = (
            (
                "hydraulic_system",
                """
                SELECT system.id AS id FROM hydraulic_systems AS system
                WHERE system.project_id = ? ORDER BY system.id
                """,
            ),
            (
                "hydraulic_node",
                """
                SELECT node.id AS id FROM hydraulic_nodes AS node
                JOIN hydraulic_systems AS system
                  ON system.id = node.hydraulic_system_id
                WHERE system.project_id = ? ORDER BY node.id
                """,
            ),
            (
                "hydraulic_reach",
                """
                SELECT reach.id AS id FROM hydraulic_reaches AS reach
                JOIN hydraulic_systems AS system
                  ON system.id = reach.hydraulic_system_id
                WHERE system.project_id = ? ORDER BY reach.id
                """,
            ),
            (
                "hydraulic_plant",
                """
                SELECT plant.id AS id FROM hydraulic_plants AS plant
                JOIN hydraulic_systems AS system
                  ON system.id = plant.hydraulic_system_id
                WHERE system.project_id = ? ORDER BY plant.id
                """,
            ),
            (
                "hydraulic_unit",
                """
                SELECT unit.id AS id FROM hydraulic_units AS unit
                JOIN hydraulic_plants AS plant
                  ON plant.id = unit.hydraulic_plant_id
                JOIN hydraulic_systems AS system
                  ON system.id = plant.hydraulic_system_id
                WHERE system.project_id = ? ORDER BY unit.id
                """,
            ),
        )
        registered: list[dict[str, Any]] = []
        for object_kind, sql in sources:
            for row in self.connection.execute(sql, (project_id,)).fetchall():
                registered.append(
                    self._register_linkable_object(
                        project_id=project_id,
                        object_kind=object_kind,
                        subtype_id=int(row["id"]),
                        actor=actor,
                    )
                )
        return registered

    def _ensure_global_signal_slot_row(
        self, *, project_id: int, slot_key: str, actor: str, display_name: str = ""
    ) -> int:
        slots = self._linkable("global_signal_slots")
        existing = self.connection.execute(
            f"SELECT id FROM {slots} WHERE project_id = ? AND slot_key = ?",
            (project_id, slot_key),
        ).fetchone()
        if existing is not None:
            return int(existing["id"])
        return self._insert_canonical_row(
            f"""
            INSERT INTO {slots} (
                project_id, slot_key, display_name, created_at, created_by
            ) VALUES (?, ?, ?, ?, ?)
            """,
            (
                project_id,
                slot_key,
                display_name or slot_key.replace("_", " ").title(),
                utc_now_iso(),
                actor,
            ),
        )

    def _materialize_component(
        self,
        *,
        project_id: int,
        component_key: str,
        component_type: str,
        display_name: str = "",
        external_reference: str | None = None,
        metadata: dict[str, Any] | None = None,
        actor: str,
    ) -> int:
        """Create the component once; a second pass changes neither key nor type."""

        components = self._linkable("components")
        existing = self.connection.execute(
            f"""
            SELECT id, component_type
            FROM {components}
            WHERE project_id = ? AND component_key = ?
            """,
            (project_id, component_key),
        ).fetchone()
        if existing is not None:
            if str(existing["component_type"]) != component_type:
                raise LinkableObjectError(
                    "TS_MIGRATION_OBJECT_AMBIGUOUS",
                    project_id=project_id,
                    component_key=component_key,
                    component_types=sorted(
                        {str(existing["component_type"]), component_type}
                    ),
                    reason="component_type_conflict",
                )
            return int(existing["id"])
        now = utc_now_iso()
        return self._insert_canonical_row(
            f"""
            INSERT INTO {components} (
                project_id, component_key, component_type, display_name,
                external_reference, is_active, metadata_json,
                created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, 1, ?, ?, ?)
            """,
            (
                project_id,
                component_key,
                component_type,
                display_name or component_key,
                external_reference,
                json.dumps(metadata or {}, ensure_ascii=False),
                now,
                now,
            ),
        )

    # -- Canonical content model (TS7-002) ---------------------------------
    #
    # The atomic revision protocol of chapter 2.7 is the only way canonical
    # content is written. There is deliberately no in-place value edit path:
    # editing a value, reclassifying a signal, changing a unit or adding and
    # retiring a signal all publish a complete new set revision.

    def _canonical(self, logical: str) -> str:
        return canonical_table_name(logical, self.database_backend)

    def _canonical_classification(self, signals: list[dict], data_class_key: str) -> dict:
        data_class = self.connection.execute(
            """
            SELECT id, data_class_key, status
            FROM time_series_data_classes
            WHERE data_class_key = ?
            """,
            (data_class_key,),
        ).fetchone()
        if data_class is None or data_class["status"] != "active":
            raise CanonicalRevisionError(
                "TS_INGEST_SIGNAL_SET_INCOMPLETE",
                data_class_key=data_class_key,
                reason="unknown_data_class",
            )

        resolved: dict[str, dict] = {}
        for signal in signals:
            semantic_type = self.connection.execute(
                """
                SELECT id, semantic_key, dimension_id, canonical_unit_id,
                       default_aggregation, status
                FROM time_series_semantic_types
                WHERE semantic_key = ?
                """,
                (signal["semantic_type_key"],),
            ).fetchone()
            if semantic_type is None or semantic_type["status"] != "active":
                raise CanonicalRevisionError(
                    "TS_INGEST_SIGNAL_SET_INCOMPLETE",
                    series_key=signal["series_key"],
                    semantic_type_key=signal["semantic_type_key"],
                    reason="semantic_type_inactive",
                )
            unit = self.connection.execute(
                """
                SELECT id, unit_key, dimension_id, status
                FROM measurement_units
                WHERE unit_key = ?
                """,
                (signal["unit_key"],),
            ).fetchone()
            if unit is None or unit["status"] != "active":
                raise CanonicalRevisionError(
                    "TS_INGEST_SIGNAL_SET_INCOMPLETE",
                    series_key=signal["series_key"],
                    unit_key=signal["unit_key"],
                    reason="unit_inactive",
                )
            # Chapter 3.1: the unit is an exact match of the canonical unit of
            # the semantic type, never an implicit conversion.
            if unit["id"] != semantic_type["canonical_unit_id"]:
                raise CanonicalRevisionError(
                    "TS_INGEST_SIGNAL_SET_INCOMPLETE",
                    series_key=signal["series_key"],
                    unit_key=signal["unit_key"],
                    semantic_type_key=signal["semantic_type_key"],
                    reason="unit_is_not_canonical",
                )
            signal_data_class_key = signal["data_class_key"] or data_class_key
            signal_data_class = self.connection.execute(
                """
                SELECT id, data_class_key, status
                FROM time_series_data_classes
                WHERE data_class_key = ?
                """,
                (signal_data_class_key,),
            ).fetchone()
            if signal_data_class is None or signal_data_class["status"] != "active":
                raise CanonicalRevisionError(
                    "TS_INGEST_SIGNAL_SET_INCOMPLETE",
                    series_key=signal["series_key"],
                    data_class_key=signal_data_class_key,
                    reason="unknown_data_class",
                )
            resolved[signal["series_key"]] = {
                "semantic_type_id": int(semantic_type["id"]),
                "semantic_type_key": semantic_type["semantic_key"],
                "unit_id": int(unit["id"]),
                "unit_key": unit["unit_key"],
                "data_class_id": int(signal_data_class["id"]),
                "data_class_key": signal_data_class["data_class_key"],
                "aggregation": signal["aggregation"]
                or semantic_type["default_aggregation"],
            }
        return {
            "data_class_id": int(data_class["id"]),
            "data_class_key": data_class["data_class_key"],
            "signals": resolved,
        }

    def _insert_canonical_row(self, sql: str, parameters: tuple) -> int:
        row = self.connection.execute(
            f"{sql.rstrip().rstrip(';')} RETURNING id", parameters
        ).fetchone()
        return int(row["id"])

    def _lock_canonical_set(self, set_id: int):
        sql = f"SELECT * FROM {self._canonical('time_series_sets')} WHERE id = ?"
        if self.database_backend == "postgresql":
            sql = f"{sql} FOR UPDATE"
        return self.connection.execute(sql, (set_id,)).fetchone()

    def publish_canonical_set_revision(
        self,
        *,
        project_id: int,
        name: str,
        signals,
        periods,
        values,
        data_class_key: str,
        timezone: str = "UTC",
        timestamp_convention: str = "period_start",
        version_label: str | None = None,
        description: str = "",
        source: dict[str, Any] | None = None,
        change_summary: str = "",
        metadata: dict[str, Any] | None = None,
        lineage: list[dict[str, Any]] | None = None,
        actor: str,
        set_id: int | None = None,
        idempotency_key: str | None = None,
        request_fingerprint: str | None = None,
    ) -> dict[str, Any]:
        """Publish one complete set revision inside a single transaction.

        With an ``idempotency_key`` the claim, the mutation and the stored
        result share that transaction (chapter 9.7), so a retry either finds a
        completed record and returns exactly its saved result, or it repeats a
        publication that never happened.
        """

        normalized_signals = normalize_canonical_signals(signals)
        normalized_periods = normalize_canonical_periods(periods)
        with self._lock:
            with self._database_transaction():
                claim = None
                if idempotency_key is not None:
                    claim = self._claim_idempotency(
                        actor_id=actor,
                        operation_kind=PUBLISH_OPERATION_KIND,
                        scope_key=publish_scope_key(
                            project_id=project_id, set_id=set_id, name=name
                        ),
                        idempotency_key=idempotency_key,
                        request_hash=idempotency_request_hash(
                            publish_request_payload(
                                project_id=project_id,
                                set_id=set_id,
                                name=name,
                                data_class_key=data_class_key,
                                timezone_name=timezone,
                                timestamp_convention=timestamp_convention,
                                signals=normalized_signals,
                                periods=normalized_periods,
                                request_fingerprint=request_fingerprint,
                            )
                        ),
                    )
                    if claim["state"] == "completed":
                        return claim["response"]
                receipt = self._publish_canonical_set_revision(
                    project_id=project_id,
                    name=name,
                    signals=normalized_signals,
                    periods=normalized_periods,
                    values=values,
                    data_class_key=data_class_key,
                    revision_timezone=timezone,
                    timestamp_convention=timestamp_convention,
                    version_label=version_label,
                    description=description,
                    source=source,
                    change_summary=change_summary,
                    metadata=metadata or {},
                    lineage=lineage or [],
                    actor=actor,
                    set_id=set_id,
                )
                if claim is not None:
                    self._complete_idempotency(
                        claim_id=claim["id"],
                        response=receipt,
                        http_status=200 if receipt["outcome"] == "unchanged" else 201,
                    )
                return receipt

    def _publish_canonical_set_revision(
        self,
        *,
        project_id: int,
        name: str,
        signals: list[dict],
        periods: list[dict],
        values,
        data_class_key: str,
        revision_timezone: str,
        timestamp_convention: str,
        version_label: str | None,
        description: str,
        source: dict[str, Any] | None,
        change_summary: str,
        metadata: dict[str, Any],
        lineage: list[dict[str, Any]],
        actor: str,
        set_id: int | None,
    ) -> dict[str, Any]:
        sets_table = self._canonical("time_series_sets")
        signals_table = self._canonical("time_series_signals")
        revisions_table = self._canonical("time_series_set_revisions")
        revision_signals_table = self._canonical("time_series_revision_signals")
        periods_table = self._canonical("time_series_periods")
        values_table = self._canonical("time_series_values")

        classification = self._canonical_classification(signals, data_class_key)
        now = utc_now_iso()

        # 1. Reserve the set and the next revision number under its lock.
        existing_set = None
        if set_id is not None:
            existing_set = self._lock_canonical_set(set_id)
            if existing_set is None:
                raise CanonicalRevisionError("TS_SET_NOT_FOUND", set_id=set_id)
            if existing_set["series_kind"] != "catalog":
                # The catalog writer must never double as a promotion or
                # conversion path for an object-owned identity (chapter 7.12).
                raise CanonicalRevisionError(
                    "TS_SET_KIND_MISMATCH",
                    set_id=set_id,
                    expected_series_kind="catalog",
                    actual_series_kind=existing_set["series_kind"],
                )
        else:
            candidate = self.connection.execute(
                f"""
                SELECT id
                FROM {sets_table}
                WHERE owner_project_id = ? AND name = ? AND series_kind = 'catalog'
                ORDER BY version_number DESC
                LIMIT 1
                """,
                (project_id, name),
            ).fetchone()
            if candidate is not None:
                existing_set = self._lock_canonical_set(int(candidate["id"]))

        if existing_set is None:
            resolved_set_id = self._insert_canonical_row(
                f"""
                INSERT INTO {sets_table} (
                    owner_project_id, name, version_number, version_label,
                    visibility_scope, series_kind, status, description,
                    data_kind, timezone, created_at, updated_at,
                    created_by, updated_by
                ) VALUES (?, ?, 1, ?, 'project', 'catalog', 'draft', ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    project_id,
                    name,
                    version_label or "v1",
                    description,
                    data_class_key,
                    revision_timezone,
                    now,
                    now,
                    actor,
                    actor,
                ),
            )
            previous_revision_id = None
            next_revision_number = 1
        else:
            resolved_set_id = int(existing_set["id"])
            previous_revision_id = existing_set["current_revision_id"]
            highest = self.connection.execute(
                f"""
                SELECT MAX(revision_number) AS highest
                FROM {revisions_table}
                WHERE time_series_set_id = ?
                """,
                (resolved_set_id,),
            ).fetchone()
            next_revision_number = int(highest["highest"] or 0) + 1

        source_id, source_created = self._register_canonical_source(
            project_id, source, actor, now
        )

        # 2. Open the building revision. ``content_hash`` stays null until the
        #    snapshot is complete and verified (P-03).
        revision_id = self._insert_canonical_row(
            f"""
            INSERT INTO {revisions_table} (
                time_series_set_id, revision_number, supersedes_revision_id,
                time_series_source_id, data_class_id, timezone,
                timestamp_convention, state, change_summary, metadata_json,
                created_at, created_by
            ) VALUES (?, ?, ?, ?, ?, ?, ?, 'building', ?, ?, ?, ?)
            """,
            (
                resolved_set_id,
                next_revision_number,
                previous_revision_id,
                source_id,
                classification["data_class_id"],
                revision_timezone,
                timestamp_convention,
                change_summary,
                json.dumps(metadata, sort_keys=True),
                now,
                actor,
            ),
        )

        # 3. Reuse identities by series_key; never recycle an archived one.
        signal_ids = self._resolve_canonical_signal_identities(
            set_id=resolved_set_id, signals=signals, actor=actor, now=now
        )

        # 4. Freeze the snapshot: contract, coverage and values.
        self.connection.executemany(
            f"""
            INSERT INTO {revision_signals_table} (
                set_revision_id, signal_id, time_series_set_id, semantic_type_id,
                unit_id, data_class_id, signal_role, aggregation, ordinal,
                metadata_json
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            [
                (
                    revision_id,
                    signal_ids[signal["series_key"]],
                    resolved_set_id,
                    classification["signals"][signal["series_key"]]["semantic_type_id"],
                    classification["signals"][signal["series_key"]]["unit_id"],
                    classification["signals"][signal["series_key"]]["data_class_id"],
                    signal["signal_role"],
                    classification["signals"][signal["series_key"]]["aggregation"],
                    signal["ordinal"],
                    json.dumps(signal["metadata"], sort_keys=True),
                )
                for signal in signals
            ],
        )
        self.connection.executemany(
            f"""
            INSERT INTO {periods_table} (
                set_revision_id, period_index, timestamp_start, timestamp_end,
                duration_hours
            ) VALUES (?, ?, ?, ?, ?)
            """,
            [
                (
                    revision_id,
                    period["period_index"],
                    period["timestamp_start"],
                    period["timestamp_end"],
                    period["duration_hours"],
                )
                for period in periods
            ],
        )
        period_ids = {
            int(row["period_index"]): int(row["id"])
            for row in self.connection.execute(
                f"""
                SELECT id, period_index
                FROM {periods_table}
                WHERE set_revision_id = ?
                """,
                (revision_id,),
            ).fetchall()
        }
        self._insert_canonical_values(
            values_table=values_table,
            revision_id=revision_id,
            values=values,
            signal_ids=signal_ids,
            period_ids=period_ids,
        )

        # 5. Verify the snapshot, then compute the canonical hash in streaming
        #    order. A doubtful revision is never made visible first.
        signal_count = len(signals)
        period_count = len(periods)
        value_count = int(
            self.connection.execute(
                f"SELECT COUNT(*) AS total FROM {values_table} WHERE set_revision_id = ?",
                (revision_id,),
            ).fetchone()["total"]
        )
        if value_count != signal_count * period_count:
            raise CanonicalRevisionError(
                "TS_REVISION_VALUE_COUNT_MISMATCH",
                signal_count=signal_count,
                period_count=period_count,
                value_count=value_count,
            )
        content_hash = self._stream_canonical_content_hash(
            revision_id=revision_id,
            revision_timezone=revision_timezone,
            timestamp_convention=timestamp_convention,
            data_class_key=classification["data_class_key"],
        )

        # 5b. A republication whose content equals the current revision is a
        #     no-op (chapter 9.7): no revision is created, the pointer does not
        #     move, no binding turns stale and the generation does not rise.
        if previous_revision_id is not None:
            current_revision = self.connection.execute(
                f"""
                SELECT id, revision_number, supersedes_revision_id, content_hash
                FROM {revisions_table}
                WHERE id = ?
                """,
                (previous_revision_id,),
            ).fetchone()
            if (
                current_revision is not None
                and current_revision["content_hash"] == content_hash
            ):
                self._discard_building_revision(
                    revision_id=revision_id,
                    source_id=source_id if source_created else None,
                )
                return {
                    "set_id": resolved_set_id,
                    "name": name,
                    "revision_id": int(current_revision["id"]),
                    "revision_number": int(current_revision["revision_number"]),
                    "supersedes_revision_id": current_revision[
                        "supersedes_revision_id"
                    ],
                    "state": "sealed",
                    "content_hash": content_hash,
                    "signal_count": signal_count,
                    "period_count": period_count,
                    "value_count": value_count,
                    "time_series_source_id": (
                        None if source_created else source_id
                    ),
                    "signal_ids": dict(signal_ids),
                    "catalog_generation": self.catalog_generation(),
                    "outcome": "unchanged",
                }

        # 6. Seal and move the current pointer inside the same transaction.
        validation_payload = {
            "signal_count": signal_count,
            "period_count": period_count,
            "value_count": value_count,
            "coverage_start": periods[0]["timestamp_start"],
            "coverage_end": periods[-1]["timestamp_end"],
        }
        self.connection.execute(
            f"""
            UPDATE {revisions_table}
            SET state = 'sealed', content_hash = ?, validation_payload_json = ?
            WHERE id = ?
            """,
            (content_hash, json.dumps(validation_payload, sort_keys=True), revision_id),
        )
        self.connection.execute(
            f"""
            UPDATE {sets_table}
            SET current_revision_id = ?, content_hash = ?, data_kind = ?,
                timezone = ?, status = 'validated', updated_at = ?, updated_by = ?
            WHERE id = ?
            """,
            (
                revision_id,
                content_hash,
                classification["data_class_key"],
                revision_timezone,
                now,
                actor,
                resolved_set_id,
            ),
        )

        # 7. Maintain the read model inside the same transaction that sealed
        #    the revision, so no background worker can leave it stale.
        self._project_catalog_entries(set_id=resolved_set_id, now=now)
        catalog_generation = self._raise_catalog_generation(now=now)

        # 7. Record the lineage of a derived revision in the same transaction.
        self._record_canonical_lineage(
            revision_id=revision_id,
            signal_ids=signal_ids,
            lineage=lineage,
            actor=actor,
            now=now,
        )
        return {
            "set_id": resolved_set_id,
            "name": name,
            "revision_id": revision_id,
            "revision_number": next_revision_number,
            "supersedes_revision_id": previous_revision_id,
            "state": "sealed",
            "content_hash": content_hash,
            "signal_count": signal_count,
            "period_count": period_count,
            "value_count": value_count,
            "time_series_source_id": source_id,
            "signal_ids": dict(signal_ids),
            "catalog_generation": catalog_generation,
            "outcome": "published",
        }

    def _record_canonical_lineage(
        self,
        *,
        revision_id: int,
        signal_ids: dict[str, int],
        lineage: list[dict[str, Any]],
        actor: str,
        now: str,
    ) -> None:
        if not lineage:
            return
        rows = []
        for entry in lineage:
            series_key = str(entry["series_key"])
            derived_signal_id = signal_ids.get(series_key)
            if derived_signal_id is None:
                raise CanonicalRevisionError(
                    "TS_INGEST_SIGNAL_SET_INCOMPLETE",
                    series_key=series_key,
                    reason="lineage_target_not_in_revision",
                )
            rows.append(
                (
                    revision_id,
                    derived_signal_id,
                    int(entry["source_set_revision_id"]),
                    int(entry["source_signal_id"]),
                    str(entry["lineage_kind"]),
                    str(entry["source_content_hash"]),
                    entry.get("source_owner_linkable_object_id"),
                    entry.get("target_owner_linkable_object_id"),
                    entry.get("transformation_id"),
                    now,
                    actor,
                    str(entry.get("reason_code") or "TS_LINEAGE_RECORDED"),
                    entry.get("reason_text"),
                )
            )
        self.connection.executemany(
            f"""
            INSERT INTO {self._canonical('time_series_revision_lineage')} (
                derived_set_revision_id, derived_signal_id, source_set_revision_id,
                source_signal_id, lineage_kind, source_content_hash,
                source_owner_linkable_object_id, target_owner_linkable_object_id,
                transformation_id, created_at, created_by, reason_code, reason_text
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            rows,
        )

    def _discard_building_revision(
        self, *, revision_id: int, source_id: int | None
    ) -> None:
        """Remove a staged revision that turned out to change nothing.

        Only a ``building`` revision reaches this path, so the sealed guards
        never fire and no published history is touched.
        """

        for logical in (
            "time_series_values",
            "time_series_periods",
            "time_series_revision_signals",
        ):
            self.connection.execute(
                f"DELETE FROM {self._canonical(logical)} WHERE set_revision_id = ?",
                (revision_id,),
            )
        self.connection.execute(
            f"DELETE FROM {self._canonical('time_series_set_revisions')} WHERE id = ?",
            (revision_id,),
        )
        if source_id is not None:
            self.connection.execute(
                f"DELETE FROM {self._canonical('time_series_sources')} WHERE id = ?",
                (source_id,),
            )

    # -- Catalog read model (TS7-005, chapters 9.3 to 9.5) ------------------

    def _validate_catalog_execution_context(
        self,
        *,
        scenario_id: int,
        variant_id: int,
        target_project_id: int,
    ) -> None:
        """Derive the variant project instead of trusting duplicated context."""

        row = self.connection.execute(
            """
            SELECT scenario.project_id
            FROM case_input_variants AS variant
            JOIN optimization_cases AS optimization_case
              ON optimization_case.id = variant.case_id
            JOIN scenarios AS scenario
              ON scenario.id = optimization_case.scenario_id
            WHERE variant.id = ? AND scenario.id = ?
            """,
            (int(variant_id), int(scenario_id)),
        ).fetchone()
        if row is None:
            raise CatalogQueryError(
                "TS_QUERY_INVALID",
                field="context_variant_id",
                reason="execution_context_not_found",
            )
        if int(row["project_id"]) != int(target_project_id):
            raise CatalogQueryError(
                "TS_COMPAT_PROJECT_CONTEXT_MISMATCH",
                scenario_id=int(scenario_id),
                variant_id=int(variant_id),
                target_project_id=int(target_project_id),
            )

    def read_catalog_page(
        self,
        *,
        limit: int | None = None,
        order: str | None = None,
        cursor: str | None = None,
        include_total: bool = False,
        section: str = CATALOG_SECTION_INPUTS,
        filters: dict[str, Any] | None = None,
        actor_class: str = "internal",
    ) -> dict[str, Any]:
        """One keyset page of the catalog, read only from the projection.

        The page never joins periods or values: everything it needs was written
        by the transaction that sealed the revision (chapter 9.3).
        """

        resolved_limit = normalize_catalog_limit(limit)
        canonical_order = normalize_catalog_order(order)
        order_terms = parse_catalog_order(order)
        entries_table = self._projection("time_series_catalog_entries")
        normalized_filters = dict(filters or {})
        if "context_linkable_object_id" in normalized_filters:
            context_object = self.get_linkable_object(
                normalized_filters["context_linkable_object_id"]
            )
            normalized_filters.update(
                {
                    "_context_object_status": context_object["status"],
                    "_context_project_id": int(context_object["project_id"]),
                    "_context_object_type_id": int(context_object["object_type_id"]),
                }
            )
            if normalized_filters["context_usage"] == "execution":
                self._validate_catalog_execution_context(
                    scenario_id=normalized_filters["context_scenario_id"],
                    variant_id=normalized_filters["context_variant_id"],
                    target_project_id=int(context_object["project_id"]),
                )
        filter_sql, filter_parameters = input_filters_sql(
            normalized_filters,
            associations_table=self.link_layer_table_names()[
                "time_series_catalog_associations"
            ],
            bindings_table=self.link_layer_table_names()["case_time_series_bindings"],
        )
        filters_digest = input_filters_hash(normalized_filters)

        with self._read_only_transaction():
            generation = self.catalog_generation(section)
            cursor_key = None
            if cursor is not None:
                cursor_key = decode_catalog_cursor(
                    cursor,
                    self._catalog_cursor_secret,
                    section=section,
                    order=canonical_order,
                    limit=resolved_limit,
                    generation=generation,
                    actor_class=actor_class,
                    filters_hash=filters_digest,
                )
            sql, parameters = catalog_page_sql(
                entries_table=entries_table,
                order_terms=order_terms,
                cursor_key=cursor_key,
                limit=resolved_limit,
                filter_sql=filter_sql,
                filter_parameters=filter_parameters,
            )
            rows = [
                dict(row)
                for row in self.connection.execute(sql, parameters).fetchall()
            ]
            total_count = None
            if include_total:
                total_count = int(
                    self.connection.execute(
                        f"SELECT COUNT(*) AS total FROM {entries_table} AS entry "
                        + (f"WHERE {filter_sql}" if filter_sql else ""),
                        filter_parameters,
                    ).fetchone()["total"]
                )

        has_more = len(rows) > resolved_limit
        items = rows[:resolved_limit]
        next_cursor = None
        if has_more and items:
            next_cursor = encode_catalog_cursor(
                {
                    "s": section,
                    "o": canonical_order,
                    "l": resolved_limit,
                    "g": generation,
                    "k": [items[-1][column] for column, _ in order_terms],
                    "t": int(time.time()),
                    "a": actor_class,
                    "f": filters_digest,
                },
                self._catalog_cursor_secret,
            )
        return {
            "items": items,
            "page": {
                "limit": resolved_limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
            "summary": None if total_count is None else {"total_count": total_count},
            "facets": None,
            "meta": {"section": section, "catalog_generation": generation},
        }

    def evaluate_catalog_signal_for_object(
        self,
        *,
        signal_id: int,
        linkable_object_id: int,
        binding_role_key: str,
        usage: str,
    ) -> dict[str, Any]:
        """Contextual decision used by the inverse catalog selector."""

        entry = self.connection.execute(
            f"SELECT * FROM {self._projection('time_series_catalog_entries')} "
            "WHERE signal_id = ?",
            (int(signal_id),),
        ).fetchone()
        if entry is None:
            raise KeyError(f"catalog signal {signal_id} not found")
        entry = dict(entry)
        linkable = self.get_linkable_object(int(linkable_object_id))
        decision = self.evaluate_time_series_compatibility(
            semantic_type_key=entry["semantic_type_key"],
            binding_role_key=binding_role_key,
            object_type_key=linkable["object_type_key"],
            unit_key=entry["unit_key"],
            usage=usage,
        )
        extra_errors = []
        if entry["set_status"] == "archived" or entry["signal_status"] == "archived":
            extra_errors.append(
                compatibility_error(
                    "TS_COMPAT_SIGNAL_UNAVAILABLE", {"signal_id": int(signal_id)}
                )
            )
        if linkable["status"] != "active":
            extra_errors.append(
                compatibility_error(
                    "TS_COMPAT_OBJECT_UNAVAILABLE",
                    {"linkable_object_id": int(linkable_object_id)},
                )
            )
        if (
            entry["visibility_scope"] == "project"
            and int(entry["owner_project_id"]) != int(linkable["project_id"])
        ):
            extra_errors.append(
                compatibility_error(
                    "TS_COMPAT_SCOPE_NOT_ACCESSIBLE",
                    {
                        "signal_id": int(signal_id),
                        "owner_project_id": int(entry["owner_project_id"]),
                        "target_project_id": int(linkable["project_id"]),
                    },
                )
            )
        errors = extra_errors + list(decision["errors"])
        evaluated = {
            **decision,
            "allowed": bool(decision["allowed"] and not extra_errors),
            "errors": errors,
            "primary_error": errors[0] if errors else None,
        }
        fingerprint_source = json.dumps(
            {
                "signal_id": int(signal_id),
                "revision_id": entry["current_revision_id"],
                "object_id": int(linkable_object_id),
                "role": binding_role_key,
                "usage": usage,
                "decision": evaluated,
            },
            sort_keys=True,
            separators=(",", ":"),
        )
        evaluated["compatibility_fingerprint"] = hashlib.sha256(
            fingerprint_source.encode()
        ).hexdigest()
        return evaluated

    def explain_catalog_page(
        self,
        *,
        limit: int | None = None,
        order: str | None = None,
        cursor_key: list | None = None,
        analyze: bool = False,
    ) -> dict[str, Any]:
        """Reference plan of the catalog page query (AC-CAT-04, chapter 9.2).

        PostgreSQL answers with ``EXPLAIN (ANALYZE, BUFFERS)`` when asked to
        analyze; SQLite answers with ``EXPLAIN QUERY PLAN``, which is enough to
        prove no plan ever walks periods or values.
        """

        resolved_limit = normalize_catalog_limit(limit)
        sql, parameters = catalog_page_sql(
            entries_table=self._projection("time_series_catalog_entries"),
            order_terms=parse_catalog_order(order),
            cursor_key=cursor_key,
            limit=resolved_limit,
        )
        return self._explain(sql, parameters, analyze=analyze)

    def read_catalog_input_detail(self, signal_id: int) -> dict[str, Any]:
        """Complete metadata for one signal admitted by the list projection."""

        row = self.connection.execute(
            f"""
            SELECT entry.*,
                   signal.description AS signal_description,
                   the_set.name AS set_name,
                   the_set.version_number AS set_version_number,
                   the_set.version_label AS set_version_label,
                   the_set.description AS set_description,
                   the_set.scope_revision AS scope_revision,
                   revision.state AS revision_state,
                   revision.content_hash AS revision_content_hash,
                   revision.timezone AS revision_timezone,
                   revision.timestamp_convention AS timestamp_convention,
                   revision.created_at AS revision_created_at,
                   revision.created_by AS revision_created_by,
                   revision.validation_payload_json AS validation_payload_json,
                   revision_signal.signal_role AS signal_role,
                   revision_signal.aggregation AS aggregation,
                   semantic_type.display_name AS semantic_type_name,
                   semantic_type.description AS semantic_type_description,
                   semantic_type.status AS semantic_type_status,
                   semantic_type.value_kind AS value_kind,
                   semantic_type.default_aggregation AS default_aggregation,
                   semantic_type.validation_rules_json AS semantic_validation_rules_json,
                   dimension.dimension_key AS dimension_key,
                   unit.symbol AS unit_symbol,
                   unit.status AS unit_status,
                   data_class.display_name AS data_class_name,
                   data_class.status AS data_class_status,
                   source.kind AS provenance_kind,
                   source.source_key AS provenance_source_key,
                   source.original_filename AS provenance_filename,
                   source.media_type AS provenance_media_type,
                   source.checksum AS provenance_checksum
            FROM {self._projection('time_series_catalog_entries')} AS entry
            JOIN {self._canonical('time_series_signals')} AS signal
              ON signal.id = entry.signal_id
            JOIN {self._canonical('time_series_sets')} AS the_set
              ON the_set.id = entry.time_series_set_id
            JOIN {self._canonical('time_series_set_revisions')} AS revision
              ON revision.id = entry.current_revision_id
            JOIN {self._canonical('time_series_revision_signals')} AS revision_signal
              ON revision_signal.set_revision_id = revision.id
             AND revision_signal.signal_id = entry.signal_id
            JOIN time_series_semantic_types AS semantic_type
              ON semantic_type.id = revision_signal.semantic_type_id
            JOIN measurement_dimensions AS dimension
              ON dimension.id = semantic_type.dimension_id
            JOIN measurement_units AS unit
              ON unit.id = revision_signal.unit_id
            JOIN time_series_data_classes AS data_class
              ON data_class.id = revision_signal.data_class_id
            LEFT JOIN {self._canonical('time_series_sources')} AS source
              ON source.id = revision.time_series_source_id
            WHERE entry.signal_id = ?
            """,
            (int(signal_id),),
        ).fetchone()
        if row is None:
            raise KeyError(f"catalog signal {signal_id} not found")
        item = dict(row)
        try:
            validation = json.loads(item["validation_payload_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            validation = {}
        try:
            semantic_validation_rules = json.loads(
                item["semantic_validation_rules_json"] or "{}"
            )
        except (TypeError, json.JSONDecodeError):
            semantic_validation_rules = {}
        lineage_table = self._canonical("time_series_revision_lineage")
        lineage_rows = self.connection.execute(
            f"""
            SELECT lineage_kind, COUNT(*) AS occurrence_count
            FROM {lineage_table}
            WHERE (derived_set_revision_id = ? AND derived_signal_id = ?)
               OR (source_set_revision_id = ? AND source_signal_id = ?)
            GROUP BY lineage_kind
            ORDER BY lineage_kind
            """,
            (
                item["current_revision_id"],
                item["signal_id"],
                item["current_revision_id"],
                item["signal_id"],
            ),
        ).fetchall()
        return {
            "entry_kind": "input",
            "signal_id": int(item["signal_id"]),
            "identity": {
                "series_key": item["series_key"],
                "display_name": item["display_name"],
                "description": item["signal_description"],
                "status": item["signal_status"],
            },
            "owner": {
                "project_id": int(item["owner_project_id"]),
                "project_name": item["owner_project_name"],
            },
            "set": {
                "id": int(item["time_series_set_id"]),
                "name": item["set_name"],
                "version_number": int(item["set_version_number"]),
                "version_label": item["set_version_label"],
                "description": item["set_description"],
                "status": item["set_status"],
                "visibility_scope": item["visibility_scope"],
                "scope_revision": int(item["scope_revision"]),
            },
            "contract": {
                "semantic_type": {
                    "key": item["semantic_type_key"],
                    "display_name": item["semantic_type_name"],
                    "description": item["semantic_type_description"],
                    "status": item["semantic_type_status"],
                    "dimension_key": item["dimension_key"],
                    "value_kind": item["value_kind"],
                    "default_aggregation": item["default_aggregation"],
                    "validation_rules": semantic_validation_rules,
                },
                "data_class": {
                    "key": item["data_class_key"],
                    "display_name": item["data_class_name"],
                    "status": item["data_class_status"],
                },
                "unit": {
                    "key": item["unit_key"],
                    "symbol": item["unit_symbol"],
                    "dimension_key": item["dimension_key"],
                    "status": item["unit_status"],
                },
                "signal_role": item["signal_role"],
                "aggregation": item["aggregation"],
            },
            "current_revision": {
                "id": int(item["current_revision_id"]),
                "number": int(item["revision_number"]),
                "state": item["revision_state"],
                "content_hash": item["revision_content_hash"],
                "timezone": item["revision_timezone"],
                "timestamp_convention": item["timestamp_convention"],
                "created_at": item["revision_created_at"],
                "created_by": item["revision_created_by"],
            },
            # Chapter 6.5 adds to the row projection instead of replacing it, so
            # the inspector answers coverage, resolution and consumers from the
            # same projection columns the list read and never from the values.
            "coverage_summary": {
                "start": item["coverage_start"],
                "end": item["coverage_end"],
                "period_count": int(item["period_count"]),
                "nominal_resolution_seconds": float(
                    item["nominal_resolution_seconds"]
                ),
                "minimum_resolution_seconds": float(item["min_resolution_seconds"]),
                "maximum_resolution_seconds": float(item["max_resolution_seconds"]),
                "regularity": item["regularity"],
                "source_timezone": item["source_timezone"],
            },
            "origin_summary": {"source_kind": item["source_kind"]},
            "link_summary": {
                "association_count": int(item["association_count"]),
                "binding_count": int(item["binding_count"]),
            },
            "provenance": {
                "kind": item["provenance_kind"] or item["source_kind"],
                "source_key": item["provenance_source_key"],
                "filename": item["provenance_filename"],
                "media_type": item["provenance_media_type"],
                "checksum": item["provenance_checksum"],
            },
            "validation_summary": {
                "status": validation.get("status"),
                "error_count": len(validation.get("errors", []))
                if isinstance(validation.get("errors"), list)
                else 0,
            },
            "lineage_summary": [
                {
                    "kind": lineage["lineage_kind"],
                    "occurrence_count": int(lineage["occurrence_count"]),
                }
                for lineage in lineage_rows
            ],
        }

    def read_catalog_input_revisions(
        self,
        signal_id: int,
        *,
        limit: int | None = None,
        cursor: str | None = None,
        actor_class: str = "internal",
    ) -> dict[str, Any]:
        """Immutable revision metadata for one projected catalog signal."""

        resolved_limit = normalize_catalog_limit(limit)
        signal_id = int(signal_id)
        section = f"input:{signal_id}:revisions"
        cursor_filter_hash = input_filters_hash({"signal_id": signal_id})
        entry = self.connection.execute(
            f"SELECT time_series_set_id FROM {self._projection('time_series_catalog_entries')} "
            "WHERE signal_id = ?",
            (signal_id,),
        ).fetchone()
        if entry is None:
            raise KeyError(f"catalog signal {signal_id} not found")

        with self._read_only_transaction():
            generation = self.catalog_generation()
            cursor_key = None
            if cursor is not None:
                cursor_key = decode_catalog_cursor(
                    cursor,
                    self._catalog_cursor_secret,
                    section=section,
                    order="-revision_number",
                    limit=resolved_limit,
                    generation=generation,
                    actor_class=actor_class,
                    filters_hash=cursor_filter_hash,
                )
            keyset = ""
            parameters: list[Any] = [signal_id]
            if cursor_key is not None:
                if len(cursor_key) != 2:
                    raise CatalogQueryError(
                        "TS_QUERY_CURSOR_MISMATCH", reason="key_arity"
                    )
                keyset = (
                    "AND (revision.revision_number < ? OR "
                    "(revision.revision_number = ? AND revision.id > ?))"
                )
                parameters.extend((cursor_key[0], cursor_key[0], cursor_key[1]))
            parameters.append(resolved_limit + 1)
            rows = self.connection.execute(
                f"""
                SELECT revision.id, revision.revision_number, revision.state,
                       revision.content_hash, revision.created_at,
                       revision.created_by, revision.change_summary,
                       revision.validation_payload_json,
                       source.kind AS source_kind
                FROM {self._canonical('time_series_revision_signals')} AS revision_signal
                JOIN {self._canonical('time_series_set_revisions')} AS revision
                  ON revision.id = revision_signal.set_revision_id
                LEFT JOIN {self._canonical('time_series_sources')} AS source
                  ON source.id = revision.time_series_source_id
                WHERE revision_signal.signal_id = ?
                  {keyset}
                ORDER BY revision.revision_number DESC, revision.id ASC
                LIMIT ?
                """,
                tuple(parameters),
            ).fetchall()
            total_count = int(
                self.connection.execute(
                    f"SELECT COUNT(*) AS total FROM "
                    f"{self._canonical('time_series_revision_signals')} "
                    "WHERE signal_id = ?",
                    (signal_id,),
                ).fetchone()["total"]
            )

        has_more = len(rows) > resolved_limit
        visible = rows[:resolved_limit]
        items = []
        for row in visible:
            try:
                validation = json.loads(row["validation_payload_json"] or "{}")
            except (TypeError, json.JSONDecodeError):
                validation = {}
            items.append(
                {
                    "id": int(row["id"]),
                    "number": int(row["revision_number"]),
                    "state": row["state"],
                    "content_hash": row["content_hash"],
                    "created_at": row["created_at"],
                    "created_by": row["created_by"],
                    "change_summary": row["change_summary"],
                    "source_kind": row["source_kind"] or "api",
                    "validation_summary": {
                        "status": validation.get("status"),
                        "error_count": len(validation.get("errors", []))
                        if isinstance(validation.get("errors"), list)
                        else 0,
                    },
                }
            )
        next_cursor = None
        if has_more and visible:
            next_cursor = encode_catalog_cursor(
                {
                    "s": section,
                    "o": "-revision_number",
                    "l": resolved_limit,
                    "g": generation,
                    "k": [visible[-1]["revision_number"], visible[-1]["id"]],
                    "t": int(time.time()),
                    "a": actor_class,
                    "f": cursor_filter_hash,
                },
                self._catalog_cursor_secret,
            )
        return {
            "items": items,
            "page": {
                "limit": resolved_limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
            "summary": {"total_count": total_count},
            "facets": None,
            "meta": {
                "section": "input_revisions",
                "signal_id": signal_id,
                "catalog_generation": generation,
            },
        }

    def read_catalog_input_preview(
        self,
        signal_id: int,
        *,
        revision_id: int,
        range_from: str,
        range_to: str,
        sampling: str,
        max_points: int,
    ) -> dict[str, Any]:
        """Bounded values from one explicitly named sealed revision."""

        signal_id = int(signal_id)
        revision_id = int(revision_id)
        metadata = self.connection.execute(
            f"""
            SELECT revision.id AS revision_id,
                   revision.content_hash,
                   revision.state,
                   unit.unit_key,
                   unit.symbol AS unit_symbol
            FROM {self._projection('time_series_catalog_entries')} AS entry
            JOIN {self._canonical('time_series_set_revisions')} AS revision
              ON revision.time_series_set_id = entry.time_series_set_id
            JOIN {self._canonical('time_series_revision_signals')} AS revision_signal
              ON revision_signal.set_revision_id = revision.id
             AND revision_signal.signal_id = entry.signal_id
            JOIN measurement_units AS unit ON unit.id = revision_signal.unit_id
            WHERE entry.signal_id = ? AND revision.id = ?
            """,
            (signal_id, revision_id),
        ).fetchone()
        if metadata is None:
            # A revision the migration left `legacy_unmaterialized` has no
            # signal contract to join, but it is part of the visible history:
            # it cannot be previewed, and saying it does not exist would be
            # a different, false answer (chapter 10.5).
            unmaterialized = self.connection.execute(
                f"""
                SELECT revision.id
                FROM {self._projection('time_series_catalog_entries')} AS entry
                JOIN {self._canonical('time_series_set_revisions')} AS revision
                  ON revision.time_series_set_id = entry.time_series_set_id
                WHERE entry.signal_id = ? AND revision.id = ?
                """,
                (signal_id, revision_id),
            ).fetchone()
            if unmaterialized is None:
                raise KeyError("catalog signal or exact revision not found")
            raise CatalogQueryError(
                "TS_PREVIEW_REVISION_UNAVAILABLE", revision_id=revision_id
            )
        if metadata["state"] != "sealed" or not metadata["content_hash"]:
            raise CatalogQueryError(
                "TS_PREVIEW_REVISION_UNAVAILABLE", revision_id=revision_id
            )

        range_summary = self.connection.execute(
            f"""
                SELECT COUNT(*) AS total,
                       MIN(period.timestamp_start) AS effective_start,
                       MAX(period.timestamp_end) AS effective_end
                FROM {self._canonical('time_series_values')} AS value
                JOIN {self._canonical('time_series_periods')} AS period
                  ON period.id = value.time_series_period_id
                 AND period.set_revision_id = value.set_revision_id
                WHERE value.set_revision_id = ? AND value.signal_id = ?
                  AND period.timestamp_start >= ? AND period.timestamp_end <= ?
            """,
            (revision_id, signal_id, range_from, range_to),
        ).fetchone()
        count = int(range_summary["total"])
        if sampling == "none" and count > max_points:
            raise CatalogQueryError(
                "TS_PREVIEW_TOO_LARGE",
                source_point_count=count,
                max_points=max_points,
            )
        base_query = f"""
                SELECT period.timestamp_start, period.timestamp_end,
                       value.value_numeric, value.quality_flag,
                       period.id AS period_id
                FROM {self._canonical('time_series_values')} AS value
                JOIN {self._canonical('time_series_periods')} AS period
                  ON period.id = value.time_series_period_id
                 AND period.set_revision_id = value.set_revision_id
                WHERE value.set_revision_id = ? AND value.signal_id = ?
                  AND period.timestamp_start >= ? AND period.timestamp_end <= ?
        """
        source_parameters: list[Any] = [
            revision_id,
            signal_id,
            range_from,
            range_to,
        ]
        if count <= max_points or sampling == "none":
            sample_sql = base_query + " ORDER BY period.timestamp_start, period.id"
            sample_parameters = tuple(source_parameters)
        elif sampling == "uniform":
            sample_sql = f"""
                WITH source AS (
                    SELECT sampled_source.*,
                           ROW_NUMBER() OVER (
                               ORDER BY timestamp_start, period_id
                           ) - 1 AS row_number
                    FROM ({base_query}) AS sampled_source
                ), bucketed AS (
                    SELECT source.*,
                           CAST((row_number * ?) / ? AS INTEGER) AS bucket
                    FROM source
                ), ranked AS (
                    SELECT bucketed.*,
                           ROW_NUMBER() OVER (
                               PARTITION BY bucket ORDER BY row_number
                           ) AS bucket_rank
                    FROM bucketed
                )
                SELECT timestamp_start, timestamp_end, value_numeric, quality_flag
                FROM ranked WHERE bucket_rank = 1
                ORDER BY row_number LIMIT ?
            """
            sample_parameters = tuple(
                [*source_parameters, max_points, count, max_points]
            )
        else:
            bucket_count = max(1, (max_points + 1) // 2)
            sample_sql = f"""
                WITH source AS (
                    SELECT sampled_source.*,
                           ROW_NUMBER() OVER (
                               ORDER BY timestamp_start, period_id
                           ) - 1 AS row_number
                    FROM ({base_query}) AS sampled_source
                ), bucketed AS (
                    SELECT source.*,
                           CAST((row_number * ?) / ? AS INTEGER) AS bucket
                    FROM source
                ), ranked AS (
                    SELECT bucketed.*,
                           ROW_NUMBER() OVER (
                               PARTITION BY bucket
                               ORDER BY value_numeric, row_number
                           ) AS low_rank,
                           ROW_NUMBER() OVER (
                               PARTITION BY bucket
                               ORDER BY value_numeric DESC, row_number
                           ) AS high_rank
                    FROM bucketed
                )
                SELECT timestamp_start, timestamp_end, value_numeric, quality_flag
                FROM ranked WHERE low_rank = 1 OR high_rank = 1
                ORDER BY row_number LIMIT ?
            """
            sample_parameters = tuple(
                [*source_parameters, bucket_count, count, max_points]
            )
        sampled = [
            dict(row)
            for row in self.connection.execute(
                sample_sql, sample_parameters
            ).fetchall()
        ]
        effective_range = (
            {
                "from": range_summary["effective_start"],
                "to": range_summary["effective_end"],
            }
            if count
            else None
        )
        return {
            "signal_id": signal_id,
            "revision": {
                "id": revision_id,
                "content_hash": metadata["content_hash"],
            },
            "requested_range": {"from": range_from, "to": range_to},
            "effective_range": effective_range,
            "sampling": sampling,
            "max_points": max_points,
            "source_point_count": count,
            "returned_point_count": len(sampled),
            "unit": {
                "key": metadata["unit_key"],
                "symbol": metadata["unit_symbol"],
            },
            "points": [
                {
                    "timestamp_start": row["timestamp_start"],
                    "timestamp_end": row["timestamp_end"],
                    "value": float(row["value_numeric"]),
                    "quality_flag": row["quality_flag"],
                }
                for row in sampled
            ],
        }

    def read_catalog_descriptors(
        self,
        *,
        kind: str,
        limit: int | None = None,
        cursor: str | None = None,
        q: str = "",
        statuses: list[str] | None = None,
        actor_class: str = "internal",
    ) -> dict[str, Any]:
        """One independently paged persistent selector catalog."""

        queries = {
            "semantic_type": """
                SELECT semantic.id, semantic.semantic_key AS key,
                       semantic.display_name, semantic.status,
                       dimension.dimension_key,
                       unit.unit_key AS canonical_unit_key,
                       semantic.value_kind, semantic.default_aggregation,
                       semantic.is_system
                FROM time_series_semantic_types AS semantic
                JOIN measurement_dimensions AS dimension
                  ON dimension.id = semantic.dimension_id
                JOIN measurement_units AS unit
                  ON unit.id = semantic.canonical_unit_id
            """,
            "data_class": """
                SELECT id, data_class_key AS key, display_name, status
                FROM time_series_data_classes
            """,
            "unit": """
                SELECT unit.id, unit.unit_key AS key, unit.symbol AS display_name,
                       unit.status, dimension.dimension_key
                FROM measurement_units AS unit
                JOIN measurement_dimensions AS dimension
                  ON dimension.id = unit.dimension_id
            """,
            "binding_role": """
                SELECT role.id, role.role_key AS key, role.display_name,
                       role.status, dimension.dimension_key,
                       unit.unit_key AS canonical_unit_key,
                       role.association_allowed, role.execution_allowed,
                       role.is_system
                FROM time_series_binding_roles AS role
                JOIN measurement_dimensions AS dimension
                  ON dimension.id = role.dimension_id
                JOIN measurement_units AS unit
                  ON unit.id = role.canonical_unit_id
            """,
            "object_type": """
                SELECT id, object_type_key AS key, display_name, status,
                       object_kind, is_system
                FROM linkable_object_types
            """,
            "source_kind": f"""
                SELECT MIN(id) AS id, kind AS key, kind AS display_name,
                       'active' AS status
                FROM {self._canonical('time_series_sources')}
                GROUP BY kind
            """,
        }
        if kind not in queries:
            raise CatalogQueryError("TS_QUERY_INVALID", field="kind")
        resolved_limit = normalize_catalog_limit(limit)
        normalized_q = normalize_search_text(q)
        selected_statuses = sorted(set(statuses or ["active"]))
        rows = [dict(row) for row in self.connection.execute(queries[kind]).fetchall()]
        items: list[dict[str, Any]] = []
        for row in rows:
            if row["status"] not in selected_statuses:
                continue
            search = normalize_search_text(row["key"], row["display_name"])
            if any(token not in search for token in normalized_q.split()):
                continue
            item = dict(row)
            for flag in (
                "is_system",
                "association_allowed",
                "execution_allowed",
            ):
                if flag in item:
                    item[flag] = bool(item[flag])
            item["capabilities"] = {
                "edit": actor_class.startswith("admin:")
                and not bool(item.get("is_system", False)),
                "archive": actor_class.startswith("admin:")
                and not bool(item.get("is_system", False)),
            }
            item["_sort_key"] = normalize_sort_text(item["display_name"])
            items.append(item)
        items.sort(key=lambda item: (item["_sort_key"], int(item["id"])))
        generation_source = json.dumps(
            [
                [item["id"], item["key"], item["status"], item["_sort_key"]]
                for item in items
            ],
            separators=(",", ":"),
        )
        generation = int(hashlib.sha256(generation_source.encode()).hexdigest()[:15], 16)
        filters_digest = input_filters_hash(
            {"kind": kind, "q": normalized_q, "statuses": selected_statuses}
        )
        cursor_key = None
        if cursor is not None:
            cursor_key = decode_catalog_cursor(
                cursor,
                self._catalog_cursor_secret,
                section=f"descriptors:{kind}",
                order="display_name",
                limit=resolved_limit,
                generation=generation,
                actor_class=actor_class,
                filters_hash=filters_digest,
            )
        if cursor_key is not None:
            if len(cursor_key) != 2:
                raise CatalogQueryError("TS_QUERY_CURSOR_MISMATCH", reason="key_arity")
            items = [
                item
                for item in items
                if (item["_sort_key"], int(item["id"]))
                > (str(cursor_key[0]), int(cursor_key[1]))
            ]
        total_count = len(
            [
                row
                for row in rows
                if row["status"] in selected_statuses
                and all(
                    token
                    in normalize_search_text(row["key"], row["display_name"])
                    for token in normalized_q.split()
                )
            ]
        )
        has_more = len(items) > resolved_limit
        visible = items[:resolved_limit]
        next_cursor = None
        if has_more and visible:
            next_cursor = encode_catalog_cursor(
                {
                    "s": f"descriptors:{kind}",
                    "o": "display_name",
                    "l": resolved_limit,
                    "g": generation,
                    "k": [visible[-1]["_sort_key"], visible[-1]["id"]],
                    "t": int(time.time()),
                    "a": actor_class,
                    "f": filters_digest,
                },
                self._catalog_cursor_secret,
            )
        for item in visible:
            item.pop("_sort_key", None)
        return {
            "items": visible,
            "page": {
                "limit": resolved_limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
            "summary": {"total_count": total_count},
            "facets": None,
            "meta": {"section": "descriptors", "kind": kind, "catalog_generation": generation},
        }

    def read_catalog_object_candidates(
        self,
        signal_id: int,
        *,
        target_project_id: int,
        binding_role_key: str,
        usage: str,
        context_scenario_id: int | None = None,
        context_variant_id: int | None = None,
        include_denied: bool = False,
        object_type_keys: list[str] | None = None,
        q: str = "",
        limit: int | None = None,
        cursor: str | None = None,
        actor_class: str = "internal",
    ) -> dict[str, Any]:
        """Real project objects evaluated by the one compatibility policy."""

        if usage not in {"association", "execution"}:
            raise CatalogQueryError("TS_QUERY_INVALID", field="usage")
        resolved_limit = normalize_catalog_limit(limit)
        signal_id = int(signal_id)
        target_project_id = int(target_project_id)
        if usage == "execution":
            if context_scenario_id is None or context_variant_id is None:
                raise CatalogQueryError(
                    "TS_QUERY_INVALID",
                    field="context_scenario_id",
                    reason="execution_context_required",
                )
            self._validate_catalog_execution_context(
                scenario_id=int(context_scenario_id),
                variant_id=int(context_variant_id),
                target_project_id=target_project_id,
            )
        entry = self.connection.execute(
            f"SELECT * FROM {self._projection('time_series_catalog_entries')} "
            "WHERE signal_id = ?",
            (signal_id,),
        ).fetchone()
        if entry is None:
            raise KeyError(f"catalog signal {signal_id} not found")
        self.get_project(target_project_id)
        entry = dict(entry)
        normalized_q = normalize_search_text(q)
        selected_types = sorted(set(object_type_keys or []))
        candidates = []
        for linkable in self.list_linkable_objects(
            project_id=target_project_id, include_archived=True
        ):
            if selected_types and linkable["object_type_key"] not in selected_types:
                continue
            search = normalize_search_text(
                linkable["object_key"],
                linkable["display_name"],
                linkable["object_type_key"],
            )
            if any(token not in search for token in normalized_q.split()):
                continue
            decision = self.evaluate_time_series_compatibility(
                semantic_type_key=entry["semantic_type_key"],
                binding_role_key=binding_role_key,
                object_type_key=linkable["object_type_key"],
                unit_key=entry["unit_key"],
                usage=usage,
            )
            extra_errors = []
            if (
                entry["set_status"] == "archived"
                or entry["signal_status"] == "archived"
            ):
                extra_errors.append(
                    compatibility_error(
                        "TS_COMPAT_SIGNAL_UNAVAILABLE",
                        {"signal_id": signal_id, "usage": usage},
                    )
                )
            if linkable["status"] != "active":
                extra_errors.append(
                    compatibility_error(
                        "TS_COMPAT_OBJECT_UNAVAILABLE",
                        {
                            "linkable_object_id": int(linkable["id"]),
                            "usage": usage,
                        },
                    )
                )
            if (
                entry["visibility_scope"] == "project"
                and int(entry["owner_project_id"]) != target_project_id
            ):
                extra_errors.append(
                    compatibility_error(
                        "TS_COMPAT_SCOPE_NOT_ACCESSIBLE",
                        {
                            "signal_id": signal_id,
                            "owner_project_id": int(entry["owner_project_id"]),
                            "target_project_id": target_project_id,
                        },
                    )
                )
            errors = extra_errors + list(decision["errors"])
            decision = {
                **decision,
                "allowed": bool(decision["allowed"] and not extra_errors),
                "errors": errors,
                "primary_error": errors[0] if errors else None,
            }
            fingerprint_source = json.dumps(
                {
                    "signal_id": signal_id,
                    "revision_id": entry["current_revision_id"],
                    "object_id": linkable["id"],
                    "role": binding_role_key,
                    "usage": usage,
                    "decision": decision,
                },
                sort_keys=True,
                separators=(",", ":"),
            )
            decision["compatibility_fingerprint"] = hashlib.sha256(
                fingerprint_source.encode()
            ).hexdigest()
            if not include_denied and not decision["allowed"]:
                continue
            candidates.append(
                {
                    "object": {
                        "id": int(linkable["id"]),
                        "project_id": int(linkable["project_id"]),
                        "object_kind": linkable["object_kind"],
                        "object_type_key": linkable["object_type_key"],
                        "object_key": linkable["object_key"],
                        "display_name": linkable["display_name"],
                        "status": linkable["status"],
                    },
                    "compatibility_decision": decision,
                    "selectable": bool(decision["allowed"]),
                    "_sort_key": normalize_sort_text(linkable["display_name"]),
                }
            )
        candidates.sort(
            key=lambda item: (item["_sort_key"], item["object"]["id"])
        )
        generation_source = json.dumps(candidates, sort_keys=True, default=str)
        generation = int(hashlib.sha256(generation_source.encode()).hexdigest()[:15], 16)
        filters_digest = input_filters_hash(
            {
                "signal_id": signal_id,
                "target_project_id": target_project_id,
                "binding_role_key": binding_role_key,
                "usage": usage,
                "include_denied": bool(include_denied),
                "object_type_keys": selected_types,
                "q": normalized_q,
                "context_scenario_id": context_scenario_id,
                "context_variant_id": context_variant_id,
            }
        )
        total_count = len(candidates)
        cursor_key = None
        if cursor is not None:
            cursor_key = decode_catalog_cursor(
                cursor,
                self._catalog_cursor_secret,
                section=f"input:{signal_id}:object-candidates",
                order="display_name",
                limit=resolved_limit,
                generation=generation,
                actor_class=actor_class,
                filters_hash=filters_digest,
            )
        if cursor_key is not None:
            if len(cursor_key) != 2:
                raise CatalogQueryError("TS_QUERY_CURSOR_MISMATCH", reason="key_arity")
            candidates = [
                item
                for item in candidates
                if (item["_sort_key"], item["object"]["id"])
                > (str(cursor_key[0]), int(cursor_key[1]))
            ]
        has_more = len(candidates) > resolved_limit
        visible = candidates[:resolved_limit]
        next_cursor = None
        if has_more and visible:
            next_cursor = encode_catalog_cursor(
                {
                    "s": f"input:{signal_id}:object-candidates",
                    "o": "display_name",
                    "l": resolved_limit,
                    "g": generation,
                    "k": [visible[-1]["_sort_key"], visible[-1]["object"]["id"]],
                    "t": int(time.time()),
                    "a": actor_class,
                    "f": filters_digest,
                },
                self._catalog_cursor_secret,
            )
        for item in visible:
            item.pop("_sort_key", None)
        return {
            "items": visible,
            "page": {
                "limit": resolved_limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
            "summary": {"total_count": total_count},
            "facets": None,
            "meta": {
                "section": "object_candidates",
                "signal_id": signal_id,
                "target_project_id": target_project_id,
                "catalog_generation": generation,
            },
        }

    # -- Administrative set scope changes (TS7-014) -----------------------

    def _time_series_set_scope_impact(
        self, set_id: int, *, target_scope: str
    ) -> dict[str, Any]:
        sets = self._canonical("time_series_sets")
        revisions = self._canonical("time_series_set_revisions")
        signals = self._canonical("time_series_signals")
        associations = self.link_layer_table_names()[
            "time_series_catalog_associations"
        ]
        bindings = self.link_layer_table_names()["case_time_series_bindings"]
        linkables = self._linkable("linkable_objects")
        row = self.connection.execute(
            f"""
            SELECT the_set.*, revision.content_hash AS revision_content_hash
            FROM {sets} AS the_set
            LEFT JOIN {revisions} AS revision
              ON revision.id = the_set.current_revision_id
            WHERE the_set.id = ?
            """,
            (int(set_id),),
        ).fetchone()
        if row is None:
            raise KeyError(f"time-series set {set_id} not found")
        item = dict(row)
        owner_project_id = int(item["owner_project_id"])
        association_rows = self.connection.execute(
            f"""
            SELECT association.id AS association_id, association.signal_id,
                   association.linkable_object_id, linkable.project_id
            FROM {associations} AS association
            JOIN {signals} AS signal ON signal.id = association.signal_id
            JOIN {linkables} AS linkable
              ON linkable.id = association.linkable_object_id
            WHERE signal.time_series_set_id = ? AND association.status = 'active'
            ORDER BY association.id
            """,
            (int(set_id),),
        ).fetchall()
        binding_rows = self.connection.execute(
            f"""
            SELECT binding.id AS binding_id, binding.signal_id,
                   binding.linkable_object_id, binding.case_input_variant_id,
                   linkable.project_id
            FROM {bindings} AS binding
            JOIN {linkables} AS linkable
              ON linkable.id = binding.linkable_object_id
            WHERE binding.time_series_set_id = ? AND binding.status = 'active'
            ORDER BY binding.id
            """,
            (int(set_id),),
        ).fetchall()

        def consumers(rows):
            items = [
                {
                    key: int(value) if value is not None else None
                    for key, value in dict(consumer).items()
                }
                for consumer in rows
            ]
            return {
                "active_count": len(items),
                "owner_project_count": sum(
                    entry["project_id"] == owner_project_id for entry in items
                ),
                "other_project_count": sum(
                    entry["project_id"] != owner_project_id for entry in items
                ),
                "items": items,
            }

        return {
            "set": {
                "id": int(item["id"]),
                "series_kind": item["series_kind"],
                "status": item["status"],
                "owner_project_id": owner_project_id,
                "visibility_scope": item["visibility_scope"],
                "scope_revision": int(item["scope_revision"]),
            },
            "current_revision": (
                {
                    "id": int(item["current_revision_id"]),
                    "content_hash": item["revision_content_hash"],
                }
                if item["current_revision_id"] is not None
                else None
            ),
            "target_scope": target_scope,
            "associations": consumers(association_rows),
            "bindings": consumers(binding_rows),
        }

    def _time_series_set_scope_state_error(
        self, set_id: int, impact: Mapping[str, Any]
    ) -> dict[str, Any] | None:
        the_set = impact["set"]
        if the_set["series_kind"] != "catalog":
            return {
                "code": "TS_SCOPE_INVALID_STATE",
                "context": {
                    "reason": "object_specific",
                    "series_kind": the_set["series_kind"],
                },
            }
        current_revision = impact["current_revision"]
        if the_set["status"] != "validated" or current_revision is None:
            return {
                "code": "TS_SCOPE_INVALID_STATE",
                "context": {
                    "reason": "set_not_active_with_sealed_revision",
                    "set_status": the_set["status"],
                },
            }
        revisions = self._canonical("time_series_set_revisions")
        revision_state = self.connection.execute(
            f"SELECT state FROM {revisions} WHERE id = ?",
            (current_revision["id"],),
        ).fetchone()
        building_count = int(
            self.connection.execute(
                f"""
                SELECT COUNT(*) AS total FROM {revisions}
                WHERE time_series_set_id = ? AND state = 'building'
                """,
                (int(set_id),),
            ).fetchone()["total"]
        )
        if revision_state is None or revision_state["state"] != "sealed" or building_count:
            return {
                "code": "TS_SCOPE_INVALID_STATE",
                "context": {
                    "reason": "set_not_active_with_sealed_revision",
                    "revision_state": (
                        None if revision_state is None else revision_state["state"]
                    ),
                    "building_revision_count": building_count,
                },
            }
        signals = self._canonical("time_series_signals")
        inactive_signal_count = int(
            self.connection.execute(
                f"""
                SELECT COUNT(*) AS total FROM {signals}
                WHERE time_series_set_id = ? AND status != 'active'
                """,
                (int(set_id),),
            ).fetchone()["total"]
        )
        if inactive_signal_count:
            return {
                "code": "TS_SCOPE_INVALID_STATE",
                "context": {
                    "reason": "inactive_signal",
                    "inactive_signal_count": inactive_signal_count,
                },
            }
        revision_signals = self._canonical("time_series_revision_signals")
        inactive_classification_count = int(
            self.connection.execute(
                f"""
                SELECT COUNT(*) AS total
                FROM {revision_signals} AS revision_signal
                JOIN time_series_semantic_types AS semantic_type
                  ON semantic_type.id = revision_signal.semantic_type_id
                JOIN measurement_units AS unit
                  ON unit.id = revision_signal.unit_id
                JOIN time_series_data_classes AS data_class
                  ON data_class.id = revision_signal.data_class_id
                WHERE revision_signal.set_revision_id = ?
                  AND (semantic_type.status != 'active'
                       OR unit.status != 'active'
                       OR data_class.status != 'active')
                """,
                (current_revision["id"],),
            ).fetchone()["total"]
        )
        if inactive_classification_count:
            return {
                "code": "TS_SCOPE_INVALID_STATE",
                "context": {
                    "reason": "inactive_classification",
                    "inactive_classification_count": inactive_classification_count,
                },
            }
        return None

    def prevalidate_time_series_set_scope_change(
        self, set_id: int, *, target_scope: str, actor_class: str
    ) -> dict[str, Any]:
        normalized = {"target_scope": str(target_scope)}
        impact = self._time_series_set_scope_impact(
            int(set_id), target_scope=normalized["target_scope"]
        )
        state_error = self._time_series_set_scope_state_error(int(set_id), impact)
        request_hash = scope_request_hash(normalized)
        commit_etag = scope_commit_etag(
            {"impact": impact, "state_error": state_error},
            actor_class=actor_class,
        )
        token, expires_at = issue_scope_prevalidation_token(
            request_hash=request_hash,
            commit_etag=commit_etag,
            actor_class=actor_class,
            secret=self._catalog_cursor_secret,
        )
        cross_project_consumers = (
            impact["associations"]["other_project_count"]
            + impact["bindings"]["other_project_count"]
        )
        state_errors: list[dict[str, Any]] = [] if state_error is None else [state_error]
        if not state_errors and (
            impact["set"]["visibility_scope"] == normalized["target_scope"]
        ):
            state_errors.append(
                {
                    "code": "TS_SCOPE_ALREADY_EFFECTIVE",
                    "context": {"target_scope": normalized["target_scope"]},
                }
            )
        elif (
            not state_errors
            and normalized["target_scope"] == "project"
            and cross_project_consumers > 0
        ):
            state_errors.append(
                {
                    "code": "TS_SCOPE_INVALID_STATE",
                    "context": {
                        "reason": "other_project_consumers",
                        "other_project_consumer_count": cross_project_consumers,
                    },
                }
            )
        can_commit = not state_errors
        return {
            "normalized_request": normalized,
            "request_hash": request_hash,
            "impact": impact,
            "can_commit": can_commit,
            "requires_confirmation": (
                impact["set"]["series_kind"] == "catalog"
                and impact["set"]["visibility_scope"] != normalized["target_scope"]
            ),
            "errors": state_errors,
            "expires_at": expires_at,
            "prevalidation_token": token,
            "commit_etag": commit_etag,
        }

    def commit_time_series_set_scope_change(
        self,
        set_id: int,
        *,
        target_scope: str,
        expected_scope_revision: int,
        observed_revision_id: int,
        observed_content_hash: str,
        actor_user: Mapping[str, Any],
        actor_class: str,
        request_id: str,
        prevalidation_token: str,
        if_match: str,
        idempotency_key: str,
        confirmed: bool,
        reason_code: str,
        reason_text: str,
    ) -> tuple[dict[str, Any], bool]:
        normalized = {"target_scope": str(target_scope)}
        normalized_reason_code = str(reason_code or "").strip()
        normalized_reason_text = str(reason_text or "").strip()
        if not normalized_reason_code or not normalized_reason_text:
            raise ScopeMutationError(
                "TS_SCOPE_INVALID_STATE",
                field=("reason_code" if not normalized_reason_code else "reason_text"),
                reason="reason_required",
            )
        request_hash = scope_request_hash(normalized)
        verify_scope_prevalidation_token(
            prevalidation_token,
            request_hash=request_hash,
            commit_etag=if_match,
            actor_class=actor_class,
            secret=self._catalog_cursor_secret,
            check_expiry=False,
        )
        claim_hash = scope_request_hash(
            {
                **normalized,
                "expected_scope_revision": int(expected_scope_revision),
                "observed_revision_id": int(observed_revision_id),
                "observed_content_hash": str(observed_content_hash),
                "confirmed": bool(confirmed),
                "reason_code": normalized_reason_code,
                "reason_text": normalized_reason_text,
            }
        )
        try:
            with self._lock:
                with self._database_transaction():
                    claim = self._claim_idempotency(
                        actor_id=actor_class,
                        operation_kind="scope_change",
                        scope_key=f"set:{int(set_id)}",
                        idempotency_key=idempotency_key,
                        request_hash=claim_hash,
                    )
                    if claim["state"] == "completed":
                        return claim["response"], True
                    verify_scope_prevalidation_token(
                        prevalidation_token,
                        request_hash=request_hash,
                        commit_etag=if_match,
                        actor_class=actor_class,
                        secret=self._catalog_cursor_secret,
                    )
                    locked = self._lock_canonical_set(int(set_id))
                    if locked is None:
                        raise KeyError(f"time-series set {set_id} not found")
                    impact = self._time_series_set_scope_impact(
                        int(set_id), target_scope=target_scope
                    )
                    current_set = impact["set"]
                    state_error = self._time_series_set_scope_state_error(
                        int(set_id), impact
                    )
                    if current_set["visibility_scope"] == target_scope:
                        raise ScopeMutationError(
                            "TS_SCOPE_ALREADY_EFFECTIVE", target_scope=target_scope
                        )
                    actual_etag = scope_commit_etag(
                        {"impact": impact, "state_error": state_error},
                        actor_class=actor_class,
                    )
                    if actual_etag != if_match:
                        raise ScopeMutationError(
                            "TS_SCOPE_PRECONDITION_CHANGED",
                            expected_etag=if_match,
                            actual_etag=actual_etag,
                            impact=impact,
                        )
                    if state_error is not None:
                        raise ScopeMutationError(
                            "TS_SCOPE_INVALID_STATE",
                            **state_error["context"],
                            impact=impact,
                        )
                    current_revision = impact["current_revision"]
                    if (
                        int(current_set["scope_revision"])
                        != int(expected_scope_revision)
                        or current_revision is None
                        or int(current_revision["id"]) != int(observed_revision_id)
                        or current_revision["content_hash"] != observed_content_hash
                    ):
                        raise ScopeMutationError(
                            "TS_SCOPE_PRECONDITION_CHANGED", impact=impact
                        )
                    cross_project_consumers = (
                        impact["associations"]["other_project_count"]
                        + impact["bindings"]["other_project_count"]
                    )
                    if target_scope == "project" and cross_project_consumers > 0:
                        raise ScopeMutationError(
                            "TS_SCOPE_INVALID_STATE",
                            reason="other_project_consumers",
                            impact=impact,
                        )
                    if not confirmed:
                        raise ScopeMutationError("TS_SCOPE_CONFIRMATION_REQUIRED")
                    occurred_at = utc_now_iso()
                    next_scope_revision = int(current_set["scope_revision"]) + 1
                    sets = self._canonical("time_series_sets")
                    self.connection.execute(
                        f"""
                        UPDATE {sets}
                        SET visibility_scope = ?, scope_revision = ?,
                            updated_at = ?, updated_by = ?
                        WHERE id = ?
                        """,
                        (
                            target_scope,
                            next_scope_revision,
                            occurred_at,
                            actor_user["email"],
                            int(set_id),
                        ),
                    )
                    self._project_catalog_entries(set_id=int(set_id), now=occurred_at)
                    catalog_generation = self._raise_catalog_generation(now=occurred_at)
                    event_type = (
                        "promoted_global"
                        if target_scope == "global"
                        else "demoted_project"
                    )
                    events = self.link_layer_table_names()["time_series_scope_events"]
                    event_id = self._insert_canonical_row(
                        f"""
                        INSERT INTO {events} (
                            time_series_set_id, event_type, from_scope, to_scope,
                            scope_revision, owner_project_id,
                            observed_set_revision_id, observed_content_hash,
                            actor_user_id, actor_identity_snapshot,
                            actor_role_snapshot, reason_code, reason_text,
                            impact_json, request_id, idempotency_key, occurred_at
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                        """,
                        (
                            int(set_id),
                            event_type,
                            current_set["visibility_scope"],
                            target_scope,
                            next_scope_revision,
                            current_set["owner_project_id"],
                            current_revision["id"],
                            current_revision["content_hash"],
                            int(actor_user["id"]),
                            actor_user["email"],
                            actor_user["role"],
                            normalized_reason_code,
                            normalized_reason_text,
                            json.dumps(impact, sort_keys=True),
                            request_id,
                            idempotency_key,
                            occurred_at,
                        ),
                    )
                    response = {
                        "outcome": event_type,
                        "set_id": int(set_id),
                        "from_scope": current_set["visibility_scope"],
                        "to_scope": target_scope,
                        "scope_revision": next_scope_revision,
                        "scope_event_id": event_id,
                        "impact": impact,
                        "catalog_generation": catalog_generation,
                        "request_id": request_id,
                    }
                    self._complete_idempotency(
                        claim_id=claim["id"], response=response, http_status=201
                    )
                    return response, False
        except CanonicalRevisionError as error:
            if error.code in {"TS_IDEMPOTENCY_KEY_CONFLICT", "TS_IDEMPOTENCY_IN_FLIGHT"}:
                raise ScopeMutationError(
                    "TS_IDEMPOTENCY_CONFLICT", reason=error.code
                ) from error
            raise

    # -- Atomic catalog associations (TS7-007) ----------------------------

    def _prevalidate_catalog_association_add(
        self,
        operation: dict[str, Any],
        *,
        target_project_id: int,
        batch_cache: dict[str, dict[Any, Any]] | None = None,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        cache = batch_cache or {
            "linkable": {},
            "compatibility": {},
            "role": {},
        }
        entry = self.connection.execute(
            f"""
            SELECT entry.*, canonical_set.scope_revision,
                   revision.content_hash AS revision_content_hash,
                   revision_signal.signal_role
            FROM {self._projection('time_series_catalog_entries')} AS entry
            JOIN {self._canonical('time_series_sets')} AS canonical_set
              ON canonical_set.id = entry.time_series_set_id
            JOIN {self._canonical('time_series_set_revisions')} AS revision
              ON revision.id = entry.current_revision_id
            JOIN {self._canonical('time_series_revision_signals')} AS revision_signal
              ON revision_signal.set_revision_id = entry.current_revision_id
             AND revision_signal.signal_id = entry.signal_id
            WHERE entry.signal_id = ?
            """,
            (operation["signal_id"],),
        ).fetchone()
        linkable_cache = cache["linkable"]
        linkable_id = operation["linkable_object_id"]
        if linkable_id not in linkable_cache:
            try:
                linkable_cache[linkable_id] = self.get_linkable_object(linkable_id)
            except LinkableObjectError:
                linkable_cache[linkable_id] = None
        linkable = linkable_cache[linkable_id]

        errors: list[dict[str, Any]] = []
        decision: dict[str, Any]
        if entry is None:
            errors.append(
                compatibility_error(
                    "TS_COMPAT_SIGNAL_UNAVAILABLE",
                    {"signal_id": operation["signal_id"], "usage": "association"},
                )
            )
            decision = {
                "allowed": False,
                "compatibility_rule_id": None,
                "rule_version": None,
                "contract_version": CLASSIFICATION_CONTRACT_VERSION,
                "errors": list(errors),
                "primary_error": errors[0],
            }
        elif linkable is None:
            errors.append(
                compatibility_error(
                    "TS_COMPAT_OBJECT_UNAVAILABLE",
                    {
                        "linkable_object_id": operation["linkable_object_id"],
                        "usage": "association",
                    },
                )
            )
            decision = {
                "allowed": False,
                "compatibility_rule_id": None,
                "rule_version": None,
                "contract_version": CLASSIFICATION_CONTRACT_VERSION,
                "errors": list(errors),
                "primary_error": errors[0],
            }
        else:
            entry = dict(entry)
            compatibility_key = (
                entry["semantic_type_key"],
                operation["binding_role_key"],
                linkable["object_type_key"],
                entry["unit_key"],
            )
            compatibility_cache = cache["compatibility"]
            if compatibility_key not in compatibility_cache:
                compatibility_cache[compatibility_key] = (
                    self.evaluate_time_series_compatibility(
                        semantic_type_key=entry["semantic_type_key"],
                        binding_role_key=operation["binding_role_key"],
                        object_type_key=linkable["object_type_key"],
                        unit_key=entry["unit_key"],
                        usage="association",
                    )
                )
            cached_decision = compatibility_cache[compatibility_key]
            decision = {
                **cached_decision,
                "errors": list(cached_decision["errors"]),
                "primary_error": cached_decision["primary_error"],
            }
            if entry["set_status"] == "archived" or entry["signal_status"] == "archived":
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_SIGNAL_UNAVAILABLE",
                        {"signal_id": operation["signal_id"], "usage": "association"},
                    )
                )
            if linkable["status"] != "active":
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_OBJECT_UNAVAILABLE",
                        {
                            "linkable_object_id": operation["linkable_object_id"],
                            "usage": "association",
                        },
                    )
                )
            if int(linkable["project_id"]) != int(target_project_id):
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_PROJECT_CONTEXT_MISMATCH",
                        {
                            "linkable_object_id": operation["linkable_object_id"],
                            "target_project_id": target_project_id,
                            "object_project_id": int(linkable["project_id"]),
                        },
                    )
                )
            if (
                entry["visibility_scope"] == "project"
                and int(entry["owner_project_id"]) != int(target_project_id)
            ):
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_SCOPE_NOT_ACCESSIBLE",
                        {
                            "signal_id": operation["signal_id"],
                            "owner_project_id": int(entry["owner_project_id"]),
                            "target_project_id": target_project_id,
                        },
                    )
                )
            if errors:
                decision = {
                    **decision,
                    "allowed": False,
                    "errors": [*errors, *decision["errors"]],
                    "primary_error": errors[0],
                }

        active_association = None
        role = None
        if entry is not None and linkable is not None and decision["compatibility_rule_id"]:
            role_cache = cache["role"]
            role_key = operation["binding_role_key"]
            if role_key not in role_cache:
                role_cache[role_key] = self.connection.execute(
                    "SELECT id FROM time_series_binding_roles WHERE role_key = ?",
                    (role_key,),
                ).fetchone()
            role = role_cache[role_key]
            if role is not None:
                active_association = self.connection.execute(
                    f"""
                    SELECT id, lifecycle_revision, status
                    FROM {self.link_layer_table_names()['time_series_catalog_associations']}
                    WHERE signal_id = ? AND linkable_object_id = ?
                      AND binding_role_id = ? AND status = 'active'
                    """,
                    (
                        operation["signal_id"],
                        operation["linkable_object_id"],
                        int(role["id"]),
                    ),
                ).fetchone()
        observation = {
            "signal": (
                {
                    "signal_id": int(entry["signal_id"]),
                    "time_series_set_id": int(entry["time_series_set_id"]),
                    "current_revision_id": int(entry["current_revision_id"]),
                    "content_hash": entry["revision_content_hash"],
                    "visibility_scope": entry["visibility_scope"],
                    "owner_project_id": int(entry["owner_project_id"]),
                    "semantic_type_key": entry["semantic_type_key"],
                    "data_class_key": entry["data_class_key"],
                    "unit_key": entry["unit_key"],
                    "signal_role": entry["signal_role"],
                    "scope_revision": int(entry["scope_revision"]),
                    "set_status": entry["set_status"],
                    "signal_status": entry["signal_status"],
                }
                if entry is not None
                else None
            ),
            "object": (
                {
                    "id": int(linkable["id"]),
                    "project_id": int(linkable["project_id"]),
                    "object_type_key": linkable["object_type_key"],
                    "status": linkable["status"],
                }
                if linkable is not None
                else None
            ),
            "compatibility_rule_id": decision["compatibility_rule_id"],
            "binding_role_id": int(role["id"]) if role is not None else None,
            "rule_version": decision["rule_version"],
            "active_association": (
                {
                    "id": int(active_association["id"]),
                    "lifecycle_revision": int(active_association["lifecycle_revision"]),
                    "status": active_association["status"],
                }
                if active_association is not None
                else None
            ),
        }
        result = {
            "client_operation_id": operation["client_operation_id"],
            "action": operation["action"],
            "normalized_operation": operation,
            "verdict": "accepted" if decision["allowed"] else "rejected",
            "compatibility_decision": decision,
            "errors": decision["errors"],
            "observed_state": observation,
            "comparison": {
                "before": observation["active_association"],
                "after": operation,
            },
        }
        return result, observation

    @staticmethod
    def _association_operation_error(
        code: str, *, field: str | None = None, **context: Any
    ) -> dict[str, Any]:
        error = AssociationMutationError(code, **context)
        return {
            "code": error.code,
            "message_key": error.message_key,
            "message": error.message,
            "field": field if field is not None else error.field,
            "context": context,
        }

    def _prevalidate_catalog_association_replace(
        self,
        operation: dict[str, Any],
        *,
        target_project_id: int,
        batch_cache: dict[str, dict[Any, Any]] | None = None,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        target_result, observation = self._prevalidate_catalog_association_add(
            operation,
            target_project_id=target_project_id,
            batch_cache=batch_cache,
        )
        try:
            previous = self.read_catalog_association(operation["association_id"])
        except KeyError:
            previous = None
        precondition_errors: list[dict[str, Any]] = []
        if previous is None:
            precondition_errors.append(
                self._association_operation_error(
                    "TS_LINK_PRECONDITION_CHANGED",
                    field="association_id",
                    association_id=operation["association_id"],
                    reason="not_found",
                )
            )
        elif (
            previous["status"] != "active"
            or previous["lifecycle_revision"]
            != operation["expected_lifecycle_revision"]
        ):
            precondition_errors.append(
                self._association_operation_error(
                    "TS_LINK_PRECONDITION_CHANGED",
                    field="expected_lifecycle_revision",
                    association_id=operation["association_id"],
                    expected_lifecycle_revision=operation[
                        "expected_lifecycle_revision"
                    ],
                    actual_lifecycle_revision=previous["lifecycle_revision"],
                    actual_status=previous["status"],
                )
            )
        elif previous["object"]["project_id"] != int(target_project_id):
            precondition_errors.append(
                compatibility_error(
                    "TS_COMPAT_PROJECT_CONTEXT_MISMATCH",
                    {
                        "linkable_object_id": previous["object"]["id"],
                        "target_project_id": target_project_id,
                        "object_project_id": previous["object"]["project_id"],
                    },
                )
            )
        errors = [*precondition_errors, *target_result["errors"]]
        allowed = not errors
        observation["previous_association"] = (
            {
                "association_id": previous["association_id"],
                "signal_id": previous["signal_id"],
                "time_series_set_id": previous["set"]["id"],
                "linkable_object_id": previous["object"]["id"],
                "binding_role_id": previous["binding_role"]["id"],
                "binding_role_key": previous["binding_role"]["key"],
                "compatibility_rule_id": previous["compatibility_rule_id"],
                "lifecycle_revision": previous["lifecycle_revision"],
                "status": previous["status"],
                "validation": previous["validation"],
            }
            if previous is not None
            else None
        )
        target_result.update(
            {
                "action": "replace",
                "normalized_operation": operation,
                "verdict": "confirmation_required" if allowed else "rejected",
                "errors": errors,
                "observed_state": observation,
                "comparison": {"before": previous, "after": operation},
            }
        )
        if precondition_errors:
            target_result["compatibility_decision"] = {
                **target_result["compatibility_decision"],
                "allowed": False,
                "errors": errors,
                "primary_error": errors[0],
            }
        return target_result, observation

    def _prevalidate_existing_catalog_association(
        self,
        operation: dict[str, Any],
        *,
        target_project_id: int,
        batch_cache: dict[str, dict[Any, Any]] | None = None,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        try:
            previous = self.read_catalog_association(operation["association_id"])
        except KeyError:
            previous = None
        errors: list[dict[str, Any]] = []
        if previous is None:
            errors.append(
                self._association_operation_error(
                    "TS_LINK_PRECONDITION_CHANGED",
                    field="association_id",
                    association_id=operation["association_id"],
                    reason="not_found",
                )
            )
        elif (
            previous["status"] != "active"
            or previous["lifecycle_revision"]
            != operation["expected_lifecycle_revision"]
        ):
            errors.append(
                self._association_operation_error(
                    "TS_LINK_PRECONDITION_CHANGED",
                    field="expected_lifecycle_revision",
                    association_id=operation["association_id"],
                    expected_lifecycle_revision=operation[
                        "expected_lifecycle_revision"
                    ],
                    actual_lifecycle_revision=previous["lifecycle_revision"],
                    actual_status=previous["status"],
                )
            )
        elif previous["object"]["project_id"] != int(target_project_id):
            errors.append(
                compatibility_error(
                    "TS_COMPAT_PROJECT_CONTEXT_MISMATCH",
                    {
                        "linkable_object_id": previous["object"]["id"],
                        "target_project_id": target_project_id,
                        "object_project_id": previous["object"]["project_id"],
                    },
                )
            )

        observation: dict[str, Any] = {
            "previous_association": (
                {
                    "association_id": previous["association_id"],
                    "signal_id": previous["signal_id"],
                    "time_series_set_id": previous["set"]["id"],
                    "linkable_object_id": previous["object"]["id"],
                    "binding_role_id": previous["binding_role"]["id"],
                    "binding_role_key": previous["binding_role"]["key"],
                    "compatibility_rule_id": previous["compatibility_rule_id"],
                    "lifecycle_revision": previous["lifecycle_revision"],
                    "status": previous["status"],
                    "validation": previous["validation"],
                }
                if previous is not None
                else None
            )
        }
        decision = {
            "allowed": not errors,
            "compatibility_rule_id": (
                previous["compatibility_rule_id"] if previous is not None else None
            ),
            "rule_version": None,
            "contract_version": CLASSIFICATION_CONTRACT_VERSION,
            "errors": list(errors),
            "primary_error": errors[0] if errors else None,
        }
        if previous is not None and operation["action"] == "revalidate":
            target_operation = {
                **operation,
                "signal_id": previous["signal_id"],
                "linkable_object_id": previous["object"]["id"],
                "binding_role_key": previous["binding_role"]["key"],
            }
            target_result, target_observation = (
                self._prevalidate_catalog_association_add(
                    target_operation,
                    target_project_id=target_project_id,
                    batch_cache=batch_cache,
                )
            )
            observation.update(target_observation)
            errors.extend(target_result["errors"])
            decision = target_result["compatibility_decision"]
        allowed = not errors
        verdict = (
            "rejected"
            if not allowed
            else "confirmation_required"
            if operation["action"] == "archive"
            else "accepted"
        )
        result = {
            "client_operation_id": operation["client_operation_id"],
            "action": operation["action"],
            "normalized_operation": operation,
            "verdict": verdict,
            "compatibility_decision": {
                **decision,
                "allowed": allowed,
                "errors": errors,
                "primary_error": errors[0] if errors else None,
            },
            "errors": errors,
            "observed_state": observation,
            "comparison": {"before": previous, "after": operation},
        }
        return result, observation

    def prevalidate_catalog_association_batch(
        self, document: Mapping[str, Any], *, actor_class: str
    ) -> dict[str, Any]:
        """Evaluate a complete batch without reserving or writing anything."""

        normalized = normalize_association_request(document)
        self.get_project(normalized["target_project_id"])
        results: list[dict[str, Any]] = []
        observations: list[dict[str, Any]] = []
        batch_cache: dict[str, dict[Any, Any]] = {
            "linkable": {},
            "compatibility": {},
            "role": {},
        }
        claimed_targets: dict[tuple[int, int, str], str] = {}
        claimed_associations: dict[int, str] = {}
        for operation in normalized["operations"]:
            if operation["action"] == "add":
                result, observation = self._prevalidate_catalog_association_add(
                    operation,
                    target_project_id=normalized["target_project_id"],
                    batch_cache=batch_cache,
                )
            elif operation["action"] == "replace":
                result, observation = self._prevalidate_catalog_association_replace(
                    operation,
                    target_project_id=normalized["target_project_id"],
                    batch_cache=batch_cache,
                )
            elif operation["action"] in {"archive", "revalidate"}:
                result, observation = self._prevalidate_existing_catalog_association(
                    operation,
                    target_project_id=normalized["target_project_id"],
                    batch_cache=batch_cache,
                )
            else:
                raise AssociationMutationError(
                    "TS_LINK_PAYLOAD_INVALID",
                    field="operations.action",
                    reason="not_implemented",
                )
            conflicting_with = None
            if operation["action"] in {"add", "replace"}:
                target = (
                    operation["signal_id"],
                    operation["linkable_object_id"],
                    operation["binding_role_key"],
                )
                conflicting_with = claimed_targets.get(target)
                claimed_targets.setdefault(target, operation["client_operation_id"])
            if operation["action"] in {"replace", "archive", "revalidate"}:
                association_id = operation["association_id"]
                conflicting_with = (
                    conflicting_with
                    or claimed_associations.get(association_id)
                )
                claimed_associations.setdefault(
                    association_id, operation["client_operation_id"]
                )
            if conflicting_with is not None:
                conflict = self._association_operation_error(
                    "TS_LINK_CONFLICT",
                    field="client_operation_id",
                    client_operation_id=operation["client_operation_id"],
                    conflicts_with=conflicting_with,
                )
                result["verdict"] = "rejected"
                result["errors"] = [conflict, *result["errors"]]
                result["compatibility_decision"] = {
                    **result["compatibility_decision"],
                    "allowed": False,
                    "errors": result["errors"],
                    "primary_error": conflict,
                }
                observation["batch_conflict"] = {
                    "conflicts_with": conflicting_with
                }
            results.append(result)
            observations.append(observation)
        request_hash = association_request_hash(normalized)
        commit_etag = association_commit_etag(
            normalized, observations, actor_class=actor_class
        )
        token, expires_at = issue_prevalidation_token(
            request_hash=request_hash,
            commit_etag=commit_etag,
            actor_class=actor_class,
            secret=self._catalog_cursor_secret,
        )
        requires_confirmation = any(
            item["verdict"] == "confirmation_required" for item in results
        )
        return {
            "normalized_request": normalized,
            "request_hash": request_hash,
            "operations": results,
            "can_commit": all(item["verdict"] != "rejected" for item in results),
            "requires_confirmation": requires_confirmation,
            "expires_at": expires_at,
            "prevalidation_token": token,
            "commit_etag": commit_etag,
        }

    @staticmethod
    def _association_fingerprint(value: Mapping[str, Any]) -> str:
        encoded = json.dumps(value, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(encoded.encode("utf-8")).hexdigest()

    def _catalog_association_fingerprints(
        self,
        *,
        observed: Mapping[str, Any],
        binding_role_key: str,
        contract_version: int,
    ) -> tuple[str, str]:
        signal = observed["signal"]
        linkable = observed["object"]
        compatibility_fingerprint = self._association_fingerprint(
            {
                "signal_role": signal["signal_role"],
                "semantic_type_key": signal["semantic_type_key"],
                "data_class_key": signal["data_class_key"],
                "unit_key": signal["unit_key"],
                "binding_role_key": binding_role_key,
                "object_type_key": linkable["object_type_key"],
                "visibility_scope": signal["visibility_scope"],
                "owner_project_id": signal["owner_project_id"],
                "compatibility_rule_id": observed["compatibility_rule_id"],
                "rule_version": observed["rule_version"],
                "contract_version": contract_version,
            }
        )
        object_scope_fingerprint = self._association_fingerprint(
            {
                "object_id": linkable["id"],
                "object_project_id": linkable["project_id"],
                "object_status": linkable["status"],
                "source_scope": signal["visibility_scope"],
                "scope_revision": signal["scope_revision"],
                "source_owner_project_id": signal["owner_project_id"],
            }
        )
        return compatibility_fingerprint, object_scope_fingerprint

    def _case_binding_fingerprints(
        self,
        *,
        observed: Mapping[str, Any],
        binding_role_key: str,
        contract_version: int,
    ) -> tuple[str, str]:
        compatibility, object_scope = self._catalog_association_fingerprints(
            observed=observed,
            binding_role_key=binding_role_key,
            contract_version=contract_version,
        )
        return (
            self._association_fingerprint(
                {
                    "compatibility_fingerprint": compatibility,
                    "catalog_association": observed.get("catalog_association"),
                }
            ),
            object_scope,
        )

    def _case_binding_variant_dependency_fingerprint(
        self, *, scenario_id: int, variant_id: int, project_id: int
    ) -> str:
        dependencies = [
            dependency
            for dependency in self._current_case_input_variant_dependencies(
                scenario_id=scenario_id,
                case_input_variant_id=variant_id,
            )
            if dependency["dependency_type"] in {"topology", "parameters"}
        ]
        return self._association_fingerprint(
            {
                "scenario_id": int(scenario_id),
                "variant_id": int(variant_id),
                "project_id": int(project_id),
                "dependencies": dependencies,
            }
        )

    def _insert_catalog_association_add(
        self,
        *,
        operation: dict[str, Any],
        prevalidated: dict[str, Any],
        actor_user: Mapping[str, Any],
        request_id: str,
        batch_id: str,
        occurred_at: str,
        supersedes_association_id: int | None = None,
        event_type: str = "created",
    ) -> dict[str, Any]:
        observed = prevalidated["observed_state"]
        existing = observed["active_association"]
        if existing is not None:
            return {
                "client_operation_id": operation["client_operation_id"],
                "action": "add",
                "outcome": "unchanged",
                "association_id": existing["id"],
            }
        signal = observed["signal"]
        linkable = observed["object"]
        rule_id = int(observed["compatibility_rule_id"])
        role_id = int(observed["binding_role_id"])
        association_table = self.link_layer_table_names()[
            "time_series_catalog_associations"
        ]
        association_id = self._insert_canonical_row(
            f"""
            INSERT INTO {association_table} (
                signal_id, time_series_set_id, linkable_object_id,
                binding_role_id, compatibility_rule_id,
                supersedes_association_id, lifecycle_revision, status, created_at, created_by,
                metadata_json
            ) VALUES (?, ?, ?, ?, ?, ?, 1, 'active', ?, ?, ?)
            """,
            (
                operation["signal_id"],
                signal["time_series_set_id"],
                operation["linkable_object_id"],
                role_id,
                rule_id,
                supersedes_association_id,
                occurred_at,
                actor_user["email"],
                json.dumps(
                    {
                        "client_operation_id": operation["client_operation_id"],
                        "request_id": request_id,
                    },
                    sort_keys=True,
                ),
            ),
        )
        compatibility_fingerprint, object_scope_fingerprint = (
            self._catalog_association_fingerprints(
                observed=observed,
                binding_role_key=operation["binding_role_key"],
                contract_version=prevalidated["compatibility_decision"][
                    "contract_version"
                ],
            )
        )
        validations = self.link_layer_table_names()["time_series_link_validations"]
        self.connection.execute(
            f"""
            INSERT INTO {validations} (
                catalog_association_id, subject_lifecycle_revision,
                validation_mode, validated_set_revision_id,
                observed_current_revision_id, compatibility_rule_id,
                compatibility_fingerprint, object_scope_fingerprint,
                validated_at, validated_by, reason_code, reason_text
            ) VALUES (?, 1, 'association_current', ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                association_id,
                signal["current_revision_id"],
                signal["current_revision_id"],
                rule_id,
                compatibility_fingerprint,
                object_scope_fingerprint,
                occurred_at,
                actor_user["email"],
                operation["reason_code"],
                operation.get("reason_text"),
            ),
        )
        event_table = self.link_layer_table_names()["time_series_link_events"]
        after = {
            "association_id": association_id,
            "signal_id": operation["signal_id"],
            "linkable_object_id": operation["linkable_object_id"],
            "binding_role_key": operation["binding_role_key"],
            "lifecycle_revision": 1,
            "status": "active",
            "supersedes_association_id": supersedes_association_id,
        }
        self.connection.execute(
            f"""
            INSERT INTO {event_table} (
                batch_id, catalog_association_id, event_type,
                actor_user_id, actor_identity_snapshot, actor_role_snapshot,
                reason_code, reason_text, before_json, after_json,
                request_id, occurred_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, '{{}}', ?, ?, ?)
            """,
            (
                batch_id,
                association_id,
                event_type,
                actor_user.get("id"),
                actor_user["email"],
                actor_user["role"],
                operation["reason_code"],
                operation.get("reason_text"),
                json.dumps(after, sort_keys=True),
                request_id,
                occurred_at,
            ),
        )
        return {
            "client_operation_id": operation["client_operation_id"],
            "action": operation["action"],
            "outcome": "replaced" if event_type == "replaced" else "created",
            "association_id": association_id,
        }

    def _replace_catalog_association(
        self,
        *,
        operation: dict[str, Any],
        prevalidated: dict[str, Any],
        actor_user: Mapping[str, Any],
        request_id: str,
        batch_id: str,
        occurred_at: str,
    ) -> dict[str, Any]:
        previous = prevalidated["observed_state"]["previous_association"]
        association_table = self.link_layer_table_names()[
            "time_series_catalog_associations"
        ]
        archived_revision = int(previous["lifecycle_revision"]) + 1
        self.connection.execute(
            f"""
            UPDATE {association_table}
            SET status = 'archived', lifecycle_revision = ?, archived_at = ?,
                archived_by = ?, archived_reason_code = ?,
                archived_reason_text = ?
            WHERE id = ? AND status = 'active' AND lifecycle_revision = ?
            """,
            (
                archived_revision,
                occurred_at,
                actor_user["email"],
                operation["reason_code"],
                operation.get("reason_text"),
                previous["association_id"],
                previous["lifecycle_revision"],
            ),
        )
        event_table = self.link_layer_table_names()["time_series_link_events"]
        before = {
            "association_id": previous["association_id"],
            "signal_id": previous["signal_id"],
            "linkable_object_id": previous["linkable_object_id"],
            "binding_role_key": previous["binding_role_key"],
            "lifecycle_revision": previous["lifecycle_revision"],
            "status": "active",
        }
        after = {
            **before,
            "lifecycle_revision": archived_revision,
            "status": "archived",
        }
        self.connection.execute(
            f"""
            INSERT INTO {event_table} (
                batch_id, catalog_association_id, event_type,
                actor_user_id, actor_identity_snapshot, actor_role_snapshot,
                reason_code, reason_text, before_json, after_json,
                request_id, occurred_at
            ) VALUES (?, ?, 'superseded', ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                batch_id,
                previous["association_id"],
                actor_user.get("id"),
                actor_user["email"],
                actor_user["role"],
                operation["reason_code"],
                operation.get("reason_text"),
                json.dumps(before, sort_keys=True),
                json.dumps(after, sort_keys=True),
                request_id,
                occurred_at,
            ),
        )
        return self._insert_catalog_association_add(
            operation=operation,
            prevalidated=prevalidated,
            actor_user=actor_user,
            request_id=request_id,
            batch_id=batch_id,
            occurred_at=occurred_at,
            supersedes_association_id=previous["association_id"],
            event_type="replaced",
        )

    def _archive_catalog_association(
        self,
        *,
        operation: dict[str, Any],
        prevalidated: dict[str, Any],
        actor_user: Mapping[str, Any],
        request_id: str,
        batch_id: str,
        occurred_at: str,
    ) -> dict[str, Any]:
        previous = prevalidated["observed_state"]["previous_association"]
        association_table = self.link_layer_table_names()[
            "time_series_catalog_associations"
        ]
        archived_revision = int(previous["lifecycle_revision"]) + 1
        self.connection.execute(
            f"""
            UPDATE {association_table}
            SET status = 'archived', lifecycle_revision = ?, archived_at = ?,
                archived_by = ?, archived_reason_code = ?,
                archived_reason_text = ?
            WHERE id = ? AND status = 'active' AND lifecycle_revision = ?
            """,
            (
                archived_revision,
                occurred_at,
                actor_user["email"],
                operation["reason_code"],
                operation.get("reason_text"),
                previous["association_id"],
                previous["lifecycle_revision"],
            ),
        )
        before = {
            "association_id": previous["association_id"],
            "signal_id": previous["signal_id"],
            "linkable_object_id": previous["linkable_object_id"],
            "binding_role_key": previous["binding_role_key"],
            "lifecycle_revision": previous["lifecycle_revision"],
            "status": "active",
        }
        after = {
            **before,
            "lifecycle_revision": archived_revision,
            "status": "archived",
        }
        event_table = self.link_layer_table_names()["time_series_link_events"]
        self.connection.execute(
            f"""
            INSERT INTO {event_table} (
                batch_id, catalog_association_id, event_type,
                actor_user_id, actor_identity_snapshot, actor_role_snapshot,
                reason_code, reason_text, before_json, after_json,
                request_id, occurred_at
            ) VALUES (?, ?, 'archived', ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                batch_id,
                previous["association_id"],
                actor_user.get("id"),
                actor_user["email"],
                actor_user["role"],
                operation["reason_code"],
                operation.get("reason_text"),
                json.dumps(before, sort_keys=True),
                json.dumps(after, sort_keys=True),
                request_id,
                occurred_at,
            ),
        )
        return {
            "client_operation_id": operation["client_operation_id"],
            "action": "archive",
            "outcome": "archived",
            "association_id": previous["association_id"],
        }

    def _revalidate_catalog_association(
        self,
        *,
        operation: dict[str, Any],
        prevalidated: dict[str, Any],
        actor_user: Mapping[str, Any],
        request_id: str,
        batch_id: str,
        occurred_at: str,
    ) -> dict[str, Any]:
        observed = prevalidated["observed_state"]
        previous = observed["previous_association"]
        signal = observed["signal"]
        linkable = observed["object"]
        compatibility_fingerprint, object_scope_fingerprint = (
            self._catalog_association_fingerprints(
                observed=observed,
                binding_role_key=previous["binding_role_key"],
                contract_version=prevalidated["compatibility_decision"][
                    "contract_version"
                ],
            )
        )
        validations = self.link_layer_table_names()["time_series_link_validations"]
        self.connection.execute(
            f"""
            INSERT INTO {validations} (
                catalog_association_id, subject_lifecycle_revision,
                validation_mode, validated_set_revision_id,
                observed_current_revision_id, compatibility_rule_id,
                compatibility_fingerprint, object_scope_fingerprint,
                validated_at, validated_by, reason_code, reason_text
            ) VALUES (?, ?, 'association_current', ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                previous["association_id"],
                previous["lifecycle_revision"],
                signal["current_revision_id"],
                signal["current_revision_id"],
                observed["compatibility_rule_id"],
                compatibility_fingerprint,
                object_scope_fingerprint,
                occurred_at,
                actor_user["email"],
                operation["reason_code"],
                operation.get("reason_text"),
            ),
        )
        event_table = self.link_layer_table_names()["time_series_link_events"]
        state = {
            "association_id": previous["association_id"],
            "signal_id": previous["signal_id"],
            "linkable_object_id": previous["linkable_object_id"],
            "binding_role_key": previous["binding_role_key"],
            "lifecycle_revision": previous["lifecycle_revision"],
            "status": "active",
        }
        self.connection.execute(
            f"""
            INSERT INTO {event_table} (
                batch_id, catalog_association_id, event_type,
                actor_user_id, actor_identity_snapshot, actor_role_snapshot,
                reason_code, reason_text, before_json, after_json,
                request_id, occurred_at
            ) VALUES (?, ?, 'revalidated_current', ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                batch_id,
                previous["association_id"],
                actor_user.get("id"),
                actor_user["email"],
                actor_user["role"],
                operation["reason_code"],
                operation.get("reason_text"),
                json.dumps(state, sort_keys=True),
                json.dumps(
                    {
                        **state,
                        "compatibility_fingerprint": compatibility_fingerprint,
                    },
                    sort_keys=True,
                ),
                request_id,
                occurred_at,
            ),
        )
        return {
            "client_operation_id": operation["client_operation_id"],
            "action": "revalidate",
            "outcome": "revalidated",
            "association_id": previous["association_id"],
        }

    def commit_catalog_association_batch(
        self,
        document: Mapping[str, Any],
        *,
        actor_user: Mapping[str, Any],
        actor_class: str,
        request_id: str,
        prevalidation_token: str,
        if_match: str,
        idempotency_key: str,
        confirmed: bool,
    ) -> tuple[dict[str, Any], bool]:
        """Reauthorize, re-evaluate and write one batch in one transaction."""

        normalized = normalize_association_request(document)
        request_hash = association_request_hash(normalized)
        verify_prevalidation_token(
            prevalidation_token,
            request_hash=request_hash,
            commit_etag=if_match,
            actor_class=actor_class,
            secret=self._catalog_cursor_secret,
            check_expiry=False,
        )
        claim_hash = association_request_hash(
            {"request": normalized, "confirmed": bool(confirmed)}
        )
        try:
            with self._lock:
                with self._database_transaction():
                    claim = self._claim_idempotency(
                        actor_id=actor_class,
                        operation_kind="association_batch",
                        scope_key=f"project:{normalized['target_project_id']}",
                        idempotency_key=idempotency_key,
                        request_hash=claim_hash,
                    )
                    if claim["state"] == "completed":
                        return claim["response"], True
                    verify_prevalidation_token(
                        prevalidation_token,
                        request_hash=request_hash,
                        commit_etag=if_match,
                        actor_class=actor_class,
                        secret=self._catalog_cursor_secret,
                    )
                    self._lock_catalog_association_batch(normalized)
                    current = self.prevalidate_catalog_association_batch(
                        normalized, actor_class=actor_class
                    )
                    if current["commit_etag"] != if_match:
                        scope_error = next(
                            (
                                error
                                for row in current["operations"]
                                for error in row["errors"]
                                if error["code"] == "TS_COMPAT_SCOPE_NOT_ACCESSIBLE"
                            ),
                            None,
                        )
                        if scope_error is not None:
                            raise AssociationMutationError(
                                "TS_COMPAT_SCOPE_NOT_ACCESSIBLE",
                                **scope_error["context"],
                                details=current["operations"],
                            )
                        raise AssociationMutationError(
                            "TS_LINK_PRECONDITION_CHANGED",
                            expected_etag=if_match,
                            actual_etag=current["commit_etag"],
                        )
                    if not current["can_commit"]:
                        raise AssociationMutationError(
                            "TS_LINK_BATCH_REJECTED",
                            details=current["operations"],
                            normalized_request=normalized,
                        )
                    if current["requires_confirmation"] and not confirmed:
                        raise AssociationMutationError(
                            "TS_LINK_CONFIRMATION_REQUIRED"
                        )
                    batch_id = f"asb_{uuid.uuid4().hex}"
                    occurred_at = utc_now_iso()
                    results = []
                    for operation, prevalidated in zip(
                        normalized["operations"], current["operations"]
                    ):
                        if operation["action"] == "replace":
                            result = self._replace_catalog_association(
                                operation=operation,
                                prevalidated=prevalidated,
                                actor_user=actor_user,
                                request_id=request_id,
                                batch_id=batch_id,
                                occurred_at=occurred_at,
                            )
                        elif operation["action"] == "archive":
                            result = self._archive_catalog_association(
                                operation=operation,
                                prevalidated=prevalidated,
                                actor_user=actor_user,
                                request_id=request_id,
                                batch_id=batch_id,
                                occurred_at=occurred_at,
                            )
                        elif operation["action"] == "revalidate":
                            result = self._revalidate_catalog_association(
                                operation=operation,
                                prevalidated=prevalidated,
                                actor_user=actor_user,
                                request_id=request_id,
                                batch_id=batch_id,
                                occurred_at=occurred_at,
                            )
                        else:
                            result = self._insert_catalog_association_add(
                                operation=operation,
                                prevalidated=prevalidated,
                                actor_user=actor_user,
                                request_id=request_id,
                                batch_id=batch_id,
                                occurred_at=occurred_at,
                            )
                        results.append(result)
                    mutated = any(item["outcome"] != "unchanged" for item in results)
                    catalog_changed = any(
                        item["outcome"] in {"created", "replaced", "archived"}
                        for item in results
                    )
                    if catalog_changed:
                        affected_signals = sorted(
                            {
                                signal_id
                                for operation, prevalidated in zip(
                                    normalized["operations"], current["operations"]
                                )
                                for signal_id in (
                                    operation.get("signal_id"),
                                    (
                                        prevalidated["observed_state"]
                                        .get("previous_association", {})
                                        .get("signal_id")
                                    ),
                                )
                                if signal_id is not None
                            }
                        )
                        association_table = self.link_layer_table_names()[
                            "time_series_catalog_associations"
                        ]
                        entries = self._projection("time_series_catalog_entries")
                        placeholders = ", ".join("?" for _ in affected_signals)
                        self.connection.execute(
                            f"""
                            UPDATE {entries}
                            SET association_count = (
                                SELECT COUNT(*) FROM {association_table}
                                WHERE signal_id = {entries}.signal_id
                                  AND status = 'active'
                            ), projection_revision = projection_revision + 1,
                                updated_at = ?
                            WHERE signal_id IN ({placeholders})
                            """,
                            (occurred_at, *affected_signals),
                        )
                        self._raise_catalog_generation(now=occurred_at)
                    response = {
                        "outcome": "created" if mutated else "unchanged",
                        "batch_id": batch_id,
                        "target_project_id": normalized["target_project_id"],
                        "operations": results,
                        "request_id": request_id,
                    }
                    self._complete_idempotency(
                        claim_id=claim["id"],
                        response=response,
                        http_status=200 if response["outcome"] == "unchanged" else 201,
                    )
                    return response, False
        except CanonicalRevisionError as error:
            if error.code in {"TS_IDEMPOTENCY_KEY_CONFLICT", "TS_IDEMPOTENCY_IN_FLIGHT"}:
                raise AssociationMutationError(
                    "TS_IDEMPOTENCY_CONFLICT", reason=error.code
                ) from error
            raise
        except Exception as error:
            constraint_name = str(
                getattr(getattr(error, "diag", None), "constraint_name", "") or ""
            )
            error_text = str(error).lower()
            active_identity_conflict = (
                constraint_name
                == "time_series_catalog_associations_next_one_active_uk"
                or (
                    "unique constraint failed" in error_text
                    and "time_series_catalog_associations" in error_text
                    and "signal_id" in error_text
                )
            )
            if active_identity_conflict:
                raise AssociationMutationError(
                    "TS_LINK_CONFLICT", reason="active_identity_race"
                ) from error
            raise

    def _lock_catalog_association_batch(
        self, normalized: Mapping[str, Any]
    ) -> None:
        """Serialize every resource a PostgreSQL association batch can mutate.

        Sets are locked first, then objects, then existing associations, each in
        ascending ID order. Revision publication and scope changes already write
        the set row, while object archival writes the object row, so revalidation
        below observes one stable world without broad table locks.
        """

        if self.database_backend != "postgresql":
            return

        association_ids = sorted(
            {
                int(operation["association_id"])
                for operation in normalized["operations"]
                if operation["action"] in {"replace", "archive", "revalidate"}
            }
        )
        signal_ids = {
            int(operation["signal_id"])
            for operation in normalized["operations"]
            if operation["action"] in {"add", "replace"}
        }
        object_ids = {
            int(operation["linkable_object_id"])
            for operation in normalized["operations"]
            if operation["action"] in {"add", "replace"}
        }
        set_ids: set[int] = set()

        association_table = self.link_layer_table_names()[
            "time_series_catalog_associations"
        ]
        if association_ids:
            placeholders = ", ".join("?" for _ in association_ids)
            rows = self.connection.execute(
                f"""
                SELECT signal_id, time_series_set_id, linkable_object_id
                FROM {association_table}
                WHERE id IN ({placeholders})
                ORDER BY id
                """,
                tuple(association_ids),
            ).fetchall()
            for row in rows:
                signal_ids.add(int(row["signal_id"]))
                set_ids.add(int(row["time_series_set_id"]))
                object_ids.add(int(row["linkable_object_id"]))

        if signal_ids:
            ordered_signal_ids = sorted(signal_ids)
            placeholders = ", ".join("?" for _ in ordered_signal_ids)
            rows = self.connection.execute(
                f"""
                SELECT DISTINCT time_series_set_id
                FROM {self._canonical('time_series_signals')}
                WHERE id IN ({placeholders})
                ORDER BY time_series_set_id
                """,
                tuple(ordered_signal_ids),
            ).fetchall()
            set_ids.update(int(row["time_series_set_id"]) for row in rows)

        for table, ids in (
            (self._canonical("time_series_sets"), sorted(set_ids)),
            (self._linkable("linkable_objects"), sorted(object_ids)),
            (association_table, association_ids),
        ):
            if not ids:
                continue
            placeholders = ", ".join("?" for _ in ids)
            self.connection.execute(
                f"""
                SELECT id FROM {table}
                WHERE id IN ({placeholders})
                ORDER BY id
                FOR UPDATE
                """,
                tuple(ids),
            ).fetchall()

    def _catalog_association_row(self, association_id: int):
        table = self.link_layer_table_names()["time_series_catalog_associations"]
        validations = self.link_layer_table_names()["time_series_link_validations"]
        return self.connection.execute(
            f"""
            SELECT association.*, role.role_key, role.display_name AS role_display_name,
                   role.status AS role_status,
                   entry.series_key, entry.display_name AS signal_display_name,
                   entry.visibility_scope, entry.owner_project_id,
                   entry.owner_project_name, entry.set_status, entry.signal_status,
                   validation.compatibility_fingerprint,
                   validation.object_scope_fingerprint,
                   validation.validated_set_revision_id,
                   validation.validated_at
            FROM {table} AS association
            JOIN time_series_binding_roles AS role
              ON role.id = association.binding_role_id
            JOIN {self._projection('time_series_catalog_entries')} AS entry
              ON entry.signal_id = association.signal_id
            LEFT JOIN {validations} AS validation
              ON validation.id = (
                  SELECT latest.id FROM {validations} AS latest
                  WHERE latest.catalog_association_id = association.id
                  ORDER BY latest.id DESC LIMIT 1
              )
            WHERE association.id = ?
            """,
            (int(association_id),),
        ).fetchone()

    def read_catalog_association(self, association_id: int) -> dict[str, Any]:
        row = self._catalog_association_row(association_id)
        if row is None:
            raise KeyError(f"catalog association {association_id} not found")
        item = dict(row)
        linkable = self.get_linkable_object(int(item["linkable_object_id"]))
        if item["status"] == "archived":
            state = "archived"
        else:
            current_result, current_observation = (
                self._prevalidate_catalog_association_add(
                    {
                        "client_operation_id": "effective-state",
                        "action": "add",
                        "signal_id": int(item["signal_id"]),
                        "linkable_object_id": int(item["linkable_object_id"]),
                        "binding_role_key": item["role_key"],
                        "expected_absent": True,
                        "reason_code": "effective_state_read",
                    },
                    target_project_id=int(linkable["project_id"]),
                )
            )
            if not current_result["compatibility_decision"]["allowed"]:
                state = "active_incompatible"
            else:
                current_compatibility, current_scope = (
                    self._catalog_association_fingerprints(
                        observed=current_observation,
                        binding_role_key=item["role_key"],
                        contract_version=current_result[
                            "compatibility_decision"
                        ]["contract_version"],
                    )
                )
                state = (
                    "active_valid"
                    if current_compatibility == item["compatibility_fingerprint"]
                    and current_scope == item["object_scope_fingerprint"]
                    else "active_stale"
                )
        association_id = int(item["id"])
        return {
            "association_id": association_id,
            "signal_id": int(item["signal_id"]),
            "signal": {
                "id": int(item["signal_id"]),
                "series_key": item["series_key"],
                "display_name": item["signal_display_name"],
            },
            "set": {
                "id": int(item["time_series_set_id"]),
                "visibility_scope": item["visibility_scope"],
                "owner_project_id": int(item["owner_project_id"]),
                "owner_project_name": item["owner_project_name"],
            },
            "object": {
                "id": int(linkable["id"]),
                "project_id": int(linkable["project_id"]),
                "object_kind": linkable["object_kind"],
                "object_type_key": linkable["object_type_key"],
                "object_key": linkable["object_key"],
                "display_name": linkable["display_name"],
                "status": linkable["status"],
            },
            "binding_role": {
                "id": int(item["binding_role_id"]),
                "key": item["role_key"],
                "display_name": item["role_display_name"],
            },
            "compatibility_rule_id": int(item["compatibility_rule_id"]),
            "supersedes_association_id": (
                int(item["supersedes_association_id"])
                if item["supersedes_association_id"] is not None
                else None
            ),
            "lifecycle_revision": int(item["lifecycle_revision"]),
            "status": item["status"],
            "state": state,
            "created_at": item["created_at"],
            "created_by": item["created_by"],
            "archived_at": item["archived_at"],
            "archived_by": item["archived_by"],
            "archive_reason": (
                {
                    "code": item["archived_reason_code"],
                    "text": item["archived_reason_text"],
                }
                if item["status"] == "archived"
                else None
            ),
            "validation": {
                "validated_revision_id": (
                    int(item["validated_set_revision_id"])
                    if item["validated_set_revision_id"] is not None
                    else None
                ),
                "compatibility_fingerprint": item["compatibility_fingerprint"],
                "object_scope_fingerprint": item["object_scope_fingerprint"],
                "validated_at": item["validated_at"],
            },
            "capabilities": {
                "replace": item["status"] == "active",
                "archive": item["status"] == "active",
                "revalidate": item["status"] == "active",
            },
            "links": {
                "detail": f"/api/time-series/catalog/associations/{association_id}",
                "events": f"/api/time-series/catalog/associations/{association_id}/events",
            },
        }

    def read_catalog_associations(
        self,
        *,
        limit: int | None = None,
        cursor: str | None = None,
        actor_class: str = "internal",
    ) -> dict[str, Any]:
        table = self.link_layer_table_names()["time_series_catalog_associations"]
        events = self.link_layer_table_names()["time_series_link_events"]
        resolved_limit = normalize_catalog_limit(limit)
        summary = self.connection.execute(
            f"""
            SELECT COUNT(*) AS total_count, COALESCE(MAX(id), 0) AS max_id,
                   COALESCE(SUM(lifecycle_revision), 0) AS lifecycle_sum
            FROM {table}
            """
        ).fetchone()
        latest_event = self.connection.execute(
            f"SELECT COALESCE(MAX(id), 0) AS max_id FROM {events}"
        ).fetchone()
        generation = int(
            hashlib.sha256(
                (
                    f"{summary['total_count']}:{summary['max_id']}:"
                    f"{summary['lifecycle_sum']}:{latest_event['max_id']}"
                ).encode("utf-8")
            ).hexdigest()[:15],
            16,
        )
        filters_hash = input_filters_hash({})
        cursor_id = 0
        if cursor is not None:
            cursor_key = decode_catalog_cursor(
                cursor,
                self._catalog_cursor_secret,
                section="associations",
                order="id",
                limit=resolved_limit,
                generation=generation,
                actor_class=actor_class,
                filters_hash=filters_hash,
            )
            if len(cursor_key) != 1:
                raise CatalogQueryError(
                    "TS_QUERY_CURSOR_MISMATCH", reason="key_arity"
                )
            cursor_id = int(cursor_key[0])
        ids = self.connection.execute(
            f"SELECT id FROM {table} WHERE id > ? ORDER BY id LIMIT ?",
            (cursor_id, resolved_limit + 1),
        ).fetchall()
        has_more = len(ids) > resolved_limit
        visible = ids[:resolved_limit]
        items = [
            self.read_catalog_association(int(row["id"])) for row in visible
        ]
        next_cursor = None
        if has_more and visible:
            next_cursor = encode_catalog_cursor(
                {
                    "s": "associations",
                    "o": "id",
                    "l": resolved_limit,
                    "g": generation,
                    "k": [int(visible[-1]["id"])],
                    "t": int(time.time()),
                    "a": actor_class,
                    "f": filters_hash,
                },
                self._catalog_cursor_secret,
            )
        return {
            "items": items,
            "page": {
                "limit": resolved_limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
            "summary": {"total_count": int(summary["total_count"])},
            "meta": {
                "section": "associations",
                "catalog_generation": generation,
            },
        }

    def read_catalog_association_events(
        self,
        association_id: int,
        *,
        limit: int | None = None,
        cursor: str | None = None,
        actor_class: str = "internal",
    ) -> dict[str, Any]:
        self.read_catalog_association(association_id)
        events = self.link_layer_table_names()["time_series_link_events"]
        resolved_limit = normalize_catalog_limit(limit)
        summary = self.connection.execute(
            f"""
            SELECT COUNT(*) AS total_count, COALESCE(MAX(id), 0) AS max_id
            FROM {events} WHERE catalog_association_id = ?
            """,
            (int(association_id),),
        ).fetchone()
        generation = int(
            hashlib.sha256(
                f"{summary['total_count']}:{summary['max_id']}".encode("utf-8")
            ).hexdigest()[:15],
            16,
        )
        section = f"association:{int(association_id)}:events"
        filters_hash = input_filters_hash({"association_id": int(association_id)})
        cursor_id = 0
        if cursor is not None:
            cursor_key = decode_catalog_cursor(
                cursor,
                self._catalog_cursor_secret,
                section=section,
                order="id",
                limit=resolved_limit,
                generation=generation,
                actor_class=actor_class,
                filters_hash=filters_hash,
            )
            if len(cursor_key) != 1:
                raise CatalogQueryError(
                    "TS_QUERY_CURSOR_MISMATCH", reason="key_arity"
                )
            cursor_id = int(cursor_key[0])
        rows = self.connection.execute(
            f"""
            SELECT * FROM {events}
            WHERE catalog_association_id = ? AND id > ?
            ORDER BY id LIMIT ?
            """,
            (int(association_id), cursor_id, resolved_limit + 1),
        ).fetchall()
        has_more = len(rows) > resolved_limit
        visible = rows[:resolved_limit]
        items = []
        for row in visible:
            event = dict(row)
            items.append(
                {
                    "event_id": int(event["id"]),
                    "batch_id": event["batch_id"],
                    "association_id": int(event["catalog_association_id"]),
                    "event_type": event["event_type"],
                    "actor": {
                        "user_id": (
                            int(event["actor_user_id"])
                            if event["actor_user_id"] is not None
                            else None
                        ),
                        "identity": event["actor_identity_snapshot"],
                        "role": event["actor_role_snapshot"],
                    },
                    "reason": {
                        "code": event["reason_code"],
                        "text": event["reason_text"],
                    },
                    "before": json.loads(event["before_json"]),
                    "after": json.loads(event["after_json"]),
                    "request_id": event["request_id"],
                    "occurred_at": event["occurred_at"],
                }
            )
        next_cursor = None
        if has_more and visible:
            next_cursor = encode_catalog_cursor(
                {
                    "s": section,
                    "o": "id",
                    "l": resolved_limit,
                    "g": generation,
                    "k": [int(visible[-1]["id"])],
                    "t": int(time.time()),
                    "a": actor_class,
                    "f": filters_hash,
                },
                self._catalog_cursor_secret,
            )
        return {
            "items": items,
            "page": {
                "limit": resolved_limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
            "meta": {
                "association_id": int(association_id),
                "catalog_generation": generation,
            },
        }

    # -- Exact case bindings (TS7-008) ------------------------------------

    def _canonical_binding_context(
        self, *, scenario_id: int, variant_id: int
    ) -> dict[str, Any]:
        row = self.connection.execute(
            """
            SELECT variant.id AS variant_id, variant.bindings_revision,
                   scenario.id AS scenario_id, scenario.project_id
            FROM case_input_variants AS variant
            JOIN optimization_cases AS optimization_case
              ON optimization_case.id = variant.case_id
            JOIN scenarios AS scenario
              ON scenario.id = optimization_case.scenario_id
            WHERE variant.id = ? AND scenario.id = ?
            """,
            (int(variant_id), int(scenario_id)),
        ).fetchone()
        if row is None:
            raise KeyError(
                f"case input variant {variant_id} not found for scenario {scenario_id}"
            )
        return {
            "scenario_id": int(row["scenario_id"]),
            "variant_id": int(row["variant_id"]),
            "project_id": int(row["project_id"]),
            "bindings_revision": int(row["bindings_revision"]),
        }

    @staticmethod
    def _binding_operation_error(
        code: str, *, field: str | None = None, **context: Any
    ) -> dict[str, Any]:
        error = BindingMutationError(code, **context)
        return {
            "code": error.code,
            "message_key": error.message_key,
            "message": error.message,
            "field": field if field is not None else error.field,
            "context": context,
        }

    def _prevalidate_case_binding_create(
        self,
        operation: dict[str, Any],
        *,
        context: Mapping[str, Any],
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        variant_dependency_fingerprint = context.get(
            "variant_dependency_fingerprint"
        ) or self._case_binding_variant_dependency_fingerprint(
            scenario_id=int(context["scenario_id"]),
            variant_id=int(context["variant_id"]),
            project_id=int(context["project_id"]),
        )
        revision_request = operation["revision"]
        requested_content_hash = str(revision_request["content_hash"]).removeprefix(
            "sha256:"
        )
        entry = self.connection.execute(
            f"""
            SELECT signal.id AS signal_id,
                   signal.time_series_set_id,
                   signal.series_key,
                   signal.display_name,
                   signal.status AS signal_status,
                   canonical_set.owner_project_id,
                   canonical_set.owner_linkable_object_id,
                   canonical_set.visibility_scope,
                   canonical_set.scope_revision,
                   canonical_set.series_kind,
                   canonical_set.status AS set_status,
                   canonical_set.current_revision_id,
                   current_revision.content_hash AS current_content_hash,
                   selected_revision.state AS selected_revision_state,
                   selected_revision.content_hash AS selected_content_hash,
                   revision_signal.signal_role,
                   semantic_type.semantic_key AS semantic_type_key,
                   data_class.data_class_key AS data_class_key,
                   unit.unit_key AS unit_key
            FROM {self._canonical('time_series_signals')} AS signal
            JOIN {self._canonical('time_series_sets')} AS canonical_set
              ON canonical_set.id = signal.time_series_set_id
            JOIN {self._canonical('time_series_set_revisions')} AS current_revision
              ON current_revision.id = canonical_set.current_revision_id
            JOIN {self._canonical('time_series_set_revisions')} AS selected_revision
              ON selected_revision.id = ?
             AND selected_revision.time_series_set_id = canonical_set.id
            JOIN {self._canonical('time_series_revision_signals')} AS revision_signal
              ON revision_signal.set_revision_id = selected_revision.id
             AND revision_signal.signal_id = signal.id
            JOIN time_series_semantic_types AS semantic_type
              ON semantic_type.id = revision_signal.semantic_type_id
            JOIN time_series_data_classes AS data_class
              ON data_class.id = revision_signal.data_class_id
            JOIN measurement_units AS unit ON unit.id = revision_signal.unit_id
            WHERE signal.id = ? AND revision_signal.signal_role = 'input'
            """,
            (revision_request["revision_id"], operation["signal_id"]),
        ).fetchone()
        try:
            linkable = self.get_linkable_object(operation["linkable_object_id"])
        except LinkableObjectError:
            linkable = None

        errors: list[dict[str, Any]] = []
        decision: dict[str, Any]
        role = None
        if entry is None:
            errors.append(
                compatibility_error(
                    "TS_COMPAT_SIGNAL_UNAVAILABLE",
                    {
                        "signal_id": operation["signal_id"],
                        "revision_id": revision_request["revision_id"],
                        "usage": "execution",
                    },
                )
            )
            decision = {
                "allowed": False,
                "compatibility_rule_id": None,
                "rule_version": None,
                "contract_version": CLASSIFICATION_CONTRACT_VERSION,
                "errors": list(errors),
                "primary_error": errors[0],
            }
        elif linkable is None:
            errors.append(
                compatibility_error(
                    "TS_COMPAT_OBJECT_UNAVAILABLE",
                    {
                        "linkable_object_id": operation["linkable_object_id"],
                        "usage": "execution",
                    },
                )
            )
            decision = {
                "allowed": False,
                "compatibility_rule_id": None,
                "rule_version": None,
                "contract_version": CLASSIFICATION_CONTRACT_VERSION,
                "errors": list(errors),
                "primary_error": errors[0],
            }
        else:
            entry = dict(entry)
            coverage = self._catalog_revision_coverage(
                int(revision_request["revision_id"])
            )
            entry.update(coverage)
            decision = self.evaluate_time_series_compatibility(
                semantic_type_key=entry["semantic_type_key"],
                binding_role_key=operation["binding_role_key"],
                object_type_key=linkable["object_type_key"],
                unit_key=entry["unit_key"],
                usage="execution",
            )
            if int(linkable["project_id"]) != int(context["project_id"]):
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_PROJECT_CONTEXT_MISMATCH",
                        {
                            "scenario_id": context["scenario_id"],
                            "variant_id": context["variant_id"],
                            "variant_project_id": context["project_id"],
                            "linkable_object_id": operation["linkable_object_id"],
                            "object_project_id": int(linkable["project_id"]),
                        },
                    )
                )
            if (
                entry["visibility_scope"] == "project"
                and int(entry["owner_project_id"]) != int(context["project_id"])
            ):
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_SCOPE_NOT_ACCESSIBLE",
                        {
                            "signal_id": operation["signal_id"],
                            "owner_project_id": int(entry["owner_project_id"]),
                            "target_project_id": context["project_id"],
                        },
                    )
                )
            if (
                entry["series_kind"] == "object_specific"
                and int(entry["owner_linkable_object_id"])
                != int(operation["linkable_object_id"])
            ):
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_OBJECT_OWNER_MISMATCH",
                        {
                            "signal_id": operation["signal_id"],
                            "owner_linkable_object_id": int(
                                entry["owner_linkable_object_id"]
                            ),
                            "linkable_object_id": operation[
                                "linkable_object_id"
                            ],
                        },
                    )
                )
            if (
                entry["set_status"] == "archived"
                or entry["signal_status"] == "archived"
                or entry["selected_revision_state"] != "sealed"
                or entry["selected_content_hash"] != requested_content_hash
                or int(entry["period_count"]) == 0
            ):
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_SIGNAL_UNAVAILABLE",
                        {
                            "signal_id": operation["signal_id"],
                            "revision_id": revision_request["revision_id"],
                            "usage": "execution",
                            "reason": "revision_not_sealed_or_hash_mismatch",
                        },
                    )
                )
            if linkable["status"] != "active":
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_OBJECT_UNAVAILABLE",
                        {
                            "linkable_object_id": operation["linkable_object_id"],
                            "usage": "execution",
                        },
                    )
                )
            current_revision_id = int(entry["current_revision_id"])
            selected_revision_id = int(revision_request["revision_id"])
            if revision_request["mode"] == "current" and (
                selected_revision_id != current_revision_id
                or requested_content_hash != entry["current_content_hash"]
            ):
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_CONTRACT_CHANGED",
                        {
                            "signal_id": operation["signal_id"],
                            "expected_current_revision_id": selected_revision_id,
                            "actual_current_revision_id": current_revision_id,
                        },
                    )
                )
            if revision_request["mode"] == "pinned" and (
                selected_revision_id == current_revision_id
            ):
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_CONTRACT_CHANGED",
                        {
                            "signal_id": operation["signal_id"],
                            "reason": "pinned_revision_must_be_historical",
                        },
                    )
                )
            if errors:
                decision = {
                    **decision,
                    "allowed": False,
                    "errors": [*errors, *decision["errors"]],
                    "primary_error": errors[0],
                }
            role = self.connection.execute(
                """
                SELECT id, status FROM time_series_binding_roles
                WHERE role_key = ?
                """,
                (operation["binding_role_key"],),
            ).fetchone()

        catalog_association = None
        association_id = operation.get("catalog_association_id")
        if association_id is not None:
            association_row = self.connection.execute(
                f"""
                SELECT id, signal_id, linkable_object_id, binding_role_id,
                       lifecycle_revision, status
                FROM {self.link_layer_table_names()['time_series_catalog_associations']}
                WHERE id = ?
                """,
                (int(association_id),),
            ).fetchone()
            association_matches = (
                association_row is not None
                and role is not None
                and association_row["status"] == "active"
                and int(association_row["signal_id"]) == int(operation["signal_id"])
                and int(association_row["linkable_object_id"])
                == int(operation["linkable_object_id"])
                and int(association_row["binding_role_id"]) == int(role["id"])
            )
            association_state = None
            if association_row is not None:
                association_detail = self.read_catalog_association(
                    int(association_id)
                )
                association_state = association_detail["state"]
                association_matches = (
                    association_matches and association_state == "active_valid"
                )
            if not association_matches:
                association_error = compatibility_error(
                    "TS_COMPAT_ASSOCIATION_MISMATCH",
                    {
                        "catalog_association_id": int(association_id),
                        "signal_id": operation["signal_id"],
                        "linkable_object_id": operation["linkable_object_id"],
                        "binding_role_key": operation["binding_role_key"],
                        "association_state": association_state,
                    },
                )
                decision = {
                    **decision,
                    "allowed": False,
                    "errors": [association_error, *decision["errors"]],
                    "primary_error": association_error,
                }
            elif association_row is not None:
                catalog_association = {
                    "id": int(association_row["id"]),
                    "lifecycle_revision": int(
                        association_row["lifecycle_revision"]
                    ),
                    "status": association_row["status"],
                    "state": association_state,
                    "compatibility_fingerprint": association_detail[
                        "validation"
                    ]["compatibility_fingerprint"],
                    "object_scope_fingerprint": association_detail["validation"][
                        "object_scope_fingerprint"
                    ],
                }

        active_binding = None
        if role is not None:
            active_binding = self.connection.execute(
                f"""
                SELECT id, lifecycle_revision, status, signal_id,
                       set_revision_id, bound_content_hash
                FROM {self.link_layer_table_names()['case_time_series_bindings']}
                WHERE case_input_variant_id = ? AND linkable_object_id = ?
                  AND binding_role_id = ? AND status = 'active'
                """,
                (
                    context["variant_id"],
                    operation["linkable_object_id"],
                    int(role["id"]),
                ),
            ).fetchone()
        if active_binding is not None:
            conflict = self._binding_operation_error(
                "TS_LINK_CONFLICT",
                field="linkable_object_id",
                binding_id=int(active_binding["id"]),
                reason="active_identity_exists",
            )
            decision = {
                **decision,
                "allowed": False,
                "errors": [conflict, *decision["errors"]],
                "primary_error": conflict,
            }

        observation = {
            "variant": {
                **dict(context),
                "variant_dependency_fingerprint": variant_dependency_fingerprint,
            },
            "signal": (
                {
                    "signal_id": int(entry["signal_id"]),
                    "time_series_set_id": int(entry["time_series_set_id"]),
                    "current_revision_id": int(entry["current_revision_id"]),
                    "selected_revision_id": int(revision_request["revision_id"]),
                    "selected_content_hash": entry["selected_content_hash"],
                    "content_hash": entry["current_content_hash"],
                    "visibility_scope": entry["visibility_scope"],
                    "owner_project_id": int(entry["owner_project_id"]),
                    "owner_linkable_object_id": (
                        int(entry["owner_linkable_object_id"])
                        if entry["owner_linkable_object_id"] is not None
                        else None
                    ),
                    "semantic_type_key": entry["semantic_type_key"],
                    "data_class_key": entry["data_class_key"],
                    "unit_key": entry["unit_key"],
                    "signal_role": entry["signal_role"],
                    "scope_revision": int(entry["scope_revision"]),
                    "set_status": entry["set_status"],
                    "signal_status": entry["signal_status"],
                    "series_kind": entry["series_kind"],
                    "coverage_start": entry["coverage_start"],
                    "coverage_end": entry["coverage_end"],
                    "period_count": int(entry["period_count"]),
                    "nominal_resolution_seconds": float(
                        entry["nominal_resolution_seconds"]
                    ),
                }
                if entry is not None
                else None
            ),
            "object": (
                {
                    "id": int(linkable["id"]),
                    "project_id": int(linkable["project_id"]),
                    "object_type_key": linkable["object_type_key"],
                    "status": linkable["status"],
                }
                if linkable is not None
                else None
            ),
            "compatibility_rule_id": decision["compatibility_rule_id"],
            "binding_role_id": int(role["id"]) if role is not None else None,
            "rule_version": decision["rule_version"],
            "catalog_association": catalog_association,
            "active_binding": dict(active_binding) if active_binding is not None else None,
        }
        verdict = (
            "rejected"
            if not decision["allowed"]
            else "confirmation_required"
            if revision_request["mode"] == "pinned"
            else "accepted"
        )
        after_state = (
            "valid_pinned"
            if revision_request["mode"] == "pinned"
            else "valid_current"
        )
        result = {
            "client_operation_id": operation["client_operation_id"],
            "action": operation["action"],
            "normalized_operation": operation,
            "verdict": verdict,
            "compatibility_decision": decision,
            "errors": decision["errors"],
            "before": observation["active_binding"],
            "after": {
                "state": after_state,
                "set_revision_id": revision_request["revision_id"],
                "bound_content_hash": revision_request["content_hash"],
                "coverage": (
                    {
                        "start": observation["signal"]["coverage_start"],
                        "end": observation["signal"]["coverage_end"],
                        "period_count": observation["signal"]["period_count"],
                        "nominal_resolution_seconds": observation["signal"][
                            "nominal_resolution_seconds"
                        ],
                    }
                    if observation["signal"] is not None
                    else None
                ),
            },
            "observed_state": observation,
        }
        return result, observation

    def _prevalidate_case_binding_replace(
        self,
        operation: dict[str, Any],
        *,
        context: Mapping[str, Any],
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        result, observation = self._prevalidate_case_binding_create(
            operation, context=context
        )
        try:
            previous = self.read_case_binding(
                scenario_id=int(context["scenario_id"]),
                variant_id=int(context["variant_id"]),
                binding_id=operation["binding_id"],
            )
        except KeyError:
            previous = None
        errors = list(result["errors"])
        if previous is None:
            errors.insert(
                0,
                self._binding_operation_error(
                    "TS_LINK_PRECONDITION_CHANGED",
                    field="binding_id",
                    binding_id=operation["binding_id"],
                    reason="binding_not_found",
                ),
            )
        else:
            errors = [
                error
                for error in errors
                if not (
                    error["code"] == "TS_LINK_CONFLICT"
                    and error["context"].get("binding_id")
                    == operation["binding_id"]
                )
            ]
            if previous["status"] != "active" or previous[
                "lifecycle_revision"
            ] != operation["expected_lifecycle_revision"]:
                errors.insert(
                    0,
                    self._binding_operation_error(
                        "TS_LINK_PRECONDITION_CHANGED",
                        field="expected_lifecycle_revision",
                        binding_id=operation["binding_id"],
                        expected_lifecycle_revision=operation[
                            "expected_lifecycle_revision"
                        ],
                        actual_lifecycle_revision=previous[
                            "lifecycle_revision"
                        ],
                        actual_status=previous["status"],
                    ),
                )
        allowed = not errors
        result["verdict"] = "confirmation_required" if allowed else "rejected"
        result["errors"] = errors
        result["compatibility_decision"] = {
            **result["compatibility_decision"],
            "allowed": allowed,
            "errors": errors,
            "primary_error": errors[0] if errors else None,
        }
        result["before"] = previous
        result["comparison"] = {
            "before": previous,
            "after": result["after"],
        }
        observation["previous_binding"] = previous
        return result, observation

    def _prevalidate_case_binding_revalidate(
        self,
        operation: dict[str, Any],
        *,
        context: Mapping[str, Any],
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        try:
            previous = self.read_case_binding(
                scenario_id=int(context["scenario_id"]),
                variant_id=int(context["variant_id"]),
                binding_id=operation["binding_id"],
            )
        except KeyError:
            previous = None
        if previous is None:
            error = self._binding_operation_error(
                "TS_LINK_PRECONDITION_CHANGED",
                field="binding_id",
                binding_id=operation["binding_id"],
                reason="binding_not_found",
            )
            return (
                {
                    "client_operation_id": operation["client_operation_id"],
                    "action": operation["action"],
                    "normalized_operation": operation,
                    "verdict": "rejected",
                    "compatibility_decision": {
                        "allowed": False,
                        "compatibility_rule_id": None,
                        "rule_version": None,
                        "contract_version": CLASSIFICATION_CONTRACT_VERSION,
                        "errors": [error],
                        "primary_error": error,
                    },
                    "errors": [error],
                    "before": None,
                    "after": None,
                    "comparison": {"before": None, "after": None},
                },
                {"variant": dict(context), "previous_binding": None},
            )
        mode = (
            "pinned"
            if operation["action"] == "revalidate_pinned"
            else "current"
        )
        target = {
            "client_operation_id": operation["client_operation_id"],
            "action": "create",
            "linkable_object_id": previous["object"]["id"],
            "binding_role_key": previous["binding_role"]["key"],
            "signal_id": previous["signal_id"],
            "revision": {
                "mode": mode,
                "revision_id": previous["set_revision_id"],
                "content_hash": previous["bound_content_hash"],
            },
            "catalog_association_id": previous["catalog_association_id"],
            "reason_code": operation["reason_code"],
            **(
                {"reason_text": operation["reason_text"]}
                if operation.get("reason_text")
                else {}
            ),
        }
        result, observation = self._prevalidate_case_binding_create(
            target, context=context
        )
        errors = [
            error
            for error in result["errors"]
            if not (
                error["code"] == "TS_LINK_CONFLICT"
                and error["context"].get("binding_id") == operation["binding_id"]
            )
        ]
        if previous["status"] != "active" or previous[
            "lifecycle_revision"
        ] != operation["expected_lifecycle_revision"]:
            errors.insert(
                0,
                self._binding_operation_error(
                    "TS_LINK_PRECONDITION_CHANGED",
                    field="expected_lifecycle_revision",
                    binding_id=operation["binding_id"],
                    expected_lifecycle_revision=operation[
                        "expected_lifecycle_revision"
                    ],
                    actual_lifecycle_revision=previous["lifecycle_revision"],
                    actual_status=previous["status"],
                ),
            )
        allowed = not errors
        after = {
            "binding_id": operation["binding_id"],
            "state": "valid_pinned" if mode == "pinned" else "valid_current",
            "set_revision_id": previous["set_revision_id"],
            "bound_content_hash": previous["bound_content_hash"],
        }
        result.update(
            {
                "action": operation["action"],
                "normalized_operation": operation,
                "verdict": (
                    "rejected"
                    if not allowed
                    else "confirmation_required"
                    if mode == "pinned"
                    else "accepted"
                ),
                "errors": errors,
                "before": previous,
                "after": after,
                "comparison": {"before": previous, "after": after},
                "compatibility_decision": {
                    **result["compatibility_decision"],
                    "allowed": allowed,
                    "errors": errors,
                    "primary_error": errors[0] if errors else None,
                },
            }
        )
        observation["previous_binding"] = previous
        observation["revalidation_mode"] = mode
        return result, observation

    def _prevalidate_case_binding_lifecycle(
        self,
        operation: dict[str, Any],
        *,
        context: Mapping[str, Any],
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        try:
            previous = self.read_case_binding(
                scenario_id=int(context["scenario_id"]),
                variant_id=int(context["variant_id"]),
                binding_id=operation["binding_id"],
            )
        except KeyError:
            previous = None
        errors: list[dict[str, Any]] = []
        observation: dict[str, Any] = {
            "variant": dict(context),
            "previous_binding": previous,
        }
        compatibility_decision: dict[str, Any] = {
            "allowed": True,
            "compatibility_rule_id": (
                previous["compatibility_rule_id"] if previous else None
            ),
            "rule_version": None,
            "contract_version": CLASSIFICATION_CONTRACT_VERSION,
            "errors": [],
            "primary_error": None,
        }
        expected_status = "active" if operation["action"] == "remove" else "removed"
        if previous is None:
            errors.append(
                self._binding_operation_error(
                    "TS_LINK_PRECONDITION_CHANGED",
                    field="binding_id",
                    binding_id=operation["binding_id"],
                    reason="binding_not_found",
                )
            )
        elif previous["status"] != expected_status or previous[
            "lifecycle_revision"
        ] != operation["expected_lifecycle_revision"]:
            errors.append(
                self._binding_operation_error(
                    "TS_LINK_PRECONDITION_CHANGED",
                    field="expected_lifecycle_revision",
                    binding_id=operation["binding_id"],
                    expected_status=expected_status,
                    actual_status=previous["status"],
                    expected_lifecycle_revision=operation[
                        "expected_lifecycle_revision"
                    ],
                    actual_lifecycle_revision=previous["lifecycle_revision"],
                )
            )
        restore_target = None
        after = {
            "binding_id": operation["binding_id"],
            "state": "inactive",
            "status": "removed",
        }
        if operation["action"] == "restore" and previous is not None and not errors:
            mode = previous["revision"]["mode"] or "current"
            restore_target = {
                "client_operation_id": operation["client_operation_id"],
                "action": "create",
                "linkable_object_id": previous["object"]["id"],
                "binding_role_key": previous["binding_role"]["key"],
                "signal_id": previous["signal_id"],
                "revision": {
                    "mode": mode,
                    "revision_id": previous["set_revision_id"],
                    "content_hash": previous["bound_content_hash"],
                },
                "catalog_association_id": previous["catalog_association_id"],
                "reason_code": operation["reason_code"],
                "reason_text": operation["reason_text"],
            }
            target_result, target_observation = self._prevalidate_case_binding_create(
                restore_target, context=context
            )
            errors.extend(target_result["errors"])
            compatibility_decision = target_result["compatibility_decision"]
            observation.update(target_observation)
            observation["previous_binding"] = previous
            after = {
                **target_result["after"],
                "status": "active",
            }
        observation["restore_target"] = restore_target
        allowed = not errors
        compatibility_decision = {
            **compatibility_decision,
            "allowed": allowed,
            "errors": errors,
            "primary_error": errors[0] if errors else None,
        }
        return (
            {
                "client_operation_id": operation["client_operation_id"],
                "action": operation["action"],
                "normalized_operation": operation,
                "verdict": "confirmation_required" if allowed else "rejected",
                "compatibility_decision": compatibility_decision,
                "errors": errors,
                "before": previous,
                "after": after,
                "comparison": {"before": previous, "after": after},
                "observed_state": observation,
            },
            observation,
        )

    def prevalidate_case_binding_batch(
        self,
        *,
        scenario_id: int,
        variant_id: int,
        document: Mapping[str, Any],
        actor_class: str,
    ) -> dict[str, Any]:
        normalized = normalize_binding_request(document)
        context = self._canonical_binding_context(
            scenario_id=scenario_id, variant_id=variant_id
        )
        context["variant_dependency_fingerprint"] = (
            self._case_binding_variant_dependency_fingerprint(
                scenario_id=scenario_id,
                variant_id=variant_id,
                project_id=context["project_id"],
            )
        )
        results = []
        observations = []
        claimed_targets: dict[tuple[int, str], str] = {}
        claimed_bindings: dict[int, str] = {}
        for operation in normalized["operations"]:
            if operation["action"] == "replace":
                result, observation = self._prevalidate_case_binding_replace(
                    operation, context=context
                )
            elif operation["action"] in {
                "revalidate_current",
                "revalidate_pinned",
            }:
                result, observation = self._prevalidate_case_binding_revalidate(
                    operation, context=context
                )
            elif operation["action"] in {"remove", "restore"}:
                result, observation = self._prevalidate_case_binding_lifecycle(
                    operation, context=context
                )
            else:
                result, observation = self._prevalidate_case_binding_create(
                    operation, context=context
                )
            conflicting_with = None
            if operation["action"] in {"create", "replace"}:
                target = (
                    operation["linkable_object_id"],
                    operation["binding_role_key"],
                )
                conflicting_with = claimed_targets.get(target)
                claimed_targets.setdefault(
                    target, operation["client_operation_id"]
                )
            if operation["action"] in {
                "replace",
                "revalidate_current",
                "revalidate_pinned",
                "remove",
                "restore",
            }:
                conflicting_with = (
                    conflicting_with
                    or claimed_bindings.get(operation["binding_id"])
                )
                claimed_bindings.setdefault(
                    operation["binding_id"], operation["client_operation_id"]
                )
            if conflicting_with is not None:
                conflict = self._binding_operation_error(
                    "TS_LINK_CONFLICT",
                    field="client_operation_id",
                    conflicts_with=conflicting_with,
                )
                result["verdict"] = "rejected"
                result["errors"] = [conflict, *result["errors"]]
                result["compatibility_decision"] = {
                    **result["compatibility_decision"],
                    "allowed": False,
                    "errors": result["errors"],
                    "primary_error": conflict,
                }
                observation["batch_conflict"] = {
                    "conflicts_with": conflicting_with
                }
            if normalized["expected_bindings_revision"] != context["bindings_revision"]:
                changed = self._binding_operation_error(
                    "TS_LINK_PRECONDITION_CHANGED",
                    field="expected_bindings_revision",
                    expected_bindings_revision=normalized["expected_bindings_revision"],
                    actual_bindings_revision=context["bindings_revision"],
                )
                result["verdict"] = "rejected"
                result["errors"] = [changed, *result["errors"]]
                result["compatibility_decision"] = {
                    **result["compatibility_decision"],
                    "allowed": False,
                    "errors": result["errors"],
                    "primary_error": changed,
                }
            results.append(result)
            observations.append(observation)
        request_hash = binding_request_hash(normalized)
        commit_etag = binding_commit_etag(
            normalized,
            observations,
            scenario_id=scenario_id,
            variant_id=variant_id,
            actor_class=actor_class,
        )
        token, expires_at = issue_binding_prevalidation_token(
            request_hash=request_hash,
            commit_etag=commit_etag,
            actor_class=actor_class,
            secret=self._catalog_cursor_secret,
        )
        return {
            "normalized_request": normalized,
            "request_hash": request_hash,
            "observed_bindings_revision": context["bindings_revision"],
            "operations": results,
            "can_commit": all(row["verdict"] != "rejected" for row in results),
            "requires_confirmation": any(
                row["verdict"] == "confirmation_required" for row in results
            ),
            "expires_at": expires_at,
            "prevalidation_token": token,
            "commit_etag": commit_etag,
        }

    def _insert_case_binding_create(
        self,
        *,
        operation: dict[str, Any],
        prevalidated: dict[str, Any],
        actor_user: Mapping[str, Any],
        request_id: str,
        batch_id: str,
        occurred_at: str,
        supersedes_binding_id: int | None = None,
        event_type: str = "created",
        before: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        observed = prevalidated["observed_state"]
        signal = observed["signal"]
        linkable = observed["object"]
        revision = operation["revision"]
        binding_id = self._insert_canonical_row(
            f"""
            INSERT INTO {self.link_layer_table_names()['case_time_series_bindings']} (
                case_input_variant_id, linkable_object_id, binding_role_id,
                signal_id, time_series_set_id, set_revision_id,
                bound_content_hash, source_kind, source_owner_linkable_object_id,
                catalog_association_id, compatibility_rule_id, required, status,
                supersedes_binding_id, lifecycle_revision, change_reason_code,
                change_reason_text, validated_at, created_at, updated_at,
                created_by, updated_by, metadata_json
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, 'active',
                      ?, 1, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                observed["variant"]["variant_id"],
                linkable["id"],
                observed["binding_role_id"],
                signal["signal_id"],
                signal["time_series_set_id"],
                revision["revision_id"],
                signal["selected_content_hash"],
                signal["series_kind"],
                signal["owner_linkable_object_id"],
                operation.get("catalog_association_id"),
                observed["compatibility_rule_id"],
                supersedes_binding_id,
                operation["reason_code"],
                operation.get("reason_text"),
                occurred_at,
                occurred_at,
                occurred_at,
                actor_user["email"],
                actor_user["email"],
                json.dumps(
                    {
                        "client_operation_id": operation["client_operation_id"],
                        "request_id": request_id,
                    },
                    sort_keys=True,
                ),
            ),
        )
        compatibility_fingerprint, object_scope_fingerprint = (
            self._case_binding_fingerprints(
                observed=observed,
                binding_role_key=operation["binding_role_key"],
                contract_version=prevalidated["compatibility_decision"][
                    "contract_version"
                ],
            )
        )
        variant_dependency_fingerprint = observed["variant"][
            "variant_dependency_fingerprint"
        ]
        validation_mode = f"binding_{revision['mode']}"
        self.connection.execute(
            f"""
            INSERT INTO {self.link_layer_table_names()['time_series_link_validations']} (
                binding_id, subject_lifecycle_revision, validation_mode,
                validated_set_revision_id, observed_current_revision_id,
                compatibility_rule_id, compatibility_fingerprint,
                object_scope_fingerprint, variant_dependency_fingerprint,
                validated_at, validated_by, reason_code, reason_text
            ) VALUES (?, 1, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                binding_id,
                validation_mode,
                revision["revision_id"],
                signal["current_revision_id"],
                observed["compatibility_rule_id"],
                compatibility_fingerprint,
                object_scope_fingerprint,
                variant_dependency_fingerprint,
                occurred_at,
                actor_user["email"],
                operation["reason_code"],
                operation.get("reason_text"),
            ),
        )
        after = {
            "binding_id": binding_id,
            "case_input_variant_id": observed["variant"]["variant_id"],
            "linkable_object_id": linkable["id"],
            "binding_role_key": operation["binding_role_key"],
            "signal_id": signal["signal_id"],
            "set_revision_id": revision["revision_id"],
            "bound_content_hash": signal["selected_content_hash"],
            "revision_mode": revision["mode"],
            "status": "active",
        }
        self.connection.execute(
            f"""
            INSERT INTO {self.link_layer_table_names()['time_series_link_events']} (
                batch_id, binding_id, event_type, actor_user_id,
                actor_identity_snapshot, actor_role_snapshot, reason_code,
                reason_text, before_json, after_json, request_id, occurred_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                batch_id,
                binding_id,
                event_type,
                actor_user.get("id"),
                actor_user["email"],
                actor_user["role"],
                operation["reason_code"],
                operation.get("reason_text"),
                json.dumps(dict(before or {}), sort_keys=True),
                json.dumps(after, sort_keys=True),
                request_id,
                occurred_at,
            ),
        )
        return {
            "client_operation_id": operation["client_operation_id"],
            "action": operation["action"],
            "outcome": "replaced" if event_type == "replaced" else "created",
            "binding_id": binding_id,
            "supersedes_binding_id": supersedes_binding_id,
        }

    def _replace_case_binding(
        self,
        *,
        operation: dict[str, Any],
        prevalidated: dict[str, Any],
        actor_user: Mapping[str, Any],
        request_id: str,
        batch_id: str,
        occurred_at: str,
    ) -> dict[str, Any]:
        previous = prevalidated["observed_state"]["previous_binding"]
        previous_id = int(previous["binding_id"])
        self.connection.execute(
            f"""
            UPDATE {self.link_layer_table_names()['case_time_series_bindings']}
            SET status = 'superseded', lifecycle_revision = lifecycle_revision + 1,
                superseded_at = ?, superseded_by = ?, updated_at = ?, updated_by = ?
            WHERE id = ? AND status = 'active' AND lifecycle_revision = ?
            """,
            (
                occurred_at,
                actor_user["email"],
                occurred_at,
                actor_user["email"],
                previous_id,
                operation["expected_lifecycle_revision"],
            ),
        )
        before_event = {
            "binding_id": previous_id,
            "status": "active",
            "lifecycle_revision": operation["expected_lifecycle_revision"],
            "set_revision_id": previous["set_revision_id"],
            "bound_content_hash": previous["bound_content_hash"],
        }
        after_event = {
            **before_event,
            "status": "superseded",
            "lifecycle_revision": operation["expected_lifecycle_revision"] + 1,
        }
        self.connection.execute(
            f"""
            INSERT INTO {self.link_layer_table_names()['time_series_link_events']} (
                batch_id, binding_id, event_type, actor_user_id,
                actor_identity_snapshot, actor_role_snapshot, reason_code,
                reason_text, before_json, after_json, request_id, occurred_at
            ) VALUES (?, ?, 'superseded', ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                batch_id,
                previous_id,
                actor_user.get("id"),
                actor_user["email"],
                actor_user["role"],
                operation["reason_code"],
                operation.get("reason_text"),
                json.dumps(before_event, sort_keys=True),
                json.dumps(after_event, sort_keys=True),
                request_id,
                occurred_at,
            ),
        )
        return self._insert_case_binding_create(
            operation=operation,
            prevalidated=prevalidated,
            actor_user=actor_user,
            request_id=request_id,
            batch_id=batch_id,
            occurred_at=occurred_at,
            supersedes_binding_id=previous_id,
            event_type="replaced",
            before=before_event,
        )

    def _revalidate_case_binding(
        self,
        *,
        operation: dict[str, Any],
        prevalidated: dict[str, Any],
        actor_user: Mapping[str, Any],
        request_id: str,
        batch_id: str,
        occurred_at: str,
    ) -> dict[str, Any]:
        observed = prevalidated["observed_state"]
        previous = observed["previous_binding"]
        signal = observed["signal"]
        mode = observed["revalidation_mode"]
        compatibility_fingerprint, object_scope_fingerprint = (
            self._case_binding_fingerprints(
                observed=observed,
                binding_role_key=previous["binding_role"]["key"],
                contract_version=prevalidated["compatibility_decision"][
                    "contract_version"
                ],
            )
        )
        variant_dependency_fingerprint = observed["variant"][
            "variant_dependency_fingerprint"
        ]
        binding_id = int(operation["binding_id"])
        self.connection.execute(
            f"""
            INSERT INTO {self.link_layer_table_names()['time_series_link_validations']} (
                binding_id, subject_lifecycle_revision, validation_mode,
                validated_set_revision_id, observed_current_revision_id,
                compatibility_rule_id, compatibility_fingerprint,
                object_scope_fingerprint, variant_dependency_fingerprint,
                validated_at, validated_by, reason_code, reason_text
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                binding_id,
                operation["expected_lifecycle_revision"],
                f"binding_{mode}",
                previous["set_revision_id"],
                signal["current_revision_id"],
                observed["compatibility_rule_id"],
                compatibility_fingerprint,
                object_scope_fingerprint,
                variant_dependency_fingerprint,
                occurred_at,
                actor_user["email"],
                operation["reason_code"],
                operation.get("reason_text"),
            ),
        )
        self.connection.execute(
            f"""
            UPDATE {self.link_layer_table_names()['case_time_series_bindings']}
            SET validated_at = ?, updated_at = ?, updated_by = ?
            WHERE id = ? AND status = 'active' AND lifecycle_revision = ?
            """,
            (
                occurred_at,
                occurred_at,
                actor_user["email"],
                binding_id,
                operation["expected_lifecycle_revision"],
            ),
        )
        before = {
            "binding_id": binding_id,
            "state": previous["state"],
            "set_revision_id": previous["set_revision_id"],
            "bound_content_hash": previous["bound_content_hash"],
        }
        after = {
            **before,
            "state": "valid_pinned" if mode == "pinned" else "valid_current",
            "observed_current_revision_id": signal["current_revision_id"],
        }
        event_type = f"revalidated_{mode}"
        self.connection.execute(
            f"""
            INSERT INTO {self.link_layer_table_names()['time_series_link_events']} (
                batch_id, binding_id, event_type, actor_user_id,
                actor_identity_snapshot, actor_role_snapshot, reason_code,
                reason_text, before_json, after_json, request_id, occurred_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                batch_id,
                binding_id,
                event_type,
                actor_user.get("id"),
                actor_user["email"],
                actor_user["role"],
                operation["reason_code"],
                operation.get("reason_text"),
                json.dumps(before, sort_keys=True),
                json.dumps(after, sort_keys=True),
                request_id,
                occurred_at,
            ),
        )
        return {
            "client_operation_id": operation["client_operation_id"],
            "action": operation["action"],
            "outcome": event_type,
            "binding_id": binding_id,
        }

    def _remove_case_binding(
        self,
        *,
        operation: dict[str, Any],
        prevalidated: dict[str, Any],
        actor_user: Mapping[str, Any],
        request_id: str,
        batch_id: str,
        occurred_at: str,
    ) -> dict[str, Any]:
        previous = prevalidated["observed_state"]["previous_binding"]
        binding_id = int(operation["binding_id"])
        self.connection.execute(
            f"""
            UPDATE {self.link_layer_table_names()['case_time_series_bindings']}
            SET status = 'removed', lifecycle_revision = lifecycle_revision + 1,
                removed_at = ?, removed_by = ?, updated_at = ?, updated_by = ?
            WHERE id = ? AND status = 'active' AND lifecycle_revision = ?
            """,
            (
                occurred_at,
                actor_user["email"],
                occurred_at,
                actor_user["email"],
                binding_id,
                operation["expected_lifecycle_revision"],
            ),
        )
        before = {
            "binding_id": binding_id,
            "status": "active",
            "state": previous["state"],
            "lifecycle_revision": operation["expected_lifecycle_revision"],
        }
        after = {
            **before,
            "status": "removed",
            "state": "inactive",
            "lifecycle_revision": operation["expected_lifecycle_revision"] + 1,
        }
        self.connection.execute(
            f"""
            INSERT INTO {self.link_layer_table_names()['time_series_link_events']} (
                batch_id, binding_id, event_type, actor_user_id,
                actor_identity_snapshot, actor_role_snapshot, reason_code,
                reason_text, before_json, after_json, request_id, occurred_at
            ) VALUES (?, ?, 'removed', ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                batch_id,
                binding_id,
                actor_user.get("id"),
                actor_user["email"],
                actor_user["role"],
                operation["reason_code"],
                operation["reason_text"],
                json.dumps(before, sort_keys=True),
                json.dumps(after, sort_keys=True),
                request_id,
                occurred_at,
            ),
        )
        return {
            "client_operation_id": operation["client_operation_id"],
            "action": "remove",
            "outcome": "removed",
            "binding_id": binding_id,
        }

    def _restore_case_binding(
        self,
        *,
        operation: dict[str, Any],
        prevalidated: dict[str, Any],
        actor_user: Mapping[str, Any],
        request_id: str,
        batch_id: str,
        occurred_at: str,
    ) -> dict[str, Any]:
        observed = prevalidated["observed_state"]
        target = observed["restore_target"]
        previous_id = int(operation["binding_id"])
        restored = self._insert_case_binding_create(
            operation=target,
            prevalidated=prevalidated,
            actor_user=actor_user,
            request_id=request_id,
            batch_id=batch_id,
            occurred_at=occurred_at,
            supersedes_binding_id=previous_id,
            event_type="recreated",
            before={
                "binding_id": previous_id,
                "status": "removed",
                "lifecycle_revision": operation["expected_lifecycle_revision"],
            },
        )
        restored.update(
            {
                "client_operation_id": operation["client_operation_id"],
                "action": "restore",
                "outcome": "restored",
            }
        )
        return restored

    def commit_case_binding_batch(
        self,
        *,
        scenario_id: int,
        variant_id: int,
        document: Mapping[str, Any],
        actor_user: Mapping[str, Any],
        actor_class: str,
        request_id: str,
        prevalidation_token: str,
        if_match: str,
        idempotency_key: str,
        confirmed: bool,
    ) -> tuple[dict[str, Any], bool]:
        normalized = normalize_binding_request(document)
        request_hash = binding_request_hash(normalized)
        verify_binding_prevalidation_token(
            prevalidation_token,
            request_hash=request_hash,
            commit_etag=if_match,
            actor_class=actor_class,
            secret=self._catalog_cursor_secret,
            check_expiry=False,
        )
        claim_hash = binding_request_hash(
            {
                "scenario_id": int(scenario_id),
                "variant_id": int(variant_id),
                "request": normalized,
                "confirmed": bool(confirmed),
            }
        )
        try:
            with self._lock:
                with self._database_transaction():
                    context = self._canonical_binding_context(
                        scenario_id=scenario_id, variant_id=variant_id
                    )
                    claim = self._claim_idempotency(
                        actor_id=actor_class,
                        operation_kind="binding_batch",
                        scope_key=(
                            f"scenario:{scenario_id}:variant:{variant_id}:"
                            f"project:{context['project_id']}"
                        ),
                        idempotency_key=idempotency_key,
                        request_hash=claim_hash,
                    )
                    if claim["state"] == "completed":
                        return claim["response"], True
                    verify_binding_prevalidation_token(
                        prevalidation_token,
                        request_hash=request_hash,
                        commit_etag=if_match,
                        actor_class=actor_class,
                        secret=self._catalog_cursor_secret,
                    )
                    self._lock_case_binding_batch(
                        normalized=normalized, variant_id=variant_id
                    )
                    current = self.prevalidate_case_binding_batch(
                        scenario_id=scenario_id,
                        variant_id=variant_id,
                        document=normalized,
                        actor_class=actor_class,
                    )
                    if current["commit_etag"] != if_match:
                        raise BindingMutationError(
                            "TS_LINK_PRECONDITION_CHANGED",
                            expected_etag=if_match,
                            actual_etag=current["commit_etag"],
                        )
                    if not current["can_commit"]:
                        raise BindingMutationError(
                            "TS_LINK_BATCH_REJECTED",
                            details=current["operations"],
                            normalized_request=normalized,
                        )
                    if current["requires_confirmation"] and not confirmed:
                        raise BindingMutationError("TS_LINK_CONFIRMATION_REQUIRED")
                    batch_id = f"bnb_{uuid.uuid4().hex}"
                    occurred_at = utc_now_iso()
                    results = []
                    for operation, prevalidated in zip(
                        normalized["operations"], current["operations"]
                    ):
                        if operation["action"] == "replace":
                            result = self._replace_case_binding(
                                operation=operation,
                                prevalidated=prevalidated,
                                actor_user=actor_user,
                                request_id=request_id,
                                batch_id=batch_id,
                                occurred_at=occurred_at,
                            )
                        elif operation["action"] in {
                            "revalidate_current",
                            "revalidate_pinned",
                        }:
                            result = self._revalidate_case_binding(
                                operation=operation,
                                prevalidated=prevalidated,
                                actor_user=actor_user,
                                request_id=request_id,
                                batch_id=batch_id,
                                occurred_at=occurred_at,
                            )
                        elif operation["action"] == "remove":
                            result = self._remove_case_binding(
                                operation=operation,
                                prevalidated=prevalidated,
                                actor_user=actor_user,
                                request_id=request_id,
                                batch_id=batch_id,
                                occurred_at=occurred_at,
                            )
                        elif operation["action"] == "restore":
                            result = self._restore_case_binding(
                                operation=operation,
                                prevalidated=prevalidated,
                                actor_user=actor_user,
                                request_id=request_id,
                                batch_id=batch_id,
                                occurred_at=occurred_at,
                            )
                        else:
                            result = self._insert_case_binding_create(
                                operation=operation,
                                prevalidated=prevalidated,
                                actor_user=actor_user,
                                request_id=request_id,
                                batch_id=batch_id,
                                occurred_at=occurred_at,
                            )
                        results.append(result)
                    structural_mutation = any(
                        operation["action"] in {
                            "create",
                            "replace",
                            "remove",
                            "restore",
                        }
                        for operation in normalized["operations"]
                    )
                    if structural_mutation:
                        self.connection.execute(
                            """
                            UPDATE case_input_variants
                            SET bindings_revision = bindings_revision + 1,
                                updated_at = ?, updated_by = ?
                            WHERE id = ?
                            """,
                            (occurred_at, actor_user["email"], int(variant_id)),
                        )
                        affected_signal_ids = sorted(
                            {
                                int(signal_id)
                                for operation, prevalidated in zip(
                                    normalized["operations"], current["operations"]
                                )
                                for signal_id in (
                                    operation.get("signal_id"),
                                    (
                                        prevalidated["observed_state"]
                                        .get("previous_binding", {})
                                        .get("signal_id")
                                        if prevalidated["observed_state"].get(
                                            "previous_binding"
                                        )
                                        else None
                                    ),
                                )
                                if signal_id is not None
                            }
                        )
                        if affected_signal_ids:
                            placeholders = ", ".join(
                                "?" for _ in affected_signal_ids
                            )
                            binding_table = self.link_layer_table_names()[
                                "case_time_series_bindings"
                            ]
                            entries = self._projection(
                                "time_series_catalog_entries"
                            )
                            self.connection.execute(
                                f"""
                                UPDATE {entries}
                                SET binding_count = (
                                    SELECT COUNT(*) FROM {binding_table}
                                    WHERE signal_id = {entries}.signal_id
                                      AND status = 'active'
                                ), projection_revision = projection_revision + 1,
                                   updated_at = ?
                                WHERE signal_id IN ({placeholders})
                                """,
                                (occurred_at, *affected_signal_ids),
                            )
                            self._raise_catalog_generation(now=occurred_at)
                    new_revision = current["observed_bindings_revision"] + int(
                        structural_mutation
                    )
                    response = {
                        "outcome": "created",
                        "batch_id": batch_id,
                        "scenario_id": int(scenario_id),
                        "variant_id": int(variant_id),
                        "bindings_revision": new_revision,
                        "operations": results,
                        "request_id": request_id,
                    }
                    self._complete_idempotency(
                        claim_id=claim["id"], response=response, http_status=201
                    )
                    return response, False
        except CanonicalRevisionError as error:
            if error.code in {
                "TS_IDEMPOTENCY_KEY_CONFLICT",
                "TS_IDEMPOTENCY_IN_FLIGHT",
            }:
                raise BindingMutationError(
                    "TS_IDEMPOTENCY_CONFLICT", reason=error.code
                ) from error
            raise
        except Exception as error:
            constraint_name = str(
                getattr(getattr(error, "diag", None), "constraint_name", "") or ""
            )
            error_text = str(error).lower()
            if constraint_name == "case_time_series_bindings_next_one_active_uk" or (
                "unique constraint failed" in error_text
                and "case_time_series_bindings" in error_text
                and "linkable_object_id" in error_text
            ):
                raise BindingMutationError(
                    "TS_LINK_CONFLICT", reason="active_identity_race"
                ) from error
            raise

    def _lock_case_binding_batch(
        self, *, normalized: Mapping[str, Any], variant_id: int
    ) -> None:
        """Lock variant, sets and link subjects in deterministic PostgreSQL order."""

        if self.database_backend != "postgresql":
            return
        self.connection.execute(
            "SELECT id FROM case_input_variants WHERE id = ? FOR UPDATE",
            (int(variant_id),),
        ).fetchone()
        operations = normalized["operations"]
        signal_ids = sorted(
            {int(row["signal_id"]) for row in operations if row.get("signal_id")}
        )
        binding_ids = sorted(
            {int(row["binding_id"]) for row in operations if row.get("binding_id")}
        )
        set_ids: set[int] = set()
        object_ids = {
            int(row["linkable_object_id"])
            for row in operations
            if row.get("linkable_object_id")
        }
        association_ids = {
            int(row["catalog_association_id"])
            for row in operations
            if row.get("catalog_association_id")
        }
        if signal_ids:
            placeholders = ", ".join("?" for _ in signal_ids)
            set_ids.update(
                int(row["time_series_set_id"])
                for row in self.connection.execute(
                    f"""
                    SELECT DISTINCT time_series_set_id
                    FROM {self._canonical('time_series_signals')}
                    WHERE id IN ({placeholders})
                    """,
                    tuple(signal_ids),
                ).fetchall()
            )
        if binding_ids:
            placeholders = ", ".join("?" for _ in binding_ids)
            rows = self.connection.execute(
                f"""
                SELECT id, time_series_set_id, linkable_object_id,
                       catalog_association_id
                FROM {self.link_layer_table_names()['case_time_series_bindings']}
                WHERE id IN ({placeholders})
                """,
                tuple(binding_ids),
            ).fetchall()
            set_ids.update(int(row["time_series_set_id"]) for row in rows)
            object_ids.update(int(row["linkable_object_id"]) for row in rows)
            association_ids.update(
                int(row["catalog_association_id"])
                for row in rows
                if row["catalog_association_id"] is not None
            )
        for table, ids in (
            (self._canonical("time_series_sets"), sorted(set_ids)),
            (self._linkable("linkable_objects"), sorted(object_ids)),
            (
                self.link_layer_table_names()[
                    "time_series_catalog_associations"
                ],
                sorted(association_ids),
            ),
            (
                self.link_layer_table_names()["case_time_series_bindings"],
                binding_ids,
            ),
        ):
            if not ids:
                continue
            placeholders = ", ".join("?" for _ in ids)
            self.connection.execute(
                f"SELECT id FROM {table} WHERE id IN ({placeholders}) "
                "ORDER BY id FOR UPDATE",
                tuple(ids),
            ).fetchall()

    def _canonical_binding_row(self, binding_id: int):
        bindings = self.link_layer_table_names()["case_time_series_bindings"]
        validations = self.link_layer_table_names()["time_series_link_validations"]
        return self.connection.execute(
            f"""
            SELECT binding.*, role.role_key, role.execution_contract_key,
                   role.display_name AS role_display_name,
                   role.status AS role_status,
                   signal.series_key, signal.display_name AS signal_display_name,
                   canonical_set.visibility_scope,
                   canonical_set.owner_project_id,
                   canonical_set.version_number AS set_version_number,
                   canonical_set.current_revision_id,
                   current_revision.content_hash AS current_content_hash,
                   canonical_set.status AS set_status,
                   signal.status AS signal_status,
                   validation.id AS validation_id, validation.validation_mode,
                   validation.validated_set_revision_id,
                   validation.observed_current_revision_id,
                   validation.compatibility_fingerprint,
                   validation.object_scope_fingerprint,
                   validation.variant_dependency_fingerprint,
                   validation.validated_at, validation.validated_by,
                   validation.reason_code AS validation_reason_code,
                   validation.reason_text AS validation_reason_text,
                   revision.state AS revision_state,
                   revision.content_hash AS revision_content_hash,
                   compatibility.rule_version AS compatibility_rule_version
            FROM {bindings} AS binding
            JOIN time_series_binding_roles AS role
              ON role.id = binding.binding_role_id
            JOIN time_series_role_compatibilities AS compatibility
              ON compatibility.id = binding.compatibility_rule_id
            JOIN {self._canonical('time_series_signals')} AS signal
              ON signal.id = binding.signal_id
             AND signal.time_series_set_id = binding.time_series_set_id
            JOIN {self._canonical('time_series_sets')} AS canonical_set
              ON canonical_set.id = binding.time_series_set_id
            JOIN {self._canonical('time_series_set_revisions')} AS current_revision
              ON current_revision.id = canonical_set.current_revision_id
            JOIN {self._canonical('time_series_set_revisions')} AS revision
              ON revision.id = binding.set_revision_id
            LEFT JOIN {validations} AS validation
              ON validation.id = (
                  SELECT latest.id FROM {validations} AS latest
                  WHERE latest.binding_id = binding.id
                  ORDER BY latest.id DESC LIMIT 1
              )
            WHERE binding.id = ?
            """,
            (int(binding_id),),
        ).fetchone()

    def read_case_binding(
        self, *, scenario_id: int, variant_id: int, binding_id: int
    ) -> dict[str, Any]:
        context = self._canonical_binding_context(
            scenario_id=scenario_id, variant_id=variant_id
        )
        row = self._canonical_binding_row(binding_id)
        if row is None or int(row["case_input_variant_id"]) != int(variant_id):
            raise KeyError(f"binding {binding_id} not found")
        item = dict(row)
        linkable = self.get_linkable_object(int(item["linkable_object_id"]))
        if item["status"] != "active":
            state = "inactive"
        elif (
            item["validation_mode"] is None
            or item["revision_state"] != "sealed"
            or item["revision_content_hash"] != item["bound_content_hash"]
            or item["set_status"] == "archived"
            or item["signal_status"] == "archived"
            or item["role_status"] != "active"
            or linkable["status"] != "active"
        ):
            state = "invalid"
        else:
            operation = {
                "client_operation_id": "effective-state",
                "action": "create",
                "linkable_object_id": int(item["linkable_object_id"]),
                "binding_role_key": item["role_key"],
                "signal_id": int(item["signal_id"]),
                "revision": {
                    "mode": str(item["validation_mode"]).removeprefix("binding_"),
                    "revision_id": int(item["set_revision_id"]),
                    "content_hash": item["bound_content_hash"],
                },
                "catalog_association_id": item["catalog_association_id"],
                "reason_code": "effective_state_read",
                **(
                    {"reason_text": "Previously accepted exact revision."}
                    if item["validation_mode"] == "binding_pinned"
                    else {}
                ),
            }
            current_result, current_observation = self._prevalidate_case_binding_create(
                operation,
                context={
                    **context,
                    "bindings_revision": context["bindings_revision"],
                },
            )
            provenance_stale = any(
                error["code"] == "TS_COMPAT_ASSOCIATION_MISMATCH"
                and error["context"].get("catalog_association_id")
                == item["catalog_association_id"]
                and error["context"].get("association_state") is not None
                for error in current_result["errors"]
            )
            current_errors = [
                error
                for error in current_result["errors"]
                if not (
                    error["code"] == "TS_LINK_CONFLICT"
                    and error["context"].get("binding_id") == int(binding_id)
                )
                and not (
                    error["code"] == "TS_COMPAT_CONTRACT_CHANGED"
                    and "actual_current_revision_id" in error["context"]
                    and int(item["observed_current_revision_id"])
                    != int(item["current_revision_id"])
                )
                and not (
                    error["code"] == "TS_COMPAT_ASSOCIATION_MISMATCH"
                    and provenance_stale
                )
            ]
            if current_errors:
                state = "invalid"
            else:
                current_variant_dependency = (
                    self._case_binding_variant_dependency_fingerprint(
                        scenario_id=int(scenario_id),
                        variant_id=int(variant_id),
                        project_id=context["project_id"],
                    )
                )
                current_compatibility, current_scope = (
                    self._case_binding_fingerprints(
                        observed=current_observation,
                        binding_role_key=item["role_key"],
                        contract_version=current_result["compatibility_decision"][
                            "contract_version"
                        ],
                    )
                )
                stale = (
                    provenance_stale
                    or
                    current_compatibility != item["compatibility_fingerprint"]
                    or current_scope != item["object_scope_fingerprint"]
                    or current_variant_dependency
                    != item["variant_dependency_fingerprint"]
                    or int(item["observed_current_revision_id"])
                    != int(item["current_revision_id"])
                )
                state = (
                    "stale"
                    if stale
                    else "valid_pinned"
                    if item["validation_mode"] == "binding_pinned"
                    else "valid_current"
                )
        binding_id = int(item["id"])
        public_content_hash = (
            f"sha256:{item['bound_content_hash']}"
            if item["source_kind"] == "object_specific"
            else item["bound_content_hash"]
        )
        return {
            "binding_id": binding_id,
            "scenario_id": int(scenario_id),
            "case_input_variant_id": int(item["case_input_variant_id"]),
            "signal_id": int(item["signal_id"]),
            "signal": {
                "id": int(item["signal_id"]),
                "series_key": item["series_key"],
                "display_name": item["signal_display_name"],
            },
            "time_series_set_id": int(item["time_series_set_id"]),
            "set_revision_id": int(item["set_revision_id"]),
            "bound_content_hash": public_content_hash,
            "revision": {
                "mode": (
                    str(item["validation_mode"]).removeprefix("binding_")
                    if item["validation_mode"]
                    else None
                ),
                "id": int(item["set_revision_id"]),
                "content_hash": public_content_hash,
                "observed_current_revision_id": (
                    int(item["observed_current_revision_id"])
                    if item["observed_current_revision_id"] is not None
                    else None
                ),
                "current_revision_id": int(item["current_revision_id"]),
            },
            "object": {
                "id": int(linkable["id"]),
                "project_id": int(linkable["project_id"]),
                "object_kind": linkable["object_kind"],
                "object_type_key": linkable["object_type_key"],
                "object_key": linkable["object_key"],
                "display_name": linkable["display_name"],
                "status": linkable["status"],
            },
            "binding_role": {
                "id": int(item["binding_role_id"]),
                "key": item["role_key"],
                "display_name": item["role_display_name"],
            },
            "catalog_association_id": (
                int(item["catalog_association_id"])
                if item["catalog_association_id"] is not None
                else None
            ),
            "source_kind": item["source_kind"],
            "source_owner_linkable_object_id": (
                int(item["source_owner_linkable_object_id"])
                if item["source_owner_linkable_object_id"] is not None
                else None
            ),
            "compatibility_rule_id": int(item["compatibility_rule_id"]),
            "status": item["status"],
            "state": state,
            "lifecycle_revision": int(item["lifecycle_revision"]),
            "supersedes_binding_id": (
                int(item["supersedes_binding_id"])
                if item["supersedes_binding_id"] is not None
                else None
            ),
            "created_at": item["created_at"],
            "created_by": item["created_by"],
            "updated_at": item["updated_at"],
            "updated_by": item["updated_by"],
            "superseded_at": item["superseded_at"],
            "superseded_by": item["superseded_by"],
            "removed_at": item["removed_at"],
            "removed_by": item["removed_by"],
            "change_reason": {
                "code": item["change_reason_code"],
                "text": item["change_reason_text"],
            },
            "validation": {
                "mode": item["validation_mode"],
                "validated_revision_id": (
                    int(item["validated_set_revision_id"])
                    if item["validated_set_revision_id"] is not None
                    else None
                ),
                "compatibility_fingerprint": item["compatibility_fingerprint"],
                "object_scope_fingerprint": item["object_scope_fingerprint"],
                "variant_dependency_fingerprint": item[
                    "variant_dependency_fingerprint"
                ],
                "validated_at": item["validated_at"],
                "validated_by": item["validated_by"],
            },
            "capabilities": {
                "replace": item["status"] == "active",
                "remove": item["status"] == "active",
                "restore": item["status"] == "removed",
                "revalidate_current": (
                    item["status"] == "active"
                    and int(item["set_revision_id"])
                    == int(item["current_revision_id"])
                ),
                "revalidate_pinned": (
                    item["status"] == "active"
                    and int(item["set_revision_id"])
                    != int(item["current_revision_id"])
                ),
            },
            "links": {
                "detail": (
                    f"/api/scenarios/{int(scenario_id)}/case-variants/"
                    f"{int(variant_id)}/time-series-bindings/{binding_id}"
                ),
                "events": (
                    f"/api/scenarios/{int(scenario_id)}/case-variants/"
                    f"{int(variant_id)}/time-series-bindings/{binding_id}/events"
                ),
            },
        }

    def read_case_bindings(
        self, *, scenario_id: int, variant_id: int
    ) -> dict[str, Any]:
        context = self._canonical_binding_context(
            scenario_id=scenario_id, variant_id=variant_id
        )
        rows = self.connection.execute(
            f"""
            SELECT id FROM {self.link_layer_table_names()['case_time_series_bindings']}
            WHERE case_input_variant_id = ?
            ORDER BY id
            """,
            (int(variant_id),),
        ).fetchall()
        items = [
            self.read_case_binding(
                scenario_id=scenario_id,
                variant_id=variant_id,
                binding_id=int(row["id"]),
            )
            for row in rows
        ]
        return {
            "items": items,
            "page": {"limit": len(items), "has_more": False, "next_cursor": None},
            "summary": {"total_count": len(items)},
            "meta": {
                "scenario_id": int(scenario_id),
                "variant_id": int(variant_id),
                # Chapter 6.8 makes `expected_bindings_revision` mandatory on
                # every batch, so the collection that opens the protected
                # journey states the number the next batch has to send.
                "bindings_revision": int(context["bindings_revision"]),
            },
        }

    def read_case_binding_events(
        self,
        *,
        scenario_id: int,
        variant_id: int,
        binding_id: int,
        limit: int | None = None,
        cursor: str | None = None,
        actor_class: str = "internal",
    ) -> dict[str, Any]:
        self.read_case_binding(
            scenario_id=scenario_id,
            variant_id=variant_id,
            binding_id=binding_id,
        )
        events = self.link_layer_table_names()["time_series_link_events"]
        resolved_limit = normalize_catalog_limit(limit)
        summary = self.connection.execute(
            f"""
            SELECT COUNT(*) AS total_count, COALESCE(MAX(id), 0) AS max_id
            FROM {events} WHERE binding_id = ?
            """,
            (int(binding_id),),
        ).fetchone()
        generation = int(
            hashlib.sha256(
                f"{summary['total_count']}:{summary['max_id']}".encode("utf-8")
            ).hexdigest()[:15],
            16,
        )
        section = f"binding:{int(binding_id)}:events"
        filters_hash = input_filters_hash(
            {
                "scenario_id": int(scenario_id),
                "variant_id": int(variant_id),
                "binding_id": int(binding_id),
            }
        )
        cursor_id = 0
        if cursor is not None:
            cursor_key = decode_catalog_cursor(
                cursor,
                self._catalog_cursor_secret,
                section=section,
                order="id",
                limit=resolved_limit,
                generation=generation,
                actor_class=actor_class,
                filters_hash=filters_hash,
            )
            if len(cursor_key) != 1:
                raise CatalogQueryError(
                    "TS_QUERY_CURSOR_MISMATCH", reason="key_arity"
                )
            cursor_id = int(cursor_key[0])
        rows = self.connection.execute(
            f"""
            SELECT * FROM {events}
            WHERE binding_id = ? AND id > ?
            ORDER BY id LIMIT ?
            """,
            (int(binding_id), cursor_id, resolved_limit + 1),
        ).fetchall()
        has_more = len(rows) > resolved_limit
        visible = rows[:resolved_limit]
        items = []
        for row in visible:
            event = dict(row)
            items.append(
                {
                    "event_id": int(event["id"]),
                    "batch_id": event["batch_id"],
                    "binding_id": int(event["binding_id"]),
                    "event_type": event["event_type"],
                    "actor": {
                        "user_id": (
                            int(event["actor_user_id"])
                            if event["actor_user_id"] is not None
                            else None
                        ),
                        "identity": event["actor_identity_snapshot"],
                        "role": event["actor_role_snapshot"],
                    },
                    "reason": {
                        "code": event["reason_code"],
                        "text": event["reason_text"],
                    },
                    "before": json.loads(event["before_json"]),
                    "after": json.loads(event["after_json"]),
                    "request_id": event["request_id"],
                    "occurred_at": event["occurred_at"],
                }
            )
        next_cursor = None
        if has_more and visible:
            next_cursor = encode_catalog_cursor(
                {
                    "s": section,
                    "o": "id",
                    "l": resolved_limit,
                    "g": generation,
                    "k": [int(visible[-1]["id"])],
                    "t": int(time.time()),
                    "a": actor_class,
                    "f": filters_hash,
                },
                self._catalog_cursor_secret,
            )
        return {
            "items": items,
            "page": {
                "limit": resolved_limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
            "summary": {"total_count": int(summary["total_count"])},
            "meta": {
                "scenario_id": int(scenario_id),
                "variant_id": int(variant_id),
                "binding_id": int(binding_id),
                "generation": generation,
            },
        }

    def assert_case_bindings_executable(
        self, *, scenario_id: int, variant_id: int
    ) -> None:
        """Fail closed before any run can consume a stale canonical binding."""

        page = self.read_case_bindings(
            scenario_id=scenario_id, variant_id=variant_id
        )
        blocked = [
            {
                "binding_id": item["binding_id"],
                "state": item["state"],
                "linkable_object_id": item["object"]["id"],
                "binding_role_key": item["binding_role"]["key"],
            }
            for item in page["items"]
            if item["status"] == "active"
            and item["state"] not in {"valid_current", "valid_pinned"}
        ]
        blocked.extend(self._open_c4_variant_anomalies(variant_id=int(variant_id)))
        if blocked:
            raise BindingMutationError(
                "TS_BINDING_EXECUTION_BLOCKED", details=blocked
            )

    def _open_c4_variant_anomalies(self, *, variant_id: int) -> list[dict[str, Any]]:
        rows = self.connection.execute(
            f"""
            SELECT id, code, evidence_json
            FROM {self._migration('time_series_migration_anomalies')}
            WHERE phase = 'C4' AND severity = 'blocking'
              AND resolution <> 'resolved'
            ORDER BY id
            """
        ).fetchall()
        blocked = []
        for row in rows:
            evidence = json.loads(row["evidence_json"] or "{}")
            if int(evidence.get("variant_id") or 0) != int(variant_id):
                continue
            blocked.append(
                {
                    "binding_id": int(evidence["binding_id"]),
                    "state": "migration_blocked",
                    "anomaly_id": int(row["id"]),
                    "anomaly_code": str(row["code"]),
                }
            )
        return blocked

    @contextlib.contextmanager
    def _run_materialization_transaction(self):
        """Open the authoritative materialization unit with an eager SQLite lock."""

        if self.database_backend == "postgresql":
            with self.connection.transaction():
                yield
            return
        self.connection.execute("BEGIN IMMEDIATE")
        try:
            yield
        except Exception:
            self.connection.rollback()
            raise
        else:
            self.connection.commit()

    def _lock_canonical_run_inputs(self, *, variant_id: int) -> None:
        if self.database_backend != "postgresql":
            return
        self.connection.execute(
            "SELECT id FROM case_input_variants WHERE id = ? FOR UPDATE",
            (int(variant_id),),
        ).fetchone()
        bindings = self.link_layer_table_names()["case_time_series_bindings"]
        rows = self.connection.execute(
            f"""
            SELECT DISTINCT time_series_set_id, set_revision_id
            FROM {bindings}
            WHERE case_input_variant_id = ? AND status = 'active'
            ORDER BY time_series_set_id, set_revision_id
            """,
            (int(variant_id),),
        ).fetchall()
        set_ids = sorted({int(row["time_series_set_id"]) for row in rows})
        revision_ids = sorted({int(row["set_revision_id"]) for row in rows})
        for table, ids in (
            (self._canonical("time_series_sets"), set_ids),
            (self._canonical("time_series_set_revisions"), revision_ids),
        ):
            if not ids:
                continue
            placeholders = ", ".join("?" for _ in ids)
            self.connection.execute(
                f"SELECT id FROM {table} WHERE id IN ({placeholders}) "
                "ORDER BY id FOR KEY SHARE",
                tuple(ids),
            ).fetchall()

    @staticmethod
    def _canonical_binding_scope(binding: Mapping[str, Any]) -> tuple[str | None, str | None]:
        object_type_key = str(binding["object"]["object_type_key"])
        if object_type_key == "global:system":
            return None, None
        return object_type_key, str(binding["object"]["object_key"])

    def _reusable_materialized_scenario_version(
        self,
        *,
        scenario_id: int,
        system_case: Mapping[str, Any],
        materialization_fingerprint: str,
    ) -> dict[str, Any] | None:
        expected_payload = json.dumps(
            system_case, sort_keys=True, separators=(",", ":")
        )
        rows = self.connection.execute(
            """
            SELECT id, system_case_json, generation_metadata_json
            FROM scenario_versions
            WHERE scenario_id = ?
            ORDER BY id DESC
            """,
            (int(scenario_id),),
        ).fetchall()
        for row in rows:
            existing_metadata = json.loads(row["generation_metadata_json"] or "{}")
            if (
                existing_metadata.get("materialization_fingerprint")
                != materialization_fingerprint
            ):
                continue
            existing_payload = json.dumps(
                json.loads(row["system_case_json"]),
                sort_keys=True,
                separators=(",", ":"),
            )
            if existing_payload == expected_payload:
                return self.get_scenario_version(int(row["id"]), include_document=False)
        return None

    def materialize_run_from_canonical_bindings(
        self,
        *,
        scenario_id: int,
        variant_id: int,
        range_start: str,
        range_end: str,
        validate_text: Callable[[str], Any],
        actor_user: Mapping[str, Any],
        request_id: str,
        expected_bindings_revision: int | None = None,
    ) -> dict[str, Any] | None:
        """Create the immutable input snapshot and queued run in one transaction.

        ``None`` means that this variant has no active TS-7 binding and the
        pre-cutover legacy materializer remains authoritative.
        """

        with self._lock:
            with self._run_materialization_transaction():
                self._canonical_binding_context(
                    scenario_id=scenario_id, variant_id=variant_id
                )
                self._lock_canonical_run_inputs(variant_id=variant_id)
                context = self._canonical_binding_context(
                    scenario_id=scenario_id, variant_id=variant_id
                )
                binding_rows = self.connection.execute(
                    f"""
                    SELECT id
                    FROM {self.link_layer_table_names()['case_time_series_bindings']}
                    WHERE case_input_variant_id = ? AND status = 'active'
                    ORDER BY id
                    """,
                    (int(variant_id),),
                ).fetchall()
                if not binding_rows:
                    migration_blocks = self._open_c4_variant_anomalies(
                        variant_id=int(variant_id)
                    )
                    if migration_blocks:
                        raise BindingMutationError(
                            "TS_BINDING_EXECUTION_BLOCKED",
                            details=migration_blocks,
                        )
                    return None
                if (
                    expected_bindings_revision is not None
                    and int(expected_bindings_revision) != context["bindings_revision"]
                ):
                    raise BindingMutationError(
                        "TS_LINK_PRECONDITION_CHANGED",
                        expected_bindings_revision=int(expected_bindings_revision),
                        actual_bindings_revision=context["bindings_revision"],
                    )

                bindings = [
                    self.read_case_binding(
                        scenario_id=scenario_id,
                        variant_id=variant_id,
                        binding_id=int(row["id"]),
                    )
                    for row in binding_rows
                ]
                blocked = [
                    {
                        "binding_id": item["binding_id"],
                        "state": item["state"],
                        "linkable_object_id": item["object"]["id"],
                        "binding_role_key": item["binding_role"]["key"],
                    }
                    for item in bindings
                    if item["state"] not in {"valid_current", "valid_pinned"}
                ]
                if blocked:
                    raise BindingMutationError(
                        "TS_BINDING_EXECUTION_BLOCKED", details=blocked
                    )

                base_system_case = self._generate_base_system_case_for_variant(
                    scenario_id
                )
                legacy_shape_bindings: list[dict[str, Any]] = []
                materialization_rows: list[
                    tuple[dict[str, Any], dict[str, Any], dict[str, Any]]
                ] = []
                revision_cache: dict[int, dict[str, Any]] = {}
                hash_cache: dict[int, str] = {}
                for binding in bindings:
                    raw_row = self._canonical_binding_row(binding["binding_id"])
                    if raw_row is None:
                        raise BindingMutationError(
                            "TS_BINDING_EXECUTION_BLOCKED",
                            details=[
                                {
                                    "binding_id": binding["binding_id"],
                                    "state": "invalid",
                                    "reason": "binding_disappeared",
                                }
                            ],
                        )
                    raw = dict(raw_row)
                    contract_key = str(raw.get("execution_contract_key") or "")
                    if not contract_key:
                        raise BindingMutationError(
                            "TS_BINDING_EXECUTION_BLOCKED",
                            details=[
                                {
                                    "binding_id": binding["binding_id"],
                                    "state": "invalid",
                                    "reason": "execution_contract_missing",
                                }
                            ],
                        )
                    entity_type, entity_id = self._canonical_binding_scope(binding)
                    legacy_shape_bindings.append(
                        {
                            "signal_key": contract_key,
                            "entity_type": entity_type,
                            "entity_id": entity_id,
                            "time_series_set_id": binding["time_series_set_id"],
                        }
                    )

                    revision_id = int(binding["set_revision_id"])
                    revision = revision_cache.get(revision_id)
                    if revision is None:
                        revision = self.read_canonical_revision(revision_id)
                        revision_cache[revision_id] = revision
                    actual_hash = hash_cache.get(revision_id)
                    if actual_hash is None:
                        actual_hash = self._stream_canonical_content_hash(
                            revision_id=revision_id,
                            revision_timezone=str(revision["timezone"]),
                            timestamp_convention=str(revision["timestamp_convention"]),
                            data_class_key=str(revision["data_class_key"]),
                        )
                        hash_cache[revision_id] = actual_hash
                    if (
                        revision.get("state") != "sealed"
                        or revision.get("content_hash")
                        != binding["bound_content_hash"]
                        or actual_hash != binding["bound_content_hash"]
                    ):
                        raise BindingMutationError(
                            "TS_BINDING_EXECUTION_BLOCKED",
                            details=[
                                {
                                    "binding_id": binding["binding_id"],
                                    "state": "invalid",
                                    "reason": "content_hash_mismatch",
                                    "expected_content_hash": binding[
                                        "bound_content_hash"
                                    ],
                                    "actual_content_hash": actual_hash,
                                }
                            ],
                        )
                    source_key = binding["signal"]["series_key"]
                    source_values = revision["values"].get(source_key)
                    if source_values is None or len(source_values) != len(
                        revision["periods"]
                    ):
                        raise BindingMutationError(
                            "TS_BINDING_EXECUTION_BLOCKED",
                            details=[
                                {
                                    "binding_id": binding["binding_id"],
                                    "state": "invalid",
                                    "reason": "bound_signal_missing",
                                }
                            ],
                        )
                    adapted_set = {
                        "id": binding["time_series_set_id"],
                        "periods": revision["periods"],
                        "values": [
                            {
                                "period_index": int(period["period_index"]),
                                "signal_key": contract_key,
                                "value_numeric": source_values[index],
                            }
                            for index, period in enumerate(revision["periods"])
                        ],
                    }
                    materialization_rows.append((binding, raw, adapted_set))

                missing = [
                    status
                    for status in evaluate_variant_completeness(
                        discover_required_signals(base_system_case),
                        legacy_shape_bindings,
                    )
                    if not status.bound
                ]
                if missing:
                    raise MissingRequiredSignalsError(missing)

                bound_signal_series: dict[Any, list[dict[str, Any]]] = {}
                lineage: list[dict[str, Any]] = []
                for binding, raw, adapted_set in materialization_rows:
                    contract_key = str(raw["execution_contract_key"])
                    entity_type, entity_id = self._canonical_binding_scope(binding)
                    binding_key: Any = contract_key
                    if entity_type is not None or entity_id is not None:
                        binding_key = (contract_key, entity_type, entity_id)
                    bound_signal_series[binding_key] = resolve_bound_signal_series(
                        adapted_set, contract_key, range_start, range_end
                    )
                    validation_evidence = {
                        "validation_id": int(raw["validation_id"]),
                        "mode": raw["validation_mode"],
                        "validated_set_revision_id": int(
                            raw["validated_set_revision_id"]
                        ),
                        "observed_current_revision_id": int(
                            raw["observed_current_revision_id"]
                        ),
                        "compatibility_fingerprint": raw[
                            "compatibility_fingerprint"
                        ],
                        "object_scope_fingerprint": raw[
                            "object_scope_fingerprint"
                        ],
                        "variant_dependency_fingerprint": raw[
                            "variant_dependency_fingerprint"
                        ],
                        "validated_at": raw["validated_at"],
                        "validated_by": raw["validated_by"],
                    }
                    validation_fingerprint = hashlib.sha256(
                        json.dumps(
                            validation_evidence,
                            sort_keys=True,
                            separators=(",", ":"),
                        ).encode("utf-8")
                    ).hexdigest()
                    revision = revision_cache[int(binding["set_revision_id"])]
                    lineage.append(
                        {
                            "binding_id": binding["binding_id"],
                            "state": binding["state"],
                            "linkable_object_id": binding["object"]["id"],
                            "object_type_key": binding["object"]["object_type_key"],
                            "object_key": binding["object"]["object_key"],
                            "binding_role_key": binding["binding_role"]["key"],
                            "signal_id": binding["signal_id"],
                            "signal_key": contract_key,
                            "source_signal_key": binding["signal"]["series_key"],
                            "time_series_set_id": binding["time_series_set_id"],
                            "set_version_number": int(raw["set_version_number"]),
                            "set_revision_id": binding["set_revision_id"],
                            "revision_number": int(revision["revision_number"]),
                            "content_hash": binding["bound_content_hash"],
                            "source_kind": raw["source_kind"],
                            "owner_project_id": int(raw["owner_project_id"]),
                            "compatibility_rule_id": binding[
                                "compatibility_rule_id"
                            ],
                            "compatibility_rule_version": int(
                                raw["compatibility_rule_version"]
                            ),
                            "compatibility_fingerprint": raw[
                                "compatibility_fingerprint"
                            ],
                            "validation_id": int(raw["validation_id"]),
                            "validation_mode": raw["validation_mode"],
                            "validation_fingerprint": validation_fingerprint,
                            "validated_at": raw["validated_at"],
                            "validated_by": raw["validated_by"],
                            "revision_mode": binding["revision"]["mode"],
                            "observed_current_revision_id": binding["revision"][
                                "observed_current_revision_id"
                            ],
                            "pin_reason": (
                                raw["validation_reason_text"]
                                if binding["revision"]["mode"] == "pinned"
                                else None
                            ),
                            "validated_range": {
                                "start": range_start,
                                "end": range_end,
                            },
                        }
                    )

                system_case = dict(base_system_case)
                system_case["time_series"] = materialize_variant_time_series(
                    bound_signal_series
                )
                variant = self.get_case_input_variant(variant_id)
                provenance = derive_case_hierarchy_provenance(base_system_case)
                actor = {
                    "id": (
                        int(actor_user["id"])
                        if actor_user.get("id") is not None
                        else None
                    ),
                    "email": str(actor_user.get("email") or "internal_analyst"),
                    "display_name": str(
                        actor_user.get("display_name") or "Internal analyst"
                    ),
                    "role": str(actor_user.get("role") or "analyst"),
                }
                lineage_metadata = {
                    **provenance,
                    "kind": "case_input_variant",
                    "input_variant": {
                        "id": int(variant_id),
                        "display_name": variant["display_name"],
                    },
                    "bindings_revision": context["bindings_revision"],
                    "date_range": {"start": range_start, "end": range_end},
                    "series_bindings": lineage,
                }
                generation_metadata = {
                    **lineage_metadata,
                    "actor": actor,
                    "request_id": request_id,
                }
                fingerprint_payload = {
                    "system_case": system_case,
                    "lineage": lineage_metadata,
                }
                materialization_fingerprint = hashlib.sha256(
                    json.dumps(
                        fingerprint_payload,
                        sort_keys=True,
                        separators=(",", ":"),
                    ).encode("utf-8")
                ).hexdigest()
                generation_metadata["materialization_fingerprint"] = (
                    materialization_fingerprint
                )

                system_case_text = json.dumps(system_case, sort_keys=True)
                validation_result = validate_text(system_case_text)
                if not getattr(validation_result, "ok", False):
                    raise CanonicalRunValidationError(validation_result)

                scenario_version = self._reusable_materialized_scenario_version(
                    scenario_id=scenario_id,
                    system_case=system_case,
                    materialization_fingerprint=materialization_fingerprint,
                )
                reused = scenario_version is not None
                if scenario_version is None:
                    system_case_metadata = extract_system_case_metadata(system_case)
                    version_cursor = self.connection.execute(
                        """
                        INSERT INTO scenario_versions (
                            scenario_id, version_number, system_case_json,
                            case_name, schema_version, period_count,
                            asset_counts_json, validation_payload_json,
                            generation_metadata_json, created_at, created_by
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                        """,
                        (
                            int(scenario_id),
                            self._next_version_number(scenario_id),
                            system_case_text,
                            system_case_metadata["case_name"],
                            system_case_metadata["schema_version"],
                            system_case_metadata["period_count"],
                            json.dumps(
                                system_case_metadata["asset_counts"], sort_keys=True
                            ),
                            json.dumps(validation_result.payload, sort_keys=True),
                            json.dumps(generation_metadata, sort_keys=True),
                            utc_now_iso(),
                            actor["email"],
                        ),
                    )
                    scenario_version = self.get_scenario_version(
                        int(version_cursor.lastrowid), include_document=False
                    )

                run_cursor = self.connection.execute(
                    """
                    INSERT INTO runs (
                        scenario_version_id, status, created_at, triggered_by,
                        trigger_type, triggered_by_user_id,
                        triggered_by_display_name, materialized_lineage_json
                    ) VALUES (?, 'queued', ?, ?, 'manual', ?, ?, ?)
                    """,
                    (
                        scenario_version["id"],
                        utc_now_iso(),
                        actor["email"],
                        actor["id"],
                        actor["display_name"],
                        json.dumps(
                            {
                                "materialization_fingerprint": materialization_fingerprint,
                                "bindings_revision": context["bindings_revision"],
                                "series_bindings": lineage,
                            },
                            sort_keys=True,
                        ),
                    ),
                )
                return {
                    "run": self.get_run(int(run_cursor.lastrowid)),
                    "scenario_version": scenario_version,
                    "scenario_version_reused": reused,
                }

    def list_catalog_results(
        self,
        *,
        limit: int | None = None,
        cursor: str | None = None,
        actor_class: str = "internal",
        filters: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Read-only result identities; never canonical signal identities."""

        resolved_limit = normalize_catalog_limit(limit)
        rows = self.connection.execute(
            """
            SELECT result_index.run_id, result_index.dispatch_columns_json,
                   result_index.signal_keys_json, result_index.created_at,
                   run.status AS run_status, scenario.id AS scenario_id,
                   scenario.name AS scenario_name, project.id AS project_id,
                   project.name AS project_name
            FROM run_dispatch_result_indexes AS result_index
            JOIN runs AS run ON run.id = result_index.run_id
            JOIN scenario_versions AS version
              ON version.id = result_index.scenario_version_id
            JOIN scenarios AS scenario ON scenario.id = version.scenario_id
            JOIN projects AS project ON project.id = scenario.project_id
            ORDER BY result_index.created_at DESC, result_index.run_id DESC
            """
        ).fetchall()
        items = []
        excluded = {"timestamp", "duration_hours", "period_index"}
        for row in rows:
            columns = json.loads(row["dispatch_columns_json"] or "[]")
            signal_keys = json.loads(row["signal_keys_json"] or "{}")
            coverage = self.connection.execute(
                """
                SELECT MIN(timestamp) AS coverage_start,
                       MAX(timestamp) AS coverage_end,
                       COUNT(*) AS period_count
                FROM run_dispatch_result_rows WHERE run_id = ?
                """,
                (row["run_id"],),
            ).fetchone()
            for column in columns:
                if column in excluded:
                    continue
                items.append(
                    {
                        "entry_kind": "result",
                        "result_series_id": f"run:{int(row['run_id'])}:dispatch:{column}",
                        "result_type": column,
                        "display_name": str(column).replace("_", " ").title(),
                        "signal_key": signal_keys.get(column),
                        "owner": {
                            "project_id": int(row["project_id"]),
                            "project_name": row["project_name"],
                        },
                        "scenario": {
                            "id": int(row["scenario_id"]),
                            "name": row["scenario_name"],
                        },
                        "run": {
                            "id": int(row["run_id"]),
                            "status": row["run_status"],
                        },
                        "coverage_summary": {
                            "start": coverage["coverage_start"],
                            "end": coverage["coverage_end"],
                            "period_count": int(coverage["period_count"]),
                        },
                        "produced_at": row["created_at"],
                        "capabilities": {"view_detail": True, "preview": True},
                    }
                )
        generation_source = json.dumps(items, sort_keys=True, default=str)
        generation = int(hashlib.sha256(generation_source.encode()).hexdigest()[:15], 16)
        normalized_filters = dict(filters or {})

        def produced_at_utc(value: str) -> str:
            parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
            if parsed.tzinfo is not None:
                parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
            return parsed.isoformat()

        def selected(item: dict[str, Any]) -> bool:
            checks = (
                ("owner_project_id", item["owner"]["project_id"]),
                ("scenario_id", item["scenario"]["id"]),
                ("run_id", item["run"]["id"]),
                ("run_status", item["run"]["status"]),
                ("result_type", item["result_type"]),
            )
            if any(
                name in normalized_filters
                and value not in normalized_filters[name]
                for name, value in checks
            ):
                return False
            produced_at = produced_at_utc(item["produced_at"])
            if produced_at < normalized_filters.get("produced_from", produced_at):
                return False
            if produced_at > normalized_filters.get("produced_to", produced_at):
                return False
            return True

        items = [item for item in items if selected(item)]
        total_count = len(items)
        filters_digest = input_filters_hash(
            {"section": "results", **normalized_filters}
        )
        if cursor is not None:
            cursor_key = decode_catalog_cursor(
                cursor,
                self._catalog_cursor_secret,
                section="results",
                order="-produced_at",
                limit=resolved_limit,
                generation=generation,
                actor_class=actor_class,
                filters_hash=filters_digest,
            )
            if len(cursor_key) != 1:
                raise CatalogQueryError("TS_QUERY_CURSOR_MISMATCH", reason="key_arity")
            positions = {
                item["result_series_id"]: index for index, item in enumerate(items)
            }
            if cursor_key[0] not in positions:
                raise CatalogQueryError("TS_QUERY_CURSOR_MISMATCH", reason="key_missing")
            items = items[positions[cursor_key[0]] + 1 :]
        visible = items[:resolved_limit]
        has_more = len(items) > resolved_limit
        next_cursor = None
        if has_more and visible:
            next_cursor = encode_catalog_cursor(
                {
                    "s": "results",
                    "o": "-produced_at",
                    "l": resolved_limit,
                    "g": generation,
                    "k": [visible[-1]["result_series_id"]],
                    "t": int(time.time()),
                    "a": actor_class,
                    "f": filters_digest,
                },
                self._catalog_cursor_secret,
            )
        return {
            "items": visible,
            "page": {
                "limit": resolved_limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
            "summary": {"total_count": total_count},
            "facets": None,
            "meta": {"section": "results", "catalog_generation": generation},
        }

    @staticmethod
    def _parse_result_series_id(result_series_id: str) -> tuple[int, str]:
        parts = str(result_series_id).split(":", 3)
        if len(parts) != 4 or parts[0] != "run" or parts[2] != "dispatch":
            raise KeyError("result series not found")
        try:
            run_id = int(parts[1])
        except ValueError as error:
            raise KeyError("result series not found") from error
        if run_id < 1 or not parts[3]:
            raise KeyError("result series not found")
        return run_id, parts[3]

    def read_catalog_result_detail(self, result_series_id: str) -> dict[str, Any]:
        run_id, column = self._parse_result_series_id(result_series_id)
        row = self.connection.execute(
            """
            SELECT result_index.dispatch_columns_json,
                   result_index.signal_keys_json, result_index.created_at,
                   run.status AS run_status, scenario.id AS scenario_id,
                   scenario.name AS scenario_name, project.id AS project_id,
                   project.name AS project_name
            FROM run_dispatch_result_indexes AS result_index
            JOIN runs AS run ON run.id = result_index.run_id
            JOIN scenario_versions AS version
              ON version.id = result_index.scenario_version_id
            JOIN scenarios AS scenario ON scenario.id = version.scenario_id
            JOIN projects AS project ON project.id = scenario.project_id
            WHERE result_index.run_id = ?
            """,
            (run_id,),
        ).fetchone()
        if row is None:
            raise KeyError("result series not found")
        columns = json.loads(row["dispatch_columns_json"] or "[]")
        if column not in columns or column in {"timestamp", "duration_hours", "period_index"}:
            raise KeyError("result series not found")
        signal_keys = json.loads(row["signal_keys_json"] or "{}")
        coverage = self.connection.execute(
            """
            SELECT MIN(timestamp) AS coverage_start,
                   MAX(timestamp) AS coverage_end,
                   COUNT(*) AS period_count
            FROM run_dispatch_result_rows WHERE run_id = ?
            """,
            (run_id,),
        ).fetchone()
        return {
            "entry_kind": "result",
            "result_series_id": result_series_id,
            "result_type": column,
            "display_name": column.replace("_", " ").title(),
            "signal_key": signal_keys.get(column),
            "owner": {
                "project_id": int(row["project_id"]),
                "project_name": row["project_name"],
            },
            "scenario": {
                "id": int(row["scenario_id"]),
                "name": row["scenario_name"],
            },
            "run": {"id": run_id, "status": row["run_status"]},
            "coverage_summary": {
                "start": coverage["coverage_start"],
                "end": coverage["coverage_end"],
                "period_count": int(coverage["period_count"]),
            },
            "produced_at": row["created_at"],
            "capabilities": {"view_detail": True, "preview": True},
        }

    def read_catalog_result_preview(
        self,
        result_series_id: str,
        *,
        range_from: str,
        range_to: str,
        sampling: str,
        max_points: int,
    ) -> dict[str, Any]:
        detail = self.read_catalog_result_detail(result_series_id)
        run_id, column = self._parse_result_series_id(result_series_id)
        rows = []
        for stored in self.connection.execute(
            """
            SELECT row_json, timestamp, duration_hours
            FROM run_dispatch_result_rows
            WHERE run_id = ? ORDER BY period_index
            """,
            (run_id,),
        ).fetchall():
            payload = json.loads(stored["row_json"] or "{}")
            timestamp_start = str(stored["timestamp"])
            duration_hours = float(stored["duration_hours"] or 0)
            timestamp_end = (
                datetime.fromisoformat(timestamp_start) + timedelta(hours=duration_hours)
            ).isoformat()
            if timestamp_start < range_from or timestamp_end > range_to:
                continue
            value = payload.get(column)
            if value is None:
                continue
            rows.append(
                {
                    "timestamp_start": timestamp_start,
                    "timestamp_end": timestamp_end,
                    "value_numeric": float(value),
                    "quality_flag": None,
                }
            )
        if sampling == "none" and len(rows) > max_points:
            raise CatalogQueryError(
                "TS_PREVIEW_TOO_LARGE",
                source_point_count=len(rows),
                max_points=max_points,
            )
        sampled = sample_preview_rows(rows, strategy=sampling, limit=max_points)
        return {
            "entry_kind": "result",
            "result_series_id": result_series_id,
            "result_type": detail["result_type"],
            "requested_range": {"from": range_from, "to": range_to},
            "effective_range": (
                {"from": rows[0]["timestamp_start"], "to": rows[-1]["timestamp_end"]}
                if rows
                else None
            ),
            "sampling": sampling,
            "max_points": max_points,
            "source_point_count": len(rows),
            "returned_point_count": len(sampled),
            "points": [
                {
                    "timestamp_start": row["timestamp_start"],
                    "timestamp_end": row["timestamp_end"],
                    "value": row["value_numeric"],
                    "quality_flag": row["quality_flag"],
                }
                for row in sampled
            ],
        }

    def _legacy_entry_ref(self, legacy_id: int) -> str:
        digest = hmac.new(
            self._catalog_cursor_secret,
            f"hydraulic:{int(legacy_id)}".encode(),
            hashlib.sha256,
        ).hexdigest()[:32]
        return f"legacy_{digest}"

    def list_catalog_legacy(
        self,
        *,
        limit: int | None = None,
        cursor: str | None = None,
        actor_class: str = "internal",
    ) -> dict[str, Any]:
        """Global internal view of the existing hydraulic legacy adapter."""

        resolved_limit = normalize_catalog_limit(limit)
        rows = self.connection.execute(
            "SELECT " + self._HYDRAULIC_TIME_SERIES_CATALOG_COLUMNS
            + self._HYDRAULIC_TIME_SERIES_CATALOG_JOINS
            + " ORDER BY hydraulic_time_series_sets.id"
        ).fetchall()
        project_names = {
            int(row["id"]): row["name"]
            for row in self.connection.execute("SELECT id, name FROM projects").fetchall()
        }
        items = []
        for raw in rows:
            summary = build_hydraulic_catalog_summary(row_to_dict(raw))
            migrated = summary["migration"] is not None
            items.append(
                {
                    "entry_kind": "legacy",
                    "legacy_entry_ref": self._legacy_entry_ref(summary["id"]),
                    "identity": {
                        "signal_key": summary["signal_key"],
                        "entity_type": summary["entity_type"],
                        "entity_key": summary["entity_key"],
                        "display_name": summary["name"],
                        "status": summary["status"],
                    },
                    "owner": {
                        "project_id": summary["project_id"],
                        "project_name": project_names.get(summary["project_id"], ""),
                    },
                    "version": {
                        "number": summary["version_number"],
                        "label": summary["version_label"],
                        "content_hash": summary["content_hash"],
                    },
                    "migration_state": "migrated" if migrated else "unmigrated",
                    "canonical_signal": summary["migration"],
                    "coverage_summary": {"period_count": summary["period_count"]},
                    "capabilities": {
                        "view_detail": True,
                        "preview": True,
                        "migrate": not migrated,
                    },
                }
            )
        generation_source = json.dumps(items, sort_keys=True, default=str)
        generation = int(hashlib.sha256(generation_source.encode()).hexdigest()[:15], 16)
        total_count = len(items)
        filters_digest = input_filters_hash({"section": "legacy"})
        if cursor is not None:
            cursor_key = decode_catalog_cursor(
                cursor,
                self._catalog_cursor_secret,
                section="legacy",
                order="legacy_id",
                limit=resolved_limit,
                generation=generation,
                actor_class=actor_class,
                filters_hash=filters_digest,
            )
            if len(cursor_key) != 1:
                raise CatalogQueryError("TS_QUERY_CURSOR_MISMATCH", reason="key_arity")
            positions = {
                item["legacy_entry_ref"]: index for index, item in enumerate(items)
            }
            if cursor_key[0] not in positions:
                raise CatalogQueryError("TS_QUERY_CURSOR_MISMATCH", reason="key_missing")
            items = items[positions[cursor_key[0]] + 1 :]
        visible = items[:resolved_limit]
        has_more = len(items) > resolved_limit
        next_cursor = None
        if has_more and visible:
            next_cursor = encode_catalog_cursor(
                {
                    "s": "legacy",
                    "o": "legacy_id",
                    "l": resolved_limit,
                    "g": generation,
                    "k": [visible[-1]["legacy_entry_ref"]],
                    "t": int(time.time()),
                    "a": actor_class,
                    "f": filters_digest,
                },
                self._catalog_cursor_secret,
            )
        return {
            "items": visible,
            "page": {
                "limit": resolved_limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
            "summary": {"total_count": total_count},
            "facets": None,
            "meta": {"section": "legacy", "catalog_generation": generation},
        }

    def _resolve_legacy_entry_ref(self, legacy_entry_ref: str) -> tuple[int, int]:
        rows = self.connection.execute(
            "SELECT id, project_id FROM hydraulic_time_series_sets ORDER BY id"
        ).fetchall()
        for row in rows:
            candidate = self._legacy_entry_ref(int(row["id"]))
            if hmac.compare_digest(candidate, str(legacy_entry_ref)):
                return int(row["project_id"]), int(row["id"])
        raise KeyError("legacy entry not found")

    def read_catalog_legacy_detail(self, legacy_entry_ref: str) -> dict[str, Any]:
        project_id, legacy_id = self._resolve_legacy_entry_ref(legacy_entry_ref)
        raw = self.get_hydraulic_time_series_set(project_id, legacy_id)
        return {
            "entry_kind": "legacy",
            "legacy_entry_ref": legacy_entry_ref,
            "identity": {
                "signal_key": raw["signal_key"],
                "entity_type": raw["entity_type"],
                "entity_key": raw["entity_key"],
                "display_name": raw["name"],
                "status": raw["status"],
            },
            "owner": {
                "project_id": project_id,
                "project_name": self.get_project(project_id)["name"],
            },
            "version": {
                "number": raw["version_number"],
                "label": raw["version_label"],
                "content_hash": raw["content_hash"],
            },
            "migration_state": "migrated" if raw["migration"] else "unmigrated",
            "canonical_signal": raw["migration"],
            "coverage_summary": raw["horizon"],
            "origin": raw["origin"],
            "capabilities": {
                "view_detail": True,
                "preview": True,
                "migrate": raw["migration"] is None,
            },
        }

    def read_catalog_legacy_preview(
        self,
        legacy_entry_ref: str,
        *,
        range_from: str,
        range_to: str,
        sampling: str,
        max_points: int,
    ) -> dict[str, Any]:
        project_id, legacy_id = self._resolve_legacy_entry_ref(legacy_entry_ref)
        raw = self.get_hydraulic_time_series_set(project_id, legacy_id)
        rows = []
        for period, value in zip(raw["periods"], raw["values"]):
            if (
                period["timestamp_start"] >= range_from
                and period["timestamp_end"] <= range_to
            ):
                rows.append(
                    {
                        "timestamp_start": period["timestamp_start"],
                        "timestamp_end": period["timestamp_end"],
                        "value_numeric": float(value["value_numeric"]),
                        "quality_flag": None,
                    }
                )
        if sampling == "none" and len(rows) > max_points:
            raise CatalogQueryError(
                "TS_PREVIEW_TOO_LARGE",
                source_point_count=len(rows),
                max_points=max_points,
            )
        sampled = sample_preview_rows(rows, strategy=sampling, limit=max_points)
        return {
            "entry_kind": "legacy",
            "legacy_entry_ref": legacy_entry_ref,
            "content_hash": raw["content_hash"],
            "requested_range": {"from": range_from, "to": range_to},
            "effective_range": (
                {"from": rows[0]["timestamp_start"], "to": rows[-1]["timestamp_end"]}
                if rows
                else None
            ),
            "sampling": sampling,
            "max_points": max_points,
            "source_point_count": len(rows),
            "returned_point_count": len(sampled),
            "unit": raw["unit"],
            "points": [
                {
                    "timestamp_start": row["timestamp_start"],
                    "timestamp_end": row["timestamp_end"],
                    "value": row["value_numeric"],
                    "quality_flag": row["quality_flag"],
                }
                for row in sampled
            ],
        }

    def explain_object_context_page(
        self,
        *,
        linkable_object_id: int,
        limit: int | None = None,
        analyze: bool = False,
    ) -> dict[str, Any]:
        """Reference plan of the contextual object list (AC-PER-02)."""

        resolved_limit = normalize_catalog_limit(limit)
        sql, parameters = object_context_page_sql(
            entries_table=self._projection("time_series_catalog_entries"),
            associations_table=link_layer_table_names(self.database_backend)[
                "time_series_catalog_associations"
            ],
            sets_table=self._canonical("time_series_sets"),
            signals_table=self._canonical("time_series_signals"),
            linkable_object_id=linkable_object_id,
            cursor_key=None,
            limit=resolved_limit,
        )
        return self._explain(sql, parameters, analyze=analyze)

    def _explain(self, sql: str, parameters: tuple, *, analyze: bool) -> dict[str, Any]:
        if self.database_backend == "postgresql":
            prefix = "EXPLAIN (ANALYZE, BUFFERS)" if analyze else "EXPLAIN (BUFFERS)"
            rows = self.connection.execute(f"{prefix} {sql}", parameters).fetchall()
            plan = [str(row["QUERY PLAN"]) for row in rows]
        else:
            rows = self.connection.execute(
                f"EXPLAIN QUERY PLAN {sql}", parameters
            ).fetchall()
            plan = [str(row["detail"]) for row in rows]
        return {
            "engine": self.database_backend,
            "sql": sql,
            "plan": plan,
            "tables": self._plan_tables(plan),
        }

    def _plan_tables(self, plan: list[str]) -> list[str]:
        """Tables a plan names, out of every table this store owns.

        PostgreSQL prints a relation without its schema, so the comparison uses
        the bare physical name on both engines.
        """

        haystack = " ".join(plan)
        candidates = set(self.canonical_table_names().values())
        candidates.update(self.catalog_projection_table_names().values())
        candidates.update(self.link_layer_table_names().values())
        candidates.update(self.linkable_object_table_names().values())
        bare = {name.split(".")[-1] for name in candidates}
        return sorted(name for name in bare if name in haystack)

    def read_object_context_page(
        self,
        *,
        linkable_object_id: int,
        limit: int | None = None,
        cursor: str | None = None,
    ) -> dict[str, Any]:
        """One keyset page of everything an object can see (chapter 9.5).

        The root is always the object, never a signal ID looked up in the
        global projection, so a local series stays unreachable from there.
        """

        resolved_limit = normalize_catalog_limit(limit)
        section = f"object:{int(linkable_object_id)}"
        with self._read_only_transaction():
            generation = self.catalog_generation()
            cursor_key = None
            if cursor is not None:
                cursor_key = decode_catalog_cursor(
                    cursor,
                    self._catalog_cursor_secret,
                    section=section,
                    order="-updated_at",
                    limit=resolved_limit,
                    generation=generation,
                )
            sql, parameters = object_context_page_sql(
                entries_table=self._projection("time_series_catalog_entries"),
                associations_table=link_layer_table_names(self.database_backend)[
                    "time_series_catalog_associations"
                ],
                sets_table=self._canonical("time_series_sets"),
                signals_table=self._canonical("time_series_signals"),
                linkable_object_id=linkable_object_id,
                cursor_key=cursor_key,
                limit=resolved_limit,
            )
            rows = [
                dict(row)
                for row in self.connection.execute(sql, parameters).fetchall()
            ]

        has_more = len(rows) > resolved_limit
        items = rows[:resolved_limit]
        next_cursor = None
        if has_more and items:
            next_cursor = encode_catalog_cursor(
                {
                    "s": section,
                    "o": "-updated_at",
                    "l": resolved_limit,
                    "g": generation,
                    "k": [items[-1]["updated_at"], items[-1]["signal_id"]],
                    "t": int(time.time()),
                },
                self._catalog_cursor_secret,
            )
        return {
            "items": items,
            "page": {
                "limit": resolved_limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
            "meta": {
                "linkable_object_id": int(linkable_object_id),
                "catalog_generation": generation,
            },
        }

    # -- Object-specific series (TS7-010, chapters 7.1 to 7.8) --------------
    #
    # The root of every call below is the normalized object, never a signal id:
    # the register row is resolved and authorized first, and only then does a
    # series of that object resolve (chapters 7.4, 9.9).

    def _object_series_table(self, logical: str) -> str:
        return object_series_table_names(self.database_backend)[logical]

    def authorize_object_series_root(
        self, *, project_id: int, linkable_object_id: int
    ) -> dict[str, Any]:
        """Resolve the object of the route, or refuse without leaking ids."""

        try:
            linkable = self.get_linkable_object(int(linkable_object_id))
        except LinkableObjectError as error:
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="the object is not registered as linkable",
                linkable_object_id=int(linkable_object_id),
            ) from error
        if int(linkable["project_id"]) != int(project_id):
            raise ObjectSeriesError(
                "TS_COMPAT_PROJECT_CONTEXT_MISMATCH",
                detail="the object belongs to another project",
                linkable_object_id=int(linkable_object_id),
                project_id=int(project_id),
            )
        return linkable

    def _resolve_object_series_classification(
        self, document: Mapping[str, Any], *, object_type_key: str
    ) -> dict[str, Any]:
        """One evaluator decides type, unit, class and role (chapter 3.5)."""

        semantic_type_key = str(document.get("semantic_type_key") or "").strip()
        unit_key = str(document.get("unit_key") or "").strip()
        data_class_key = str(document.get("data_class_key") or "").strip()
        role_key = str(document.get("intended_binding_role_key") or "").strip()
        for field, value in (
            ("semantic_type_key", semantic_type_key),
            ("unit_key", unit_key),
            ("data_class_key", data_class_key),
            ("intended_binding_role_key", role_key),
        ):
            if not value:
                raise ObjectSeriesError(
                    "TS_OBJECT_SERIES_DEFINITION_INVALID", field=field, reason="required"
                )
        semantic_type = self.connection.execute(
            """
            SELECT id, semantic_key, canonical_unit_id, default_aggregation, status
            FROM time_series_semantic_types WHERE semantic_key = ?
            """,
            (semantic_type_key,),
        ).fetchone()
        unit = self.connection.execute(
            "SELECT id, unit_key, status FROM measurement_units WHERE unit_key = ?",
            (unit_key,),
        ).fetchone()
        data_class = self.connection.execute(
            """
            SELECT id, data_class_key, status
            FROM time_series_data_classes WHERE data_class_key = ?
            """,
            (data_class_key,),
        ).fetchone()
        role = self.connection.execute(
            "SELECT id, role_key, status FROM time_series_binding_roles WHERE role_key = ?",
            (role_key,),
        ).fetchone()
        for field, row in (
            ("semantic_type_key", semantic_type),
            ("unit_key", unit),
            ("data_class_key", data_class),
            ("intended_binding_role_key", role),
        ):
            if row is None or row["status"] != "active":
                raise ObjectSeriesError(
                    "TS_OBJECT_SERIES_DEFINITION_INVALID",
                    field=field,
                    reason="unknown_or_inactive",
                )
        decision = self.evaluate_time_series_compatibility(
            semantic_type_key=semantic_type_key,
            binding_role_key=role_key,
            object_type_key=object_type_key,
            unit_key=unit_key,
            usage="association",
        )
        if not decision["allowed"]:
            raise ObjectSeriesError(
                "TS_COMPAT_ROLE_NOT_ALLOWED",
                detail="type, unit, role and object are not a useful combination",
                errors=[
                    {
                        "code": entry["code"],
                        "message": entry.get("message", entry["code"]),
                        "location": {"record_index": 0, "json_pointer": "/"},
                    }
                    for entry in decision.get("errors", [])
                ],
            )
        return {
            "semantic_type_id": int(semantic_type["id"]),
            "semantic_type_key": semantic_type["semantic_key"],
            "unit_id": int(unit["id"]),
            "unit_key": unit["unit_key"],
            "data_class_id": int(data_class["id"]),
            "data_class_key": data_class["data_class_key"],
            "binding_role_id": int(role["id"]),
            "binding_role_key": role["role_key"],
            "aggregation": str(
                document.get("aggregation") or semantic_type["default_aggregation"]
            ),
        }

    def compatible_object_series_role_keys(
        self, *, semantic_type_id: int, unit_id: int, object_type_id: int
    ) -> list[str]:
        """Executable compatibility is derived from the matrix, not from the
        declared intention (chapter 7.5)."""

        return [
            row["role_key"]
            for row in self.connection.execute(
                """
                SELECT role.role_key AS role_key
                FROM time_series_role_compatibilities AS rule
                JOIN time_series_binding_roles AS role
                  ON role.id = rule.binding_role_id
                WHERE rule.semantic_type_id = ?
                  AND rule.object_type_id = ?
                  AND rule.status = 'active'
                  AND role.status = 'active'
                  AND role.canonical_unit_id = ?
                ORDER BY role.role_key
                """,
                (int(semantic_type_id), int(object_type_id), int(unit_id)),
            ).fetchall()
        ]

    def create_object_series_definition(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        document: Mapping[str, Any],
        actor: str,
    ) -> dict[str, Any]:
        """Definition only, in one transaction, with no periods and no values.

        The object exists first (AC-ESP-01): this call refuses an unknown or
        foreign object before it looks at the payload, and it never creates the
        object it is called under.
        """

        with self._lock:
            with self._database_transaction():
                linkable = self.authorize_object_series_root(
                    project_id=project_id, linkable_object_id=linkable_object_id
                )
                signal_id = self._insert_object_series_definition(
                    linkable=linkable, document=document, actor=actor
                )
                return self._read_object_series(
                    linkable=linkable, signal_id=signal_id
                )

    def _insert_object_series_definition(
        self,
        *,
        linkable: Mapping[str, Any],
        document: Mapping[str, Any],
        actor: str,
    ) -> int:
        """Write one local identity and its ``building`` revision 1.

        Shared by the ordinary definition call and by the derivation of
        chapter 7.9, which seals the same revision from a copied snapshot.
        """

        if linkable["status"] != "active":
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="the owner object is archived",
                linkable_object_id=int(linkable["id"]),
            )
        object_series_key = normalize_object_series_key(
            document.get("object_series_key")
        )
        metadata = normalize_curated_metadata(document.get("metadata"))
        contract = normalize_temporal_contract(
            document.get("temporal_contract")
        )
        source_expectation = normalize_source_expectation(
            document.get("source_expectation")
        )
        timezone_name = str(document.get("timezone") or "UTC").strip()
        classification = self._resolve_object_series_classification(
            document, object_type_key=linkable["object_type_key"]
        )

        definitions = self._object_series_table("object_series_definitions")
        taken = self.connection.execute(
            f"""
            SELECT time_series_set_id FROM {definitions}
            WHERE owner_linkable_object_id = ? AND object_series_key = ?
            """,
            (int(linkable["id"]), object_series_key),
        ).fetchone()
        if taken is not None:
            # The key stays reserved for the whole life of the object,
            # archived or not (chapter 7.1).
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_KEY_CONFLICT",
                detail="the object already used this local key",
                object_series_key=object_series_key,
            )

        now = utc_now_iso()
        sets_table = self._canonical("time_series_sets")
        signals_table = self._canonical("time_series_signals")
        revisions_table = self._canonical("time_series_set_revisions")
        display_name = str(
            document.get("display_name") or object_series_key
        ).strip()
        description = str(document.get("description") or "").strip()

        # The set names its single signal and the signal names its set.
        # The pointer is written last, inside the same transaction, so
        # the deferred reference of chapter 2.3 is satisfied at commit.
        set_id = self._insert_canonical_row(
            f"""
            INSERT INTO {sets_table} (
                owner_project_id, name, version_number, version_label,
                visibility_scope, series_kind, owner_linkable_object_id,
                object_series_key, object_specific_signal_id, status,
                description, data_kind, timezone, created_at, updated_at,
                created_by, updated_by
            ) VALUES (?, ?, 1, 'object', 'project', 'object_specific',
                      ?, ?, 0, 'draft', ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                int(linkable["project_id"]),
                object_series_key,
                int(linkable["id"]),
                object_series_key,
                description,
                classification["data_class_key"],
                timezone_name,
                now,
                now,
                actor,
                actor,
            ),
        )
        signal_id = self._insert_canonical_row(
            f"""
            INSERT INTO {signals_table} (
                time_series_set_id, series_kind, series_key, display_name,
                description, status, created_at, created_by
            ) VALUES (?, 'object_specific', ?, ?, ?, 'active', ?, ?)
            """,
            (set_id, object_series_key, display_name, description, now, actor),
        )
        self.connection.execute(
            f"UPDATE {sets_table} SET object_specific_signal_id = ? WHERE id = ?",
            (signal_id, set_id),
        )

        # Revision 1 opens ``building``: it records the contract but no
        # period and no value, and it is not selectable (chapter 7.2).
        revision_id = self._insert_canonical_row(
            f"""
            INSERT INTO {revisions_table} (
                time_series_set_id, revision_number, data_class_id,
                timezone, timestamp_convention, state, change_summary,
                metadata_json, created_at, created_by
            ) VALUES (?, 1, ?, ?, ?, 'building', 'definition_created',
                      ?, ?, ?)
            """,
            (
                set_id,
                classification["data_class_id"],
                timezone_name,
                contract["timestamp_convention"],
                json.dumps(
                    {"temporal_contract": contract}, sort_keys=True
                ),
                now,
                actor,
            ),
        )
        self.connection.execute(
            f"""
            INSERT INTO {self._canonical('time_series_revision_signals')} (
                set_revision_id, signal_id, time_series_set_id,
                semantic_type_id, unit_id, data_class_id, signal_role,
                aggregation, ordinal, metadata_json
            ) VALUES (?, ?, ?, ?, ?, ?, 'input', ?, 0, '{{}}')
            """,
            (
                revision_id,
                signal_id,
                set_id,
                classification["semantic_type_id"],
                classification["unit_id"],
                classification["data_class_id"],
                classification["aggregation"],
            ),
        )
        self.connection.execute(
            f"""
            INSERT INTO {definitions} (
                time_series_set_id, signal_id, owner_linkable_object_id,
                owner_project_id, object_series_key,
                intended_binding_role_id, semantic_type_id, unit_id,
                data_class_id, aggregation, timezone, regularity,
                nominal_resolution_seconds, timestamp_convention,
                source_expectation_json, metadata_json, resource_version,
                created_at, created_by, updated_at, updated_by
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1,
                      ?, ?, ?, ?)
            """,
            (
                set_id,
                signal_id,
                int(linkable["id"]),
                int(linkable["project_id"]),
                object_series_key,
                classification["binding_role_id"],
                classification["semantic_type_id"],
                classification["unit_id"],
                classification["data_class_id"],
                classification["aggregation"],
                timezone_name,
                contract["regularity"],
                contract["nominal_resolution_seconds"],
                contract["timestamp_convention"],
                json.dumps(source_expectation, sort_keys=True),
                json.dumps(metadata, sort_keys=True),
                now,
                actor,
                now,
                actor,
            ),
        )
        return int(signal_id)

    def patch_object_series(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        signal_id: int,
        document: Mapping[str, Any],
        if_match: str,
        actor: str,
    ) -> dict[str, Any]:
        """Rename, redescribe or recurate - nothing else (chapter 7.5).

        Owner, local key, semantic type, unit and ``series_kind`` are not
        editable here and never travel in this payload, so no patch can
        reassign the owner (AC-ESP-05).
        """

        with self._lock:
            with self._database_transaction():
                linkable = self.authorize_object_series_root(
                    project_id=project_id, linkable_object_id=linkable_object_id
                )
                row = self._object_series_row(
                    linkable_object_id=int(linkable["id"]), signal_id=int(signal_id)
                )
                if row is None:
                    raise ObjectSeriesError(
                        "TS_OBJECT_SERIES_NOT_FOUND",
                        detail="no local series with that id belongs to this object",
                        signal_id=int(signal_id),
                    )
                if (
                    linkable["status"] != "active"
                    or row["set_status"] == "archived"
                    or row["signal_status"] == "archived"
                ):
                    raise ObjectSeriesError(
                        "TS_OBJECT_SERIES_NOT_FOUND",
                        detail="the owner or the local series is archived",
                    )
                expected = object_series_etag(
                    signal_id=int(row["signal_id"]),
                    resource_version=int(row["resource_version"]),
                )
                if str(if_match or "").strip() != expected:
                    raise ObjectSeriesError(
                        "TS_INGEST_PRECONDITION_CHANGED",
                        detail="the series changed since the ETag was read",
                        expected=expected,
                    )
                display_name = str(
                    document.get("display_name", row["display_name"]) or ""
                ).strip()
                if not display_name:
                    raise ObjectSeriesError(
                        "TS_OBJECT_SERIES_DEFINITION_INVALID",
                        field="display_name",
                        reason="required",
                    )
                description = str(
                    document.get("description", row["description"]) or ""
                ).strip()
                metadata = (
                    normalize_curated_metadata(document["metadata"])
                    if "metadata" in document
                    else json.loads(row["metadata_json"] or "{}")
                )
                now = utc_now_iso()
                self.connection.execute(
                    f"""
                    UPDATE {self._canonical('time_series_signals')}
                    SET display_name = ?, description = ?
                    WHERE id = ?
                    """,
                    (display_name, description, int(row["signal_id"])),
                )
                self.connection.execute(
                    f"""
                    UPDATE {self._object_series_table('object_series_definitions')}
                    SET metadata_json = ?, resource_version = resource_version + 1,
                        updated_at = ?, updated_by = ?
                    WHERE time_series_set_id = ?
                    """,
                    (
                        json.dumps(metadata, sort_keys=True),
                        now,
                        actor,
                        int(row["time_series_set_id"]),
                    ),
                )
                self.connection.execute(
                    f"""
                    UPDATE {self._canonical('time_series_sets')}
                    SET description = ?, updated_at = ?, updated_by = ?
                    WHERE id = ?
                    """,
                    (description, now, actor, int(row["time_series_set_id"])),
                )
                return self._read_object_series(
                    linkable=linkable, signal_id=int(row["signal_id"])
                )

    def read_object_series(
        self, *, project_id: int, linkable_object_id: int, signal_id: int
    ) -> dict[str, Any]:
        linkable = self.authorize_object_series_root(
            project_id=project_id, linkable_object_id=linkable_object_id
        )
        return self._read_object_series(linkable=linkable, signal_id=int(signal_id))

    def archive_object_series(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        signal_id: int,
        if_match: str,
        actor: str,
        reason_code: str,
        reason_text: str,
    ) -> dict[str, Any]:
        """Retire one local identity while leaving all immutable history intact."""

        with self._lock:
            with self._database_transaction():
                linkable = self.authorize_object_series_root(
                    project_id=project_id, linkable_object_id=linkable_object_id
                )
                row = self._object_series_row(
                    linkable_object_id=int(linkable["id"]), signal_id=int(signal_id)
                )
                if row is None:
                    raise ObjectSeriesError(
                        "TS_OBJECT_SERIES_NOT_FOUND",
                        detail="no local series with that id belongs to this object",
                        signal_id=int(signal_id),
                    )
                expected = object_series_etag(
                    signal_id=int(row["signal_id"]),
                    resource_version=int(row["resource_version"]),
                )
                if str(if_match or "").strip() != expected:
                    raise ObjectSeriesError(
                        "TS_INGEST_PRECONDITION_CHANGED",
                        detail="the series changed since the ETag was read",
                        expected=expected,
                    )
                if linkable["status"] != "active":
                    raise ObjectSeriesError(
                        "TS_OBJECT_SERIES_NOT_FOUND",
                        detail="the owner object is archived",
                    )
                if row["set_status"] == "archived":
                    return self._project_object_series(row, linkable=linkable)

                now = utc_now_iso()
                self.connection.execute(
                    f"""
                    UPDATE {self._canonical('time_series_sets')}
                    SET status = 'archived', archived_at = ?, archived_by = ?,
                        archived_reason_code = ?, archived_reason_text = ?,
                        updated_at = ?, updated_by = ?
                    WHERE id = ?
                    """,
                    (
                        now,
                        actor,
                        reason_code,
                        reason_text,
                        now,
                        actor,
                        int(row["time_series_set_id"]),
                    ),
                )
                self.connection.execute(
                    f"""
                    UPDATE {self._canonical('time_series_signals')}
                    SET status = 'archived', archived_at = ?, archived_by = ?
                    WHERE id = ?
                    """,
                    (now, actor, int(row["signal_id"])),
                )
                self.connection.execute(
                    f"""
                    UPDATE {self._object_series_table('object_series_definitions')}
                    SET resource_version = resource_version + 1,
                        updated_at = ?, updated_by = ?
                    WHERE time_series_set_id = ?
                    """,
                    (now, actor, int(row["time_series_set_id"])),
                )
                # Local list membership/capabilities share the catalog cursor
                # generation, so an archival invalidates older pages once.
                self._raise_catalog_generation(now=now)
                return self._read_object_series(
                    linkable=linkable, signal_id=int(row["signal_id"])
                )

    def _object_series_row(self, *, linkable_object_id: int, signal_id: int):
        definitions = self._object_series_table("object_series_definitions")
        return self.connection.execute(
            f"""
            SELECT definition.*, the_set.status AS set_status,
                   the_set.current_revision_id AS current_revision_id,
                   the_set.updated_at AS set_updated_at,
                   signal.display_name AS display_name,
                   signal.description AS description,
                   signal.status AS signal_status,
                   semantic_type.semantic_key AS semantic_type_key,
                   unit.unit_key AS unit_key,
                   data_class.data_class_key AS data_class_key,
                   role.role_key AS intended_binding_role_key,
                   object_type.id AS object_type_id
            FROM {definitions} AS definition
            JOIN {self._canonical('time_series_sets')} AS the_set
              ON the_set.id = definition.time_series_set_id
            JOIN {self._canonical('time_series_signals')} AS signal
              ON signal.id = definition.signal_id
            JOIN {self._linkable('linkable_objects')} AS registered
              ON registered.id = definition.owner_linkable_object_id
            JOIN linkable_object_types AS object_type
              ON object_type.id = registered.object_type_id
            JOIN time_series_semantic_types AS semantic_type
              ON semantic_type.id = definition.semantic_type_id
            JOIN measurement_units AS unit ON unit.id = definition.unit_id
            JOIN time_series_data_classes AS data_class
              ON data_class.id = definition.data_class_id
            JOIN time_series_binding_roles AS role
              ON role.id = definition.intended_binding_role_id
            WHERE definition.signal_id = ?
              AND definition.owner_linkable_object_id = ?
            """,
            (int(signal_id), int(linkable_object_id)),
        ).fetchone()

    def _read_object_series(
        self, *, linkable: Mapping[str, Any], signal_id: int
    ) -> dict[str, Any]:
        row = self._object_series_row(
            linkable_object_id=int(linkable["id"]), signal_id=int(signal_id)
        )
        if row is None:
            # A signal of another object or of the catalog is not a resource
            # under this root, even for an internal user (chapter 7.10).
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="no local series with that id belongs to this object",
                signal_id=int(signal_id),
            )
        return self._project_object_series(row, linkable=linkable)

    def _project_object_series(
        self, row: Mapping[str, Any], *, linkable: Mapping[str, Any]
    ) -> dict[str, Any]:
        revisions_table = self._canonical("time_series_set_revisions")
        current = None
        if row["current_revision_id"] is not None:
            current = self.connection.execute(
                f"""
                SELECT id, revision_number, content_hash, created_at,
                       validation_payload_json
                FROM {revisions_table} WHERE id = ?
                """,
                (int(row["current_revision_id"]),),
            ).fetchone()
        building = self.connection.execute(
            f"""
            SELECT id, revision_number FROM {revisions_table}
            WHERE time_series_set_id = ? AND state = 'building'
            ORDER BY revision_number DESC LIMIT 1
            """,
            (int(row["time_series_set_id"]),),
        ).fetchone()

        compatible_roles = self.compatible_object_series_role_keys(
            semantic_type_id=int(row["semantic_type_id"]),
            unit_id=int(row["unit_id"]),
            object_type_id=int(row["object_type_id"]),
        )
        if linkable["status"] != "active":
            availability = "owner_archived"
        elif row["set_status"] == "archived" or row["signal_status"] == "archived":
            availability = "archived"
        elif current is None:
            availability = "awaiting_data"
        else:
            availability = "ready"
        binding_ready = availability == "ready" and bool(compatible_roles)
        coverage = (
            json.loads(current["validation_payload_json"] or "{}")
            if current is not None
            else {}
        )
        return {
            "source_kind": "object_specific",
            "signal_id": int(row["signal_id"]),
            "set_id": int(row["time_series_set_id"]),
            "owner": {
                "project_id": int(row["owner_project_id"]),
                "linkable_object_id": int(row["owner_linkable_object_id"]),
                "object_kind": linkable["object_kind"],
                "object_type_key": linkable["object_type_key"],
            },
            "object_series_key": row["object_series_key"],
            "display_name": row["display_name"],
            "description": row["description"],
            "classification": {
                "semantic_type_key": row["semantic_type_key"],
                "unit_key": row["unit_key"],
                "data_class_key": row["data_class_key"],
                "aggregation": row["aggregation"],
                "intended_binding_role_key": row["intended_binding_role_key"],
            },
            "temporal_contract": {
                "regularity": row["regularity"],
                "nominal_resolution_seconds": row["nominal_resolution_seconds"],
                "timestamp_convention": row["timestamp_convention"],
                "timezone": row["timezone"],
            },
            "source_expectation": json.loads(row["source_expectation_json"] or "{}"),
            "metadata": json.loads(row["metadata_json"] or "{}"),
            "set_status": row["set_status"],
            "availability": availability,
            "current_revision": (
                None
                if current is None
                else {
                    "revision_id": int(current["id"]),
                    "revision_number": int(current["revision_number"]),
                    "content_hash": current["content_hash"],
                    "created_at": current["created_at"],
                    "coverage_start": coverage.get("coverage_start"),
                    "coverage_end": coverage.get("coverage_end"),
                    "period_count": coverage.get("period_count"),
                    "value_count": coverage.get("value_count"),
                }
            ),
            "building_revision": (
                None
                if building is None
                else {
                    "revision_id": int(building["id"]),
                    "revision_number": int(building["revision_number"]),
                }
            ),
            "binding_ready": binding_ready,
            "compatible_role_keys": compatible_roles,
            "resource_version": int(row["resource_version"]),
        }

    def read_object_time_series_context(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        limit: int | None = None,
        cursor: str | None = None,
        filters: Mapping[str, Any] | None = None,
        actor_class: str = "internal",
    ) -> dict[str, Any]:
        """The contextual list of one object: associations and local series.

        The union is a read model and nothing else (chapter 7.4): every row
        carries the mandatory ``source_kind`` discriminator, no row carries
        values or an unbounded consumer list, and every mutation lives on its
        own typed subresource.
        """

        linkable = self.authorize_object_series_root(
            project_id=project_id, linkable_object_id=linkable_object_id
        )
        resolved_limit = normalize_catalog_limit(limit)
        resolved_filters = dict(filters or {})
        section = f"object-context:{int(linkable['id'])}"
        filters_digest = input_filters_hash(resolved_filters)
        tables = {
            "entries_table": self._projection("time_series_catalog_entries"),
            "associations_table": self.link_layer_table_names()[
                "time_series_catalog_associations"
            ],
            "sets_table": self._canonical("time_series_sets"),
            "signals_table": self._canonical("time_series_signals"),
            "definitions_table": self._object_series_table(
                "object_series_definitions"
            ),
        }
        with self._read_only_transaction():
            generation = self.catalog_generation()
            cursor_key = None
            if cursor is not None:
                cursor_key = decode_catalog_cursor(
                    cursor,
                    self._catalog_cursor_secret,
                    section=section,
                    order="-updated_at",
                    limit=resolved_limit,
                    generation=generation,
                    actor_class=actor_class,
                    filters_hash=filters_digest,
                )
            sql, parameters = object_context_page_sql(
                **tables,
                linkable_object_id=int(linkable["id"]),
                cursor_key=cursor_key,
                limit=resolved_limit,
                filters=resolved_filters,
                object_type_id=int(linkable["object_type_id"]),
            )
            rows = [
                dict(row) for row in self.connection.execute(sql, parameters).fetchall()
            ]
            total_sql, total_parameters = object_context_page_sql(
                **tables,
                linkable_object_id=int(linkable["id"]),
                cursor_key=None,
                limit=CATALOG_PAGE_MAX_LIMIT,
                filters=resolved_filters,
                object_type_id=int(linkable["object_type_id"]),
            )
            total_count = len(
                self.connection.execute(total_sql, total_parameters).fetchall()
            )

        has_more = len(rows) > resolved_limit
        visible = rows[:resolved_limit]
        items = [
            self._object_context_item(row, linkable=linkable) for row in visible
        ]
        next_cursor = None
        if has_more and visible:
            next_cursor = encode_catalog_cursor(
                {
                    "s": section,
                    "o": "-updated_at",
                    "l": resolved_limit,
                    "g": generation,
                    "k": [visible[-1]["updated_at"], visible[-1]["signal_id"]],
                    "t": int(time.time()),
                    "a": actor_class,
                    "f": filters_digest,
                },
                self._catalog_cursor_secret,
            )
        return {
            "items": items,
            "page": {
                "limit": resolved_limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
            "summary": {"total_count": total_count},
            "meta": {
                "section": "object_context",
                "project_id": int(linkable["project_id"]),
                "linkable_object_id": int(linkable["id"]),
                "object": {
                    "id": int(linkable["id"]),
                    "display_name": linkable["display_name"],
                    "object_kind": linkable["object_kind"],
                    "object_type_key": linkable["object_type_key"],
                },
                "catalog_generation": generation,
            },
        }

    def _object_context_binding_summary(
        self, *, signal_id: int, linkable_object_id: int
    ) -> dict[str, Any]:
        """Project a bounded set of executable uses for one contextual row."""

        bindings = self.link_layer_table_names()["case_time_series_bindings"]
        revisions = self._canonical("time_series_set_revisions")
        rows = self.connection.execute(
            f"""
            SELECT binding.id AS binding_id,
                   variant.id AS variant_id,
                   variant.display_name AS variant_name,
                   scenario.id AS scenario_id,
                   scenario.name AS scenario_name,
                   role.role_key AS binding_role_key,
                   revision.revision_number AS revision_number
            FROM {bindings} AS binding
            JOIN case_input_variants AS variant
              ON variant.id = binding.case_input_variant_id
            JOIN optimization_cases AS optimization_case
              ON optimization_case.id = variant.case_id
            JOIN scenarios AS scenario
              ON scenario.id = optimization_case.scenario_id
            JOIN time_series_binding_roles AS role
              ON role.id = binding.binding_role_id
            JOIN {revisions} AS revision
              ON revision.id = binding.set_revision_id
            WHERE binding.signal_id = ?
              AND binding.linkable_object_id = ?
              AND binding.status = 'active'
            ORDER BY binding.id
            LIMIT 21
            """,
            (int(signal_id), int(linkable_object_id)),
        ).fetchall()
        visible = rows[:20]
        items = []
        for row in visible:
            effective = self.read_case_binding(
                scenario_id=int(row["scenario_id"]),
                variant_id=int(row["variant_id"]),
                binding_id=int(row["binding_id"]),
            )
            items.append(
                {
                    "binding_id": int(row["binding_id"]),
                    "scenario_id": int(row["scenario_id"]),
                    "scenario_name": row["scenario_name"],
                    "variant_id": int(row["variant_id"]),
                    "variant_name": row["variant_name"],
                    "binding_role_key": row["binding_role_key"],
                    "revision_id": int(effective["set_revision_id"]),
                    "revision_number": int(row["revision_number"]),
                    "content_hash": effective["bound_content_hash"],
                    "state": effective["state"],
                    "execution_blocked": effective["state"]
                    not in {"valid_current", "valid_pinned"},
                }
            )
        total = self.connection.execute(
            f"""
            SELECT COUNT(*) AS total
            FROM {bindings}
            WHERE signal_id = ? AND linkable_object_id = ? AND status = 'active'
            """,
            (int(signal_id), int(linkable_object_id)),
        ).fetchone()
        total_count = int(total["total"])
        return {
            "total_count": total_count,
            "truncated": total_count > len(items),
            "items": items,
        }

    def _object_context_item(
        self, row: Mapping[str, Any], *, linkable: Mapping[str, Any]
    ) -> dict[str, Any]:
        project_id = int(linkable["project_id"])
        object_id = int(linkable["id"])
        signal_id = int(row["signal_id"])
        if row["source"] == "object_specific":
            series = self._read_object_series(linkable=linkable, signal_id=signal_id)
            binding_summary = self._object_context_binding_summary(
                signal_id=signal_id, linkable_object_id=object_id
            )
            return {
                "source_kind": "object_specific",
                "signal_id": signal_id,
                "set_id": series["set_id"],
                "series_key": series["object_series_key"],
                "display_name": series["display_name"],
                "semantic_type_key": series["classification"]["semantic_type_key"],
                "unit_key": series["classification"]["unit_key"],
                "data_class_key": series["classification"]["data_class_key"],
                "availability": series["availability"],
                "current_revision": series["current_revision"],
                "temporal_contract": series["temporal_contract"],
                "compatible_role_keys": series["compatible_role_keys"],
                "need": {
                    "binding_role_key": series["classification"][
                        "intended_binding_role_key"
                    ],
                    "source": "object_specific_intention",
                },
                # A local series has no catalog association behind it; its
                # executable link goes directly back to this owner.
                "association": None,
                "binding_state": (
                    "bound" if binding_summary["total_count"] else "unbound"
                ),
                "binding_summary": binding_summary,
                "capabilities": {
                    "edit_definition": series["availability"]
                    not in {"archived", "owner_archived"},
                    "ingest_points": series["availability"]
                    in {"awaiting_data", "ready"},
                    "preview": series["current_revision"] is not None,
                    "bind": series["binding_ready"],
                    "archive": series["availability"]
                    not in {"archived", "owner_archived"},
                },
                "links": {
                    "detail": (
                        f"/api/projects/{project_id}/linkable-objects/{object_id}"
                        f"/time-series/object-series/{signal_id}"
                    )
                },
                "updated_at": row["updated_at"],
            }

        entry = self.connection.execute(
            f"""
            SELECT * FROM {self._projection('time_series_catalog_entries')}
            WHERE signal_id = ?
            """,
            (signal_id,),
        ).fetchone()
        association = self.connection.execute(
            f"""
            SELECT association.id AS association_id, role.role_key AS role_key,
                   association.status AS status
            FROM {self.link_layer_table_names()['time_series_catalog_associations']}
                 AS association
            JOIN time_series_binding_roles AS role
              ON role.id = association.binding_role_id
            WHERE association.id = ?
            """,
            (int(row["association_id"]),),
        ).fetchone()
        binding_summary = self._object_context_binding_summary(
            signal_id=signal_id, linkable_object_id=object_id
        )
        association_detail = (
            None
            if association is None
            else self.read_catalog_association(int(association["association_id"]))
        )
        return {
            "source_kind": "catalog",
            "signal_id": signal_id,
            "set_id": int(entry["time_series_set_id"]),
            "series_key": entry["series_key"],
            "display_name": entry["display_name"],
            "semantic_type_key": entry["semantic_type_key"],
            "unit_key": entry["unit_key"],
            "data_class_key": entry["data_class_key"],
            "availability": (
                "archived"
                if entry["set_status"] == "archived"
                or entry["signal_status"] == "archived"
                else "ready"
            ),
            "current_revision": {
                "revision_id": int(entry["current_revision_id"]),
                "revision_number": int(entry["revision_number"]),
                "coverage_start": utc_presentation(entry["coverage_start"]),
                "coverage_end": utc_presentation(entry["coverage_end"]),
                "period_count": int(entry["period_count"]),
                "value_count": int(entry["value_count"]),
            },
            "temporal_contract": {
                "regularity": entry["regularity"],
                "nominal_resolution_seconds": entry["nominal_resolution_seconds"],
                "timestamp_convention": "period_start",
                "timezone": entry["source_timezone"],
            },
            "compatible_role_keys": self.compatible_object_series_role_keys(
                semantic_type_id=int(entry["semantic_type_id"]),
                unit_id=int(entry["unit_id"]),
                object_type_id=int(linkable["object_type_id"]),
            ),
            "need": {
                "binding_role_key": association["role_key"],
                "source": "catalog_association",
            },
            "association": (
                None
                if association is None
                else {
                    "association_id": int(association["association_id"]),
                    "binding_role_key": association["role_key"],
                    "status": association["status"],
                    "state": association_detail["state"],
                }
            ),
            "binding_state": (
                "bound" if binding_summary["total_count"] else "unbound"
            ),
            "binding_summary": binding_summary,
            "capabilities": {
                "edit_definition": False,
                "ingest_points": False,
                "preview": True,
                "bind": True,
            },
            "links": {
                "detail": f"/api/time-series/catalog/inputs/{signal_id}",
                "association": (
                    None
                    if association is None
                    else (
                        f"/api/projects/{project_id}/linkable-objects/{object_id}"
                        f"/time-series/catalog-associations/"
                        f"{int(association['association_id'])}"
                    )
                ),
            },
            "updated_at": row["updated_at"],
        }

    def read_object_series_revisions(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        signal_id: int,
        limit: int | None = None,
        cursor: str | None = None,
        actor_class: str = "internal",
    ) -> dict[str, Any]:
        """Paginated revision metadata of one local identity (chapter 7.4)."""

        linkable = self.authorize_object_series_root(
            project_id=project_id, linkable_object_id=linkable_object_id
        )
        row = self._object_series_row(
            linkable_object_id=int(linkable["id"]), signal_id=int(signal_id)
        )
        if row is None:
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="no local series with that id belongs to this object",
                signal_id=int(signal_id),
            )
        resolved_limit = normalize_catalog_limit(limit)
        section = f"object-series:{int(signal_id)}:revisions"
        filters_digest = input_filters_hash({"signal_id": int(signal_id)})
        with self._read_only_transaction():
            generation = self.catalog_generation()
            keyset = ""
            parameters: list[Any] = [int(signal_id)]
            if cursor is not None:
                cursor_key = decode_catalog_cursor(
                    cursor,
                    self._catalog_cursor_secret,
                    section=section,
                    order="-revision_number",
                    limit=resolved_limit,
                    generation=generation,
                    actor_class=actor_class,
                    filters_hash=filters_digest,
                )
                if len(cursor_key) != 2:
                    raise CatalogQueryError(
                        "TS_QUERY_CURSOR_MISMATCH", reason="key_arity"
                    )
                keyset = (
                    "AND (revision.revision_number < ? OR "
                    "(revision.revision_number = ? AND revision.id > ?))"
                )
                parameters.extend((cursor_key[0], cursor_key[0], cursor_key[1]))
            parameters.append(resolved_limit + 1)
            rows = self.connection.execute(
                f"""
                SELECT revision.id, revision.revision_number, revision.state,
                       revision.content_hash, revision.created_at,
                       revision.created_by, revision.change_summary,
                       revision.validation_payload_json,
                       source.kind AS source_kind
                FROM {self._canonical('time_series_revision_signals')} AS revision_signal
                JOIN {self._canonical('time_series_set_revisions')} AS revision
                  ON revision.id = revision_signal.set_revision_id
                LEFT JOIN {self._canonical('time_series_sources')} AS source
                  ON source.id = revision.time_series_source_id
                WHERE revision_signal.signal_id = ?
                  {keyset}
                ORDER BY revision.revision_number DESC, revision.id ASC
                LIMIT ?
                """,
                tuple(parameters),
            ).fetchall()
            total_count = int(
                self.connection.execute(
                    f"""
                    SELECT COUNT(*) AS total
                    FROM {self._canonical('time_series_revision_signals')}
                    WHERE signal_id = ?
                    """,
                    (int(signal_id),),
                ).fetchone()["total"]
            )
        has_more = len(rows) > resolved_limit
        visible = rows[:resolved_limit]
        items = []
        for entry in visible:
            payload = json.loads(entry["validation_payload_json"] or "{}")
            items.append(
                {
                    "id": int(entry["id"]),
                    "number": int(entry["revision_number"]),
                    "state": entry["state"],
                    "content_hash": (
                        None
                        if entry["content_hash"] is None
                        else f"sha256:{entry['content_hash']}"
                    ),
                    "created_at": entry["created_at"],
                    "created_by": entry["created_by"],
                    "change_summary": entry["change_summary"],
                    "source_kind": entry["source_kind"] or "api",
                    "coverage_start": utc_presentation(payload.get("coverage_start")),
                    "coverage_end": utc_presentation(payload.get("coverage_end")),
                    "period_count": payload.get("period_count"),
                    "value_count": payload.get("value_count"),
                }
            )
        next_cursor = None
        if has_more and visible:
            next_cursor = encode_catalog_cursor(
                {
                    "s": section,
                    "o": "-revision_number",
                    "l": resolved_limit,
                    "g": generation,
                    "k": [visible[-1]["revision_number"], visible[-1]["id"]],
                    "t": int(time.time()),
                    "a": actor_class,
                    "f": filters_digest,
                },
                self._catalog_cursor_secret,
            )
        return {
            "items": items,
            "page": {
                "limit": resolved_limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
            "summary": {"total_count": total_count},
            "meta": {
                "section": "object_series_revisions",
                "signal_id": int(signal_id),
                "catalog_generation": generation,
            },
        }

    def read_object_series_preview(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        signal_id: int,
        revision_id: int,
        range_from: str,
        range_to: str,
        sampling: str,
        max_points: int,
    ) -> dict[str, Any]:
        """Bounded values of one exact revision; never an unbounded export.

        The preview keeps the contract of the global catalog (chapter 7.10):
        an explicit revision, an explicit range, and a hard point ceiling.
        """

        linkable = self.authorize_object_series_root(
            project_id=project_id, linkable_object_id=linkable_object_id
        )
        row = self._object_series_row(
            linkable_object_id=int(linkable["id"]), signal_id=int(signal_id)
        )
        if row is None:
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="no local series with that id belongs to this object",
                signal_id=int(signal_id),
            )
        revision = self.connection.execute(
            f"""
            SELECT revision.id, revision.state, revision.content_hash,
                   unit.unit_key, unit.symbol AS unit_symbol
            FROM {self._canonical('time_series_set_revisions')} AS revision
            JOIN {self._canonical('time_series_revision_signals')} AS revision_signal
              ON revision_signal.set_revision_id = revision.id
             AND revision_signal.signal_id = ?
            JOIN measurement_units AS unit ON unit.id = revision_signal.unit_id
            WHERE revision.id = ? AND revision.time_series_set_id = ?
            """,
            (int(signal_id), int(revision_id), int(row["time_series_set_id"])),
        ).fetchone()
        if revision is None:
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="that revision does not belong to this local series",
                revision_id=int(revision_id),
            )
        if revision["state"] != "sealed":
            raise ObjectSeriesError(
                "TS_INGEST_SESSION_UNAVAILABLE",
                detail="the revision is not sealed",
                revision_id=int(revision_id),
            )
        rows = [
            dict(entry)
            for entry in self.connection.execute(
                f"""
                SELECT period.timestamp_start, period.timestamp_end,
                       value.value_numeric, value.quality_flag
                FROM {self._canonical('time_series_values')} AS value
                JOIN {self._canonical('time_series_periods')} AS period
                  ON period.id = value.time_series_period_id
                 AND period.set_revision_id = value.set_revision_id
                WHERE value.set_revision_id = ? AND value.signal_id = ?
                  AND period.timestamp_start >= ? AND period.timestamp_end <= ?
                ORDER BY period.timestamp_start, period.id
                """,
                (int(revision_id), int(signal_id), range_from, range_to),
            ).fetchall()
        ]
        if sampling == "none" and len(rows) > max_points:
            raise ObjectSeriesError(
                "TS_QUERY_INVALID",
                detail="the range holds more points than max_points",
                source_point_count=len(rows),
                max_points=max_points,
            )
        sampled = sample_preview_rows(rows, strategy=sampling, limit=max_points)
        return {
            "signal_id": int(signal_id),
            "source_kind": "object_specific",
            "revision": {
                "id": int(revision_id),
                "content_hash": f"sha256:{revision['content_hash']}",
            },
            "requested_range": {"from": range_from, "to": range_to},
            "effective_range": (
                {
                    "from": utc_presentation(rows[0]["timestamp_start"]),
                    "to": utc_presentation(rows[-1]["timestamp_end"]),
                }
                if rows
                else None
            ),
            "sampling": sampling,
            "max_points": max_points,
            "source_point_count": len(rows),
            "returned_point_count": len(sampled),
            "unit": {
                "key": revision["unit_key"],
                "symbol": revision["unit_symbol"],
            },
            "points": [
                {
                    "timestamp_start": utc_presentation(entry["timestamp_start"]),
                    "timestamp_end": utc_presentation(entry["timestamp_end"]),
                    "value": float(entry["value_numeric"]),
                    "quality_flag": entry["quality_flag"],
                }
                for entry in sampled
            ],
        }

    # -- Points ingestion against an object target (chapters 7.6 to 7.8) ----

    def _object_series_binding_impact(self, *, signal_id: int, set_id: int):
        """What the current bindings of this identity will feel (chapter 7.10)."""

        bindings = self.link_layer_table_names()["case_time_series_bindings"]
        current_revision = self.connection.execute(
            f"""
            SELECT current_revision_id FROM {self._canonical('time_series_sets')}
            WHERE id = ?
            """,
            (int(set_id),),
        ).fetchone()
        pointer = (
            None
            if current_revision is None
            else current_revision["current_revision_id"]
        )
        rows = self.connection.execute(
            f"""
            SELECT set_revision_id FROM {bindings}
            WHERE signal_id = ? AND status = 'active'
            """,
            (int(signal_id),),
        ).fetchall()
        on_current = sum(
            1 for row in rows if pointer is not None and row["set_revision_id"] == pointer
        )
        return {
            "bindings_current": on_current,
            "bindings_pinned": len(rows) - on_current,
            # Publishing never moves a binding in silence: every active one
            # turns stale until it is resolved explicitly.
            "will_become_stale": len(rows),
        }

    def _object_series_ingestion_contract(
        self, row: Mapping[str, Any], document: Mapping[str, Any]
    ) -> dict[str, Any]:
        declared = document.get("revision_contract") or {}
        if not isinstance(declared, Mapping):
            raise ObjectSeriesError(
                "TS_INGEST_VALIDATION_FAILED",
                detail="revision_contract must be an object",
            )
        data_class_key = str(
            declared.get("data_class_key") or row["data_class_key"]
        ).strip()
        data_class = self.connection.execute(
            """
            SELECT id, data_class_key, status FROM time_series_data_classes
            WHERE data_class_key = ?
            """,
            (data_class_key,),
        ).fetchone()
        if data_class is None or data_class["status"] != "active":
            raise ObjectSeriesError(
                "TS_INGEST_VALIDATION_FAILED",
                detail="the declared data class is unknown",
                errors=[
                    {
                        "code": "TS_INGEST_TEMPORAL_CONTRACT_INVALID",
                        "message": "unknown data_class_key",
                        "location": {
                            "record_index": 0,
                            "json_pointer": "/revision_contract/data_class_key",
                        },
                    }
                ],
            )
        regularity = str(declared.get("regularity") or row["regularity"]).strip()
        if regularity not in {"regular", "irregular"}:
            raise ObjectSeriesError(
                "TS_INGEST_VALIDATION_FAILED",
                detail="the declared regularity is unknown",
            )
        resolution = declared.get(
            "nominal_resolution_seconds", row["nominal_resolution_seconds"]
        )
        return {
            "data_class_id": int(data_class["id"]),
            "data_class_key": data_class["data_class_key"],
            "timezone": str(declared.get("timezone") or row["timezone"]).strip(),
            "timestamp_convention": row["timestamp_convention"],
            "regularity": regularity,
            "nominal_resolution_seconds": (
                None if resolution is None else float(resolution)
            ),
            # A change of semantic type or unit never enters disguised as a
            # load: they are not part of this payload at all (chapter 7.5).
            "changed": (
                data_class["data_class_key"] != row["data_class_key"]
                or str(declared.get("timezone") or row["timezone"]).strip()
                != row["timezone"]
                or regularity != row["regularity"]
            ),
        }

    def _object_series_snapshot(self, revision_id: int) -> dict[str, Any]:
        """Read one sealed revision back as a normalized snapshot."""

        periods = [
            {
                "period_index": int(row["period_index"]),
                "timestamp_start": row["timestamp_start"],
                "timestamp_end": row["timestamp_end"],
                "duration_hours": float(row["duration_hours"]),
                "source_row_number": None,
            }
            for row in self.connection.execute(
                f"""
                SELECT period_index, timestamp_start, timestamp_end, duration_hours
                FROM {self._canonical('time_series_periods')}
                WHERE set_revision_id = ? ORDER BY period_index
                """,
                (int(revision_id),),
            ).fetchall()
        ]
        values = [
            {
                "series_key": row["series_key"],
                "period_index": int(row["period_index"]),
                "value": float(row["value_numeric"]),
                "quality_flag": row["quality_flag"],
                "source_row_number": None,
            }
            for row in self.connection.execute(
                f"""
                SELECT signal.series_key AS series_key,
                       period.period_index AS period_index,
                       value.value_numeric AS value_numeric,
                       value.quality_flag AS quality_flag
                FROM {self._canonical('time_series_values')} AS value
                JOIN {self._canonical('time_series_periods')} AS period
                  ON period.id = value.time_series_period_id
                JOIN {self._canonical('time_series_signals')} AS signal
                  ON signal.id = value.signal_id
                WHERE value.set_revision_id = ?
                ORDER BY period.period_index
                """,
                (int(revision_id),),
            ).fetchall()
        ]
        return {"periods": periods, "values": values}

    def _merge_object_series_file_tail(
        self,
        *,
        mode: str,
        base_revision_id: int | None,
        contract: Mapping[str, Any],
        periods: list[dict[str, Any]],
        values: list[dict[str, Any]],
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        if mode != "append_tail" or base_revision_id is None:
            return periods, values
        base = self._object_series_snapshot(int(base_revision_id))
        base_periods = base["periods"]
        coverage_end = base_periods[-1]["timestamp_end"] if base_periods else None
        if periods and coverage_end is not None:
            if periods[0]["timestamp_start"] < coverage_end:
                raise ObjectSeriesError(
                    "TS_INGEST_APPEND_CONFLICT",
                    detail="the tail overlaps the current coverage",
                )
            if (
                contract["regularity"] == "regular"
                and periods[0]["timestamp_start"] != coverage_end
            ):
                raise ObjectSeriesError(
                    "TS_INGEST_APPEND_CONFLICT",
                    detail="a regular tail must start where the coverage ends",
                )
        offset = len(base_periods)
        return (
            base_periods
            + [
                {**period, "period_index": period["period_index"] + offset}
                for period in periods
            ],
            base["values"]
            + [
                {**value, "period_index": value["period_index"] + offset}
                for value in values
            ],
        )

    def _object_series_content_hash(
        self,
        *,
        row: Mapping[str, Any],
        contract: Mapping[str, Any],
        periods: list[dict[str, Any]],
        values: list[dict[str, Any]],
    ) -> str:
        """The canonical hash of a snapshot that is not written yet.

        It walks the same fields in the same order as the streaming hash of the
        sealed revision, so validation and publication cannot disagree.
        """

        digest = CanonicalContentHash(
            timezone=contract["timezone"],
            timestamp_convention=contract["timestamp_convention"],
            data_class_key=contract["data_class_key"],
        )
        digest.add_signal(
            ordinal=0,
            series_key=row["object_series_key"],
            semantic_type_key=row["semantic_type_key"],
            unit_key=row["unit_key"],
            data_class_key=contract["data_class_key"],
            signal_role="input",
            aggregation=row["aggregation"],
        )
        for period in periods:
            digest.add_period(
                period_index=period["period_index"],
                timestamp_start=period["timestamp_start"],
                timestamp_end=period["timestamp_end"],
                duration_hours=period["duration_hours"],
            )
        for value in sorted(values, key=lambda entry: entry["period_index"]):
            digest.add_value(
                ordinal=0, period_index=value["period_index"], value=value["value"]
            )
        return digest.seal()

    def _object_series_file_source(
        self, uploaded: Mapping[str, Any], mapping: Mapping[str, Any]
    ) -> dict[str, Any]:
        """Keep file provenance server-owned and free of storage paths."""

        raw = mapping.get("source") or {}
        if not isinstance(raw, Mapping):
            raise ObjectSeriesError(
                "TS_INGEST_MAPPING_INVALID", detail="source must be an object"
            )
        allowed = {"kind", "display_name", "external_reference"}
        unknown = sorted(set(raw) - allowed)
        if unknown:
            raise ObjectSeriesError(
                "TS_INGEST_MAPPING_INVALID",
                detail="source contains server-owned or unknown fields",
                fields=unknown,
            )
        expected_kind = str(uploaded["kind"])
        declared_kind = str(raw.get("kind") or expected_kind)
        if declared_kind != expected_kind:
            raise ObjectSeriesError(
                "TS_INGEST_MAPPING_INVALID",
                detail="source.kind must match the uploaded file",
            )
        return {
            "kind": expected_kind,
            "original_filename": uploaded["original_filename"],
            "media_type": uploaded["media_type"],
            "selected_sheet": uploaded.get("selected_sheet"),
            "metadata": {
                "display_name": str(
                    raw.get("display_name") or uploaded["original_filename"]
                ),
                "external_reference": str(raw.get("external_reference") or ""),
            },
        }

    def prepare_object_series_points_ingestion(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        signal_id: int,
        document: Mapping[str, Any],
        actor: str,
    ) -> dict[str, Any]:
        """Validate one JSON batch and stage it; publishing is a second step.

        Nothing staged is selectable by a binding: the snapshot lives in its
        own tables until the publication transaction copies it into the
        canonical ones (chapter 9.7).
        """

        with self._lock:
            with self._database_transaction():
                linkable = self.authorize_object_series_root(
                    project_id=project_id, linkable_object_id=linkable_object_id
                )
                row = self._object_series_row(
                    linkable_object_id=int(linkable["id"]), signal_id=int(signal_id)
                )
                if row is None or linkable["status"] != "active":
                    raise ObjectSeriesError(
                        "TS_OBJECT_SERIES_NOT_FOUND",
                        detail="no local series with that id belongs to this object",
                        signal_id=int(signal_id),
                    )
                if row["set_status"] == "archived" or row["signal_status"] == "archived":
                    raise ObjectSeriesError(
                        "TS_OBJECT_SERIES_NOT_FOUND",
                        detail="the local series is archived",
                        signal_id=int(signal_id),
                    )
                receipt, refusal = self._stage_object_series_points(
                    linkable=linkable, row=row, document=document, actor=actor
                )
            # A job that failed validation is still a job: it commits so the
            # client can read its errors, fix the mapping and revalidate. Only
            # then is the refusal raised (chapter 7.4).
            if refusal is not None:
                raise refusal
            return receipt

    def prepare_object_series_file_ingestion(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        signal_id: int,
        uploaded: Mapping[str, Any],
        document: Mapping[str, Any] | None,
        idempotency_key: str,
        actor: str,
    ) -> dict[str, Any]:
        """Create the file job after parsing has completed outside the transaction."""

        with self._lock:
            with self._database_transaction():
                linkable = self.authorize_object_series_root(
                    project_id=project_id, linkable_object_id=linkable_object_id
                )
                row = self._object_series_row(
                    linkable_object_id=int(linkable["id"]), signal_id=int(signal_id)
                )
                if row is None or linkable["status"] != "active":
                    raise ObjectSeriesError(
                        "TS_OBJECT_SERIES_NOT_FOUND",
                        detail="no local series with that id belongs to this object",
                        signal_id=int(signal_id),
                    )
                mapping = dict(document or {})
                try:
                    claim = self._claim_idempotency(
                        actor_id=actor,
                        operation_kind=FILE_INGESTION_OPERATION_KIND,
                        scope_key=f"object-series:{int(row['time_series_set_id'])}",
                        idempotency_key=idempotency_key,
                        request_hash=idempotency_request_hash(
                            {
                                "signal_id": int(row["signal_id"]),
                                "filename": uploaded["original_filename"],
                                "media_type": uploaded["media_type"],
                                "checksum": uploaded["checksum"],
                                "mapping": mapping,
                            }
                        ),
                    )
                except CanonicalRevisionError as error:
                    if error.code in {
                        "TS_IDEMPOTENCY_KEY_CONFLICT",
                        "TS_IDEMPOTENCY_IN_FLIGHT",
                    }:
                        raise ObjectSeriesError(
                            "TS_INGEST_IDEMPOTENCY_CONFLICT",
                            detail="the key is already bound to another upload",
                            idempotency_key=idempotency_key,
                        ) from error
                    raise
                if claim["state"] == "completed":
                    return claim["response"]
                active_jobs = int(
                    self.connection.execute(
                        f"""
                        SELECT COUNT(*) AS total
                        FROM {self._object_series_table('time_series_ingestions')}
                        WHERE project_id = ? AND actor = ?
                          AND state IN ('awaiting_mapping', 'invalid', 'ready_to_publish')
                          AND expires_at > ?
                        """,
                        (int(row["owner_project_id"]), actor, utc_now_iso()),
                    ).fetchone()["total"]
                )
                if active_jobs >= FILE_MAX_ACTIVE_JOBS:
                    raise ObjectSeriesError(
                        "TS_INGEST_QUOTA_EXCEEDED",
                        detail="the actor already has the maximum active ingestion jobs",
                        maximum_active_jobs=FILE_MAX_ACTIVE_JOBS,
                    )
                mode = str(mapping.get("mode") or "replace_full").strip()
                if mode not in {"replace_full", "append_tail"}:
                    raise ObjectSeriesError(
                        "TS_INGEST_VALIDATION_FAILED", detail="mode is not supported"
                    )
                current = None
                if row["current_revision_id"] is not None:
                    current = self.connection.execute(
                        f"""
                        SELECT id, content_hash
                        FROM {self._canonical('time_series_set_revisions')}
                        WHERE id = ?
                        """,
                        (int(row["current_revision_id"]),),
                    ).fetchone()
                expected_base = mapping.get("expected_base")
                if current is None:
                    if mode != "replace_full":
                        raise ObjectSeriesError(
                            "TS_INGEST_APPEND_CONFLICT",
                            detail="the first load only accepts replace_full",
                        )
                    if expected_base is not None:
                        raise ObjectSeriesError(
                            "TS_INGEST_PRECONDITION_CHANGED",
                            detail="the series has no current revision yet",
                        )
                else:
                    if not isinstance(expected_base, Mapping):
                        raise ObjectSeriesError(
                            "TS_INGEST_PRECONDITION_REQUIRED",
                            detail="expected_base must name the exact current revision",
                            field="expected_base",
                        )
                    declared_hash = str(
                        expected_base.get("content_hash") or ""
                    ).split(":")[-1]
                    if (
                        int(expected_base.get("revision_id") or 0)
                        != int(current["id"])
                        or declared_hash != current["content_hash"]
                    ):
                        raise ObjectSeriesError(
                            "TS_INGEST_PRECONDITION_CHANGED",
                            detail="the declared base is not the current revision",
                            current_revision_id=int(current["id"]),
                        )
                contract = self._object_series_ingestion_contract(row, mapping)
                normalized = normalize_file_payload(
                    uploaded,
                    mapping,
                    series_keys=(row["object_series_key"],),
                    contract=contract,
                )
                uploaded = normalized.get("uploaded", uploaded)
                source = self._object_series_file_source(uploaded, mapping)
                errors = list(normalized["errors"])
                periods = normalized["periods"]
                values = normalized["values"]
                if not errors:
                    periods, values = self._merge_object_series_file_tail(
                        mode=mode,
                        base_revision_id=(
                            None if current is None else int(current["id"])
                        ),
                        contract=contract,
                        periods=periods,
                        values=values,
                    )
                    errors.extend(
                        check_file_temporal_contract(
                            periods,
                            contract=contract,
                            mapping=mapping,
                            sheet=uploaded.get("selected_sheet"),
                        )
                    )
                content_hash = (
                    None
                    if errors
                    else self._object_series_content_hash(
                        row=row, contract=contract, periods=periods, values=values
                    )
                )
                mapping_only = bool(errors) and all(
                    entry["code"] == "TS_INGEST_MAPPING_INVALID" for entry in errors
                )
                state = (
                    "ready_to_publish"
                    if not errors
                    else ("awaiting_mapping" if mapping_only else "invalid")
                )
                now = utc_now_iso()
                file_document = {
                    key: uploaded[key]
                    for key in (
                        "original_filename",
                        "media_type",
                        "available_sheets",
                        "selected_sheet",
                        "columns",
                        "preview_rows",
                        "mapping_suggestions",
                        "rows",
                        "kind",
                        "errors",
                        "worksheets",
                    )
                }
                ingestion_key = new_ingestion_key()
                ingestion_id = self._insert_canonical_row(
                    f"""
                    INSERT INTO {self._object_series_table('time_series_ingestions')} (
                        ingestion_key, project_id, linkable_object_id,
                        time_series_set_id, signal_id, target_kind, channel, state,
                        mode, actor, base_revision_id, base_content_hash,
                        contract_json, source_json, mapping_json, submitted_json,
                        normalized_json, validation_json, payload_checksum,
                        content_hash, created_at, updated_at, expires_at
                    ) VALUES (?, ?, ?, ?, ?, 'object_specific', ?,
                              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        ingestion_key,
                        int(row["owner_project_id"]),
                        int(linkable["id"]),
                        int(row["time_series_set_id"]),
                        int(row["signal_id"]),
                        f"file_{uploaded['kind']}",
                        state,
                        mode,
                        actor,
                        None if current is None else int(current["id"]),
                        None if current is None else current["content_hash"],
                        json.dumps(contract, sort_keys=True),
                        json.dumps(source, sort_keys=True),
                        json.dumps(mapping, sort_keys=True),
                        json.dumps(file_document, sort_keys=True),
                        json.dumps(summarize_normalized(periods, values), sort_keys=True),
                        json.dumps({"errors": errors}, sort_keys=True),
                        str(uploaded["checksum"]).split(":", 1)[-1],
                        content_hash,
                        now,
                        now,
                        ingestion_expiry(now),
                    ),
                )
                self._write_ingestion_staging(
                    ingestion_id=ingestion_id, periods=periods, values=values
                )
                receipt = self._read_object_series_ingestion_row(ingestion_id)
                self._complete_idempotency(
                    claim_id=claim["id"], response=receipt, http_status=202
                )
                return receipt

    def _stage_object_series_points(
        self,
        *,
        linkable: Mapping[str, Any],
        row: Mapping[str, Any],
        document: Mapping[str, Any],
        actor: str,
    ) -> tuple[dict[str, Any], ObjectSeriesError | None]:
        mode = str(document.get("mode") or "replace_full").strip()
        if mode not in {"replace_full", "append_tail"}:
            raise ObjectSeriesError(
                "TS_INGEST_VALIDATION_FAILED", detail="mode is not supported"
            )
        contract = self._object_series_ingestion_contract(row, document)
        current_revision_id = row["current_revision_id"]
        current = None
        if current_revision_id is not None:
            current = self.connection.execute(
                f"""
                SELECT id, revision_number, content_hash
                FROM {self._canonical('time_series_set_revisions')}
                WHERE id = ?
                """,
                (int(current_revision_id),),
            ).fetchone()

        expected_base = document.get("expected_base")
        if current is None:
            if mode != "replace_full":
                raise ObjectSeriesError(
                    "TS_INGEST_APPEND_CONFLICT",
                    detail="the first load only accepts replace_full",
                )
            if expected_base is not None:
                raise ObjectSeriesError(
                    "TS_INGEST_PRECONDITION_CHANGED",
                    detail="the series has no current revision yet",
                )
        else:
            if not isinstance(expected_base, Mapping):
                raise ObjectSeriesError(
                    "TS_INGEST_PRECONDITION_REQUIRED",
                    detail="expected_base must name the exact current revision",
                    field="expected_base",
                )
            declared_hash = str(expected_base.get("content_hash") or "").split(":")[-1]
            if (
                int(expected_base.get("revision_id") or 0) != int(current["id"])
                or declared_hash != current["content_hash"]
            ):
                raise ObjectSeriesError(
                    "TS_INGEST_PRECONDITION_CHANGED",
                    detail="the declared base is not the current revision",
                    current_revision_id=int(current["id"]),
                )

        series_key = row["object_series_key"]
        normalized = normalize_points_payload(
            document, series_keys=(series_key,), mapping={}
        )
        errors = list(normalized["errors"])
        periods = normalized["periods"]
        values = normalized["values"]

        if mode == "append_tail" and current is not None and not errors:
            base_snapshot = self._object_series_snapshot(int(current["id"]))
            base_periods = base_snapshot["periods"]
            coverage_end = base_periods[-1]["timestamp_end"] if base_periods else None
            if periods and coverage_end is not None:
                if periods[0]["timestamp_start"] < coverage_end:
                    raise ObjectSeriesError(
                        "TS_INGEST_APPEND_CONFLICT",
                        detail="the tail overlaps the current coverage",
                    )
                if (
                    contract["regularity"] == "regular"
                    and periods[0]["timestamp_start"] != coverage_end
                ):
                    raise ObjectSeriesError(
                        "TS_INGEST_APPEND_CONFLICT",
                        detail="a regular tail must start where the coverage ends",
                    )
            # ``append_tail`` still produces a self-contained snapshot: the hash
            # and the stored revision describe the whole resulting coverage.
            offset = len(base_periods)
            periods = base_periods + [
                {**period, "period_index": period["period_index"] + offset}
                for period in periods
            ]
            values = base_snapshot["values"] + [
                {**value, "period_index": value["period_index"] + offset}
                for value in values
            ]

        errors.extend(check_temporal_contract(periods, contract=contract))
        content_hash = (
            None
            if errors
            else self._object_series_content_hash(
                row=row, contract=contract, periods=periods, values=values
            )
        )
        mapping_only = bool(errors) and all(
            entry["code"] == "TS_INGEST_MAPPING_INVALID" for entry in errors
        )
        state = (
            "ready_to_publish"
            if not errors
            else ("awaiting_mapping" if mapping_only else "invalid")
        )

        now = utc_now_iso()
        ingestion_key = new_ingestion_key()
        ingestion_id = self._insert_canonical_row(
            f"""
            INSERT INTO {self._object_series_table('time_series_ingestions')} (
                ingestion_key, project_id, linkable_object_id, time_series_set_id,
                signal_id, target_kind, channel, state, mode, actor,
                base_revision_id, base_content_hash, contract_json, source_json,
                mapping_json, submitted_json, normalized_json, validation_json,
                payload_checksum, content_hash, created_at, updated_at, expires_at
            ) VALUES (?, ?, ?, ?, ?, 'object_specific', 'api_points', ?, ?, ?,
                      ?, ?, ?, ?, '{{}}', ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                ingestion_key,
                int(row["owner_project_id"]),
                int(linkable["id"]),
                int(row["time_series_set_id"]),
                int(row["signal_id"]),
                state,
                mode,
                actor,
                None if current is None else int(current["id"]),
                None if current is None else current["content_hash"],
                json.dumps(contract, sort_keys=True),
                json.dumps(document.get("source") or {}, sort_keys=True),
                json.dumps(document.get("points") or [], sort_keys=True),
                json.dumps(
                    summarize_normalized(periods, values), sort_keys=True
                ),
                json.dumps({"errors": errors}, sort_keys=True),
                payload_checksum(document.get("points") or []),
                content_hash,
                now,
                now,
                ingestion_expiry(now),
            ),
        )
        self._write_ingestion_staging(
            ingestion_id=ingestion_id, periods=periods, values=values
        )
        receipt = self._read_object_series_ingestion_row(ingestion_id)
        if errors:
            return receipt, ObjectSeriesError(
                "TS_INGEST_MAPPING_INVALID"
                if mapping_only
                else "TS_INGEST_VALIDATION_FAILED",
                detail=f"{len(errors)} records require correction",
                errors=errors,
                ingestion=receipt,
            )
        return receipt, None

    def _write_ingestion_staging(
        self,
        *,
        ingestion_id: int,
        periods: list[dict[str, Any]],
        values: list[dict[str, Any]],
    ) -> None:
        periods_table = self._object_series_table("time_series_ingestion_periods")
        values_table = self._object_series_table("time_series_ingestion_values")
        self.connection.execute(
            f"DELETE FROM {values_table} WHERE ingestion_id = ?", (int(ingestion_id),)
        )
        self.connection.execute(
            f"DELETE FROM {periods_table} WHERE ingestion_id = ?", (int(ingestion_id),)
        )
        if periods:
            self.connection.executemany(
                f"""
                INSERT INTO {periods_table} (
                    ingestion_id, period_index, timestamp_start, timestamp_end,
                    duration_hours, source_row_number
                ) VALUES (?, ?, ?, ?, ?, ?)
                """,
                [
                    (
                        int(ingestion_id),
                        period["period_index"],
                        period["timestamp_start"],
                        period["timestamp_end"],
                        period["duration_hours"],
                        period.get("source_row_number"),
                    )
                    for period in periods
                ],
            )
        if values:
            self.connection.executemany(
                f"""
                INSERT INTO {values_table} (
                    ingestion_id, series_key, period_index, value_numeric,
                    quality_flag, source_row_number
                ) VALUES (?, ?, ?, ?, ?, ?)
                """,
                [
                    (
                        int(ingestion_id),
                        value["series_key"],
                        value["period_index"],
                        value["value"],
                        value.get("quality_flag"),
                        value.get("source_row_number"),
                    )
                    for value in values
                ],
            )

    def _read_ingestion_staging(self, ingestion_id: int) -> dict[str, Any]:
        periods = [
            {
                "period_index": int(row["period_index"]),
                "timestamp_start": row["timestamp_start"],
                "timestamp_end": row["timestamp_end"],
                "duration_hours": float(row["duration_hours"]),
                "source_row_number": row["source_row_number"],
            }
            for row in self.connection.execute(
                f"""
                SELECT period_index, timestamp_start, timestamp_end,
                       duration_hours, source_row_number
                FROM {self._object_series_table('time_series_ingestion_periods')}
                WHERE ingestion_id = ? ORDER BY period_index
                """,
                (int(ingestion_id),),
            ).fetchall()
        ]
        values = [
            {
                "series_key": row["series_key"],
                "period_index": int(row["period_index"]),
                "value": float(row["value_numeric"]),
                "quality_flag": row["quality_flag"],
                "source_row_number": row["source_row_number"],
            }
            for row in self.connection.execute(
                f"""
                SELECT series_key, period_index, value_numeric, quality_flag,
                       source_row_number
                FROM {self._object_series_table('time_series_ingestion_values')}
                WHERE ingestion_id = ? ORDER BY period_index, series_key
                """,
                (int(ingestion_id),),
            ).fetchall()
        ]
        return {"periods": periods, "values": values}

    def _ingestion_row(self, ingestion_id: int):
        return self.connection.execute(
            f"""
            SELECT * FROM {self._object_series_table('time_series_ingestions')}
            WHERE id = ?
            """,
            (int(ingestion_id),),
        ).fetchone()

    def _ingestion_row_by_key(self, ingestion_key: str):
        return self.connection.execute(
            f"""
            SELECT * FROM {self._object_series_table('time_series_ingestions')}
            WHERE ingestion_key = ?
            """,
            (str(ingestion_key),),
        ).fetchone()

    def _read_object_series_ingestion_row(
        self,
        ingestion_id: int,
        *,
        actor_role: str = "analyst",
        intent: str = "shared",
    ) -> dict[str, Any]:
        row = self._ingestion_row(ingestion_id)
        if row is None:
            raise ObjectSeriesError(
                "TS_INGEST_SESSION_UNAVAILABLE", detail="the job no longer exists"
            )
        normalized = json.loads(row["normalized_json"] or "{}")
        errors = json.loads(row["validation_json"] or "{}").get("errors", [])
        shared = row["target_kind"] == "catalog_shared"
        if shared:
            # A shared job answers the impact of the whole set, and it always
            # requires an explicit confirmation (chapter 7.9).
            association = self._catalog_association_row(
                int(row["catalog_association_id"])
            )
            contract_changes = bool(
                json.loads(row["contract_json"] or "{}").get("changed")
            )
            view = self._shared_decision_view(
                linkable=self.get_linkable_object(int(row["linkable_object_id"])),
                association=association,
                actor_role=actor_role,
                intent=intent,
                contract_changes=contract_changes,
                # The incompleteness is read off the diagnosis the validator
                # already produced, so a batch that failed for another reason
                # is not mislabelled as a partial set (chapter 7.9).
                payload_incomplete=any(
                    entry.get("code") == "TS_INGEST_SIGNAL_SET_INCOMPLETE"
                    for entry in errors
                ),
            )
            impact = view["impact"]
            target = {
                "source_kind": "catalog",
                "signal_id": int(row["signal_id"]),
                "set_id": int(row["time_series_set_id"]),
                "association_id": int(row["catalog_association_id"]),
            }
        else:
            view = None
            impact = self._object_series_binding_impact(
                signal_id=int(row["signal_id"]), set_id=int(row["time_series_set_id"])
            )
            target = {
                "source_kind": "object_specific",
                "signal_id": int(row["signal_id"]),
                "set_id": int(row["time_series_set_id"]),
            }
        content_hash = row["content_hash"]
        receipt = {
            "ingestion_id": row["ingestion_key"],
            "channel": row["channel"],
            "state": row["state"],
            "mode": row["mode"],
            "target": target,
            "base": (
                None
                if row["base_revision_id"] is None
                else {
                    "revision_id": int(row["base_revision_id"]),
                    "content_hash": f"sha256:{row['base_content_hash']}",
                }
            ),
            "normalized": {
                **normalized,
                "coverage_start": utc_presentation(normalized.get("coverage_start")),
                "coverage_end": utc_presentation(normalized.get("coverage_end")),
                "content_hash": None if content_hash is None else f"sha256:{content_hash}",
            },
            "contract": json.loads(row["contract_json"] or "{}"),
            "mapping": json.loads(row["mapping_json"] or "{}"),
            "validation": {
                "valid": not errors,
                "error_count": len(errors),
                "errors": errors[:INGESTION_ERROR_LIMIT],
                "errors_truncated": len(errors) > INGESTION_ERROR_LIMIT,
                "error_counts": {
                    code: sum(1 for error in errors if error.get("code") == code)
                    for code in sorted(
                        {str(error.get("code")) for error in errors}
                    )
                },
            },
            "impact": impact,
            "requires_confirmation": (
                True if shared else impact["will_become_stale"] > 0
            ),
            "validation_token": (
                None
                if content_hash is None
                else ingestion_validation_token(
                    ingestion_key=row["ingestion_key"],
                    content_hash=content_hash,
                    secret=self._catalog_cursor_secret,
                )
            ),
            "capabilities": {
                "publish": row["state"] == "ready_to_publish",
                "remap": row["state"] in {"awaiting_mapping", "invalid"}
                or (
                    str(row["channel"]).startswith("file_")
                    and row["state"] == "ready_to_publish"
                ),
                "cancel": row["state"]
                in {"awaiting_mapping", "invalid", "ready_to_publish"},
                "preview": row["state"] != "cancelled",
            },
            "created_at": row["created_at"],
            "expires_at": row["expires_at"],
            "published_revision_id": row["published_revision_id"],
        }
        if shared and view is not None:
            receipt["impact_fingerprint"] = view["impact_fingerprint"]
            receipt["recommendation"] = view["recommendation"]
            receipt["derivation_required"] = view["derivation_required"]
            receipt["derivation_required_codes"] = view["derivation_required_codes"]
            receipt["alternatives"] = view["alternatives"]
            receipt["set_signals"] = view["set_signals"]
            receipt["links"] = view["links"]
            receipt["etag"] = shared_source_etag(
                set_id=int(row["time_series_set_id"]),
                current_revision_id=impact["source"]["current_revision_id"],
            )
        if str(row["channel"]).startswith("file_"):
            submitted = json.loads(row["submitted_json"] or "{}")
            receipt["file"] = {
                key: submitted.get(key)
                for key in (
                    "original_filename",
                    "media_type",
                    "available_sheets",
                    "selected_sheet",
                    "columns",
                    "preview_rows",
                    "mapping_suggestions",
                )
            }
        return receipt

    def _resolve_object_series_ingestion(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        signal_id: int,
        ingestion_key: str,
    ):
        """Knowing the opaque id never skips authorization (AC-SEG-03).

        The object of the route is resolved and authorized first; the job is
        then required to belong to exactly that object, project and target.
        """

        linkable = self.authorize_object_series_root(
            project_id=project_id, linkable_object_id=linkable_object_id
        )
        row = self._object_series_row(
            linkable_object_id=int(linkable["id"]), signal_id=int(signal_id)
        )
        if row is None:
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="no local series with that id belongs to this object",
                signal_id=int(signal_id),
            )
        ingestion = self._ingestion_row_by_key(ingestion_key)
        if (
            ingestion is None
            or int(ingestion["linkable_object_id"]) != int(linkable["id"])
            or int(ingestion["project_id"]) != int(linkable["project_id"])
            or int(ingestion["signal_id"]) != int(row["signal_id"])
        ):
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="no ingestion with that id belongs to this target",
            )
        return linkable, row, ingestion

    def read_object_series_ingestion(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        signal_id: int,
        ingestion_key: str,
    ) -> dict[str, Any]:
        _, _, ingestion = self._resolve_object_series_ingestion(
            project_id=project_id,
            linkable_object_id=linkable_object_id,
            signal_id=signal_id,
            ingestion_key=ingestion_key,
        )
        return self._read_object_series_ingestion_row(int(ingestion["id"]))

    def read_object_series_ingestion_preview(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        signal_id: int,
        ingestion_key: str,
        max_rows: int | None = None,
    ) -> dict[str, Any]:
        """A bounded normalized sample of what is staged - never a download."""

        _, row, ingestion = self._resolve_object_series_ingestion(
            project_id=project_id,
            linkable_object_id=linkable_object_id,
            signal_id=signal_id,
            ingestion_key=ingestion_key,
        )
        if ingestion["state"] == "cancelled":
            raise ObjectSeriesError(
                "TS_INGEST_SESSION_UNAVAILABLE", detail="the job was cancelled"
            )
        limit = INGESTION_PREVIEW_MAX_ROWS if max_rows is None else int(max_rows)
        if limit < 1 or limit > INGESTION_PREVIEW_MAX_ROWS:
            raise ObjectSeriesError(
                "TS_QUERY_INVALID",
                field="max_rows",
                detail="max_rows is out of range",
                maximum=INGESTION_PREVIEW_MAX_ROWS,
            )
        staging = self._read_ingestion_staging(int(ingestion["id"]))
        by_period = {
            value["period_index"]: value for value in staging["values"]
        }
        rows = []
        for period in staging["periods"][:limit]:
            value = by_period.get(period["period_index"])
            rows.append(
                {
                    "period_index": period["period_index"],
                    "timestamp_start": utc_presentation(period["timestamp_start"]),
                    "timestamp_end": utc_presentation(period["timestamp_end"]),
                    "series_key": row["object_series_key"],
                    "value": None if value is None else value["value"],
                    "quality_flag": None if value is None else value["quality_flag"],
                }
            )
        return {
            "ingestion_id": ingestion["ingestion_key"],
            "unit_key": row["unit_key"],
            "source_row_count": len(staging["periods"]),
            "returned_row_count": len(rows),
            "max_rows": limit,
            "rows": rows,
        }

    def update_object_series_ingestion_mapping(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        signal_id: int,
        ingestion_key: str,
        mapping: Mapping[str, Any],
        actor: str,
    ) -> dict[str, Any]:
        """Fix the mapping of a staged batch and revalidate it (chapter 7.4)."""

        candidate = self._ingestion_row_by_key(ingestion_key)
        if candidate is not None and str(candidate["channel"]).startswith("file_"):
            return self._update_object_series_file_ingestion_mapping(
                project_id=project_id,
                linkable_object_id=linkable_object_id,
                signal_id=signal_id,
                ingestion_key=ingestion_key,
                mapping=mapping,
                actor=actor,
            )

        with self._lock:
            with self._database_transaction():
                _, row, ingestion = self._resolve_object_series_ingestion(
                    project_id=project_id,
                    linkable_object_id=linkable_object_id,
                    signal_id=signal_id,
                    ingestion_key=ingestion_key,
                )
                if ingestion["state"] in {"published", "cancelled"}:
                    raise ObjectSeriesError(
                        "TS_INGEST_SESSION_UNAVAILABLE",
                        detail="the job is closed",
                        state=ingestion["state"],
                    )
                value_keys = mapping.get("value_keys")
                if not isinstance(value_keys, Mapping) or not value_keys:
                    raise ObjectSeriesError(
                        "TS_INGEST_MAPPING_INVALID",
                        detail="value_keys must map every incoming key",
                    )
                resolved = {str(key): str(value) for key, value in value_keys.items()}
                unknown = sorted(
                    value
                    for value in resolved.values()
                    if value != row["object_series_key"]
                )
                if unknown:
                    raise ObjectSeriesError(
                        "TS_INGEST_MAPPING_INVALID",
                        detail="the mapping names a signal the target does not have",
                        errors=[
                            {
                                "code": "TS_INGEST_MAPPING_INVALID",
                                "message": f"'{value}' is not a signal of the target",
                                "location": {
                                    "record_index": 0,
                                    "json_pointer": f"/mapping/value_keys/{value}",
                                },
                            }
                            for value in unknown
                        ],
                    )
                document = {
                    "mode": ingestion["mode"],
                    "points": json.loads(ingestion["submitted_json"] or "[]"),
                }
                contract = json.loads(ingestion["contract_json"] or "{}")
                normalized = normalize_points_payload(
                    document,
                    series_keys=(row["object_series_key"],),
                    mapping=resolved,
                )
                errors = list(normalized["errors"])
                errors.extend(
                    check_temporal_contract(normalized["periods"], contract=contract)
                )
                content_hash = (
                    None
                    if errors
                    else self._object_series_content_hash(
                        row=row,
                        contract=contract,
                        periods=normalized["periods"],
                        values=normalized["values"],
                    )
                )
                mapping_only = bool(errors) and all(
                    entry["code"] == "TS_INGEST_MAPPING_INVALID" for entry in errors
                )
                state = (
                    "ready_to_publish"
                    if not errors
                    else ("awaiting_mapping" if mapping_only else "invalid")
                )
                self.connection.execute(
                    f"""
                    UPDATE {self._object_series_table('time_series_ingestions')}
                    SET mapping_json = ?, normalized_json = ?, validation_json = ?,
                        content_hash = ?, state = ?, actor = ?, updated_at = ?
                    WHERE id = ?
                    """,
                    (
                        json.dumps({"value_keys": resolved}, sort_keys=True),
                        json.dumps(
                            summarize_normalized(
                                normalized["periods"], normalized["values"]
                            ),
                            sort_keys=True,
                        ),
                        json.dumps({"errors": errors}, sort_keys=True),
                        content_hash,
                        state,
                        actor,
                        utc_now_iso(),
                        int(ingestion["id"]),
                    ),
                )
                self._write_ingestion_staging(
                    ingestion_id=int(ingestion["id"]),
                    periods=normalized["periods"],
                    values=normalized["values"],
                )
                receipt = self._read_object_series_ingestion_row(int(ingestion["id"]))
                refusal = (
                    None
                    if not errors
                    else ObjectSeriesError(
                        "TS_INGEST_MAPPING_INVALID"
                        if mapping_only
                        else "TS_INGEST_VALIDATION_FAILED",
                        detail=f"{len(errors)} records require correction",
                        errors=errors,
                        ingestion=receipt,
                    )
                )
            # The corrected job keeps its new state even when it is still
            # invalid, so a second correction starts from what was stored.
            if refusal is not None:
                raise refusal
            return receipt

    def _update_object_series_file_ingestion_mapping(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        signal_id: int,
        ingestion_key: str,
        mapping: Mapping[str, Any],
        actor: str,
    ) -> dict[str, Any]:
        """Revalidate immutable parsed file rows under a corrected mapping."""

        with self._lock:
            with self._database_transaction():
                _, row, ingestion = self._resolve_object_series_ingestion(
                    project_id=project_id,
                    linkable_object_id=linkable_object_id,
                    signal_id=signal_id,
                    ingestion_key=ingestion_key,
                )
                if ingestion["state"] in {"published", "cancelled"}:
                    raise ObjectSeriesError(
                        "TS_INGEST_SESSION_UNAVAILABLE",
                        detail="the job is closed",
                        state=ingestion["state"],
                    )
                uploaded = json.loads(ingestion["submitted_json"] or "{}")
                contract = self._object_series_ingestion_contract(row, mapping)
                normalized = normalize_file_payload(
                    uploaded,
                    mapping,
                    series_keys=(row["object_series_key"],),
                    contract=contract,
                )
                uploaded = normalized.get("uploaded", uploaded)
                source = self._object_series_file_source(uploaded, mapping)
                errors = list(normalized["errors"])
                periods = normalized["periods"]
                values = normalized["values"]
                if not errors:
                    periods, values = self._merge_object_series_file_tail(
                        mode=str(ingestion["mode"]),
                        base_revision_id=(
                            None
                            if ingestion["base_revision_id"] is None
                            else int(ingestion["base_revision_id"])
                        ),
                        contract=contract,
                        periods=periods,
                        values=values,
                    )
                    errors.extend(
                        check_file_temporal_contract(
                            periods,
                            contract=contract,
                            mapping=mapping,
                            sheet=uploaded.get("selected_sheet"),
                        )
                    )
                content_hash = (
                    None
                    if errors
                    else self._object_series_content_hash(
                        row=row, contract=contract, periods=periods, values=values
                    )
                )
                mapping_only = bool(errors) and all(
                    entry["code"] == "TS_INGEST_MAPPING_INVALID" for entry in errors
                )
                state = (
                    "ready_to_publish"
                    if not errors
                    else ("awaiting_mapping" if mapping_only else "invalid")
                )
                self.connection.execute(
                    f"""
                    UPDATE {self._object_series_table('time_series_ingestions')}
                    SET mapping_json = ?, contract_json = ?, source_json = ?,
                        submitted_json = ?,
                        normalized_json = ?, validation_json = ?, content_hash = ?,
                        state = ?, actor = ?, updated_at = ?
                    WHERE id = ?
                    """,
                    (
                        json.dumps(dict(mapping), sort_keys=True),
                        json.dumps(contract, sort_keys=True),
                        json.dumps(source, sort_keys=True),
                        json.dumps(uploaded, sort_keys=True),
                        json.dumps(summarize_normalized(periods, values), sort_keys=True),
                        json.dumps({"errors": errors}, sort_keys=True),
                        content_hash,
                        state,
                        actor,
                        utc_now_iso(),
                        int(ingestion["id"]),
                    ),
                )
                self._write_ingestion_staging(
                    ingestion_id=int(ingestion["id"]),
                    periods=periods,
                    values=values,
                )
                receipt = self._read_object_series_ingestion_row(int(ingestion["id"]))
                refusal = (
                    None
                    if not errors
                    else ObjectSeriesError(
                        "TS_INGEST_MAPPING_INVALID"
                        if mapping_only
                        else "TS_INGEST_VALIDATION_FAILED",
                        detail=f"{len(errors)} records require correction",
                        errors=errors,
                        ingestion=receipt,
                    )
                )
            if refusal is not None:
                raise refusal
            return receipt

    def cancel_object_series_ingestion(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        signal_id: int,
        ingestion_key: str,
        actor: str,
    ) -> dict[str, Any]:
        """Withdraw an unpublished job and its staging (chapter 7.4)."""

        with self._lock:
            with self._database_transaction():
                _, _, ingestion = self._resolve_object_series_ingestion(
                    project_id=project_id,
                    linkable_object_id=linkable_object_id,
                    signal_id=signal_id,
                    ingestion_key=ingestion_key,
                )
                if ingestion["state"] == "published":
                    raise ObjectSeriesError(
                        "TS_INGEST_SESSION_UNAVAILABLE",
                        detail="a published job cannot be cancelled",
                    )
                self._write_ingestion_staging(
                    ingestion_id=int(ingestion["id"]), periods=[], values=[]
                )
                submitted = json.loads(ingestion["submitted_json"] or "{}")
                if str(ingestion["channel"]).startswith("file_"):
                    submitted["rows"] = []
                    submitted["preview_rows"] = []
                    submitted["worksheets"] = {}
                self.connection.execute(
                    f"""
                    UPDATE {self._object_series_table('time_series_ingestions')}
                    SET state = 'cancelled', content_hash = NULL, actor = ?,
                        submitted_json = ?, updated_at = ?
                    WHERE id = ?
                    """,
                    (
                        actor,
                        json.dumps(submitted, sort_keys=True),
                        utc_now_iso(),
                        int(ingestion["id"]),
                    ),
                )
                return self._read_object_series_ingestion_row(int(ingestion["id"]))

    def publish_object_series_ingestion(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        signal_id: int,
        ingestion_key: str,
        validation_token: str,
        confirm: bool,
        reason_code: str,
        reason_text: str,
        if_match: str,
        idempotency_key: str,
        actor: str,
    ) -> tuple[dict[str, Any], bool]:
        """Seal the staged snapshot in one transaction (chapters 7.8, 9.7).

        Either the revision exists complete and current when the transaction
        commits, or it never existed: no interval exposes a half-written
        revision as the current one (AC-ESP-10).
        """

        with self._lock:
            with self._database_transaction():
                linkable, row, ingestion = self._resolve_object_series_ingestion(
                    project_id=project_id,
                    linkable_object_id=linkable_object_id,
                    signal_id=signal_id,
                    ingestion_key=ingestion_key,
                )
                claim = self._claim_object_series_publication(
                    ingestion=ingestion,
                    actor=actor,
                    idempotency_key=idempotency_key,
                    if_match=if_match,
                    confirm=confirm,
                    reason_code=reason_code,
                )
                if claim["state"] == "completed":
                    return claim["response"], True
                receipt = self._publish_object_series_revision(
                    linkable=linkable,
                    row=row,
                    ingestion=ingestion,
                    validation_token=validation_token,
                    confirm=confirm,
                    reason_code=reason_code,
                    reason_text=reason_text,
                    if_match=if_match,
                    actor=actor,
                )
                self._complete_idempotency(
                    claim_id=claim["id"],
                    response=receipt,
                    http_status=200 if receipt["outcome"] == "unchanged" else 201,
                )
                return receipt, False

    def _claim_object_series_publication(
        self,
        *,
        ingestion: Mapping[str, Any],
        actor: str,
        idempotency_key: str,
        if_match: str,
        confirm: bool,
        reason_code: str,
    ) -> dict[str, Any]:
        try:
            return self._claim_idempotency(
                actor_id=actor,
                operation_kind=PUBLISH_INGESTION_OPERATION_KIND,
                scope_key=f"object-series:{int(ingestion['time_series_set_id'])}",
                idempotency_key=idempotency_key,
                request_hash=idempotency_request_hash(
                    {
                        "ingestion_key": ingestion["ingestion_key"],
                        "content_hash": ingestion["content_hash"],
                        "base_revision_id": ingestion["base_revision_id"],
                        "if_match": if_match,
                        "confirm": bool(confirm),
                        "reason_code": reason_code,
                    }
                ),
            )
        except CanonicalRevisionError as error:
            if error.code == "TS_IDEMPOTENCY_KEY_CONFLICT":
                raise ObjectSeriesError(
                    "TS_INGEST_IDEMPOTENCY_CONFLICT",
                    detail="the key was already used for another payload",
                    idempotency_key=idempotency_key,
                ) from error
            raise

    def _publish_object_series_revision(
        self,
        *,
        linkable: Mapping[str, Any],
        row: Mapping[str, Any],
        ingestion: Mapping[str, Any],
        validation_token: str,
        confirm: bool,
        reason_code: str,
        reason_text: str,
        if_match: str,
        actor: str,
    ) -> dict[str, Any]:
        set_id = int(row["time_series_set_id"])
        locked = self._lock_canonical_set(set_id)
        if locked is None:
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND", detail="the target set disappeared"
            )
        if linkable["status"] != "active" or locked["status"] == "archived":
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND", detail="the owner or the set is archived"
            )
        if ingestion["state"] in {"cancelled", "published"}:
            raise ObjectSeriesError(
                "TS_INGEST_SESSION_UNAVAILABLE",
                detail="the job is not publishable any more",
                state=ingestion["state"],
            )
        if ingestion["state"] != "ready_to_publish" or ingestion["content_hash"] is None:
            raise ObjectSeriesError(
                "TS_INGEST_VALIDATION_FAILED",
                detail="the job has not validated cleanly",
                errors=json.loads(ingestion["validation_json"] or "{}").get(
                    "errors", []
                ),
            )
        if ingestion["expires_at"] <= utc_now_iso():
            raise ObjectSeriesError(
                "TS_INGEST_SESSION_UNAVAILABLE", detail="the job expired"
            )

        expected_etag = object_series_etag(
            signal_id=int(row["signal_id"]),
            resource_version=int(row["resource_version"]),
        )
        if str(if_match or "").strip() != expected_etag:
            raise ObjectSeriesError(
                "TS_INGEST_PRECONDITION_CHANGED",
                detail="the series changed since the ETag was read",
                expected=expected_etag,
            )
        expected_token = ingestion_validation_token(
            ingestion_key=ingestion["ingestion_key"],
            content_hash=ingestion["content_hash"],
            secret=self._catalog_cursor_secret,
        )
        if str(validation_token or "").strip() != expected_token:
            raise ObjectSeriesError(
                "TS_INGEST_PRECONDITION_CHANGED",
                detail="the validation token does not describe this content",
            )
        current_pointer = locked["current_revision_id"]
        base_pointer = ingestion["base_revision_id"]
        if (current_pointer is None) != (base_pointer is None) or (
            current_pointer is not None
            and int(current_pointer) != int(base_pointer)
        ):
            raise ObjectSeriesError(
                "TS_INGEST_PRECONDITION_CHANGED",
                detail="the current revision moved since the batch validated",
            )

        impact = self._object_series_binding_impact(
            signal_id=int(row["signal_id"]), set_id=set_id
        )
        if impact["will_become_stale"] > 0 and not confirm:
            raise ObjectSeriesError(
                "TS_SHARED_REVISION_CONFIRMATION_REQUIRED",
                detail="the publication turns live bindings stale",
                impact=impact,
            )
        if not str(reason_code or "").strip():
            raise ObjectSeriesError(
                "TS_INGEST_PRECONDITION_REQUIRED",
                detail="reason_code is required",
                field="reason_code",
            )

        contract = json.loads(ingestion["contract_json"] or "{}")
        staged = self._read_ingestion_staging(int(ingestion["id"]))
        now = utc_now_iso()

        # A republication whose content equals the current revision is a no-op:
        # no revision, no pointer move, no staleness, no generation (chapter 7.8).
        if current_pointer is not None:
            current = self.connection.execute(
                f"""
                SELECT id, revision_number, content_hash
                FROM {self._canonical('time_series_set_revisions')} WHERE id = ?
                """,
                (int(current_pointer),),
            ).fetchone()
            if current is not None and current["content_hash"] == ingestion["content_hash"]:
                self._close_object_series_ingestion(
                    ingestion_id=int(ingestion["id"]),
                    revision_id=int(current["id"]),
                    now=now,
                )
                series = self._read_object_series(
                    linkable=linkable, signal_id=int(row["signal_id"])
                )
                return self._object_series_publication_receipt(
                    series=series,
                    outcome="unchanged",
                    revision_id=int(current["id"]),
                    revision_number=int(current["revision_number"]),
                    content_hash=current["content_hash"],
                    source_checksum=ingestion["payload_checksum"],
                    source_kind=json.loads(ingestion["source_json"] or "{}").get(
                        "kind", "api"
                    ),
                    impact=impact,
                    now_stale=0,
                )

        revisions_table = self._canonical("time_series_set_revisions")
        building = self.connection.execute(
            f"""
            SELECT id, revision_number FROM {revisions_table}
            WHERE time_series_set_id = ? AND state = 'building'
            ORDER BY revision_number DESC LIMIT 1
            """,
            (set_id,),
        ).fetchone()
        source_id, _ = self._register_canonical_source(
            int(row["owner_project_id"]),
            {
                **json.loads(ingestion["source_json"] or "{}"),
                "source_key": f"object-series:{ingestion['ingestion_key']}",
                "checksum": ingestion["payload_checksum"],
            },
            actor,
            now,
        )
        if building is not None:
            # The first separate load completes and seals the revision 1 that
            # the definition already opened (chapter 7.8).
            revision_id = int(building["id"])
            revision_number = int(building["revision_number"])
            self.connection.execute(
                f"""
                UPDATE {revisions_table}
                SET time_series_source_id = ?, data_class_id = ?, timezone = ?,
                    timestamp_convention = ?, change_summary = ?,
                    metadata_json = ?, created_at = ?, created_by = ?
                WHERE id = ?
                """,
                (
                    source_id,
                    contract["data_class_id"],
                    contract["timezone"],
                    contract["timestamp_convention"],
                    reason_code,
                    json.dumps(
                        {"temporal_contract": contract, "reason_text": reason_text},
                        sort_keys=True,
                    ),
                    now,
                    actor,
                    revision_id,
                ),
            )
            self.connection.execute(
                f"""
                UPDATE {self._canonical('time_series_revision_signals')}
                SET semantic_type_id = ?, unit_id = ?, data_class_id = ?,
                    aggregation = ?
                WHERE set_revision_id = ? AND signal_id = ?
                """,
                (
                    int(row["semantic_type_id"]),
                    int(row["unit_id"]),
                    contract["data_class_id"],
                    row["aggregation"],
                    revision_id,
                    int(row["signal_id"]),
                ),
            )
        else:
            highest = self.connection.execute(
                f"""
                SELECT MAX(revision_number) AS highest FROM {revisions_table}
                WHERE time_series_set_id = ?
                """,
                (set_id,),
            ).fetchone()
            revision_number = int(highest["highest"] or 0) + 1
            revision_id = self._insert_canonical_row(
                f"""
                INSERT INTO {revisions_table} (
                    time_series_set_id, revision_number, supersedes_revision_id,
                    time_series_source_id, data_class_id, timezone,
                    timestamp_convention, state, change_summary, metadata_json,
                    created_at, created_by
                ) VALUES (?, ?, ?, ?, ?, ?, ?, 'building', ?, ?, ?, ?)
                """,
                (
                    set_id,
                    revision_number,
                    current_pointer,
                    source_id,
                    contract["data_class_id"],
                    contract["timezone"],
                    contract["timestamp_convention"],
                    reason_code,
                    json.dumps(
                        {"temporal_contract": contract, "reason_text": reason_text},
                        sort_keys=True,
                    ),
                    now,
                    actor,
                ),
            )
            self.connection.execute(
                f"""
                INSERT INTO {self._canonical('time_series_revision_signals')} (
                    set_revision_id, signal_id, time_series_set_id,
                    semantic_type_id, unit_id, data_class_id, signal_role,
                    aggregation, ordinal, metadata_json
                ) VALUES (?, ?, ?, ?, ?, ?, 'input', ?, 0, '{{}}')
                """,
                (
                    revision_id,
                    int(row["signal_id"]),
                    set_id,
                    int(row["semantic_type_id"]),
                    int(row["unit_id"]),
                    contract["data_class_id"],
                    row["aggregation"],
                ),
            )

        periods_table = self._canonical("time_series_periods")
        self.connection.executemany(
            f"""
            INSERT INTO {periods_table} (
                set_revision_id, period_index, timestamp_start, timestamp_end,
                duration_hours
            ) VALUES (?, ?, ?, ?, ?)
            """,
            [
                (
                    revision_id,
                    period["period_index"],
                    period["timestamp_start"],
                    period["timestamp_end"],
                    period["duration_hours"],
                )
                for period in staged["periods"]
            ],
        )
        period_ids = {
            int(entry["period_index"]): int(entry["id"])
            for entry in self.connection.execute(
                f"SELECT id, period_index FROM {periods_table} WHERE set_revision_id = ?",
                (revision_id,),
            ).fetchall()
        }
        self._insert_canonical_values(
            values_table=self._canonical("time_series_values"),
            revision_id=revision_id,
            values=staged["values"],
            signal_ids={row["object_series_key"]: int(row["signal_id"])},
            period_ids=period_ids,
        )

        value_count = int(
            self.connection.execute(
                f"""
                SELECT COUNT(*) AS total FROM {self._canonical('time_series_values')}
                WHERE set_revision_id = ?
                """,
                (revision_id,),
            ).fetchone()["total"]
        )
        if value_count != len(staged["periods"]):
            raise ObjectSeriesError(
                "TS_INGEST_VALIDATION_FAILED",
                detail="the snapshot is not dense",
                period_count=len(staged["periods"]),
                value_count=value_count,
            )
        content_hash = self._stream_canonical_content_hash(
            revision_id=revision_id,
            revision_timezone=contract["timezone"],
            timestamp_convention=contract["timestamp_convention"],
            data_class_key=contract["data_class_key"],
        )
        if content_hash != ingestion["content_hash"]:
            raise ObjectSeriesError(
                "TS_INGEST_PRECONDITION_CHANGED",
                detail="the stored snapshot does not match the validated hash",
            )

        self.connection.execute(
            f"""
            UPDATE {revisions_table}
            SET state = 'sealed', content_hash = ?, validation_payload_json = ?
            WHERE id = ?
            """,
            (
                content_hash,
                json.dumps(
                    {
                        "signal_count": 1,
                        "period_count": len(staged["periods"]),
                        "value_count": value_count,
                        "coverage_start": staged["periods"][0]["timestamp_start"],
                        "coverage_end": staged["periods"][-1]["timestamp_end"],
                    },
                    sort_keys=True,
                ),
                revision_id,
            ),
        )
        self.connection.execute(
            f"""
            UPDATE {self._canonical('time_series_sets')}
            SET current_revision_id = ?, content_hash = ?, data_kind = ?,
                timezone = ?, status = 'validated', updated_at = ?, updated_by = ?
            WHERE id = ?
            """,
            (
                revision_id,
                content_hash,
                contract["data_class_key"],
                contract["timezone"],
                now,
                actor,
                set_id,
            ),
        )
        self.connection.execute(
            f"""
            UPDATE {self._object_series_table('object_series_definitions')}
            SET data_class_id = ?, timezone = ?, regularity = ?,
                nominal_resolution_seconds = ?,
                resource_version = resource_version + 1,
                updated_at = ?, updated_by = ?
            WHERE time_series_set_id = ?
            """,
            (
                contract["data_class_id"],
                contract["timezone"],
                contract["regularity"],
                contract["nominal_resolution_seconds"],
                now,
                actor,
                set_id,
            ),
        )
        self._close_object_series_ingestion(
            ingestion_id=int(ingestion["id"]), revision_id=revision_id, now=now
        )
        # The local set never enters the global projection, but the object
        # context list reads the same generation, so it rises exactly once.
        self._raise_catalog_generation(now=now)

        series = self._read_object_series(
            linkable=linkable, signal_id=int(row["signal_id"])
        )
        return self._object_series_publication_receipt(
            series=series,
            outcome="new_revision",
            revision_id=revision_id,
            revision_number=revision_number,
            content_hash=content_hash,
            source_checksum=ingestion["payload_checksum"],
            source_kind=json.loads(ingestion["source_json"] or "{}").get("kind", "api"),
            impact=impact,
            now_stale=impact["will_become_stale"],
        )

    def _close_object_series_ingestion(
        self, *, ingestion_id: int, revision_id: int, now: str
    ) -> None:
        ingestion = self._ingestion_row(int(ingestion_id))
        submitted = json.loads(ingestion["submitted_json"] or "{}")
        if str(ingestion["channel"]).startswith("file_"):
            submitted["rows"] = []
            submitted["preview_rows"] = []
            submitted["worksheets"] = {}
        self.connection.execute(
            f"""
            UPDATE {self._object_series_table('time_series_ingestions')}
            SET state = 'published', published_revision_id = ?,
                submitted_json = ?, updated_at = ?
            WHERE id = ?
            """,
            (
                int(revision_id),
                json.dumps(submitted, sort_keys=True),
                now,
                int(ingestion_id),
            ),
        )
        self._write_ingestion_staging(
            ingestion_id=int(ingestion_id), periods=[], values=[]
        )

    def _object_series_publication_receipt(
        self,
        *,
        series: dict[str, Any],
        outcome: str,
        revision_id: int,
        revision_number: int,
        content_hash: str,
        source_checksum: str,
        source_kind: str,
        impact: Mapping[str, Any],
        now_stale: int,
    ) -> dict[str, Any]:
        return {
            "outcome": outcome,
            "set_id": series["set_id"],
            "signal_ids": [series["signal_id"]],
            "revision_id": int(revision_id),
            "revision_number": int(revision_number),
            "state": "sealed",
            "content_hash": f"sha256:{content_hash}",
            "source": {"kind": source_kind, "checksum": source_checksum},
            "availability": series["availability"],
            "binding_ready": series["binding_ready"],
            "staleness": {
                "bindings_current": impact["bindings_current"],
                "bindings_pinned": impact["bindings_pinned"],
                "now_stale": now_stale,
            },
            "resource_version": series["resource_version"],
            "object_series": series,
        }

    # -- Shared generic source from the object (TS7-013, chapter 7.9) -------
    #
    # ``SHARED_TARGET`` is a mutation base of its own. It is reachable only
    # through an active association that matches signal, role and object, so a
    # client cannot turn a local load into a shared revision by editing one
    # path segment. An administrative integration that does not start from an
    # object uses the canonical revision resource of the set and never
    # simulates an ``association_id``.

    def _shared_source_association(
        self, *, linkable: Mapping[str, Any], association_id: int
    ):
        """The association this object really owns, or a 404 that leaks nothing."""

        row = self._catalog_association_row(int(association_id))
        if row is None or int(row["linkable_object_id"]) != int(linkable["id"]):
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="no catalog association with that id belongs to this object",
                association_id=int(association_id),
            )
        return row

    def _shared_source_set(self, set_id: int):
        return self.connection.execute(
            f"""
            SELECT canonical_set.id, canonical_set.visibility_scope,
                   canonical_set.owner_project_id, canonical_set.status,
                   canonical_set.current_revision_id, canonical_set.name,
                   canonical_set.timezone, project.name AS owner_project_name,
                   revision.revision_number AS current_revision_number,
                   revision.content_hash AS current_content_hash
            FROM {self._canonical('time_series_sets')} AS canonical_set
            JOIN projects AS project ON project.id = canonical_set.owner_project_id
            LEFT JOIN {self._canonical('time_series_set_revisions')} AS revision
              ON revision.id = canonical_set.current_revision_id
            WHERE canonical_set.id = ?
            """,
            (int(set_id),),
        ).fetchone()

    def _shared_source_signals(self, *, set_id: int, revision_id: int | None):
        """Every active signal the atomic revision of this set must carry."""

        if revision_id is None:
            return []
        return [
            dict(row)
            for row in self.connection.execute(
                f"""
                SELECT signal.id AS signal_id, signal.series_key,
                       signal.display_name, signal.status,
                       revision_signal.semantic_type_id, revision_signal.unit_id,
                       revision_signal.data_class_id, revision_signal.signal_role,
                       revision_signal.aggregation, revision_signal.ordinal,
                       semantic_type.semantic_key AS semantic_type_key,
                       unit.unit_key AS unit_key
                FROM {self._canonical('time_series_revision_signals')}
                     AS revision_signal
                JOIN {self._canonical('time_series_signals')} AS signal
                  ON signal.id = revision_signal.signal_id
                JOIN time_series_semantic_types AS semantic_type
                  ON semantic_type.id = revision_signal.semantic_type_id
                JOIN measurement_units AS unit ON unit.id = revision_signal.unit_id
                WHERE revision_signal.set_revision_id = ?
                  AND signal.status = 'active'
                ORDER BY revision_signal.ordinal, signal.id
                """,
                (int(revision_id),),
            ).fetchall()
        ]

    def _shared_source_impact(
        self,
        *,
        association: Mapping[str, Any],
        contract_changes: bool = False,
    ) -> dict[str, Any]:
        """What a shared revision on this set would do to everyone (7.9).

        The unit of a generic revision is the set, so the blast radius is read
        over the whole set and not over the one signal this association happens
        to point at.
        """

        set_id = int(association["time_series_set_id"])
        owner_object_id = int(association["linkable_object_id"])
        set_row = self._shared_source_set(set_id)
        pointer = None if set_row is None else set_row["current_revision_id"]
        associations_table = self.link_layer_table_names()[
            "time_series_catalog_associations"
        ]
        bindings_table = self.link_layer_table_names()["case_time_series_bindings"]
        linkables = self._linkable("linkable_objects")

        association_rows = self.connection.execute(
            f"""
            SELECT association.linkable_object_id AS linkable_object_id,
                   linkable.project_id AS project_id
            FROM {associations_table} AS association
            JOIN {linkables} AS linkable
              ON linkable.id = association.linkable_object_id
            WHERE association.time_series_set_id = ?
              AND association.status = 'active'
            ORDER BY association.linkable_object_id
            """,
            (set_id,),
        ).fetchall()
        binding_rows = self.connection.execute(
            f"""
            SELECT binding.linkable_object_id AS linkable_object_id,
                   binding.case_input_variant_id AS case_input_variant_id,
                   binding.set_revision_id AS set_revision_id,
                   linkable.project_id AS project_id
            FROM {bindings_table} AS binding
            JOIN {linkables} AS linkable
              ON linkable.id = binding.linkable_object_id
            WHERE binding.time_series_set_id = ? AND binding.status = 'active'
            ORDER BY binding.linkable_object_id, binding.id
            """,
            (set_id,),
        ).fetchall()

        on_current = sum(
            1
            for row in binding_rows
            if pointer is not None and row["set_revision_id"] == pointer
        )
        consumers: dict[int, dict[str, Any]] = {}
        for row in association_rows:
            consumers.setdefault(
                int(row["linkable_object_id"]),
                {
                    "linkable_object_id": int(row["linkable_object_id"]),
                    "project_id": int(row["project_id"]),
                    "relation": "association_only",
                },
            )
        for row in binding_rows:
            observed = (
                "current"
                if pointer is not None and row["set_revision_id"] == pointer
                else "pinned"
            )
            consumer = consumers.setdefault(
                int(row["linkable_object_id"]),
                {
                    "linkable_object_id": int(row["linkable_object_id"]),
                    "project_id": int(row["project_id"]),
                    "relation": observed,
                },
            )
            # A pinned consumer is the louder fact, so it keeps the label.
            if consumer["relation"] != "pinned":
                consumer["relation"] = observed
        listed = [consumers[key] for key in sorted(consumers)]
        content_hash = None if set_row is None else set_row["current_content_hash"]
        return {
            "source": {
                "set_id": set_id,
                "set_name": None if set_row is None else set_row["name"],
                "visibility_scope": (
                    None if set_row is None else set_row["visibility_scope"]
                ),
                "owner_project_id": (
                    None if set_row is None else int(set_row["owner_project_id"])
                ),
                "owner_project_name": (
                    None if set_row is None else set_row["owner_project_name"]
                ),
                "current_revision_id": None if pointer is None else int(pointer),
                "current_revision_number": (
                    None
                    if set_row is None or set_row["current_revision_number"] is None
                    else int(set_row["current_revision_number"])
                ),
                "current_content_hash": (
                    None if content_hash is None else f"sha256:{content_hash}"
                ),
                "signal_count": len(
                    self._shared_source_signals(set_id=set_id, revision_id=pointer)
                ),
            },
            "associations": {
                "total": len(association_rows),
                "other_objects": len(
                    {
                        int(row["linkable_object_id"])
                        for row in association_rows
                        if int(row["linkable_object_id"]) != owner_object_id
                    }
                ),
            },
            "bindings": {
                "total_active": len(binding_rows),
                "current": on_current,
                "pinned": len(binding_rows) - on_current,
                "projects_affected": len(
                    {int(row["project_id"]) for row in binding_rows}
                ),
                "variants_affected": len(
                    {int(row["case_input_variant_id"]) for row in binding_rows}
                ),
            },
            "effect": {
                # Publishing never moves a binding in silence: the ones that
                # followed the pointer and the pinned ones both go stale (7.10).
                "bindings_will_become_stale": len(binding_rows),
                "associations_will_require_revalidation": (
                    len(association_rows) if contract_changes else 0
                ),
            },
            "listed_consumers": listed[:SHARED_CONSUMER_SAMPLE_LIMIT],
            "consumers_truncated": len(listed) > SHARED_CONSUMER_SAMPLE_LIMIT,
        }

    def _shared_publication_authority(
        self, *, association: Mapping[str, Any], actor_role: str
    ) -> dict[str, Any]:
        """Opening the flow never grants the right to publish (chapter 7.9)."""

        role = str(actor_role or "analyst").strip().lower()
        requires_admin = association["visibility_scope"] == "global"
        if role == "external":
            return {
                "may_publish": False,
                "requires_admin": requires_admin,
                "refusal": "TS_INGEST_FORBIDDEN",
            }
        if requires_admin and role != "admin":
            return {
                "may_publish": False,
                "requires_admin": True,
                "refusal": "TS_SHARED_REVISION_ADMIN_REQUIRED",
            }
        if role not in {"admin", "analyst"}:
            return {
                "may_publish": False,
                "requires_admin": requires_admin,
                "refusal": "TS_INGEST_FORBIDDEN",
            }
        return {"may_publish": True, "requires_admin": requires_admin, "refusal": None}

    def _shared_target_links(
        self, *, project_id: int, linkable_object_id: int, association_id: int
    ) -> dict[str, str]:
        root = (
            f"/api/projects/{int(project_id)}/linkable-objects/"
            f"{int(linkable_object_id)}/time-series/catalog-associations/"
            f"{int(association_id)}"
        )
        return {
            "detail": root,
            "catalog_detail": (
                f"/api/time-series/catalog/associations/{int(association_id)}"
            ),
            "shared_point_ingestions": (
                f"{root}/shared-series/revision-ingestions/points"
            ),
            "derivation_prevalidations": (
                f"{root}/object-series-derivation-prevalidations"
            ),
            "derivations": f"{root}/object-series-derivations",
        }

    def _shared_decision_view(
        self,
        *,
        linkable: Mapping[str, Any],
        association: Mapping[str, Any],
        actor_role: str,
        intent: str,
        contract_changes: bool = False,
        payload_incomplete: bool = False,
    ) -> dict[str, Any]:
        """Impact, recommendation and the two ordered outcomes (chapter 8.6)."""

        impact = self._shared_source_impact(
            association=association, contract_changes=contract_changes
        )
        authority = self._shared_publication_authority(
            association=association, actor_role=actor_role
        )
        signals = self._shared_source_signals(
            set_id=int(association["time_series_set_id"]),
            revision_id=impact["source"]["current_revision_id"],
        )
        blocking: list[str] = []
        if not authority["may_publish"]:
            blocking.append(authority["refusal"])
        if association["status"] != "active":
            blocking.append("TS_OBJECT_SERIES_NOT_FOUND")
        if payload_incomplete:
            # One association never authorizes a partial revision of a
            # multi-signal set (chapter 7.9).
            blocking.append("TS_INGEST_SIGNAL_SET_INCOMPLETE")
        derivation_required = bool(blocking)
        links = self._shared_target_links(
            project_id=int(linkable["project_id"]),
            linkable_object_id=int(linkable["id"]),
            association_id=int(association["id"]),
        )
        alternatives = shared_decision_alternatives(
            derivation_href=links["derivation_prevalidations"],
            shared_href=links["shared_point_ingestions"],
            derivation_required=derivation_required,
            may_publish_shared=(
                authority["may_publish"] and association["status"] == "active"
            ),
            requires_admin=authority["requires_admin"],
            intent=intent,
        )
        recommendation = (
            "derive_object_specific"
            if derivation_required
            or (
                impact["associations"]["other_objects"] > 0
                and str(intent).strip().lower() == "local"
            )
            else "publish_shared"
        )
        return {
            "impact": impact,
            "impact_fingerprint": shared_impact_fingerprint(impact),
            "recommendation": recommendation,
            "requires_confirmation": True,
            "derivation_required": derivation_required,
            "derivation_required_codes": blocking,
            "alternatives": alternatives,
            "set_signals": [
                {
                    "signal_id": int(signal["signal_id"]),
                    "series_key": signal["series_key"],
                    "display_name": signal["display_name"],
                    "semantic_type_key": signal["semantic_type_key"],
                    "unit_key": signal["unit_key"],
                }
                for signal in signals
            ],
            "links": links,
        }

    def read_object_catalog_association(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        association_id: int,
        actor_role: str = "analyst",
        intent: str = "shared",
    ) -> dict[str, Any]:
        """The contextual view of one generic association, with its impact.

        Chapter 8.6 requires the whole impact to be visible **before** the
        caller decides, so this read already answers scope, owner, current
        revision, associations, other objects and projects, and the bindings
        that would go stale (AC-SHR-01).
        """

        with self._read_only_transaction():
            linkable = self.authorize_object_series_root(
                project_id=project_id, linkable_object_id=linkable_object_id
            )
            association = self._shared_source_association(
                linkable=linkable, association_id=association_id
            )
            view = self._shared_decision_view(
                linkable=linkable,
                association=association,
                actor_role=actor_role,
                intent=intent,
            )
        return {
            "association": {
                "association_id": int(association["id"]),
                "signal_id": int(association["signal_id"]),
                "set_id": int(association["time_series_set_id"]),
                "series_key": association["series_key"],
                "display_name": association["signal_display_name"],
                "binding_role_key": association["role_key"],
                "status": association["status"],
                "linkable_object_id": int(association["linkable_object_id"]),
                "project_id": int(linkable["project_id"]),
            },
            **view,
            "capabilities": {
                "publish_shared": any(
                    alternative["kind"] == "publish_shared"
                    and alternative["available"]
                    for alternative in view["alternatives"]
                ),
                "derive_object_specific": association["status"] == "active",
                "preview_source": association["set_status"] != "archived",
            },
        }

    def _require_shared_target(
        self,
        *,
        linkable: Mapping[str, Any],
        association: Mapping[str, Any],
        actor_role: str,
    ) -> dict[str, Any]:
        """Everything ``SHARED_TARGET`` demands before it looks at a payload.

        Chapter 7.9: an archived, incompatible or foreign association does not
        open the flow, and opening the flow is not permission to publish. The
        authority check runs before the source is read, so an `analyst` on a
        `global` set is refused without learning anything else (AC-SHR-05).
        """

        if linkable["status"] != "active":
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND", detail="the object is archived"
            )
        if association["status"] != "active":
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="an archived association does not open the shared flow",
                association_id=int(association["id"]),
            )
        if association["role_status"] != "active":
            raise ObjectSeriesError(
                "TS_COMPAT_ROLE_NOT_ALLOWED",
                detail="the binding role of the association is not active",
                binding_role_key=association["role_key"],
            )
        authority = self._shared_publication_authority(
            association=association, actor_role=actor_role
        )
        if not authority["may_publish"]:
            raise ObjectSeriesError(
                authority["refusal"],
                detail=(
                    "a global source is published only by an administrator"
                    if authority["refusal"] == "TS_SHARED_REVISION_ADMIN_REQUIRED"
                    else "this actor may not publish on the shared source"
                ),
                visibility_scope=association["visibility_scope"],
                required_role="admin" if authority["requires_admin"] else "analyst",
            )
        if (
            association["set_status"] == "archived"
            or association["signal_status"] == "archived"
        ):
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND", detail="the shared source is archived"
            )
        set_row = self._shared_source_set(int(association["time_series_set_id"]))
        if set_row is None or set_row["current_revision_id"] is None:
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="the shared source has no sealed revision",
            )
        signals = self._shared_source_signals(
            set_id=int(association["time_series_set_id"]),
            revision_id=int(set_row["current_revision_id"]),
        )
        if not any(
            int(signal["signal_id"]) == int(association["signal_id"])
            for signal in signals
        ):
            # Signal, role and object must all still match; a stale association
            # is not a mutation base (chapter 7.4).
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="the association does not match a signal of the current revision",
                association_id=int(association["id"]),
            )
        return {"set": set_row, "signals": signals, "authority": authority}

    def _shared_ingestion_contract(
        self,
        *,
        association: Mapping[str, Any],
        set_row: Mapping[str, Any],
        document: Mapping[str, Any],
    ) -> dict[str, Any]:
        """The contract the shared revision declares, defaulted from the source."""

        declared = document.get("revision_contract") or {}
        if not isinstance(declared, Mapping):
            raise ObjectSeriesError(
                "TS_INGEST_VALIDATION_FAILED",
                detail="revision_contract must be an object",
            )
        revision = self.connection.execute(
            f"""
            SELECT revision.timezone, revision.timestamp_convention,
                   data_class.id AS data_class_id,
                   data_class.data_class_key AS data_class_key
            FROM {self._canonical('time_series_set_revisions')} AS revision
            JOIN time_series_data_classes AS data_class
              ON data_class.id = revision.data_class_id
            WHERE revision.id = ?
            """,
            (int(set_row["current_revision_id"]),),
        ).fetchone()
        entry = self.connection.execute(
            f"""
            SELECT regularity, nominal_resolution_seconds
            FROM {self._projection('time_series_catalog_entries')}
            WHERE signal_id = ?
            """,
            (int(association["signal_id"]),),
        ).fetchone()
        data_class_key = str(
            declared.get("data_class_key") or revision["data_class_key"]
        ).strip()
        data_class = self.connection.execute(
            """
            SELECT id, data_class_key, status FROM time_series_data_classes
            WHERE data_class_key = ?
            """,
            (data_class_key,),
        ).fetchone()
        if data_class is None or data_class["status"] != "active":
            raise ObjectSeriesError(
                "TS_INGEST_VALIDATION_FAILED",
                detail="the declared data class is unknown",
                errors=[
                    {
                        "code": "TS_INGEST_TEMPORAL_CONTRACT_INVALID",
                        "message": "unknown data_class_key",
                        "location": {
                            "record_index": 0,
                            "json_pointer": "/revision_contract/data_class_key",
                        },
                    }
                ],
            )
        regularity = str(
            declared.get("regularity")
            or (None if entry is None else entry["regularity"])
            or "regular"
        ).strip()
        if regularity not in {"regular", "irregular"}:
            raise ObjectSeriesError(
                "TS_INGEST_VALIDATION_FAILED",
                detail="the declared regularity is unknown",
            )
        resolution = declared.get(
            "nominal_resolution_seconds",
            None if entry is None else entry["nominal_resolution_seconds"],
        )
        timezone_name = str(declared.get("timezone") or revision["timezone"]).strip()
        return {
            "data_class_id": int(data_class["id"]),
            "data_class_key": data_class["data_class_key"],
            "timezone": timezone_name,
            "timestamp_convention": revision["timestamp_convention"],
            "regularity": regularity,
            "nominal_resolution_seconds": (
                None if resolution is None else float(resolution)
            ),
            # A contract change is not forbidden, but it is not silent either:
            # chapter 7.9 makes the associations it would stale part of the
            # impact the caller confirms.
            "changed": (
                data_class["data_class_key"] != revision["data_class_key"]
                or timezone_name != revision["timezone"]
            ),
        }

    def _shared_content_hash(
        self,
        *,
        signals: list[dict[str, Any]],
        contract: Mapping[str, Any],
        periods: list[dict[str, Any]],
        values: list[dict[str, Any]],
    ) -> str:
        """The canonical hash of a multi-signal snapshot that is not written yet."""

        digest = CanonicalContentHash(
            timezone=contract["timezone"],
            timestamp_convention=contract["timestamp_convention"],
            data_class_key=contract["data_class_key"],
        )
        ordinals: dict[str, int] = {}
        for ordinal, signal in enumerate(signals):
            ordinals[signal["series_key"]] = ordinal
            digest.add_signal(
                ordinal=ordinal,
                series_key=signal["series_key"],
                semantic_type_key=signal["semantic_type_key"],
                unit_key=signal["unit_key"],
                data_class_key=contract["data_class_key"],
                signal_role=signal["signal_role"],
                aggregation=signal["aggregation"],
            )
        for period in periods:
            digest.add_period(
                period_index=period["period_index"],
                timestamp_start=period["timestamp_start"],
                timestamp_end=period["timestamp_end"],
                duration_hours=period["duration_hours"],
            )
        for value in sorted(
            values,
            key=lambda entry: (
                ordinals.get(entry["series_key"], 0),
                entry["period_index"],
            ),
        ):
            digest.add_value(
                ordinal=ordinals.get(value["series_key"], 0),
                period_index=value["period_index"],
                value=value["value"],
            )
        return digest.seal()

    def prepare_shared_series_points_ingestion(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        association_id: int,
        document: Mapping[str, Any],
        actor: str,
        actor_role: str,
        intent: str = "shared",
    ) -> dict[str, Any]:
        """Validate and stage a shared generic revision started from an object.

        Nothing is published here: the job carries the impact the caller must
        confirm, and the confirmation is a second, separate transaction
        (chapters 7.9 and 8.6).
        """

        with self._lock:
            with self._database_transaction():
                linkable = self.authorize_object_series_root(
                    project_id=project_id, linkable_object_id=linkable_object_id
                )
                association = self._shared_source_association(
                    linkable=linkable, association_id=association_id
                )
                target = self._require_shared_target(
                    linkable=linkable, association=association, actor_role=actor_role
                )
                receipt, refusal = self._stage_shared_series_points(
                    linkable=linkable,
                    association=association,
                    set_row=target["set"],
                    signals=target["signals"],
                    document=document,
                    actor=actor,
                    actor_role=actor_role,
                    intent=intent,
                )
            # An invalid job still commits so its errors can be read and the
            # same job corrected (chapter 7.4); the refusal follows it.
            if refusal is not None:
                raise refusal
            return receipt

    def _stage_shared_series_points(
        self,
        *,
        linkable: Mapping[str, Any],
        association: Mapping[str, Any],
        set_row: Mapping[str, Any],
        signals: list[dict[str, Any]],
        document: Mapping[str, Any],
        actor: str,
        actor_role: str,
        intent: str,
    ) -> tuple[dict[str, Any], ObjectSeriesError | None]:
        mode = str(document.get("mode") or "replace_full").strip()
        if mode not in {"replace_full", "append_tail"}:
            raise ObjectSeriesError(
                "TS_INGEST_VALIDATION_FAILED", detail="mode is not supported"
            )
        contract = self._shared_ingestion_contract(
            association=association, set_row=set_row, document=document
        )
        current = self.connection.execute(
            f"""
            SELECT id, revision_number, content_hash
            FROM {self._canonical('time_series_set_revisions')} WHERE id = ?
            """,
            (int(set_row["current_revision_id"]),),
        ).fetchone()
        expected_base = document.get("expected_base")
        if not isinstance(expected_base, Mapping):
            raise ObjectSeriesError(
                "TS_INGEST_PRECONDITION_REQUIRED",
                detail="expected_base must name the exact current revision",
                field="expected_base",
            )
        declared_hash = str(expected_base.get("content_hash") or "").split(":")[-1]
        if (
            int(expected_base.get("revision_id") or 0) != int(current["id"])
            or declared_hash != current["content_hash"]
        ):
            raise ObjectSeriesError(
                "TS_INGEST_PRECONDITION_CHANGED",
                detail="the declared base is not the current revision",
                current_revision_id=int(current["id"]),
            )

        series_keys = tuple(signal["series_key"] for signal in signals)
        normalized = normalize_points_payload(
            document, series_keys=series_keys, mapping={}
        )
        errors = list(normalized["errors"])
        periods = normalized["periods"]
        values = normalized["values"]

        if mode == "append_tail" and not errors:
            base_snapshot = self._object_series_snapshot(int(current["id"]))
            base_periods = base_snapshot["periods"]
            coverage_end = base_periods[-1]["timestamp_end"] if base_periods else None
            if periods and coverage_end is not None:
                if periods[0]["timestamp_start"] < coverage_end:
                    raise ObjectSeriesError(
                        "TS_INGEST_APPEND_CONFLICT",
                        detail="the tail overlaps the current coverage",
                    )
                if (
                    contract["regularity"] == "regular"
                    and periods[0]["timestamp_start"] != coverage_end
                ):
                    raise ObjectSeriesError(
                        "TS_INGEST_APPEND_CONFLICT",
                        detail="a regular tail must start where the coverage ends",
                    )
            offset = len(base_periods)
            periods = base_periods + [
                {**period, "period_index": period["period_index"] + offset}
                for period in periods
            ]
            values = base_snapshot["values"] + [
                {**value, "period_index": value["period_index"] + offset}
                for value in values
            ]

        errors.extend(check_temporal_contract(periods, contract=contract))
        content_hash = (
            None
            if errors
            else self._shared_content_hash(
                signals=signals, contract=contract, periods=periods, values=values
            )
        )
        state = "ready_to_publish" if not errors else "invalid"
        now = utc_now_iso()
        ingestion_key = new_ingestion_key()
        ingestion_id = self._insert_canonical_row(
            f"""
            INSERT INTO {self._object_series_table('time_series_ingestions')} (
                ingestion_key, project_id, linkable_object_id, time_series_set_id,
                signal_id, catalog_association_id, target_kind, channel, state,
                mode, actor, base_revision_id, base_content_hash, contract_json,
                source_json, mapping_json, submitted_json, normalized_json,
                validation_json, payload_checksum, content_hash, created_at,
                updated_at, expires_at
            ) VALUES (?, ?, ?, ?, ?, ?, 'catalog_shared', 'api_points', ?, ?, ?,
                      ?, ?, ?, ?, '{{}}', ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                ingestion_key,
                int(linkable["project_id"]),
                int(linkable["id"]),
                int(association["time_series_set_id"]),
                int(association["signal_id"]),
                int(association["id"]),
                state,
                mode,
                actor,
                int(current["id"]),
                current["content_hash"],
                json.dumps(contract, sort_keys=True),
                json.dumps(document.get("source") or {}, sort_keys=True),
                json.dumps(document.get("points") or [], sort_keys=True),
                json.dumps(summarize_normalized(periods, values), sort_keys=True),
                json.dumps({"errors": errors}, sort_keys=True),
                payload_checksum(document.get("points") or []),
                content_hash,
                now,
                now,
                ingestion_expiry(now),
            ),
        )
        self._write_ingestion_staging(
            ingestion_id=ingestion_id, periods=periods, values=values
        )
        receipt = self._read_object_series_ingestion_row(
            ingestion_id, actor_role=actor_role, intent=intent
        )
        if errors:
            return receipt, ObjectSeriesError(
                "TS_INGEST_VALIDATION_FAILED",
                detail=f"{len(errors)} records require correction",
                errors=errors,
                ingestion=receipt,
            )
        return receipt, None

    def _resolve_shared_series_ingestion(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        association_id: int,
        ingestion_key: str,
    ):
        """Knowing the opaque id never skips authorization (AC-SEG-03)."""

        linkable = self.authorize_object_series_root(
            project_id=project_id, linkable_object_id=linkable_object_id
        )
        association = self._shared_source_association(
            linkable=linkable, association_id=association_id
        )
        ingestion = self._ingestion_row_by_key(ingestion_key)
        if (
            ingestion is None
            or ingestion["target_kind"] != "catalog_shared"
            or ingestion["catalog_association_id"] is None
            or int(ingestion["catalog_association_id"]) != int(association["id"])
            or int(ingestion["linkable_object_id"]) != int(linkable["id"])
            or int(ingestion["project_id"]) != int(linkable["project_id"])
        ):
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="no ingestion with that id belongs to this target",
            )
        return linkable, association, ingestion

    def read_shared_series_ingestion(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        association_id: int,
        ingestion_key: str,
        actor_role: str = "analyst",
        intent: str = "shared",
    ) -> dict[str, Any]:
        _, _, ingestion = self._resolve_shared_series_ingestion(
            project_id=project_id,
            linkable_object_id=linkable_object_id,
            association_id=association_id,
            ingestion_key=ingestion_key,
        )
        return self._read_object_series_ingestion_row(
            int(ingestion["id"]), actor_role=actor_role, intent=intent
        )

    def read_shared_series_ingestion_preview(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        association_id: int,
        ingestion_key: str,
        max_rows: int | None = None,
    ) -> dict[str, Any]:
        """A bounded normalized sample of what is staged - never a download."""

        _, association, ingestion = self._resolve_shared_series_ingestion(
            project_id=project_id,
            linkable_object_id=linkable_object_id,
            association_id=association_id,
            ingestion_key=ingestion_key,
        )
        if ingestion["state"] == "cancelled":
            raise ObjectSeriesError(
                "TS_INGEST_SESSION_UNAVAILABLE", detail="the job was cancelled"
            )
        limit = INGESTION_PREVIEW_MAX_ROWS if max_rows is None else int(max_rows)
        if limit < 1 or limit > INGESTION_PREVIEW_MAX_ROWS:
            raise ObjectSeriesError(
                "TS_QUERY_INVALID",
                field="max_rows",
                detail="max_rows is out of range",
                maximum=INGESTION_PREVIEW_MAX_ROWS,
            )
        staging = self._read_ingestion_staging(int(ingestion["id"]))
        by_period: dict[int, list[dict[str, Any]]] = {}
        for value in staging["values"]:
            by_period.setdefault(value["period_index"], []).append(value)
        rows = []
        for period in staging["periods"][:limit]:
            for value in sorted(
                by_period.get(period["period_index"], []),
                key=lambda entry: entry["series_key"],
            ):
                rows.append(
                    {
                        "period_index": period["period_index"],
                        "timestamp_start": utc_presentation(period["timestamp_start"]),
                        "timestamp_end": utc_presentation(period["timestamp_end"]),
                        "series_key": value["series_key"],
                        "value": value["value"],
                        "quality_flag": value["quality_flag"],
                    }
                )
        return {
            "ingestion_id": ingestion["ingestion_key"],
            "set_id": int(association["time_series_set_id"]),
            "source_row_count": len(staging["periods"]),
            "returned_row_count": len(rows),
            "max_rows": limit,
            "rows": rows,
        }

    def cancel_shared_series_ingestion(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        association_id: int,
        ingestion_key: str,
        actor: str,
    ) -> None:
        with self._lock:
            with self._database_transaction():
                _, _, ingestion = self._resolve_shared_series_ingestion(
                    project_id=project_id,
                    linkable_object_id=linkable_object_id,
                    association_id=association_id,
                    ingestion_key=ingestion_key,
                )
                if ingestion["state"] == "published":
                    raise ObjectSeriesError(
                        "TS_INGEST_SESSION_UNAVAILABLE",
                        detail="a published job is not cancellable",
                    )
                self.connection.execute(
                    f"""
                    UPDATE {self._object_series_table('time_series_ingestions')}
                    SET state = 'cancelled', submitted_json = '[]', updated_at = ?
                    WHERE id = ?
                    """,
                    (utc_now_iso(), int(ingestion["id"])),
                )
                self._write_ingestion_staging(
                    ingestion_id=int(ingestion["id"]), periods=[], values=[]
                )

    def publish_shared_series_ingestion(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        association_id: int,
        ingestion_key: str,
        validation_token: str,
        confirm: bool,
        comprehension_acknowledged: bool,
        impact_fingerprint: str,
        reason_code: str,
        reason_text: str,
        if_match: str,
        idempotency_key: str,
        actor: str,
        actor_role: str,
    ) -> tuple[dict[str, Any], bool]:
        """Publish for everyone, in one transaction, once (chapters 7.9, 9.7)."""

        with self._lock:
            with self._database_transaction():
                linkable, association, ingestion = (
                    self._resolve_shared_series_ingestion(
                        project_id=project_id,
                        linkable_object_id=linkable_object_id,
                        association_id=association_id,
                        ingestion_key=ingestion_key,
                    )
                )
                target = self._require_shared_target(
                    linkable=linkable, association=association, actor_role=actor_role
                )
                try:
                    claim = self._claim_idempotency(
                        actor_id=actor,
                        operation_kind=PUBLISH_SHARED_OPERATION_KIND,
                        scope_key=(
                            f"shared-series:{int(association['time_series_set_id'])}"
                        ),
                        idempotency_key=idempotency_key,
                        request_hash=idempotency_request_hash(
                            {
                                "ingestion_key": ingestion["ingestion_key"],
                                "content_hash": ingestion["content_hash"],
                                "base_revision_id": ingestion["base_revision_id"],
                                "if_match": if_match,
                                "confirm": bool(confirm),
                                "impact_fingerprint": impact_fingerprint,
                                "reason_code": reason_code,
                            }
                        ),
                    )
                except CanonicalRevisionError as error:
                    if error.code == "TS_IDEMPOTENCY_KEY_CONFLICT":
                        raise ObjectSeriesError(
                            "TS_INGEST_IDEMPOTENCY_CONFLICT",
                            detail="the key was already used for another payload",
                            idempotency_key=idempotency_key,
                        ) from error
                    raise
                if claim["state"] == "completed":
                    return claim["response"], True
                receipt = self._publish_shared_series_revision(
                    linkable=linkable,
                    association=association,
                    target=target,
                    ingestion=ingestion,
                    validation_token=validation_token,
                    confirm=confirm,
                    comprehension_acknowledged=comprehension_acknowledged,
                    impact_fingerprint=impact_fingerprint,
                    reason_code=reason_code,
                    reason_text=reason_text,
                    if_match=if_match,
                    actor=actor,
                    actor_role=actor_role,
                )
                self._complete_idempotency(
                    claim_id=claim["id"],
                    response=receipt,
                    http_status=200 if receipt["outcome"] == "unchanged" else 201,
                )
                return receipt, False

    def _publish_shared_series_revision(
        self,
        *,
        linkable: Mapping[str, Any],
        association: Mapping[str, Any],
        target: Mapping[str, Any],
        ingestion: Mapping[str, Any],
        validation_token: str,
        confirm: bool,
        comprehension_acknowledged: bool,
        impact_fingerprint: str,
        reason_code: str,
        reason_text: str,
        if_match: str,
        actor: str,
        actor_role: str,
    ) -> dict[str, Any]:
        set_row = target["set"]
        signals = target["signals"]
        set_id = int(association["time_series_set_id"])
        if ingestion["state"] in {"cancelled", "published"}:
            raise ObjectSeriesError(
                "TS_INGEST_SESSION_UNAVAILABLE",
                detail="the job is not publishable any more",
                state=ingestion["state"],
            )
        if ingestion["state"] != "ready_to_publish" or ingestion["content_hash"] is None:
            raise ObjectSeriesError(
                "TS_INGEST_VALIDATION_FAILED",
                detail="the job has not validated cleanly",
                errors=json.loads(ingestion["validation_json"] or "{}").get(
                    "errors", []
                ),
            )
        if ingestion["expires_at"] <= utc_now_iso():
            raise ObjectSeriesError(
                "TS_INGEST_SESSION_UNAVAILABLE", detail="the job expired"
            )
        expected_token = ingestion_validation_token(
            ingestion_key=ingestion["ingestion_key"],
            content_hash=ingestion["content_hash"],
            secret=self._catalog_cursor_secret,
        )
        if str(validation_token or "").strip() != expected_token:
            raise ObjectSeriesError(
                "TS_INGEST_PRECONDITION_CHANGED",
                detail="the validation token does not describe this content",
            )
        if not str(reason_code or "").strip():
            raise ObjectSeriesError(
                "TS_INGEST_PRECONDITION_REQUIRED",
                detail="reason_code is required",
                field="reason_code",
            )
        contract = json.loads(ingestion["contract_json"] or "{}")
        impact = self._shared_source_impact(
            association=association, contract_changes=bool(contract.get("changed"))
        )
        if not confirm or not comprehension_acknowledged:
            # Chapter 8.6 asks for permission, reason, comprehension mark and a
            # final review that repeats the impact (AC-SHR-04).
            raise ObjectSeriesError(
                "TS_SHARED_REVISION_CONFIRMATION_REQUIRED",
                detail="publishing for everyone needs an explicit confirmation",
                impact=impact,
                impact_fingerprint=shared_impact_fingerprint(impact),
                missing=(
                    "confirm" if not confirm else "comprehension_acknowledged"
                ),
            )
        expected_etag = shared_source_etag(
            set_id=set_id, current_revision_id=set_row["current_revision_id"]
        )
        if str(if_match or "").strip() != expected_etag:
            raise ObjectSeriesError(
                "TS_INGEST_PRECONDITION_CHANGED",
                detail="the shared source changed since the ETag was read",
                expected=expected_etag,
                requires_new_confirmation=True,
            )
        if int(set_row["current_revision_id"]) != int(ingestion["base_revision_id"]):
            raise ObjectSeriesError(
                "TS_INGEST_PRECONDITION_CHANGED",
                detail="the current revision moved since the batch validated",
                requires_new_confirmation=True,
            )
        observed_fingerprint = shared_impact_fingerprint(impact)
        if str(impact_fingerprint or "").strip() != observed_fingerprint:
            # AC-SHR-06: any movement between preview and confirmation blocks
            # the action and demands a fresh confirmation.
            raise ObjectSeriesError(
                "TS_INGEST_PRECONDITION_CHANGED",
                detail="the impact changed since it was previewed",
                impact=impact,
                impact_fingerprint=observed_fingerprint,
                requires_new_confirmation=True,
            )

        staged = self._read_ingestion_staging(int(ingestion["id"]))
        now = utc_now_iso()
        receipt = self._publish_canonical_set_revision(
            project_id=int(set_row["owner_project_id"]),
            name=set_row["name"],
            signals=normalize_canonical_signals(
                [
                    {
                        "series_key": signal["series_key"],
                        "display_name": signal["display_name"],
                        "semantic_type_key": signal["semantic_type_key"],
                        "unit_key": signal["unit_key"],
                        "signal_role": signal["signal_role"],
                        "aggregation": signal["aggregation"],
                    }
                    for signal in signals
                ]
            ),
            periods=normalize_canonical_periods(staged["periods"]),
            values=staged["values"],
            data_class_key=contract["data_class_key"],
            revision_timezone=contract["timezone"],
            timestamp_convention=contract["timestamp_convention"],
            version_label=None,
            description="",
            source={
                **json.loads(ingestion["source_json"] or "{}"),
                "source_key": f"shared-series:{ingestion['ingestion_key']}",
                "checksum": ingestion["payload_checksum"],
            },
            change_summary=reason_code,
            metadata={
                "shared_revision": {
                    "association_id": int(association["id"]),
                    "linkable_object_id": int(linkable["id"]),
                    "reason_code": reason_code,
                    "reason_text": reason_text,
                    "confirmed_impact_fingerprint": observed_fingerprint,
                }
            },
            lineage=[],
            actor=actor,
            set_id=set_id,
        )
        if receipt["content_hash"] != ingestion["content_hash"]:
            raise ObjectSeriesError(
                "TS_INGEST_PRECONDITION_CHANGED",
                detail="the stored snapshot does not match the validated hash",
            )
        self._close_object_series_ingestion(
            ingestion_id=int(ingestion["id"]),
            revision_id=int(receipt["revision_id"]),
            now=now,
        )
        # The stale states stay visible and unresolved: publication and binding
        # replacement are separate transactions (AC-SHR-08, chapter 7.10).
        after = self._shared_source_impact(association=association)
        return {
            "outcome": receipt["outcome"],
            "set_id": set_id,
            "association_id": int(association["id"]),
            "revision_id": int(receipt["revision_id"]),
            "revision_number": int(receipt["revision_number"]),
            "state": "sealed",
            "content_hash": f"sha256:{receipt['content_hash']}",
            "signal_ids": receipt["signal_ids"],
            "source": {
                "kind": json.loads(ingestion["source_json"] or "{}").get("kind", "api"),
                "checksum": ingestion["payload_checksum"],
            },
            "reason": {"code": reason_code, "text": reason_text},
            "confirmed_impact": impact,
            "staleness": {
                "bindings_now_stale": impact["effect"]["bindings_will_become_stale"],
                "bindings_still_stale": after["bindings"]["total_active"],
                "resolved_in_this_action": 0,
                "resolution_required": (
                    impact["effect"]["bindings_will_become_stale"] > 0
                ),
            },
            "etag": shared_source_etag(
                set_id=set_id, current_revision_id=int(receipt["revision_id"])
            ),
            "impact_after": after,
            "impact_fingerprint_after": shared_impact_fingerprint(after),
        }

    # -- Deriving a local copy instead of touching the shared source -------
    #
    # Chapter 7.9. Deriving is the safe outcome: it creates a local identity by
    # copy, with lineage, and it neither modifies the shared source nor
    # reassigns the associations and bindings that already exist.

    def _derivation_source(
        self, *, association: Mapping[str, Any]
    ) -> dict[str, Any]:
        """The exact revision and hash the copy is pinned to (chapter 7.9)."""

        set_row = self._shared_source_set(int(association["time_series_set_id"]))
        if set_row is None or set_row["current_revision_id"] is None:
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="the shared source has no sealed revision to copy",
            )
        revision = self.connection.execute(
            f"""
            SELECT revision.id, revision.revision_number, revision.content_hash,
                   revision.timezone, revision.timestamp_convention,
                   data_class.data_class_key AS data_class_key
            FROM {self._canonical('time_series_set_revisions')} AS revision
            JOIN time_series_data_classes AS data_class
              ON data_class.id = revision.data_class_id
            WHERE revision.id = ?
            """,
            (int(set_row["current_revision_id"]),),
        ).fetchone()
        signal = self.connection.execute(
            f"""
            SELECT signal.id AS signal_id, signal.series_key,
                   signal.display_name, signal.description,
                   semantic_type.semantic_key AS semantic_type_key,
                   unit.unit_key AS unit_key,
                   revision_signal.aggregation AS aggregation
            FROM {self._canonical('time_series_revision_signals')} AS revision_signal
            JOIN {self._canonical('time_series_signals')} AS signal
              ON signal.id = revision_signal.signal_id
            JOIN time_series_semantic_types AS semantic_type
              ON semantic_type.id = revision_signal.semantic_type_id
            JOIN measurement_units AS unit ON unit.id = revision_signal.unit_id
            WHERE revision_signal.set_revision_id = ? AND revision_signal.signal_id = ?
            """,
            (int(revision["id"]), int(association["signal_id"])),
        ).fetchone()
        if signal is None:
            raise ObjectSeriesError(
                "TS_OBJECT_SERIES_NOT_FOUND",
                detail="the association does not match a signal of the current revision",
                association_id=int(association["id"]),
            )
        entry = self.connection.execute(
            f"""
            SELECT regularity, nominal_resolution_seconds, coverage_start,
                   coverage_end, period_count
            FROM {self._projection('time_series_catalog_entries')}
            WHERE signal_id = ?
            """,
            (int(association["signal_id"]),),
        ).fetchone()
        return {
            "set": set_row,
            "revision": revision,
            "signal": signal,
            "entry": entry,
        }

    def _derived_definition_document(
        self,
        *,
        association: Mapping[str, Any],
        source: Mapping[str, Any],
        document: Mapping[str, Any],
    ) -> dict[str, Any]:
        """The local definition the copy will be born with.

        The classification is inherited from the source signal: a derivation
        that changed semantic type or unit would not be a copy (chapter 7.9).
        """

        signal = source["signal"]
        entry = source["entry"]
        return {
            "object_series_key": document.get("object_series_key"),
            "display_name": (
                document.get("display_name") or signal["display_name"]
            ),
            "description": (
                document.get("description") or signal["description"] or ""
            ),
            "intended_binding_role_key": (
                document.get("intended_binding_role_key") or association["role_key"]
            ),
            "semantic_type_key": signal["semantic_type_key"],
            "unit_key": signal["unit_key"],
            "data_class_key": source["revision"]["data_class_key"],
            "aggregation": signal["aggregation"],
            "timezone": source["revision"]["timezone"],
            "temporal_contract": {
                "regularity": (
                    "regular" if entry is None else entry["regularity"]
                ),
                "nominal_resolution_seconds": (
                    None if entry is None else entry["nominal_resolution_seconds"]
                ),
                "timestamp_convention": source["revision"]["timestamp_convention"],
            },
            "source_expectation": {
                "kind": "api",
                "display_name": f"Copia de {signal['series_key']}",
            },
            "metadata": document.get("metadata") or {},
        }

    def _derivation_view(
        self,
        *,
        linkable: Mapping[str, Any],
        association: Mapping[str, Any],
        source: Mapping[str, Any],
        proposed: Mapping[str, Any],
    ) -> dict[str, Any]:
        impact = self._shared_source_impact(association=association)
        links = self._shared_target_links(
            project_id=int(linkable["project_id"]),
            linkable_object_id=int(linkable["id"]),
            association_id=int(association["id"]),
        )
        entry = source["entry"]
        return {
            "source": {
                "set_id": int(association["time_series_set_id"]),
                "signal_id": int(association["signal_id"]),
                "series_key": source["signal"]["series_key"],
                "revision_id": int(source["revision"]["id"]),
                "revision_number": int(source["revision"]["revision_number"]),
                "content_hash": f"sha256:{source['revision']['content_hash']}",
                "visibility_scope": association["visibility_scope"],
                "owner_project_id": int(association["owner_project_id"]),
                "owner_project_name": association["owner_project_name"],
            },
            "proposed": {
                **{
                    key: proposed[key]
                    for key in (
                        "object_series_key",
                        "display_name",
                        "description",
                        "intended_binding_role_key",
                        "semantic_type_key",
                        "unit_key",
                        "data_class_key",
                        "timezone",
                        "temporal_contract",
                    )
                },
                "visibility_scope": "object_specific",
                "owner_linkable_object_id": int(linkable["id"]),
                "period_count": 0 if entry is None else int(entry["period_count"]),
                "coverage_start": (
                    None if entry is None else utc_presentation(entry["coverage_start"])
                ),
                "coverage_end": (
                    None if entry is None else utc_presentation(entry["coverage_end"])
                ),
            },
            "differences": [
                {
                    "field": "visibility_scope",
                    "before": association["visibility_scope"],
                    "after": "object_specific",
                },
                {
                    "field": "owner",
                    "before": f"project:{int(association['owner_project_id'])}",
                    "after": f"linkable_object:{int(linkable['id'])}",
                },
                {
                    "field": "consumers",
                    "before": impact["associations"]["total"],
                    "after": 0,
                },
            ],
            # Deriving never moves what already exists (AC-SHR-07).
            "reassignments": {"associations": 0, "bindings": 0},
            "impact": impact,
            "links": links,
        }

    def prevalidate_object_series_derivation(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        association_id: int,
        document: Mapping[str, Any],
    ) -> dict[str, Any]:
        """Compare the shared source with the local copy it would produce.

        Phase one of the two-phase derivation: it fixes the source revision and
        hash so the commit can refuse a source that moved underneath it.
        """

        with self._read_only_transaction():
            linkable = self.authorize_object_series_root(
                project_id=project_id, linkable_object_id=linkable_object_id
            )
            association = self._shared_source_association(
                linkable=linkable, association_id=association_id
            )
            if association["status"] != "active":
                raise ObjectSeriesError(
                    "TS_OBJECT_SERIES_NOT_FOUND",
                    detail="an archived association does not open the derivation",
                    association_id=int(association["id"]),
                )
            source = self._derivation_source(association=association)
            proposed = self._derived_definition_document(
                association=association, source=source, document=document
            )
            object_series_key = normalize_object_series_key(
                proposed["object_series_key"]
            )
            taken = self.connection.execute(
                f"""
                SELECT time_series_set_id
                FROM {self._object_series_table('object_series_definitions')}
                WHERE owner_linkable_object_id = ? AND object_series_key = ?
                """,
                (int(linkable["id"]), object_series_key),
            ).fetchone()
            view = self._derivation_view(
                linkable=linkable,
                association=association,
                source=source,
                proposed=proposed,
            )
        blockers = (
            []
            if taken is None
            else [
                {
                    "code": "TS_OBJECT_SERIES_KEY_CONFLICT",
                    "message": "the object already used this local key",
                    "location": {
                        "record_index": 0,
                        "json_pointer": "/object_series_key",
                    },
                }
            ]
        )
        return {
            **view,
            "can_commit": not blockers,
            "blockers": blockers,
            "requires_confirmation": True,
            "prevalidation_token": derivation_prevalidation_token(
                association_id=int(association["id"]),
                source_revision_id=int(source["revision"]["id"]),
                content_hash=source["revision"]["content_hash"],
                object_series_key=object_series_key,
                secret=self._catalog_cursor_secret,
            ),
        }

    def commit_object_series_derivation(
        self,
        *,
        project_id: int,
        linkable_object_id: int,
        association_id: int,
        document: Mapping[str, Any],
        actor: str,
        idempotency_key: str,
    ) -> tuple[dict[str, Any], bool]:
        """Create the local identity by copy, in one transaction (chapter 7.9)."""

        with self._lock:
            with self._database_transaction():
                linkable = self.authorize_object_series_root(
                    project_id=project_id, linkable_object_id=linkable_object_id
                )
                association = self._shared_source_association(
                    linkable=linkable, association_id=association_id
                )
                if association["status"] != "active":
                    raise ObjectSeriesError(
                        "TS_OBJECT_SERIES_NOT_FOUND",
                        detail="an archived association does not open the derivation",
                        association_id=int(association["id"]),
                    )
                if not bool(document.get("confirmed")):
                    raise ObjectSeriesError(
                        "TS_LINK_CONFIRMATION_REQUIRED",
                        detail="the derivation is confirmed explicitly",
                        association_id=int(association["id"]),
                    )
                if not str(document.get("reason_code") or "").strip():
                    raise ObjectSeriesError(
                        "TS_INGEST_PRECONDITION_REQUIRED",
                        detail="reason_code is required",
                        field="reason_code",
                    )
                source = self._derivation_source(association=association)
                proposed = self._derived_definition_document(
                    association=association, source=source, document=document
                )
                object_series_key = normalize_object_series_key(
                    proposed["object_series_key"]
                )
                declared = document.get("source_revision")
                declared_token = str(document.get("prevalidation_token") or "").strip()
                if not isinstance(declared, Mapping) and not declared_token:
                    # The derivation is a two-phase action: the commit names the
                    # exact revision and hash it compared (chapter 7.9).
                    raise ObjectSeriesError(
                        "TS_INGEST_PRECONDITION_REQUIRED",
                        detail="name the source revision the copy was compared with",
                        field="source_revision",
                    )
                if isinstance(declared, Mapping):
                    declared_hash = str(
                        declared.get("content_hash") or ""
                    ).split(":")[-1]
                    if (
                        int(declared.get("revision_id") or 0)
                        != int(source["revision"]["id"])
                        or declared_hash != source["revision"]["content_hash"]
                    ):
                        raise ObjectSeriesError(
                            "TS_INGEST_PRECONDITION_CHANGED",
                            detail="the shared source moved since it was compared",
                            current_revision_id=int(source["revision"]["id"]),
                        )
                expected_token = derivation_prevalidation_token(
                    association_id=int(association["id"]),
                    source_revision_id=int(source["revision"]["id"]),
                    content_hash=source["revision"]["content_hash"],
                    object_series_key=object_series_key,
                    secret=self._catalog_cursor_secret,
                )
                if declared_token and declared_token != expected_token:
                    raise ObjectSeriesError(
                        "TS_INGEST_PRECONDITION_CHANGED",
                        detail="the comparison no longer describes this source",
                    )
                try:
                    claim = self._claim_idempotency(
                        actor_id=actor,
                        operation_kind=DERIVE_OBJECT_SERIES_OPERATION_KIND,
                        scope_key=(
                            f"object-derivation:{int(linkable['id'])}"
                            f":{object_series_key}"
                        ),
                        idempotency_key=idempotency_key,
                        request_hash=idempotency_request_hash(
                            {
                                "association_id": int(association["id"]),
                                "source_revision_id": int(source["revision"]["id"]),
                                "content_hash": source["revision"]["content_hash"],
                                "object_series_key": object_series_key,
                                "reason_code": document.get("reason_code"),
                            }
                        ),
                    )
                except CanonicalRevisionError as error:
                    if error.code == "TS_IDEMPOTENCY_KEY_CONFLICT":
                        raise ObjectSeriesError(
                            "TS_INGEST_IDEMPOTENCY_CONFLICT",
                            detail="the key was already used for another payload",
                            idempotency_key=idempotency_key,
                        ) from error
                    raise
                if claim["state"] == "completed":
                    return claim["response"], True
                receipt = self._derive_object_series_from_catalog(
                    linkable=linkable,
                    association=association,
                    source=source,
                    proposed=proposed,
                    document=document,
                    actor=actor,
                )
                self._complete_idempotency(
                    claim_id=claim["id"], response=receipt, http_status=201
                )
                return receipt, False

    def _derive_object_series_from_catalog(
        self,
        *,
        linkable: Mapping[str, Any],
        association: Mapping[str, Any],
        source: Mapping[str, Any],
        proposed: Mapping[str, Any],
        document: Mapping[str, Any],
        actor: str,
    ) -> dict[str, Any]:
        source_revision_id = int(source["revision"]["id"])
        source_signal_id = int(association["signal_id"])
        signal_id = self._insert_object_series_definition(
            linkable=linkable, document=proposed, actor=actor
        )
        row = self._object_series_row(
            linkable_object_id=int(linkable["id"]), signal_id=signal_id
        )
        set_id = int(row["time_series_set_id"])
        revisions_table = self._canonical("time_series_set_revisions")
        building = self.connection.execute(
            f"""
            SELECT id, revision_number FROM {revisions_table}
            WHERE time_series_set_id = ? AND state = 'building'
            ORDER BY revision_number DESC LIMIT 1
            """,
            (set_id,),
        ).fetchone()
        revision_id = int(building["id"])
        revision_number = int(building["revision_number"])
        now = utc_now_iso()
        source_id, _ = self._register_canonical_source(
            int(linkable["project_id"]),
            {
                "kind": "api",
                "source_key": (
                    f"catalog-copy:{int(association['id'])}:{source_revision_id}"
                ),
                "checksum": source["revision"]["content_hash"],
                "display_name": f"Copia de {source['signal']['series_key']}",
            },
            actor,
            now,
        )
        self.connection.execute(
            f"""
            UPDATE {revisions_table}
            SET time_series_source_id = ?, change_summary = ?, metadata_json = ?,
                created_at = ?, created_by = ?
            WHERE id = ?
            """,
            (
                source_id,
                str(document.get("reason_code") or "catalog_object_specific_copy"),
                json.dumps(
                    {
                        "temporal_contract": proposed["temporal_contract"],
                        "reason_text": str(document.get("reason_text") or ""),
                        "derived_from": {
                            "association_id": int(association["id"]),
                            "set_id": int(association["time_series_set_id"]),
                            "signal_id": source_signal_id,
                            "revision_id": source_revision_id,
                            "content_hash": (
                                f"sha256:{source['revision']['content_hash']}"
                            ),
                        },
                    },
                    sort_keys=True,
                ),
                now,
                actor,
                revision_id,
            ),
        )

        # Copy only the periods and the values of the identified signal, even
        # when the source revision belongs to a multi-signal set (chapter 7.9).
        snapshot = self._object_series_snapshot(source_revision_id)
        periods = snapshot["periods"]
        values = [
            {**value, "series_key": row["object_series_key"]}
            for value in snapshot["values"]
            if value["series_key"] == source["signal"]["series_key"]
        ]
        periods_table = self._canonical("time_series_periods")
        self.connection.executemany(
            f"""
            INSERT INTO {periods_table} (
                set_revision_id, period_index, timestamp_start, timestamp_end,
                duration_hours
            ) VALUES (?, ?, ?, ?, ?)
            """,
            [
                (
                    revision_id,
                    period["period_index"],
                    period["timestamp_start"],
                    period["timestamp_end"],
                    period["duration_hours"],
                )
                for period in periods
            ],
        )
        period_ids = {
            int(entry["period_index"]): int(entry["id"])
            for entry in self.connection.execute(
                f"SELECT id, period_index FROM {periods_table} WHERE set_revision_id = ?",
                (revision_id,),
            ).fetchall()
        }
        self._insert_canonical_values(
            values_table=self._canonical("time_series_values"),
            revision_id=revision_id,
            values=values,
            signal_ids={row["object_series_key"]: signal_id},
            period_ids=period_ids,
        )
        content_hash = self._stream_canonical_content_hash(
            revision_id=revision_id,
            revision_timezone=proposed["timezone"],
            timestamp_convention=proposed["temporal_contract"]["timestamp_convention"],
            data_class_key=proposed["data_class_key"],
        )
        self.connection.execute(
            f"""
            UPDATE {revisions_table}
            SET state = 'sealed', content_hash = ?, validation_payload_json = ?
            WHERE id = ?
            """,
            (
                content_hash,
                json.dumps(
                    {
                        "signal_count": 1,
                        "period_count": len(periods),
                        "value_count": len(values),
                        "coverage_start": (
                            periods[0]["timestamp_start"] if periods else None
                        ),
                        "coverage_end": (
                            periods[-1]["timestamp_end"] if periods else None
                        ),
                    },
                    sort_keys=True,
                ),
                revision_id,
            ),
        )
        self.connection.execute(
            f"""
            UPDATE {self._canonical('time_series_sets')}
            SET current_revision_id = ?, content_hash = ?, status = 'validated',
                updated_at = ?, updated_by = ?
            WHERE id = ?
            """,
            (revision_id, content_hash, now, actor, set_id),
        )
        self.connection.execute(
            f"""
            INSERT INTO {self._canonical('time_series_revision_lineage')} (
                derived_set_revision_id, derived_signal_id, source_set_revision_id,
                source_signal_id, lineage_kind, source_content_hash,
                source_owner_linkable_object_id, target_owner_linkable_object_id,
                created_at, created_by, reason_code, reason_text
            ) VALUES (?, ?, ?, ?, 'catalog_object_specific_copy', ?, NULL, ?, ?, ?, ?, ?)
            """,
            (
                revision_id,
                signal_id,
                source_revision_id,
                source_signal_id,
                source["revision"]["content_hash"],
                int(linkable["id"]),
                now,
                actor,
                str(document.get("reason_code") or "catalog_object_specific_copy"),
                str(document.get("reason_text") or ""),
            ),
        )
        self._raise_catalog_generation(now=now)
        series = self._read_object_series(linkable=linkable, signal_id=signal_id)
        return {
            "outcome": "derived",
            "object_series": series,
            "lineage": {
                "kind": "catalog_object_specific_copy",
                "source_set_id": int(association["time_series_set_id"]),
                "source_signal_id": source_signal_id,
                "source_revision_id": source_revision_id,
                "source_content_hash": (
                    f"sha256:{source['revision']['content_hash']}"
                ),
                "derived_revision_id": revision_id,
                "derived_revision_number": revision_number,
            },
            # The source, its associations and its bindings are untouched.
            "reassignments": {"associations": 0, "bindings": 0},
            "source_unchanged": {
                "set_id": int(association["time_series_set_id"]),
                "current_revision_id": source_revision_id,
                "current_content_hash": (
                    f"sha256:{source['revision']['content_hash']}"
                ),
            },
            "suggested_binding_request": {
                "action": "create",
                "linkable_object_id": int(linkable["id"]),
                "binding_role_key": proposed["intended_binding_role_key"],
                "signal_id": signal_id,
                "revision": {
                    "mode": "current",
                    "revision_id": revision_id,
                    "content_hash": f"sha256:{content_hash}",
                },
                "catalog_association_id": None,
                "reason_code": "variant_input_selected",
            },
        }

    def _read_only_transaction(self):
        """Read a page and its summary from one snapshot (chapter 9.8)."""

        if self.database_backend == "postgresql":
            return self.connection.transaction()
        return contextlib.nullcontext()

    # -- Durable idempotency (TS7-005, chapter 9.7) -------------------------

    def _claim_idempotency(
        self,
        *,
        actor_id: str,
        operation_kind: str,
        scope_key: str,
        idempotency_key: str,
        request_hash: str,
    ) -> dict[str, Any]:
        """Reserve one operation key, or hand back the result it already has.

        A key reused for a different request is refused; the uniqueness of
        ``(actor, operation, scope, key)`` resolves the final race.
        """

        table = self._projection("time_series_operation_idempotency")
        now = utc_now_iso()
        existing = self.connection.execute(
            f"""
            SELECT * FROM {table}
            WHERE actor_id = ? AND operation_kind = ? AND scope_key = ?
              AND idempotency_key = ?
            """,
            (actor_id, operation_kind, scope_key, idempotency_key),
        ).fetchone()
        if existing is not None:
            if existing["request_hash"] != request_hash:
                raise CanonicalRevisionError(
                    "TS_IDEMPOTENCY_KEY_CONFLICT",
                    operation_kind=operation_kind,
                    scope_key=scope_key,
                    idempotency_key=idempotency_key,
                )
            if existing["state"] == "completed":
                return {
                    "id": int(existing["id"]),
                    "state": "completed",
                    "response": json.loads(existing["response_json"]),
                }
            if (
                existing["state"] == "reserved"
                and existing["lease_expires_at"] is not None
                and existing["lease_expires_at"] > now
            ):
                raise CanonicalRevisionError(
                    "TS_IDEMPOTENCY_IN_FLIGHT",
                    operation_kind=operation_kind,
                    scope_key=scope_key,
                    idempotency_key=idempotency_key,
                )
            # The previous attempt died before commit; take its lease over.
            self.connection.execute(
                f"""
                UPDATE {table}
                SET state = 'reserved', lease_owner = ?, lease_expires_at = ?,
                    completed_at = NULL, http_status = NULL,
                    response_json = '{{}}', resource_refs_json = '{{}}'
                WHERE id = ?
                """,
                (
                    actor_id,
                    self._lease_deadline(now, seconds=IDEMPOTENCY_LEASE_SECONDS),
                    int(existing["id"]),
                ),
            )
            return {"id": int(existing["id"]), "state": "reserved", "response": None}

        claim_id = self._insert_canonical_row(
            f"""
            INSERT INTO {table} (
                actor_id, operation_kind, scope_key, idempotency_key,
                request_hash, state, lease_owner, lease_expires_at,
                created_at, expires_at
            ) VALUES (?, ?, ?, ?, ?, 'reserved', ?, ?, ?, ?)
            """,
            (
                actor_id,
                operation_kind,
                scope_key,
                idempotency_key,
                request_hash,
                actor_id,
                self._lease_deadline(now, seconds=IDEMPOTENCY_LEASE_SECONDS),
                now,
                self._lease_deadline(now, hours=IDEMPOTENCY_RETENTION_HOURS),
            ),
        )
        return {"id": claim_id, "state": "reserved", "response": None}

    def _complete_idempotency(
        self, *, claim_id: int, response: dict[str, Any], http_status: int
    ) -> None:
        table = self._projection("time_series_operation_idempotency")
        self.connection.execute(
            f"""
            UPDATE {table}
            SET state = 'completed', http_status = ?, response_json = ?,
                resource_refs_json = ?, completed_at = ?,
                lease_owner = NULL, lease_expires_at = NULL
            WHERE id = ?
            """,
            (
                http_status,
                json.dumps(response, sort_keys=True, ensure_ascii=False),
                json.dumps(
                    {
                        "set_id": response.get("set_id"),
                        "revision_id": response.get("revision_id"),
                    },
                    sort_keys=True,
                ),
                utc_now_iso(),
                claim_id,
            ),
        )

    @staticmethod
    def _lease_deadline(now: str, *, seconds: int = 0, hours: int = 0) -> str:
        moment = datetime.fromisoformat(now) + timedelta(seconds=seconds, hours=hours)
        return moment.isoformat(timespec="seconds")

    # -- Transactional catalog projection (TS7-005) -------------------------
    #
    # ``time_series_catalog_entries`` is derived from ``current_revision_id``
    # through ``time_series_revision_signals``. Chapter 9.3 requires it to be
    # written by the same transaction that changes its source, so every writer
    # below is called from inside an open transaction and never from a queue.

    def _projection(self, logical: str) -> str:
        return catalog_projection_table_names(self.database_backend)[logical]

    def _catalog_revision_coverage(self, revision_id: int) -> dict[str, Any]:
        """Coverage and resolution of a revision, from its period durations."""

        periods_table = self._canonical("time_series_periods")
        bounds = self.connection.execute(
            f"""
            SELECT MIN(timestamp_start) AS coverage_start,
                   MAX(timestamp_end) AS coverage_end,
                   COUNT(*) AS period_count
            FROM {periods_table}
            WHERE set_revision_id = ?
            """,
            (revision_id,),
        ).fetchone()
        histogram = {
            float(row["duration_hours"]): int(row["occurrences"])
            for row in self.connection.execute(
                f"""
                SELECT duration_hours, COUNT(*) AS occurrences
                FROM {periods_table}
                WHERE set_revision_id = ?
                GROUP BY duration_hours
                """,
                (revision_id,),
            ).fetchall()
        }
        return summarize_coverage(
            coverage_start=bounds["coverage_start"],
            coverage_end=bounds["coverage_end"],
            period_count=int(bounds["period_count"] or 0),
            duration_histogram=histogram,
        )

    def _catalog_entry_rows(self, set_id: int) -> list[dict[str, Any]]:
        """Project the visible signals of one set from its current revision."""

        sets_table = self._canonical("time_series_sets")
        set_row = self.connection.execute(
            f"""
            SELECT the_set.*, project.name AS owner_project_name,
                   source.kind AS source_kind
            FROM {sets_table} AS the_set
            JOIN projects AS project ON project.id = the_set.owner_project_id
            LEFT JOIN {self._canonical('time_series_set_revisions')} AS revision
              ON revision.id = the_set.current_revision_id
            LEFT JOIN {self._canonical('time_series_sources')} AS source
              ON source.id = revision.time_series_source_id
            WHERE the_set.id = ?
            """,
            (set_id,),
        ).fetchone()
        if (
            set_row is None
            or set_row["series_kind"] != "catalog"
            or set_row["current_revision_id"] is None
        ):
            return []

        revision_id = int(set_row["current_revision_id"])
        coverage = self._catalog_revision_coverage(revision_id)
        revision = self.connection.execute(
            f"""
            SELECT revision_number, created_at, timezone
            FROM {self._canonical('time_series_set_revisions')}
            WHERE id = ?
            """,
            (revision_id,),
        ).fetchone()
        source_kind = set_row["source_kind"] or "api"
        project_name_sort = normalize_sort_text(set_row["owner_project_name"])

        contract = self.connection.execute(
            f"""
            SELECT signal.id AS signal_id, signal.series_key AS series_key,
                   signal.display_name AS display_name,
                   signal.description AS signal_description,
                   signal.status AS signal_status,
                   revision_signal.semantic_type_id AS semantic_type_id,
                   semantic_type.semantic_key AS semantic_type_key,
                   revision_signal.data_class_id AS data_class_id,
                   data_class.data_class_key AS data_class_key,
                   revision_signal.unit_id AS unit_id,
                   unit.unit_key AS unit_key
            FROM {self._canonical('time_series_revision_signals')} AS revision_signal
            JOIN {self._canonical('time_series_signals')} AS signal
              ON signal.id = revision_signal.signal_id
            JOIN time_series_semantic_types AS semantic_type
              ON semantic_type.id = revision_signal.semantic_type_id
            JOIN time_series_data_classes AS data_class
              ON data_class.id = revision_signal.data_class_id
            JOIN measurement_units AS unit ON unit.id = revision_signal.unit_id
            WHERE revision_signal.set_revision_id = ?
            ORDER BY revision_signal.ordinal
            """,
            (revision_id,),
        ).fetchall()
        signal_ids = [int(signal["signal_id"]) for signal in contract]
        association_counts = self._catalog_link_counts(
            "time_series_catalog_associations", signal_ids
        )
        binding_counts = self._catalog_link_counts(
            "case_time_series_bindings", signal_ids
        )

        rows: list[dict[str, Any]] = []
        for signal in contract:
            rows.append(
                {
                    "signal_id": int(signal["signal_id"]),
                    "time_series_set_id": set_id,
                    "owner_project_id": int(set_row["owner_project_id"]),
                    "owner_project_name": set_row["owner_project_name"],
                    "owner_project_name_sort": project_name_sort,
                    "set_name": set_row["name"],
                    "set_version_number": int(set_row["version_number"]),
                    "set_version_label": set_row["version_label"],
                    "set_description": set_row["description"],
                    "visibility_scope": set_row["visibility_scope"],
                    "set_status": set_row["status"],
                    "signal_status": signal["signal_status"],
                    "series_key": signal["series_key"],
                    "display_name": signal["display_name"],
                    "signal_description": signal["signal_description"],
                    "display_name_sort": normalize_sort_text(signal["display_name"]),
                    "search_text_normalized": normalize_search_text(
                        signal["display_name"],
                        signal["series_key"],
                        set_row["name"],
                        set_row["version_label"],
                        set_row["owner_project_name"],
                        source_kind,
                    ),
                    "semantic_type_id": int(signal["semantic_type_id"]),
                    "semantic_type_key": signal["semantic_type_key"],
                    "data_class_id": int(signal["data_class_id"]),
                    "data_class_key": signal["data_class_key"],
                    "unit_id": int(signal["unit_id"]),
                    "unit_key": signal["unit_key"],
                    "source_kind": source_kind,
                    "current_revision_id": revision_id,
                    "revision_number": int(revision["revision_number"]),
                    "revision_created_at": revision["created_at"],
                    "source_timezone": revision["timezone"],
                    "coverage_start": coverage["coverage_start"],
                    "coverage_end": coverage["coverage_end"],
                    "period_count": coverage["period_count"],
                    # One value per signal and period is already enforced by the
                    # revision protocol, so the count never reads the cells.
                    "value_count": coverage["period_count"],
                    "nominal_resolution_seconds": coverage[
                        "nominal_resolution_seconds"
                    ],
                    "min_resolution_seconds": coverage["min_resolution_seconds"],
                    "max_resolution_seconds": coverage["max_resolution_seconds"],
                    "regularity": coverage["regularity"],
                    "updated_at": set_row["updated_at"],
                    "association_count": association_counts.get(
                        int(signal["signal_id"]), 0
                    ),
                    "binding_count": binding_counts.get(
                        int(signal["signal_id"]), 0
                    ),
                }
            )
        return rows

    def _catalog_link_counts(
        self, logical: str, signal_ids: list[int]
    ) -> dict[int, int]:
        """Active links of a whole revision, counted once through their index.

        One grouped read per revision rather than one per signal: the counts sit
        on the publication path, and a set of fifty signals should not cost a
        hundred round trips to project.
        """

        if not signal_ids:
            return {}
        table = link_layer_table_names(self.database_backend)[logical]
        placeholders = ", ".join("?" for _ in signal_ids)
        return {
            int(row["signal_id"]): int(row["total"])
            for row in self.connection.execute(
                f"""
                SELECT signal_id, COUNT(*) AS total FROM {table}
                WHERE status = 'active' AND signal_id IN ({placeholders})
                GROUP BY signal_id
                """,
                tuple(signal_ids),
            ).fetchall()
        }

    def _project_catalog_entries(self, *, set_id: int, now: str) -> int:
        """Rewrite the projection rows of one set. Returns the rows written."""

        entries_table = self._projection("time_series_catalog_entries")
        rows = self._catalog_entry_rows(set_id)
        keep = [row["signal_id"] for row in rows]
        if keep:
            placeholders = ", ".join("?" for _ in keep)
            self.connection.execute(
                f"""
                DELETE FROM {entries_table}
                WHERE time_series_set_id = ?
                  AND signal_id NOT IN ({placeholders})
                """,
                (set_id, *keep),
            )
        else:
            self.connection.execute(
                f"DELETE FROM {entries_table} WHERE time_series_set_id = ?",
                (set_id,),
            )
        for row in rows:
            self._upsert_catalog_entry(entries_table, row)
        return len(rows)

    def catalog_generation(self, section: str = CATALOG_SECTION_INPUTS) -> int:
        """Monotonic generation of one catalog section (chapter 6.2)."""

        row = self.connection.execute(
            f"""
            SELECT generation
            FROM {self._projection('time_series_catalog_generations')}
            WHERE section = ?
            """,
            (section,),
        ).fetchone()
        return 0 if row is None else int(row["generation"])

    def _raise_catalog_generation(
        self, *, now: str, section: str = CATALOG_SECTION_INPUTS
    ) -> int:
        """Raise the section generation once, at the end of a mutation.

        Chapter 9.3 raises it a single time per transaction that can change
        membership, ordering, summary or representation. A no-op publication
        never reaches this call.
        """

        generations = self._projection("time_series_catalog_generations")
        self.connection.execute(
            f"""
            INSERT INTO {generations} (section, generation, updated_at)
            VALUES (?, 1, ?)
            ON CONFLICT (section) DO UPDATE SET
                generation = {generations}.generation + 1,
                updated_at = EXCLUDED.updated_at
            """,
            (section, now),
        )
        return self.catalog_generation(section)

    def _projected_catalog_set_ids(self) -> list[int]:
        """Every catalog set that owes the projection rows."""

        return [
            int(row["id"])
            for row in self.connection.execute(
                f"""
                SELECT id
                FROM {self._canonical('time_series_sets')}
                WHERE series_kind = 'catalog' AND current_revision_id IS NOT NULL
                ORDER BY id
                """
            ).fetchall()
        ]

    def _catalog_projection_content_hash(self, table_name: str) -> str:
        rows = self.connection.execute(
            f"SELECT * FROM {table_name} ORDER BY signal_id"
        ).fetchall()
        return catalog_projection_content_hash(rows)

    def rebuild_catalog_projection(
        self, *, section: str = CATALOG_SECTION_INPUTS
    ) -> dict[str, Any]:
        """Rebuild the whole projection through a shadow table (chapter 9.3).

        The shadow is filled and compared by counts and content hash before any
        swap. A rebuild that finds the live table already correct changes
        nothing and does not raise the generation.
        """

        entries_table = self._projection("time_series_catalog_entries")
        shadow_table = f"{entries_table}_shadow"
        columns = ", ".join(CATALOG_ENTRY_COLUMNS)
        with self._lock:
            divergence_before = self.catalog_projection_divergence(section=section)
            with self._database_transaction():
                rows_before = int(
                    self.connection.execute(
                        f"SELECT COUNT(*) AS total FROM {entries_table}"
                    ).fetchone()["total"]
                )
                previous_hash = self._catalog_projection_content_hash(entries_table)

                self.connection.execute(f"DROP TABLE IF EXISTS {shadow_table}")
                self.connection.execute(
                    f"""
                    CREATE TABLE {shadow_table} AS
                    SELECT {columns} FROM {entries_table} WHERE 1 = 0
                    """
                )
                shadow_rows = 0
                for set_id in self._projected_catalog_set_ids():
                    for row in self._catalog_entry_rows(set_id):
                        self.connection.execute(
                            f"""
                            INSERT INTO {shadow_table} ({columns})
                            VALUES ({", ".join("?" for _ in CATALOG_ENTRY_COLUMNS)})
                            """,
                            tuple(row[column] for column in CATALOG_ENTRY_COLUMNS),
                        )
                        shadow_rows += 1
                content_hash = self._catalog_projection_content_hash(shadow_table)

                replaced_rows = 0
                generation = self.catalog_generation(section)
                if content_hash == previous_hash:
                    outcome = "unchanged"
                else:
                    # Readers keep the old snapshot until this commit, then see
                    # the whole new one.
                    self.connection.execute(f"DELETE FROM {entries_table}")
                    self.connection.execute(
                        f"""
                        INSERT INTO {entries_table} ({columns})
                        SELECT {columns} FROM {shadow_table}
                        """
                    )
                    replaced_rows = shadow_rows
                    generation = self._raise_catalog_generation(
                        now=utc_now_iso(), section=section
                    )
                    outcome = "rebuilt"
                self.connection.execute(f"DROP TABLE IF EXISTS {shadow_table}")

        return {
            "section": section,
            "outcome": outcome,
            "rows_before": rows_before,
            "shadow_rows": shadow_rows,
            "replaced_rows": replaced_rows,
            "previous_content_hash": previous_hash,
            "content_hash": content_hash,
            "divergence_before": divergence_before,
            "shadow_dropped": True,
            "catalog_generation": generation,
        }

    def catalog_projection_divergence(
        self, *, section: str = CATALOG_SECTION_INPUTS
    ) -> dict[str, Any]:
        """Compare the projection against the canonical model (chapter 9.10).

        The reconciliation reports divergence; it never repairs silently, and a
        leaked ``object_specific`` row is reported on its own because the global
        list must never be able to see one.
        """

        entries_table = self._projection("time_series_catalog_entries")
        expected = {
            row["signal_id"]: row
            for set_id in self._projected_catalog_set_ids()
            for row in self._catalog_entry_rows(set_id)
        }
        actual = {
            int(row["signal_id"]): dict(row)
            for row in self.connection.execute(
                f"SELECT * FROM {entries_table}"
            ).fetchall()
        }
        stale = sorted(
            signal_id
            for signal_id, row in expected.items()
            if signal_id in actual
            and any(
                actual[signal_id][column] != value for column, value in row.items()
            )
        )
        leaked = sorted(
            int(row["signal_id"])
            for row in self.connection.execute(
                f"""
                SELECT entry.signal_id
                FROM {entries_table} AS entry
                JOIN {self._canonical('time_series_sets')} AS the_set
                  ON the_set.id = entry.time_series_set_id
                WHERE the_set.series_kind <> 'catalog'
                """
            ).fetchall()
        )
        missing = sorted(set(expected) - set(actual))
        unexpected = sorted(set(actual) - set(expected))
        return {
            "section": section,
            "missing": missing,
            "unexpected": unexpected,
            "stale": stale,
            "object_specific": leaked,
            "converged": not (missing or unexpected or stale or leaked),
        }

    def _upsert_catalog_entry(self, entries_table: str, row: dict[str, Any]) -> None:
        columns = CATALOG_ENTRY_COLUMNS
        assignments = ", ".join(
            f"{column} = EXCLUDED.{column}" for column in columns[1:]
        )
        self.connection.execute(
            f"""
            INSERT INTO {entries_table} (
                {", ".join(columns)}, series_kind
            ) VALUES ({", ".join("?" for _ in columns)}, 'catalog')
            ON CONFLICT (signal_id) DO UPDATE SET
                {assignments},
                projection_revision = {entries_table}.projection_revision + 1
            """,
            tuple(row[column] for column in columns),
        )

    def _register_canonical_source(
        self, project_id: int, source: dict[str, Any] | None, actor: str, now: str
    ) -> tuple[int | None, bool]:
        """Resolve the source row, reporting whether this call created it."""

        if not source:
            return None, False
        sources_table = self._canonical("time_series_sources")
        source_key = str(source["source_key"])
        existing = self.connection.execute(
            f"SELECT id FROM {sources_table} WHERE project_id = ? AND source_key = ?",
            (project_id, source_key),
        ).fetchone()
        if existing is not None:
            return int(existing["id"]), False
        return self._insert_canonical_row(
            f"""
            INSERT INTO {sources_table} (
                project_id, source_key, kind, original_filename, media_type,
                checksum, stored_path, selected_sheet, metadata_json,
                created_at, created_by
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                project_id,
                source_key,
                str(source.get("kind") or "api"),
                str(source.get("original_filename") or ""),
                str(source.get("media_type") or ""),
                str(source.get("checksum") or ""),
                str(source.get("stored_path") or ""),
                source.get("selected_sheet"),
                json.dumps(source.get("metadata") or {}, sort_keys=True),
                now,
                actor,
            ),
        ), True

    def _resolve_canonical_signal_identities(
        self, *, set_id: int, signals: list[dict], actor: str, now: str
    ) -> dict[str, int]:
        signals_table = self._canonical("time_series_signals")
        known = {
            row["series_key"]: row
            for row in self.connection.execute(
                f"""
                SELECT id, series_key, status
                FROM {signals_table}
                WHERE time_series_set_id = ?
                """,
                (set_id,),
            ).fetchall()
        }
        resolved: dict[str, int] = {}
        for signal in signals:
            series_key = signal["series_key"]
            existing = known.get(series_key)
            if existing is not None:
                # An archived identity is history, never a slot to recycle.
                if existing["status"] != "active":
                    raise CanonicalRevisionError(
                        "TS_OBJECT_SERIES_KEY_CONFLICT",
                        series_key=series_key,
                        signal_id=int(existing["id"]),
                        status=existing["status"],
                    )
                resolved[series_key] = int(existing["id"])
                continue
            resolved[series_key] = self._insert_canonical_row(
                f"""
                INSERT INTO {signals_table} (
                    time_series_set_id, series_kind, series_key, display_name,
                    description, status, created_at, created_by
                ) VALUES (?, 'catalog', ?, ?, ?, 'active', ?, ?)
                """,
                (
                    set_id,
                    series_key,
                    signal["display_name"],
                    signal["description"],
                    now,
                    actor,
                ),
            )
        return resolved

    def _insert_canonical_values(
        self,
        *,
        values_table: str,
        revision_id: int,
        values,
        signal_ids: dict[str, int],
        period_ids: dict[int, int],
    ) -> None:
        chunk: list[tuple] = []
        for record in canonical_value_records(values):
            series_key, period_index, value, quality_flag, source_row_number = record
            signal_id = signal_ids.get(series_key)
            if signal_id is None:
                raise CanonicalRevisionError(
                    "TS_INGEST_VALUE_INVALID",
                    series_key=series_key,
                    reason="unknown_series_key",
                )
            period_id = period_ids.get(
                period_index if period_index is None else int(period_index)
            )
            if period_id is None:
                raise CanonicalRevisionError(
                    "TS_INGEST_VALUE_INVALID",
                    series_key=series_key,
                    period_index=period_index,
                    reason="unknown_period_index",
                )
            try:
                numeric = float(value)
            except (TypeError, ValueError) as error:
                raise CanonicalRevisionError(
                    "TS_INGEST_VALUE_INVALID",
                    series_key=series_key,
                    period_index=period_index,
                    reason="not_numeric",
                ) from error
            if not math.isfinite(numeric):
                raise CanonicalRevisionError(
                    "TS_INGEST_VALUE_INVALID",
                    series_key=series_key,
                    period_index=period_index,
                    reason="not_finite",
                )
            chunk.append(
                (
                    revision_id,
                    signal_id,
                    period_id,
                    numeric,
                    quality_flag,
                    source_row_number,
                )
            )
            if len(chunk) >= CANONICAL_VALUE_CHUNK_SIZE:
                self._flush_canonical_values(values_table, chunk)
                chunk = []
        if chunk:
            self._flush_canonical_values(values_table, chunk)

    def _flush_canonical_values(self, values_table: str, chunk: list[tuple]) -> None:
        try:
            self.connection.executemany(
                f"""
                INSERT INTO {values_table} (
                    set_revision_id, signal_id, time_series_period_id,
                    value_numeric, quality_flag, source_row_number
                ) VALUES (?, ?, ?, ?, ?, ?)
                """,
                chunk,
            )
        except Exception as error:
            if _is_canonical_duplicate_value(error):
                raise CanonicalRevisionError(
                    "TS_INGEST_VALUE_INVALID", reason="duplicated_value"
                ) from error
            raise

    def _stream_canonical_content_hash(
        self,
        *,
        revision_id: int,
        revision_timezone: str,
        timestamp_convention: str,
        data_class_key: str,
    ) -> str:
        revision_signals_table = self._canonical("time_series_revision_signals")
        periods_table = self._canonical("time_series_periods")
        values_table = self._canonical("time_series_values")
        digest = CanonicalContentHash(
            timezone=revision_timezone,
            timestamp_convention=timestamp_convention,
            data_class_key=data_class_key,
        )
        for row in self._stream_canonical_rows(
            f"""
            SELECT revision_signal.ordinal AS ordinal,
                   signal.series_key AS series_key,
                   semantic_type.semantic_key AS semantic_key,
                   unit.unit_key AS unit_key,
                   data_class.data_class_key AS data_class_key,
                   revision_signal.signal_role AS signal_role,
                   revision_signal.aggregation AS aggregation
            FROM {revision_signals_table} AS revision_signal
            JOIN {self._canonical('time_series_signals')} AS signal
              ON signal.id = revision_signal.signal_id
            JOIN time_series_semantic_types AS semantic_type
              ON semantic_type.id = revision_signal.semantic_type_id
            JOIN measurement_units AS unit ON unit.id = revision_signal.unit_id
            JOIN time_series_data_classes AS data_class
              ON data_class.id = revision_signal.data_class_id
            WHERE revision_signal.set_revision_id = ?
            ORDER BY revision_signal.ordinal
            """,
            (revision_id,),
        ):
            digest.add_signal(
                ordinal=int(row["ordinal"]),
                series_key=row["series_key"],
                semantic_type_key=row["semantic_key"],
                unit_key=row["unit_key"],
                data_class_key=row["data_class_key"],
                signal_role=row["signal_role"],
                aggregation=row["aggregation"],
            )
        for row in self._stream_canonical_rows(
            f"""
            SELECT period_index, timestamp_start, timestamp_end, duration_hours
            FROM {periods_table}
            WHERE set_revision_id = ?
            ORDER BY period_index
            """,
            (revision_id,),
        ):
            digest.add_period(
                period_index=int(row["period_index"]),
                timestamp_start=row["timestamp_start"],
                timestamp_end=row["timestamp_end"],
                duration_hours=float(row["duration_hours"]),
            )
        for row in self._stream_canonical_rows(
            f"""
            SELECT revision_signal.ordinal AS ordinal,
                   period.period_index AS period_index,
                   value.value_numeric AS value_numeric
            FROM {values_table} AS value
            JOIN {revision_signals_table} AS revision_signal
              ON revision_signal.set_revision_id = value.set_revision_id
             AND revision_signal.signal_id = value.signal_id
            JOIN {periods_table} AS period
              ON period.id = value.time_series_period_id
            WHERE value.set_revision_id = ?
            ORDER BY revision_signal.ordinal, period.period_index
            """,
            (revision_id,),
        ):
            digest.add_value(
                ordinal=int(row["ordinal"]),
                period_index=int(row["period_index"]),
                value=float(row["value_numeric"]),
            )
        return digest.seal()

    def _stream_canonical_rows(self, sql: str, parameters: tuple):
        cursor = self.connection.execute(sql, parameters)
        while True:
            row = cursor.fetchone()
            if row is None:
                return
            yield row

    def list_canonical_signal_identities(self, set_id: int) -> list[dict[str, Any]]:
        """Every identity the set ever had, current or historical.

        A signal that disappears from a revision keeps its identity: it leaves
        the current view but stays readable as history, and it is never
        redirected to another signal of the same type (chapter 2.7).
        """

        sets_table = self._canonical("time_series_sets")
        signals_table = self._canonical("time_series_signals")
        revision_signals_table = self._canonical("time_series_revision_signals")
        revisions_table = self._canonical("time_series_set_revisions")
        current = self.connection.execute(
            f"SELECT current_revision_id FROM {sets_table} WHERE id = ?", (set_id,)
        ).fetchone()
        if current is None:
            raise CanonicalRevisionError("TS_SET_NOT_FOUND", set_id=set_id)
        current_revision_id = current["current_revision_id"]
        identities = []
        for row in self.connection.execute(
            f"""
            SELECT signal.id AS signal_id,
                   signal.series_key AS series_key,
                   signal.display_name AS display_name,
                   signal.status AS status,
                   signal.created_at AS created_at,
                   signal.archived_at AS archived_at,
                   signal.archived_by AS archived_by,
                   MIN(revision.revision_number) AS first_revision_number,
                   MAX(revision.revision_number) AS last_revision_number,
                   COUNT(revision_signal.set_revision_id) AS revision_count
            FROM {signals_table} AS signal
            LEFT JOIN {revision_signals_table} AS revision_signal
              ON revision_signal.signal_id = signal.id
            LEFT JOIN {revisions_table} AS revision
              ON revision.id = revision_signal.set_revision_id
             AND revision.state = 'sealed'
            WHERE signal.time_series_set_id = ?
            GROUP BY signal.id, signal.series_key, signal.display_name,
                     signal.status, signal.created_at, signal.archived_at,
                     signal.archived_by
            ORDER BY signal.id
            """,
            (set_id,),
        ).fetchall():
            identity = dict(row)
            identity["signal_id"] = int(identity["signal_id"])
            identity["in_current_revision"] = current_revision_id is not None and bool(
                self.connection.execute(
                    f"""
                    SELECT 1 AS present
                    FROM {revision_signals_table}
                    WHERE set_revision_id = ? AND signal_id = ?
                    """,
                    (current_revision_id, identity["signal_id"]),
                ).fetchone()
            )
            identities.append(identity)
        return identities

    def archive_canonical_signal_identity(
        self,
        *,
        set_id: int,
        series_key: str,
        actor: str,
        reason_text: str = "",
    ) -> dict[str, Any]:
        """Retire an identity without erasing the history that used it."""

        signals_table = self._canonical("time_series_signals")
        with self._lock:
            with self._database_transaction():
                row = self.connection.execute(
                    f"""
                    SELECT id, status
                    FROM {signals_table}
                    WHERE time_series_set_id = ? AND series_key = ?
                    """,
                    (set_id, series_key),
                ).fetchone()
                if row is None:
                    raise CanonicalRevisionError(
                        "TS_SET_NOT_FOUND", set_id=set_id, series_key=series_key
                    )
                if row["status"] == "archived":
                    return {
                        "signal_id": int(row["id"]),
                        "series_key": series_key,
                        "status": "archived",
                    }
                now = utc_now_iso()
                self.connection.execute(
                    f"""
                    UPDATE {signals_table}
                    SET status = 'archived', archived_at = ?, archived_by = ?,
                        description = ?
                    WHERE id = ?
                    """,
                    (now, actor, reason_text, int(row["id"])),
                )
                # Archival changes list membership and capabilities, so the
                # read projection and its snapshot generation move atomically.
                self._project_catalog_entries(set_id=set_id, now=now)
                self._raise_catalog_generation(now=now)
                return {
                    "signal_id": int(row["id"]),
                    "series_key": series_key,
                    "status": "archived",
                }

    def read_canonical_set(self, set_id: int) -> dict[str, Any]:
        """The set, its current sealed revision and the signals it shows."""

        sets_table = self._canonical("time_series_sets")
        row = self.connection.execute(
            f"SELECT * FROM {sets_table} WHERE id = ?", (set_id,)
        ).fetchone()
        if row is None:
            raise CanonicalRevisionError("TS_SET_NOT_FOUND", set_id=set_id)
        set_view = dict(row)
        current_revision_id = set_view.get("current_revision_id")
        set_view["current_revision"] = (
            self.read_canonical_revision(int(current_revision_id), with_values=False)
            if current_revision_id is not None
            else None
        )
        set_view["signals"] = (
            set_view["current_revision"]["signals"]
            if set_view["current_revision"] is not None
            else []
        )
        return set_view

    def read_canonical_revision(
        self, revision_id: int, *, with_values: bool = True
    ) -> dict[str, Any]:
        """One revision as the frozen snapshot it is."""

        revisions_table = self._canonical("time_series_set_revisions")
        row = self.connection.execute(
            f"""
            SELECT revision.*, data_class.data_class_key AS data_class_key
            FROM {revisions_table} AS revision
            JOIN time_series_data_classes AS data_class
              ON data_class.id = revision.data_class_id
            WHERE revision.id = ?
            """,
            (revision_id,),
        ).fetchone()
        if row is None:
            raise CanonicalRevisionError("TS_SET_NOT_FOUND", revision_id=revision_id)
        revision = dict(row)
        revision["signals"] = [
            dict(signal)
            for signal in self.connection.execute(
                f"""
                SELECT revision_signal.ordinal AS ordinal,
                       revision_signal.signal_id AS signal_id,
                       signal.series_key AS series_key,
                       signal.display_name AS display_name,
                       signal.status AS signal_status,
                       semantic_type.semantic_key AS semantic_type_key,
                       unit.unit_key AS unit_key,
                       data_class.data_class_key AS data_class_key,
                       revision_signal.signal_role AS signal_role,
                       revision_signal.aggregation AS aggregation
                FROM {self._canonical('time_series_revision_signals')} AS revision_signal
                JOIN {self._canonical('time_series_signals')} AS signal
                  ON signal.id = revision_signal.signal_id
                JOIN time_series_semantic_types AS semantic_type
                  ON semantic_type.id = revision_signal.semantic_type_id
                JOIN measurement_units AS unit ON unit.id = revision_signal.unit_id
                JOIN time_series_data_classes AS data_class
                  ON data_class.id = revision_signal.data_class_id
                WHERE revision_signal.set_revision_id = ?
                ORDER BY revision_signal.ordinal
                """,
                (revision_id,),
            ).fetchall()
        ]
        revision["periods"] = [
            dict(period)
            for period in self.connection.execute(
                f"""
                SELECT id, period_index, timestamp_start, timestamp_end,
                       duration_hours
                FROM {self._canonical('time_series_periods')}
                WHERE set_revision_id = ?
                ORDER BY period_index
                """,
                (revision_id,),
            ).fetchall()
        ]
        revision["signal_count"] = len(revision["signals"])
        revision["period_count"] = len(revision["periods"])
        if not with_values:
            return revision
        matrix: dict[str, list[float]] = {
            signal["series_key"]: [] for signal in revision["signals"]
        }
        for row in self._stream_canonical_rows(
            f"""
            SELECT signal.series_key AS series_key,
                   period.period_index AS period_index,
                   value.value_numeric AS value_numeric
            FROM {self._canonical('time_series_values')} AS value
            JOIN {self._canonical('time_series_revision_signals')} AS revision_signal
              ON revision_signal.set_revision_id = value.set_revision_id
             AND revision_signal.signal_id = value.signal_id
            JOIN {self._canonical('time_series_signals')} AS signal
              ON signal.id = value.signal_id
            JOIN {self._canonical('time_series_periods')} AS period
              ON period.id = value.time_series_period_id
            WHERE value.set_revision_id = ?
            ORDER BY revision_signal.ordinal, period.period_index
            """,
            (revision_id,),
        ):
            matrix[row["series_key"]].append(float(row["value_numeric"]))
        revision["values"] = matrix
        revision["value_count"] = sum(len(column) for column in matrix.values())
        return revision

    def _database_transaction(self):
        if self.database_backend == "postgresql":
            return self.connection.transaction()
        return self.connection

    def seed_time_series_classification_catalog(self) -> dict[str, Any]:
        with self._lock:
            before = self._time_series_classification_row_count()
            with self._database_transaction():
                self._seed_time_series_classification_catalog()
            inserted_rows = self._time_series_classification_row_count() - before
        return {
            "contract_version": CLASSIFICATION_CONTRACT_VERSION,
            "status": "converged" if inserted_rows == 0 else "seeded",
            "inserted_rows": inserted_rows,
        }

    def _time_series_classification_row_count(self) -> int:
        tables = (
            "measurement_dimensions",
            "measurement_units",
            "time_series_data_classes",
            "time_series_semantic_types",
            "time_series_binding_roles",
            "linkable_object_types",
            "time_series_role_compatibilities",
        )
        return sum(
            int(
                self.connection.execute(
                    f"SELECT COUNT(*) AS row_count FROM {table_name}"
                ).fetchone()["row_count"]
            )
            for table_name in tables
        )

    def get_time_series_classification_catalog(self) -> dict[str, Any]:
        tables_and_keys = (
            ("measurement_dimensions", "dimension_key"),
            ("measurement_units", "unit_key"),
            ("time_series_data_classes", "data_class_key"),
            ("time_series_semantic_types", "semantic_key"),
            ("time_series_binding_roles", "role_key"),
            ("linkable_object_types", "object_type_key"),
        )
        catalog = {
            table_name: [
                dict(row)
                for row in self.connection.execute(
                    f"SELECT * FROM {table_name} ORDER BY {key_column}"
                ).fetchall()
            ]
            for table_name, key_column in tables_and_keys
        }
        catalog["time_series_role_compatibilities"] = [
            dict(row)
            for row in self.connection.execute(
                """
                SELECT *
                FROM time_series_role_compatibilities
                ORDER BY id
                """
            ).fetchall()
        ]
        return catalog

    def signal_catalog_entries(self) -> list[dict[str, Any]]:
        entries = []
        for signal_key, definition in TIME_SERIES_SIGNAL_CATALOG.items():
            semantic_key = SIGNAL_SEMANTIC_TYPE_KEYS.get(signal_key)
            if semantic_key is None:
                # Compatibility adapter only: an unknown legacy declaration is
                # visible to its old callers but never creates canonical rows.
                entries.append(
                    {
                        "signal_key": definition.signal_key,
                        "unit": definition.unit,
                        "entity_type": definition.entity_type,
                        "nonnegative": definition.nonnegative,
                    }
                )
                continue
            classification = self.connection.execute(
                """
                SELECT units.symbol, semantic_types.validation_rules_json
                FROM time_series_semantic_types AS semantic_types
                JOIN measurement_units AS units
                  ON units.id = semantic_types.canonical_unit_id
                WHERE semantic_types.semantic_key = ?
                  AND semantic_types.status = 'active'
                """,
                (semantic_key,),
            ).fetchone()
            if classification is None:
                raise ClassificationContractDriftError(
                    context={
                        "catalog": "time_series_semantic_types",
                        "key": semantic_key,
                        "field": "status",
                        "expected": "active",
                        "actual": None,
                    }
                )
            object_types = self.connection.execute(
                """
                SELECT DISTINCT object_types.object_type_key
                FROM time_series_role_compatibilities AS compatibility
                JOIN time_series_semantic_types AS semantic_types
                  ON semantic_types.id = compatibility.semantic_type_id
                JOIN linkable_object_types AS object_types
                  ON object_types.id = compatibility.object_type_id
                WHERE semantic_types.semantic_key = ?
                  AND compatibility.status = 'active'
                ORDER BY object_types.object_type_key
                """,
                (semantic_key,),
            ).fetchall()
            entity_type = (
                None
                if not object_types
                or object_types[0]["object_type_key"] == "global:system"
                else object_types[0]["object_type_key"]
            )
            validation_rules = json.loads(classification["validation_rules_json"])
            entries.append(
                {
                    "signal_key": signal_key,
                    "unit": classification["symbol"],
                    "entity_type": entity_type,
                    "nonnegative": validation_rules.get("minimum") == 0,
                }
            )
        return entries

    def create_custom_time_series_semantic_type(
        self,
        *,
        semantic_key: str,
        display_name: str,
        description: str,
        dimension_key: str,
        canonical_unit_key: str,
        value_kind: str,
        default_aggregation: str,
        validation_rules: dict[str, Any],
        created_by: str,
    ) -> dict[str, Any]:
        semantic_key = str(semantic_key).strip()
        display_name = str(display_name).strip()
        description = str(description).strip()
        dimension_key = str(dimension_key).strip()
        canonical_unit_key = str(canonical_unit_key).strip()
        value_kind = str(value_kind).strip()
        default_aggregation = str(default_aggregation).strip()
        created_by = str(created_by).strip()
        required_text = {
            "semantic_key": semantic_key,
            "display_name": display_name,
            "description": description,
            "dimension_key": dimension_key,
            "canonical_unit_key": canonical_unit_key,
            "value_kind": value_kind,
            "default_aggregation": default_aggregation,
            "created_by": created_by,
        }
        missing = [key for key, value in required_text.items() if not value]
        if missing:
            raise ValueError(
                "custom semantic type requires " + ", ".join(sorted(missing))
            )
        if not re.fullmatch(r"[a-z][a-z0-9_]*", semantic_key):
            raise ValueError(
                "semantic_key must start with a lowercase letter and contain only "
                "lowercase letters, numbers and underscores"
            )
        if not isinstance(validation_rules, dict):
            raise ValueError("validation_rules must be an object")
        forbidden_rule_keys = {"code", "expression", "formula", "script"}
        if any(str(key).lower() in forbidden_rule_keys for key in validation_rules):
            raise ValueError("validation_rules cannot contain executable code or formulas")
        try:
            validation_rules_json = json.dumps(
                validation_rules, sort_keys=True, separators=(",", ":")
            )
        except (TypeError, ValueError) as error:
            raise ValueError("validation_rules must be valid JSON") from error

        dimension = self.connection.execute(
            """
            SELECT id
            FROM measurement_dimensions
            WHERE dimension_key = ? AND status = 'active'
            """,
            (dimension_key,),
        ).fetchone()
        if dimension is None:
            raise ValueError(f"unknown active dimension_key {dimension_key!r}")
        unit = self.connection.execute(
            """
            SELECT id, dimension_id
            FROM measurement_units
            WHERE unit_key = ? AND status = 'active'
            """,
            (canonical_unit_key,),
        ).fetchone()
        if unit is None:
            raise ValueError(f"unknown active canonical_unit_key {canonical_unit_key!r}")
        if int(unit["dimension_id"]) != int(dimension["id"]):
            raise ValueError("canonical unit must belong to the semantic type dimension")
        existing = self.connection.execute(
            "SELECT 1 FROM time_series_semantic_types WHERE semantic_key = ?",
            (semantic_key,),
        ).fetchone()
        if existing is not None:
            raise ValueError(f"semantic_key {semantic_key!r} already exists")

        timestamp = utc_now_iso()
        with self._lock:
            with self._database_transaction():
                cursor = self.connection.execute(
                    """
                    INSERT INTO time_series_semantic_types (
                        semantic_key, display_name, description, dimension_id,
                        canonical_unit_id, value_kind, default_aggregation,
                        validation_rules_json, is_system, status, created_at,
                        updated_at, created_by, updated_by
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, 'active', ?, ?, ?, ?)
                    """,
                    (
                        semantic_key,
                        display_name,
                        description,
                        dimension["id"],
                        unit["id"],
                        value_kind,
                        default_aggregation,
                        validation_rules_json,
                        timestamp,
                        timestamp,
                        created_by,
                        created_by,
                    ),
                )
                semantic_type_id = int(cursor.lastrowid)
        return self.get_time_series_semantic_type(semantic_type_id)

    def get_time_series_semantic_type(self, semantic_type_id: int) -> dict[str, Any]:
        row = self.connection.execute(
            """
            SELECT
                semantic_types.*,
                dimensions.dimension_key,
                units.unit_key AS canonical_unit_key
            FROM time_series_semantic_types AS semantic_types
            JOIN measurement_dimensions AS dimensions
              ON dimensions.id = semantic_types.dimension_id
            JOIN measurement_units AS units
              ON units.id = semantic_types.canonical_unit_id
            WHERE semantic_types.id = ?
            """,
            (semantic_type_id,),
        ).fetchone()
        if row is None:
            raise KeyError(f"time-series semantic type {semantic_type_id} was not found")
        result = dict(row)
        result["is_system"] = bool(result["is_system"])
        result["validation_rules"] = json.loads(result.pop("validation_rules_json"))
        return result

    def evaluate_time_series_compatibility(
        self,
        *,
        semantic_type_key: str,
        binding_role_key: str,
        object_type_key: str,
        unit_key: str,
        usage: str,
    ) -> dict[str, Any]:
        if usage not in {"association", "execution"}:
            raise ValueError("usage must be 'association' or 'execution'")
        semantic_type = self.connection.execute(
            """
            SELECT
                semantic_types.*,
                dimensions.dimension_key,
                units.unit_key
            FROM time_series_semantic_types AS semantic_types
            JOIN measurement_dimensions AS dimensions
              ON dimensions.id = semantic_types.dimension_id
            JOIN measurement_units AS units
              ON units.id = semantic_types.canonical_unit_id
            WHERE semantic_types.semantic_key = ?
            """,
            (semantic_type_key,),
        ).fetchone()
        role = self.connection.execute(
            """
            SELECT
                roles.*,
                dimensions.dimension_key,
                units.unit_key
            FROM time_series_binding_roles AS roles
            JOIN measurement_dimensions AS dimensions
              ON dimensions.id = roles.dimension_id
            JOIN measurement_units AS units
              ON units.id = roles.canonical_unit_id
            WHERE roles.role_key = ?
            """,
            (binding_role_key,),
        ).fetchone()
        object_type = self.connection.execute(
            """
            SELECT *
            FROM linkable_object_types
            WHERE object_type_key = ?
            """,
            (object_type_key,),
        ).fetchone()

        base_context = {
            "semantic_type_key": semantic_type_key,
            "role_key": binding_role_key,
            "object_type_key": object_type_key,
            "usage": usage,
        }
        errors = []
        if semantic_type is None or semantic_type["status"] != "active":
            errors.append(
                compatibility_error(
                    "TS_COMPAT_SEMANTIC_TYPE_INACTIVE", dict(base_context)
                )
            )
        if role is None or role["status"] != "active":
            errors.append(
                compatibility_error("TS_COMPAT_ROLE_INACTIVE", dict(base_context))
            )
        if object_type is None or object_type["status"] != "active":
            errors.append(
                compatibility_error(
                    "TS_COMPAT_OBJECT_UNAVAILABLE", dict(base_context)
                )
            )

        rule = None
        if (
            semantic_type is not None
            and semantic_type["status"] == "active"
            and role is not None
            and role["status"] == "active"
            and object_type is not None
            and object_type["status"] == "active"
        ):
            if not bool(role[f"{usage}_allowed"]):
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_ROLE_USAGE_NOT_ALLOWED", dict(base_context)
                    )
                )

            rules = self.connection.execute(
                """
                SELECT compatibility.*, object_types.object_type_key
                FROM time_series_role_compatibilities AS compatibility
                JOIN linkable_object_types AS object_types
                  ON object_types.id = compatibility.object_type_id
                WHERE compatibility.semantic_type_id = ?
                  AND compatibility.binding_role_id = ?
                  AND compatibility.status = 'active'
                ORDER BY compatibility.id
                """,
                (semantic_type["id"], role["id"]),
            ).fetchall()
            usage_rules = [row for row in rules if bool(row[f"{usage}_allowed"])]
            if not usage_rules:
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_SEMANTIC_TYPE_NOT_ALLOWED", dict(base_context)
                    )
                )
            else:
                rule = next(
                    (
                        row
                        for row in usage_rules
                        if row["object_type_key"] == object_type_key
                    ),
                    None,
                )
                if rule is None:
                    errors.append(
                        compatibility_error(
                            "TS_COMPAT_OBJECT_TYPE_NOT_ALLOWED", dict(base_context)
                        )
                    )

            if semantic_type["dimension_id"] != role["dimension_id"]:
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_DIMENSION_MISMATCH",
                        {
                            **base_context,
                            "semantic_dimension_key": semantic_type["dimension_key"],
                            "role_dimension_key": role["dimension_key"],
                        },
                    )
                )
            expected_unit_key = semantic_type["unit_key"]
            if (
                semantic_type["canonical_unit_id"] != role["canonical_unit_id"]
                or unit_key != expected_unit_key
            ):
                errors.append(
                    compatibility_error(
                        "TS_COMPAT_UNIT_MISMATCH",
                        {
                            **base_context,
                            "expected_unit_key": expected_unit_key,
                            "actual_unit_key": unit_key,
                        },
                    )
                )

        allowed = rule is not None and not errors
        return {
            "allowed": allowed,
            "compatibility_rule_id": (
                int(rule["id"]) if rule is not None else None
            ),
            "rule_version": int(rule["rule_version"]) if rule is not None else None,
            "contract_version": CLASSIFICATION_CONTRACT_VERSION,
            "errors": errors,
            "primary_error": errors[0] if errors else None,
        }

    def _ensure_external_user_role_constraint(self) -> None:
        if self.database_backend == "postgresql":
            self.connection.execute(
                "ALTER TABLE users DROP CONSTRAINT IF EXISTS users_role_check"
            )
            self.connection.execute(
                "UPDATE users SET role = 'external' WHERE role = 'client'"
            )
            self.connection.execute(
                "ALTER TABLE users ADD CONSTRAINT users_role_check "
                "CHECK (role IN ('admin', 'analyst', 'external'))"
            )
            return

        row = self.connection.execute(
            "SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'users'"
        ).fetchone()
        if row is None or "'client'" not in str(row["sql"]):
            return

        self.connection.commit()
        self.connection.execute("PRAGMA foreign_keys = OFF")
        try:
            self.connection.executescript(
                """
                CREATE TABLE users_without_legacy_client_role (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    email TEXT NOT NULL UNIQUE COLLATE NOCASE,
                    display_name TEXT NOT NULL DEFAULT '',
                    role TEXT NOT NULL,
                    password_hash TEXT NOT NULL,
                    is_active INTEGER NOT NULL DEFAULT 1,
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL,
                    created_by TEXT NOT NULL,
                    deactivated_at TEXT,
                    CHECK (role IN ('admin', 'analyst', 'external'))
                );
                INSERT INTO users_without_legacy_client_role (
                    id, email, display_name, role, password_hash, is_active,
                    created_at, updated_at, created_by, deactivated_at
                )
                SELECT id, email, display_name,
                       CASE WHEN role = 'client' THEN 'external' ELSE role END,
                       password_hash, is_active,
                       created_at, updated_at, created_by, deactivated_at
                FROM users;
                DROP TABLE users;
                ALTER TABLE users_without_legacy_client_role RENAME TO users;
                """
            )
        finally:
            self.connection.execute("PRAGMA foreign_keys = ON")

    def _migrate_legacy_external_access(self) -> None:
        self.connection.execute(
            """
            UPDATE project_client_access
            SET updated_at = assigned_at
            WHERE updated_at IS NULL OR updated_at = ''
            """
        )
        self.connection.execute(
            """
            UPDATE project_client_access
            SET updated_by = assigned_by
            WHERE updated_by IS NULL OR updated_by = ''
            """
        )
        self.connection.execute("UPDATE users SET role = 'external' WHERE role = 'client'")

    def _apply_migration_once(self, name: str, migration) -> None:
        """Run a one-shot data migration and remember that it already ran.

        Without the marker a project published after the cutover would be
        configured from its dashboard template on the next start, silently
        enabling panels the analyst never declared.
        """

        applied = self.connection.execute(
            "SELECT 1 FROM schema_migrations WHERE name = ?", (name,)
        ).fetchone()
        if applied is not None:
            return
        migration()
        with self._lock:
            self.connection.execute(
                "INSERT INTO schema_migrations (name, applied_at) VALUES (?, ?)",
                (name, utc_now_iso()),
            )
            self.connection.commit()

    def _ensure_column(self, table_name: str, column_name: str, definition: str) -> None:
        if self.database_backend == "postgresql":
            row = self.connection.execute(
                """
                SELECT 1
                FROM information_schema.columns
                WHERE table_schema = current_schema()
                  AND table_name = ?
                  AND column_name = ?
                """,
                (table_name, column_name),
            ).fetchone()
            if row is None:
                self.connection.execute(
                    f"ALTER TABLE {table_name} ADD COLUMN {column_name} {definition}"
                )
            return

        columns = {
            row["name"]
            for row in self.connection.execute(f"PRAGMA table_info({table_name})").fetchall()
        }
        if column_name not in columns:
            self.connection.execute(f"ALTER TABLE {table_name} ADD COLUMN {column_name} {definition}")

    def _ensure_query_shape_indexes(self) -> None:
        self.connection.execute(
            """
            CREATE INDEX IF NOT EXISTS idx_time_series_values_set_period_signal
            ON time_series_values (time_series_set_id, time_series_period_id, time_series_signal_id)
            """
        )
        self.connection.execute(
            """
            CREATE INDEX IF NOT EXISTS idx_runs_status_scenario_version
            ON runs (status, scenario_version_id, id)
            """
        )
        self.connection.execute(
            """
            CREATE INDEX IF NOT EXISTS idx_scenario_versions_scenario
            ON scenario_versions (scenario_id, id)
            """
        )
        self.connection.execute(
            """
            CREATE INDEX IF NOT EXISTS idx_scenarios_project
            ON scenarios (project_id, id)
            """
        )
        self.connection.execute(
            """
            CREATE INDEX IF NOT EXISTS idx_run_schedules_due
            ON run_schedules (is_active, next_run_at, id)
            """
        )
        self.connection.execute(
            """
            CREATE INDEX IF NOT EXISTS idx_run_schedule_ticks_schedule
            ON run_schedule_ticks (schedule_id, id)
            """
        )

